-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 5 من 7. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ مما يأتي من الخصائص الفيزيائية للألكينات؟', null, null, '["مواد قطبية كثيرة الذوبان في الماء","درجات انصهارها وغليانها مرتفعة جدًّا","مواد أيونية توصل الكهرباء وهي سائلة","مواد غير قطبية قليلة الذوبان في الماء"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('mcq', 2, 'ما الألكين الذي تنتجه النباتات طبيعيًّا ويعمل هرمونًا مسؤولًا عن نضج الفاكهة؟', null, null, '["الإيثين","الإيثاين","الميثان","البروبان"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('mcq', 3, 'تمثل الصيغتان الآتيتان جزيئي الإيثان (أ) والإيثين (ب). لماذا يكون الإيثين أكثر نشاطًا كيميائيًّا من الإيثان؟', null, '[{"src":"qimg/chem22/c4-l3a-ethane-ethene.svg","alt":"صيغتان بنائيتان كاملتان. (أ): ذرتا كربون بينهما رابطة أحادية، وترتبط كل ذرة كربون بثلاث ذرات هيدروجين بروابط أحادية (H₃C–CH₃). (ب): ذرتا كربون بينهما رابطة ثنائية (خطان متوازيان)، وترتبط كل ذرة كربون بذرتي هيدروجين بروابط أحادية (H₂C=CH₂)."}]'::jsonb, '["لأن الإيثين مركب قطبي يذوب في الماء بسهولة فيتفاعل بسرعة أكبر","لأن الرابطة الثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون فتجعلها موقعًا للتفاعل","لأن عدد ذرات الهيدروجين في الإيثين أكبر منه في الإيثان فيزداد نشاطه","لأن الرابطة الثنائية تقل فيها الكثافة الإلكترونية بين ذرتي الكربون فتسهل مهاجمتها"]'::jsonb, 'فهم', 'تفسير النشاط الكيميائي', 'متوسط', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('mcq', 4, 'يُعدّ الإيثين من المواد الأولية المستخدمة في تصنيع مادة بلاستيكية تُصنع منها الحقائب والحبال وعلب الحليب. ما هذه المادة؟', null, null, '["البولي ستايرين","كلوريد البولي فينيل","البولي إيثيلين","النايلون"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('mcq', 5, 'يقطف المزارعون كثيرًا من الفواكه قبل تمام نضجها، ثم يعرّضونها للإيثين قبل بيعها. ما الفائدة من ذلك؟', null, null, '["يزيد الإيثين حجم الثمار بعد قطفها فيرتفع وزنها","يقتل الإيثين البكتيريا على سطح الثمار فتطول مدة صلاحيتها","يمنع الإيثين نضج الثمار طوال مدة النقل والتخزين","تتحمل الثمار غير الناضجة النقل والتخزين، ثم يُنضجها الإيثين قبل البيع"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها (الشكل 4-14)'),
('mcq', 6, 'يبين الجدول الآتي درجات الانصهار والغليان لألكانين وألكينين. أيّ استنتاج يتفق مع هذه البيانات؟', '{"headers":["المركب","عدد ذرات C","درجة الانصهار (°C)","درجة الغليان (°C)"],"rows":[["هبتان","7","−90.6","98.5"],["1-هبتين","7","−119.7","93.6"],["أوكتان","8","−56.8","125.6"],["1-أوكتين","8","−101.7","121.2"]]}'::jsonb, null, '["درجتا انصهار الألكين وغليانه أقل من درجتي الألكان الذي له عدد ذرات الكربون نفسه","درجتا انصهار الألكين وغليانه أعلى بكثير من درجتي الألكان المناظر له","تنخفض درجة الغليان بزيادة عدد ذرات الكربون في السلسلة","الألكينات في الجدول صلبة والألكانات سائلة عند 25 °C"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 139، 164 — خصائص الألكينات وجدول بيانات الهيدروكربونات'),
('mcq', 7, 'إلى جانب دوره في نضج الفواكه، ما الدور الآخر الذي يؤديه الإيثين في النباتات؟', null, null, '["امتصاص الماء والأملاح من التربة","تساقط أوراق الأشجار إيذانًا بدخول فصل الشتاء","صنع الغذاء في الأوراق بعملية البناء الضوئي","تثبيت النيتروجين في جذور النباتات"]'::jsonb, 'تذكر', 'تذكر دور حيوي', 'متوسط', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('essay', 1, 'عدّد ثلاثًا من الخصائص الفيزيائية للألكينات، واذكر استعمالين للإيثين.', null, null, null, 'تذكر', 'تعداد خصائص واستعمالات', 'سهل', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها'),
('essay', 2, 'قارن بين البروبان CH₃CH₂CH₃ والبروبين CH₂=CHCH₃ من حيث: القطبية، والذوبان في الماء، والنشاط الكيميائي، مع تفسير الاختلاف في النشاط الكيميائي.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها؛ ص 142 — س20'),
('essay', 3, 'يريد تاجر فواكه استيراد شحنة كبيرة من الموز من بلد بعيد وبيعها ناضجة في متجره. اقترح كيف يستفيد من الإيثين في ذلك مع التفسير، ثم اذكر استعمالًا صناعيًّا آخر للإيثين يرتبط بمنتجات يستعملها التاجر في متجره.', null, null, null, 'تطبيق', 'توظيف المعرفة في موقف حياتي', 'صعب', 'الكتاب ص 139 — خصائص الألكينات واستخداماتها (الشكل 4-14)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الألكينات، مثل الألكانات، مواد غير قطبية؛ لذا فإن ذائبيتها قليلة في الماء، ودرجات انصهارها وغليانها منخفضة.', '["الألكينات غير قطبية، لذا ذائبيتها في الماء قليلة.","درجات انصهار الألكينات وغليانها منخفضة.","الألكينات مركبات جزيئية تساهمية غير قطبية لا أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 2, 0, 'الإيثين هرمون تنتجه النباتات على نحو طبيعي، وهو المسؤول عن عملية النضج في الفواكه.', '["","الإيثاين (الأسيتيلين) ألكاين يُستعمل في لحام الفلزات، وليس هرمون النضج.","الميثان ألكان وهو المكون الرئيس للغاز الطبيعي.","البروبان ألكان يُستعمل وقودًا، وليس ألكينًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 3, 1, 'الرابطة المشتركة الثانية في الإيثين تزيد من الكثافة الإلكترونية بين ذرتي الكربون، فتصبح موقعًا جيدًا للنشاط الكيميائي، وتستطيع المواد المتفاعلة جذب إلكترونات الرابطة باي بعيدًا عن الرابطة الثنائية.', '["الإيثين غير قطبي وذائبيته في الماء قليلة، كالإيثان.","","الإيثين (C₂H₄) فيه ذرات هيدروجين أقل من الإيثان (C₂H₆).","العكس هو الصحيح: الرابطة الثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 4, 2, 'يُستعمل الإيثين مادة أولية في تصنيع البولي إيثيلين، وهو مادة بلاستيكية تُصنع منها الحقائب البلاستيكية والحبال وعلب الحليب.', '["البولي ستايرين لا يُصنع من الإيثين وحده؛ والمادة المرتبطة بالإيثين هي البولي إيثيلين.","كلوريد البولي فينيل لا يُصنع من الإيثين وحده؛ والمادة التي يُصنع منها هي البولي إيثيلين.","","النايلون ليس من بوليمرات الإيثين؛ فالبوليمر المصنوع من الإيثين هو البولي إيثيلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 5, 3, 'الإيثين هرمون النضج؛ فقطف الثمار قبل نضجها يجعلها تتحمل النقل والتخزين، ثم يُسرّع تعريضها للإيثين نضجها صناعيًّا قبل عرضها للبيع.', '["الإيثين مسؤول عن النضج لا عن زيادة حجم الثمار.","دور الإيثين هنا إنضاج الثمار لا تعقيمها.","الإيثين يسبب النضج ولا يمنعه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 6, 0, 'الهبتان يغلي عند 98.5 °C و1-هبتين عند 93.6 °C، والأوكتان عند 125.6 °C و1-أوكتين عند 121.2 °C، وكذلك درجات الانصهار؛ فالألكين أقل من الألكان المناظر في الدرجتين.', '["","الأرقام تبين العكس: درجتا الألكين أقل من درجتي الألكان المناظر.","درجة الغليان ترتفع بزيادة عدد ذرات الكربون (الأوكتان أعلى من الهبتان).","درجات الانصهار كلها تحت الصفر ودرجات الغليان فوق 25 °C، فالمركبات الأربعة سائلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('mcq', 7, 1, 'يؤدي الإيثين دورًا في عملية تساقط أوراق الأشجار إيذانًا بدخول فصل الشتاء، إضافة إلى أنه المسؤول عن نضج الفواكه.', '["امتصاص الماء والأملاح وظيفة الجذور، وليس دور الإيثين.","","البناء الضوئي عملية تقوم بها الأوراق الخضراء، ولا يُنسب إلى الإيثين.","تثبيت النيتروجين تقوم به بكتيريا في الجذور، وليس من أدوار الإيثين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخصائص الفيزيائية: (1) الألكينات مواد غير قطبية. (2) ذائبيتها في الماء قليلة. (3) درجات انصهارها وغليانها منخفضة. استعمالات الإيثين: (1) هرمون طبيعي مسؤول عن نضج الفواكه، ويُستعمل صناعيًّا لإنضاج الفواكه والخضراوات بعد قطفها. (2) مادة أولية في تصنيع البولي إيثيلين الذي تُصنع منه الحقائب البلاستيكية والحبال وعلب الحليب.', '["غير قطبية","قليلة الذوبان في الماء","درجات انصهار وغليان منخفضة","إنضاج الفواكه","مادة أولية للبولي إيثيلين"]'::jsonb, '[]'::jsonb, '[{"element":"ثلاث خصائص فيزيائية","marks":3},{"element":"استعمالان للإيثين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث خصائص صحيحة واستعمالان صحيحان"},{"level":"3–4 درجات","description":"أربعة عناصر صحيحة أو ثلاثة"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألكينات قطبية تذوب في الماء","ذكر استعمال الإيثاين في اللحام على أنه من استعمالات الإيثين","ذكر خصائص كيميائية بدل الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القطبية: كلاهما غير قطبي. الذوبان في الماء: كلاهما قليل الذوبان في الماء لأنهما غير قطبيين. النشاط الكيميائي: البروبين أكثر نشاطًا من البروبان؛ لأن الرابطة الثنائية فيه تزيد الكثافة الإلكترونية بين ذرتي الكربون فتجعلها موقعًا جيدًا للنشاط الكيميائي، وتستطيع المواد المتفاعلة جذب إلكترونات الرابطة باي بعيدًا عن الرابطة الثنائية، أما البروبان فروابطه أحادية فقط.', '["كلاهما غير قطبي","كلاهما قليل الذوبان في الماء","البروبين أنشط","التفسير بالكثافة الإلكترونية للرابطة الثنائية"]'::jsonb, '[]'::jsonb, '[{"element":"القطبية","marks":1},{"element":"الذوبان","marks":1},{"element":"مقارنة النشاط","marks":1},{"element":"تفسير النشاط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في البنود الثلاثة مع تفسير صحيح للنشاط"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تفسير ناقص"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن البروبين قطبي بسبب الرابطة الثنائية","القول إن البروبان أنشط لاحتوائه على ذرات هيدروجين أكثر","تفسير النشاط بضعف الكثافة الإلكترونية في الرابطة الثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.600Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُقطف الموز قبل نضجه (أخضر) فيتحمل النقل الطويل والتخزين دون أن يتلف، ثم يُعرَّض في مخازن المتجر لغاز الإيثين قبل البيع؛ لأن الإيثين هرمون النضج الطبيعي في النباتات فيُنضج الثمار صناعيًّا في الوقت المطلوب. ويُستعمل الإيثين أيضًا مادةً أولية في تصنيع البولي إيثيلين الذي تُصنع منه الحقائب البلاستيكية التي يضع فيها الزبائن مشترياتهم.', '["القطف قبل النضج لتحمل النقل والتخزين","التعريض للإيثين قبل البيع","التفسير: الإيثين هرمون النضج","البولي إيثيلين (الحقائب البلاستيكية/علب الحليب)"]'::jsonb, '[]'::jsonb, '[{"element":"خطة القطف والتعريض للإيثين","marks":2},{"element":"التفسير","marks":1},{"element":"الاستعمال الصناعي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطة صحيحة مفسرة واستعمال صناعي مناسب"},{"level":"2–3 درجات","description":"خطة صحيحة دون تفسير، أو تفسير مع نقص في الخطة"},{"level":"1 درجة","description":"ذكر الاستعمال الصناعي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريض الموز للإيثين قبل الشحن فيتلف في الطريق","القول إن الإيثين يحفظ الثمار من النضج","ذكر استعمال الإيثاين في اللحام بدل استعمالات الإيثين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
