from (values
('mcq', 1, 'ما التعريف الصحيح للألكاينات؟', null, null, '["هيدروكربونات غير مشبعة تحتوي على رابطة ثنائية واحدة أو أكثر بين ذرات الكربون","هيدروكربونات غير مشبعة تحتوي على رابطة ثلاثية واحدة أو أكثر بين ذرات الكربون","هيدروكربونات مشبعة تحتوي على روابط أحادية فقط بين ذرات الكربون","هيدروكربونات مشبعة تتصل فيها ذرات الكربون على شكل حلقة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة)'),
('mcq', 2, 'ما الصيغة العامة للألكاينات التي تحتوي على رابطة ثلاثية واحدة؟', null, null, '["CₙH₂ₙ","CₙH₂ₙ₊₂","CₙHₙ","CₙH₂ₙ₋₂"]'::jsonb, 'تذكر', 'تذكر صيغة عامة', 'سهل', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة)'),
('mcq', 3, 'ما أبسط الألكاينات وأكثرها استخدامًا؟', null, null, '["الإيثاين C₂H₂","البروباين C₃H₄","الإيثين C₂H₄","الميثان CH₄"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة) (الشكل 4-15)'),
('mcq', 4, 'تمثل الصيغة الآتية جزيء الإيثاين. ما عدد أزواج الإلكترونات المشتركة بين ذرتي الكربون فيه، وما نوع الروابط التي تكوّنها؟', null, '[{"src":"qimg/chem22/c4-l3a-ethyne.svg","alt":"صيغة بنائية كاملة: H–C≡C–H؛ ذرتا كربون بينهما رابطة ثلاثية (ثلاثة خطوط متوازية)، وترتبط كل ذرة كربون بذرة هيدروجين واحدة برابطة أحادية."}]'::jsonb, '["زوجان: رابطة سيجما ورابطة باي","ثلاثة أزواج: ثلاث روابط سيجما","ثلاثة أزواج: رابطة سيجما ورابطتا باي","ستة أزواج: ثلاث روابط سيجما وثلاث باي"]'::jsonb, 'فهم', 'تحليل رابطة', 'متوسط', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة)'),
('mcq', 5, 'تمثل الصيغ الآتية أربعة مركبات يحتوي كل منها على أربع ذرات كربون. أيّ هذه المركبات ألكاين؟', null, '[{"src":"qimg/chem22/c4-l3a-o5-four.svg","alt":"أربع صيغ بنائية مكثفة مرقمة، في كل منها أربع ذرات كربون. المركب (1): CH₃–CH=CH–CH₃ وفيه رابطة ثنائية بين ذرتي الكربون الثانية والثالثة. المركب (2): CH₃–C≡C–CH₃ وفيه رابطة ثلاثية بين ذرتي الكربون الثانية والثالثة. المركب (3): CH₃–CH₂–CH₂–CH₃ وكل روابطه أحادية. المركب (4): CH₂=CH–CH=CH₂ وفيه رابطتان ثنائيتان: بين الذرتين الأولى والثانية، وبين الثالثة والرابعة."}]'::jsonb, '["المركب (1)","المركب (2)","المركب (3)","المركب (4)"]'::jsonb, 'فهم', 'تصنيف من الصيغة البنائية', 'متوسط', 'الكتاب ص 137، 140 — الجدول 4-6'),
('mcq', 6, 'ما الصيغة الجزيئية لألكاين ذي سلسلة مستقيمة يحتوي على 5 ذرات كربون ورابطة ثلاثية واحدة؟', null, null, '["C₅H₈","C₅H₁₀","C₅H₁₂","C₅H₆"]'::jsonb, 'تطبيق', 'تطبيق الصيغة العامة', 'متوسط', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة)'),
('mcq', 7, 'أيّ الصيغ الجزيئية الآتية تتفق مع الصيغة العامة للألكاينات ذات الرابطة الثلاثية الواحدة؟', null, null, '["C₆H₁₂","C₇H₁₆","C₈H₁₄","C₉H₂₀"]'::jsonb, 'فهم', 'تمييز صيغة عامة', 'صعب', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة)'),
('essay', 1, 'عرّف الألكاينات، واكتب صيغتها العامة، ثم اذكر أبسط ألكاين: اسمه النظامي واسمه الشائع وصيغته الجزيئية.', null, null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 140 — الألكاينات (التعريف والصيغة العامة) (الشكل 4-15)'),
('essay', 2, 'قارن بين الألكينات والألكاينات من حيث: نوع الرابطة المميزة، وعدد أزواج الإلكترونات المشتركة فيها بين ذرتي الكربون، والصيغة العامة (لرابطة واحدة)، ثم اكتب الصيغة الجزيئية لكل من الألكين والألكاين اللذين يحتوي كل منهما على 4 ذرات كربون.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 136، 140 — الألكينات والألكاينات؛ ص 159 — س45'),
('essay', 3, 'تمثل الصيغ الآتية ثلاثة مركبات. اكتب الصيغة الجزيئية لكل منها، وحدّد أيها ألكاين مع التبرير، ثم فسّر لماذا لا تكفي الصيغة الجزيئية وحدها للحكم بأن المركب ألكاين.', null, '[{"src":"qimg/chem22/c4-l3a-c5h8.svg","alt":"ثلاث صيغ لمركبات تحتوي كل منها على خمس ذرات كربون. (أ): صيغة بنائية مكثفة CH≡C–CH₂–CH₂–CH₃ وفيها رابطة ثلاثية بين ذرتي الكربون الأولى والثانية. (ب): صيغة هيكلية لحلقة خماسية من خمس ذرات كربون فيها رابطة ثنائية واحدة (خط داخلي ثانٍ) بين ذرتين متجاورتين، وبقية روابط الحلقة أحادية. (ج): صيغة بنائية مكثفة CH₃–C≡C–CH₂–CH₃ وفيها رابطة ثلاثية بين ذرتي الكربون الثانية والثالثة."}]'::jsonb, null, 'تحليل', 'تصنيف وتفسير', 'صعب', 'الكتاب ص 137، 140 — الألكينات الحلقية والألكاينات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
