from (values
('mcq', 1, 1, 'تُسمّى الهيدروكربونات غير المشبعة التي تحتوي على رابطة ثلاثية واحدة أو أكثر بين ذرات الكربون الألكاينات.', '["هذا تعريف الألكينات؛ فالرابطة الثنائية تميزها.","","هذا تعريف الألكانات المشبعة.","هذا وصف الألكانات الحلقية، وليس فيها روابط ثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 2, 3, 'تشكّل الألكاينات المحتوية على رابطة ثلاثية واحدة سلسلة متماثلة صيغتها العامة CₙH₂ₙ₋₂.', '["هذه الصيغة العامة للألكينات ذات الرابطة الثنائية الواحدة.","هذه الصيغة العامة للألكانات.","عدد ذرات الهيدروجين في الألكاين 2n − 2 وليس n (تتساويان في الإيثاين فقط).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 3, 0, 'يُعدّ الإيثاين C₂H₂ أبسط الألكاينات وأكثرها استخدامًا، ويُعرف باسمه الشائع الأسيتيلين.', '["","البروباين ألكاين لكنه ليس أبسطها؛ ففيه ثلاث ذرات كربون.","الإيثين أبسط الألكينات، وفيه رابطة ثنائية لا ثلاثية.","الميثان ألكان مشبع، وذرة كربون واحدة لا تكوّن رابطة ثلاثية بين ذرتي كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 4, 2, 'في الرابطة الثلاثية تشترك ذرتا الكربون في ثلاثة أزواج من الإلكترونات: أحدها يكوّن رابطة سيجما، والزوجان الآخران يكوّنان رابطتي باي.', '["زوجان مشتركان يكوّنان رابطة ثنائية كما في الألكينات، لا ثلاثية.","لا يكون بين ذرتين إلا رابطة سيجما واحدة؛ والزوجان الآخران رابطتا باي.","","كل خط في الصيغة يمثل زوجًا واحدًا، فالرابطة الثلاثية ثلاثة أزواج لا ستة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 5, 1, 'المركب (2) CH₃C≡CCH₃ يحتوي على رابطة ثلاثية بين ذرتي كربون، فهو ألكاين (2-بيوتاين).', '["المركب (1) يحتوي على رابطة ثنائية، فهو ألكين (2-بيوتين).","","المركب (3) كل روابطه أحادية، فهو ألكان (بيوتان).","المركب (4) صيغته C₄H₆ كالبيوتاين، لكنه يحتوي على رابطتين ثنائيتين لا رابطة ثلاثية، فهو ألكين (1، 3-بيوتادايين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 6, 0, 'بالتعويض في الصيغة العامة للألكاينات CₙH₂ₙ₋₂ حيث n = 5: عدد ذرات الهيدروجين 2 × 5 − 2 = 8، فالصيغة C₅H₈.', '["","استُعملت الصيغة العامة للألكينات CₙH₂ₙ.","استُعملت الصيغة العامة للألكانات CₙH₂ₙ₊₂.","طُرحت 4 ذرات هيدروجين بدل ذرتين من 2n."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('mcq', 7, 2, 'في C₈H₁₄: n = 8 و2n − 2 = 14، فهي تتفق مع الصيغة العامة للألكاينات CₙH₂ₙ₋₂.', '["C₆H₁₂ تتفق مع CₙH₂ₙ (ألكين أو ألكان حلقي)، لا مع صيغة الألكاينات.","C₇H₁₆ تتفق مع CₙH₂ₙ₊₂، فهي صيغة ألكان (هبتان).","","C₉H₂₀ تتفق مع CₙH₂ₙ₊₂، فهي صيغة ألكان (نونان)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الألكاينات: هيدروكربونات غير مشبعة تحتوي على رابطة ثلاثية واحدة أو أكثر بين ذرات الكربون. صيغتها العامة (لرابطة ثلاثية واحدة) CₙH₂ₙ₋₂. أبسطها الإيثاين، واسمه الشائع الأسيتيلين، وصيغته الجزيئية C₂H₂.', '["التعريف: رابطة ثلاثية واحدة أو أكثر بين ذرات الكربون","غير مشبعة","الصيغة العامة CₙH₂ₙ₋₂","الإيثاين (الأسيتيلين) C₂H₂"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الصيغة العامة","marks":1},{"element":"الاسم النظامي والشائع","marks":1},{"element":"الصيغة الجزيئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وصيغة عامة صحيحان، وذكر الإيثاين والأسيتيلين وC₂H₂"},{"level":"2–3 درجات","description":"عنصران أو ثلاثة صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الإيثاين والإيثين","كتابة الصيغة العامة CₙH₂ₙ","كتابة صيغة الإيثاين C₂H₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.601Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الألكينات: الرابطة المميزة ثنائية بين ذرتي كربون، يُشترك فيها بزوجين من الإلكترونات، والصيغة العامة CₙH₂ₙ؛ والألكين ذو الأربع ذرات C₄H₈. الألكاينات: الرابطة المميزة ثلاثية بين ذرتي كربون، يُشترك فيها بثلاثة أزواج من الإلكترونات (سيجما ورابطتا باي)، والصيغة العامة CₙH₂ₙ₋₂؛ والألكاين ذو الأربع ذرات C₄H₆.', '["الألكين: رابطة ثنائية، زوجان","الألكاين: رابطة ثلاثية، ثلاثة أزواج","CₙH₂ₙ مقابل CₙH₂ₙ₋₂","C₄H₈ وC₄H₆"]'::jsonb, '["الألكين: n = 4 ← H = 2 × 4 = 8 ← C₄H₈","الألكاين: n = 4 ← H = 2 × 4 − 2 = 6 ← C₄H₆"]'::jsonb, '[{"element":"نوع الرابطة","marks":1},{"element":"عدد الأزواج المشتركة","marks":1},{"element":"الصيغتان العامتان","marks":1},{"element":"الصيغتان الجزيئيتان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة صحيحة في البنود الثلاثة والصيغتان الجزيئيتان صحيحتان"},{"level":"2–3 درجات","description":"بندان أو ثلاثة صحيحة"},{"level":"1 درجة","description":"بند واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرابطة الثلاثية ستة أزواج من الإلكترونات","تبديل الصيغتين العامتين","كتابة C₄H₁₀ للألكين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) CH≡CCH₂CH₂CH₃: صيغته C₅H₈، وهو ألكاين لاحتوائه على رابطة ثلاثية بين ذرتي كربون. (ب) حلقة خماسية فيها رابطة ثنائية: صيغتها C₅H₈، وهي ألكين حلقي (بنتين حلقي) لا ألكاين؛ إذ لا رابطة ثلاثية فيها. (ج) CH₃C≡CCH₂CH₃: صيغته C₅H₈، وهو ألكاين لاحتوائه على رابطة ثلاثية. المركبات الثلاثة لها الصيغة نفسها C₅H₈ التي تتفق مع CₙH₂ₙ₋₂، لكن (ب) ليس ألكاينًا؛ لأن تعريف الألكاين يشترط وجود رابطة ثلاثية بين ذرتي كربون، والصيغة الجزيئية لا تبين نوع الروابط ولا ترتيب الذرات، فنحتاج إلى الصيغة البنائية.', '["الصيغ الثلاث C₅H₈","(أ) و(ج) ألكاينان لوجود الرابطة الثلاثية","(ب) ألكين حلقي لا ألكاين","الصيغة الجزيئية لا تبين نوع الروابط"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغ الجزيئية","marks":1.5},{"element":"تحديد الألكاينين مع التبرير","marks":1.5},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"صيغ صحيحة وتصنيف مبرر وتفسير يربط تعريف الألكاين بالرابطة الثلاثية"},{"level":"3–4 درجات","description":"صيغ وتصنيف صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"بعض الصيغ أو التصنيفات صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الحلقة ألكاينًا لأن صيغتها C₅H₈","عدّ ذرات الهيدروجين في الحلقة خطأً","الحكم على نوع المركب من الصيغة الجزيئية وحدها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L3-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الاسم النظامي (IUPAC) للألكاين غير المتفرع الممثل بالصيغة الآتية؟', null, '[{"src":"qimg/chem22/c4-l3a-1pentyne.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₃–CH₂–CH₂–C≡CH؛ سلسلة مستقيمة من خمس ذرات كربون، والرابطة الثلاثية بين المجموعتين الرابعة (C) والخامسة (CH) من اليسار، أي عند الطرف الأيمن للسلسلة."}]'::jsonb, '["4-بنتاين","1-بنتين","1-بنتاين","2-بنتاين"]'::jsonb, 'تطبيق', 'تسمية من الصيغة', 'سهل', 'الكتاب ص 140 — تسمية الألكاينات'),
('mcq', 2, 'يحتوي الألكاين الآتي على مجموعة ميثيل واحدة تتفرع من السلسلة بعد الرابطة الثلاثية. ما اسمه وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3a-4m2pentyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–C≡C–CH–CH₃، والرابطة الثلاثية بين المجموعتين الثانية والثالثة من اليسار، وتتفرع من المجموعة الرابعة (CH) مجموعة CH₃ إلى الأسفل."}]'::jsonb, '["2-ميثيل-3-بنتاين","4-ميثيل-2-بنتاين","4-ميثيل-2-بنتين","4-ميثيل-2-هكساين"]'::jsonb, 'تطبيق', 'تسمية ألكاين متفرع', 'متوسط', 'الكتاب ص 140 — تسمية الألكاينات'),
('mcq', 3, 'تقع الرابطة الثلاثية في المركب الآتي عند طرف السلسلة. أيّ الأسماء الآتية هو اسمه النظامي الصحيح؟', null, '[{"src":"qimg/chem22/c4-l3a-3m1butyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH≡C–CH–CH₃، والرابطة الثلاثية بين المجموعتين الأولى (CH) والثانية (C)، وتتفرع من المجموعة الثالثة (CH) مجموعة CH₃ إلى الأعلى."}]'::jsonb, '["3-ميثيل-1-بيوتاين","2-ميثيل-3-بيوتاين","3-ميثيل-1-بيوتين","2-ميثيل-1-بيوتاين"]'::jsonb, 'تطبيق', 'تسمية ألكاين متفرع', 'متوسط', 'الكتاب ص 140 — تسمية الألكاينات؛ ص 142 — س21'),
('mcq', 4, 'ترتبط بإحدى ذرات الكربون في الألكاين الآتي مجموعتا ميثيل. ما اسمه وفق قواعد الأيوباك؟', null, '[{"src":"qimg/chem22/c4-l3a-22dm3hexyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–C–C≡C–CH₂–CH₃، والرابطة الثلاثية بين المجموعتين الثالثة والرابعة من اليسار. وترتبط بالمجموعة الثانية (C) مجموعتا CH₃ إضافيتان: إحداهما إلى الأعلى والأخرى إلى الأسفل."}]'::jsonb, '["5، 5-ثنائي ميثيل-3-هكساين","2، 2-ثنائي ميثيل-3-هكسين","2-ميثيل-3-هبتاين","2، 2-ثنائي ميثيل-3-هكساين"]'::jsonb, 'تطبيق', 'تسمية ألكاين متفرع', 'صعب', 'الكتاب ص 140، 160 — تسمية الألكاينات (س62)'),
('mcq', 5, 'ما الفرق الوحيد بين طريقة تسمية الألكاينات وطريقة تسمية الألكينات؟', null, null, '["تُرقّم السلسلة في الألكاينات من الطرف الأبعد عن الرابطة الثلاثية","لا يُكتب رقم موقع الرابطة الثلاثية في اسم الألكاين","ينتهي اسم السلسلة الرئيسة بالمقطع «اين» بدلًا من «ين»","تُختار أطول سلسلة ولو لم تحتوِ على الرابطة الثلاثية"]'::jsonb, 'فهم', 'مقارنة قواعد التسمية', 'سهل', 'الكتاب ص 140 — تسمية الألكاينات'),
('mcq', 6, 'سمّى طالب المركب CH₃CH₂C≡CCH(CH₃)CH₃ بالاسم «5-ميثيل-3-هكساين». ما الاسم الصحيح وفق نظام IUPAC؟', null, null, '["2-ميثيل-3-هكساين","5-ميثيل-4-هكساين","2-ميثيل-4-هكساين","2-ميثيل-3-هبتاين"]'::jsonb, 'تقويم', 'تقويم اسم وتصحيحه', 'صعب', 'الكتاب ص 140، 162 — تسمية الألكاينات (س87)'),
('mcq', 7, 'يحمل الألكاين الآتي تفرعًا مكوّنًا من ذرتي كربون. ما اسمه النظامي بعد اختيار السلسلة الرئيسة الصحيحة؟', null, '[{"src":"qimg/chem22/c4-l3a-4m1hexyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH≡C–CH₂–CH–CH₃، والرابطة الثلاثية بين المجموعتين الأولى (CH) والثانية (C). وتتفرع من المجموعة الرابعة (CH) إلى الأسفل مجموعة CH₂ مرتبطة بمجموعة CH₃ تحتها (مجموعة إيثيل)."}]'::jsonb, '["4-إيثيل-1-بنتاين","3-ميثيل-5-هكساين","4-ميثيل-1-هكسين","4-ميثيل-1-هكساين"]'::jsonb, 'تحليل', 'تحديد السلسلة الرئيسة وتسمية', 'متوسط', 'الكتاب ص 140 — تسمية الألكاينات'),
('essay', 1, 'سمِّ المركبين (أ) و(ب) الممثلين بالصيغتين الآتيتين وفق نظام IUPAC، مبينًا في كل منهما عدد ذرات السلسلة الرئيسة والطرف الذي بدأت منه الترقيم.', null, '[{"src":"qimg/chem22/c4-l3a-two-alkynes.svg","alt":"صيغتان بنائيتان مكثفتان. (أ): سلسلة مستقيمة من اليسار إلى اليمين CH₃–CH₂–C≡C–CH₃، والرابطة الثلاثية بين المجموعتين الثالثة والرابعة من اليسار. (ب): سلسلة أفقية من اليسار إلى اليمين CH₃–C≡C–CH₂–CH–CH₃، والرابطة الثلاثية بين المجموعتين الثانية والثالثة من اليسار، وتتفرع من المجموعة الخامسة (CH) مجموعة CH₃ إلى الأسفل."}]'::jsonb, null, 'تطبيق', 'تسمية مع تبرير', 'متوسط', 'الكتاب ص 140 — تسمية الألكاينات'),
('essay', 2, 'سمِّ المركب الممثل بالصيغة الآتية وفق نظام IUPAC، موضحًا خطوات التسمية، ثم اكتب صيغته الجزيئية.', null, '[{"src":"qimg/chem22/c4-l3a-25dm3heptyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–CH–C≡C–CH–CH₂–CH₃، والرابطة الثلاثية بين المجموعتين الثالثة والرابعة من اليسار. وتتفرع مجموعة CH₃ إلى الأسفل من المجموعة الثانية (CH)، ومجموعة CH₃ أخرى إلى الأسفل من المجموعة الخامسة (CH)."}]'::jsonb, null, 'تطبيق', 'تسمية بخطوات', 'صعب', 'الكتاب ص 140 — تسمية الألكاينات'),
('essay', 3, 'قوّم كل اسم من الأسماء الآتية: هل هو صحيح؟ إن لم يكن صحيحًا فبيّن السبب واكتب الاسم الصحيح إن أمكن: (أ) 1-ميثيل-2-بيوتاين، (ب) 2-ميثيل-1-بيوتاين، (ج) 3، 3-ثنائي ميثيل-1-بيوتاين.', null, null, null, 'تقويم', 'تقويم أسماء', 'صعب', 'الكتاب ص 140، 162 — تسمية الألكاينات (س87)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
