insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'السلسلة خمس ذرات (بنت-) فيها رابطة ثلاثية فينتهي الاسم بـ«اين». نرقّم من الطرف الأيمن الأقرب إلى الرابطة الثلاثية فتبدأ عند الذرة 1: 1-بنتاين.', '["رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثلاثية.","المقطع «ين» للألكينات، والمركب فيه رابطة ثلاثية فينتهي بـ«اين».","","في 2-بنتاين تكون الرابطة الثلاثية بين الذرتين 2 و3، وهي هنا عند طرف السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 2, 1, 'أطول سلسلة تحتوي على الرابطة الثلاثية خمس ذرات (بنتاين). نرقّم من اليسار فتأخذ الرابطة الثلاثية الرقم 2، وتقع مجموعة الميثيل على الذرة 4: 4-ميثيل-2-بنتاين.', '["رُقّمت السلسلة لتأخذ المجموعة البديلة أصغر رقم؛ والقاعدة أن تأخذ الرابطة الثلاثية أصغر رقم.","","المقطع «ين» للرابطة الثنائية، والمركب فيه رابطة ثلاثية.","السلسلة الرئيسة خمس ذرات لا ست؛ فمجموعة الميثيل تفرّع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 3, 0, 'السلسلة الرئيسة أربع ذرات تحتوي على الرابطة الثلاثية (بيوتاين). نرقّم من طرف CH≡ فتأخذ الرابطة الرقم 1، وتقع مجموعة الميثيل على الذرة 3: 3-ميثيل-1-بيوتاين.', '["","رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثلاثية.","المقطع «ين» للرابطة الثنائية، والمركب فيه رابطة ثلاثية.","مجموعة الميثيل على الذرة 3؛ فالذرة 2 داخلة في الرابطة الثلاثية ولا تتسع لتفرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 4, 3, 'السلسلة الرئيسة ست ذرات (هكساين). الرابطة الثلاثية تأخذ الرقم 3 من الاتجاهين، فنرقّم من اليسار لتأخذ مجموعتا الميثيل الرقمين الأصغرين 2 و2 بدل 5 و5: 2، 2-ثنائي ميثيل-3-هكساين.', '["عند تعادل موقع الرابطة الثلاثية تُعطى المجموعات البديلة أصغر الأرقام (2، 2 لا 5، 5).","المقطع «ين» للرابطة الثنائية، والمركب فيه رابطة ثلاثية.","أُدخلت إحدى مجموعات الميثيل في السلسلة خطأً؛ وأطول سلسلة ست ذرات فقط، مع تفرعين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 5, 2, 'تُسمّى الألكاينات المستقيمة والمتفرعة بطريقة مماثلة للألكينات، والفرق الوحيد أن اسم السلسلة الرئيسة ينتهي بـ«اين» بدلًا من «ين».', '["الترقيم يبدأ من الطرف الأقرب إلى الرابطة الثلاثية، كما في الألكينات.","يُكتب رقم موقع الرابطة الثلاثية كما يُكتب موقع الرابطة الثنائية، مثل 1-بيوتاين و2-بيوتاين.","","السلسلة الرئيسة يجب أن تحتوي على الرابطة الثلاثية، كما في الألكينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 6, 0, 'السلسلة ست ذرات، والرابطة الثلاثية تأخذ الرقم 3 من الطرفين، فنرقّم من الطرف الذي يعطي مجموعة الميثيل أصغر رقم (2 لا 5): 2-ميثيل-3-هكساين.', '["","رقم الرابطة الثلاثية 3 من الطرفين، والذرتان 4 و5 لا تعطيانه أصغر رقم.","بالترقيم الذي يعطي الميثيل الرقم 2 تقع الرابطة الثلاثية بين الذرتين 3 و4، فرقمها 3 لا 4.","السلسلة الرئيسة ست ذرات لا سبع؛ فمجموعة الميثيل تفرّع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('mcq', 7, 3, 'أطول سلسلة تحتوي على الرابطة الثلاثية تمر بمجموعة الإيثيل فتضم ست ذرات (هكساين). نرقّم من طرف CH≡ فتأخذ الرابطة الرقم 1، وتبقى مجموعة ميثيل على الذرة 4: 4-ميثيل-1-هكساين.', '["اختيرت السلسلة الأفقية المرسومة (خمس ذرات)، والأطول المحتوية على الرابطة الثلاثية ست ذرات تمر بمجموعة الإيثيل.","رُقّمت السلسلة من الطرف الأبعد عن الرابطة الثلاثية.","المقطع «ين» للرابطة الثنائية، والمركب فيه رابطة ثلاثية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.602Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السلسلة خمس ذرات (بنتاين)، نرقّم من الطرف الأيمن الأقرب إلى الرابطة الثلاثية فتأخذ الرقم 2: 2-بنتاين. (ب) السلسلة الرئيسة ست ذرات (هكساين)، نرقّم من الطرف الأيسر الأقرب إلى الرابطة الثلاثية فتأخذ الرقم 2 (من اليمين تأخذ 4)، وتقع مجموعة الميثيل على الذرة 5: 5-ميثيل-2-هكساين.', '["(أ) خمس ذرات، الترقيم من اليمين","(أ) 2-بنتاين","(ب) ست ذرات، الترقيم من اليسار","(ب) 5-ميثيل-2-هكساين"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل (أ)","marks":1},{"element":"اسم (أ)","marks":1},{"element":"تحليل (ب)","marks":1},{"element":"اسم (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاسمان صحيحان مع بيان السلسلة واتجاه الترقيم"},{"level":"2–3 درجات","description":"اسم صحيح مع تحليله، أو الاسمان دون تحليل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (أ) 3-بنتاين","تسمية (ب) 2-ميثيل-4-هكساين بإعطاء الميثيل الأولوية","استعمال المقطع «ين» بدل «اين»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أطول سلسلة تحتوي على الرابطة الثلاثية سبع ذرات (هبتاين). الترقيم من اليسار يعطي الرابطة الثلاثية الرقم 3، ومن اليمين الرقم 4؛ فنرقّم من اليسار. تقع مجموعتا الميثيل على الذرتين 2 و5، فنستعمل «ثنائي». الاسم: 2، 5-ثنائي ميثيل-3-هبتاين. الصيغة الجزيئية: عدد ذرات الكربون 9، وهو ألكاين برابطة ثلاثية واحدة CₙH₂ₙ₋₂، فالصيغة C₉H₁₆.', '["السلسلة الرئيسة سبع ذرات: هبتاين","الترقيم من اليسار: الرابطة الثلاثية عند 3","مجموعتا ميثيل عند 2 و5","الاسم 2، 5-ثنائي ميثيل-3-هبتاين","الصيغة C₉H₁₆"]'::jsonb, '["تحديد أطول سلسلة تحتوي على الرابطة الثلاثية: 7 ذرات ← هبتاين","المقارنة: من اليسار 3 ، من اليمين 4 ← الترقيم من اليسار","مواقع المجموعات البديلة: ميثيل عند 2 و5 ← 2، 5-ثنائي ميثيل","الاسم: 2، 5-ثنائي ميثيل-3-هبتاين","عدد C = 7 + 2 = 9 ، عدد H = 2 × 9 − 2 = 16 ← C₉H₁₆"]'::jsonb, '[{"element":"السلسلة الرئيسة","marks":1},{"element":"اتجاه الترقيم","marks":1},{"element":"المجموعات البديلة والبادئة","marks":1},{"element":"الاسم كاملًا","marks":1},{"element":"الصيغة الجزيئية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوات صحيحة كاملة واسم صحيح وصيغة جزيئية صحيحة"},{"level":"3–4 درجات","description":"اسم صحيح مع نقص في الخطوات أو خطأ في الصيغة الجزيئية"},{"level":"1–2 درجة","description":"تحديد السلسلة أو اتجاه الترقيم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترقيم من اليمين وكتابة 3، 6-ثنائي ميثيل-4-هبتاين","نسيان البادئة «ثنائي»","إهمال ذرتي كربون الميثيل في الصيغة الجزيئية (C₇H₁₂)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) غير صحيح: مجموعة الميثيل على الذرة 1 تطيل السلسلة، فالمركب CH₃CH₂C≡CCH₃ سلسلته خمس ذرات، واسمه الصحيح 2-بنتاين. (ب) غير ممكن: الذرة 2 في 1-بيوتاين داخلة في الرابطة الثلاثية (ثلاث روابط) ومرتبطة بالذرة 3 (رابطة رابعة)، فلا تتسع لمجموعة ميثيل؛ إذ ستكوّن خمس روابط. (ج) صحيح: CH≡CC(CH₃)₂CH₃، السلسلة أربع ذرات، والرابطة الثلاثية عند 1، ومجموعتا الميثيل على الذرة 3.', '["(أ) خطأ: السلسلة الأطول خمس ذرات ← 2-بنتاين","(ب) مستحيل: الذرة 2 ستكوّن خمس روابط","(ج) صحيح مع التبرير"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم (أ) وتصحيحه","marks":2},{"element":"تقويم (ب) وتبريره","marks":2},{"element":"تقويم (ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح ومبرر للأسماء الثلاثة مع الاسم الصحيح لـ(أ)"},{"level":"3–4 درجات","description":"تقويم صحيح لاسمين مع تبرير"},{"level":"1–2 درجة","description":"تقويم صحيح لاسم واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول (أ) لأن الصيغة يمكن رسمها منه","تصحيح (ب) إلى 3-ميثيل-1-بيوتاين دون بيان سبب استحالته","الحكم بخطأ (ج) لوجود مجموعتين على الذرة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
