('mcq', 1, 'ما الصيغة البنائية المكثفة للبروباين؟', null, null, '["CH₂=CHCH₃","CH≡CCH₃","CH₃C≡CCH₃","CH≡CCH₂CH₃"]'::jsonb, 'تطبيق', 'صيغة مكثفة من الاسم', 'سهل', 'الكتاب ص 140 — الجدول 4-6 أمثلة على الألكاينات'),
('mcq', 2, 'ما الصيغة الجزيئية للمركب 3-هبتاين؟', null, null, '["C₇H₁₄","C₇H₁₆","C₇H₁₀","C₇H₁₂"]'::jsonb, 'تطبيق', 'صيغة جزيئية من الاسم', 'سهل', 'الكتاب ص 140 — تسمية الألكاينات'),
('mcq', 3, 'أيّ الصيغ البنائية الآتية تمثل المركب 2-بيوتاين؟', null, '[{"src":"qimg/chem22/c4-l3b-o7-c4-full.svg","alt":"أربع صيغ بنائية كاملة مرقمة، في كل منها أربع ذرات كربون في سلسلة أفقية، وذرة هيدروجين طرفية عند كل من طرفي السلسلة. الصيغة (1): H–C≡C–C–C–H، والرابطة الثلاثية بين ذرتي الكربون الأولى والثانية من اليسار، وترتبط بكل من ذرتي الكربون الثالثة والرابعة ذرتا هيدروجين (واحدة فوقها وأخرى تحتها). الصيغة (2): H–C–C=C–C–H، والرابطة الثنائية بين ذرتي الكربون الثانية والثالثة، وترتبط بكل من ذرتي الكربون الطرفيتين ذرتا هيدروجين إضافيتان (فوق وتحت)، وترتبط بكل من ذرتي الكربون الوسطيين ذرة هيدروجين واحدة فوقها. الصيغة (3): H–C–C≡C–C–H، والرابطة الثلاثية بين ذرتي الكربون الثانية والثالثة، وترتبط بكل من ذرتي الكربون الطرفيتين ذرتا هيدروجين إضافيتان (فوق وتحت)، ولا ترتبط أي ذرة هيدروجين بذرتي الكربون الوسطيين. الصيغة (4): مثل الصيغة (3) تمامًا (رابطة ثلاثية بين ذرتي الكربون الثانية والثالثة)، لكن ترتبط أيضًا بكل من ذرتي الكربون الوسطيين ذرة هيدروجين واحدة فوقها."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'تطبيق', 'اختيار الصيغة البنائية من الاسم', 'متوسط', 'الكتاب ص 140 — الجدول 4-6 أمثلة على الألكاينات'),
('mcq', 4, 'ما الصيغة البنائية المكثفة للمركب 4-ميثيل-1-بنتاين؟', null, null, '["CH≡CCH₂CH(CH₃)CH₃","CH≡CCH(CH₃)CH₂CH₃","CH₃C≡CCH(CH₃)CH₃","CH₂=CHCH₂CH(CH₃)CH₃"]'::jsonb, 'تطبيق', 'صيغة مكثفة من الاسم', 'متوسط', 'الكتاب ص 140 — تسمية الألكاينات'),
('mcq', 5, 'رسم طالب الصيغة الآتية على أنها صيغة المركب 4-ميثيل-2-هكساين. ما الخطأ في رسمه؟', null, '[{"src":"qimg/chem22/c4-l3b-o7-student.svg","alt":"صيغة بنائية مكثفة رسمها طالب، وفوق مجموعات السلسلة الأفقية أرقام الترقيم من 1 إلى 6 من اليسار إلى اليمين. السلسلة: CH₃(1)–C(2)≡CH(3)–CH(4)–CH₂(5)–CH₃(6)، والرابطة الثلاثية بين المجموعة 2 (C) والمجموعة 3 (CH)، وتتفرع مجموعة CH₃ إلى الأسفل من المجموعة 4 (CH)."}]'::jsonb, '["يجب أن تكون مجموعة الميثيل على ذرة الكربون 3","ذرة الكربون 3 مرتبطة بذرة هيدروجين فتكوّن خمس روابط","يجب أن تكون الرابطة الثلاثية بين ذرتي الكربون 3 و4","يجب أن تحتوي السلسلة الرئيسة على خمس ذرات كربون"]'::jsonb, 'تحليل', 'اكتشاف خطأ في صيغة', 'صعب', 'الكتاب ص 140 — تسمية الألكاينات'),
