from (values
('mcq', 1, 1, 'البروباين ألكاين من ثلاث ذرات كربون فيه رابطة ثلاثية بين الذرتين 1 و2؛ ترتبط ذرة الكربون الطرفية بذرة هيدروجين واحدة، والوسطى بلا هيدروجين، والثالثة بثلاث: CH≡CCH₃.', '["هذه صيغة البروبين؛ فيها رابطة ثنائية لا ثلاثية.","","هذه صيغة 2-بيوتاين؛ فيها أربع ذرات كربون.","هذه صيغة 1-بيوتاين؛ فيها أربع ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 2, 3, '«هبت» تعني سبع ذرات كربون، و«اين» تعني رابطة ثلاثية واحدة، فبالتعويض في CₙH₂ₙ₋₂: عدد ذرات الهيدروجين 2 × 7 − 2 = 12، والصيغة C₇H₁₂. والرقم 3 يحدد موقع الرابطة فقط ولا يغيّر الصيغة الجزيئية.', '["هذه صيغة الهبتين (ألكين برابطة ثنائية واحدة).","هذه صيغة الهبتان المشبع.","طُرحت 4 ذرات هيدروجين من 2n بدل ذرتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 3, 2, 'في 2-بيوتاين أربع ذرات كربون والرابطة الثلاثية بين الذرتين 2 و3، فلا ترتبط بهاتين الذرتين أي ذرة هيدروجين (كل منهما تكوّن ثلاث روابط مع الأخرى ورابطة مع الذرة الطرفية)، وترتبط بكل ذرة طرفية ثلاث ذرات هيدروجين: CH₃C≡CCH₃، وهذه الصيغة (3).', '["الصيغة (1) تمثل 1-بيوتاين؛ فالرابطة الثلاثية عند طرف السلسلة.","الصيغة (2) فيها رابطة ثنائية، فهي 2-بيوتين.","","في الصيغة (4) ترتبط كل ذرة من ذرتي الرابطة الثلاثية بذرة هيدروجين، فتكوّن خمس روابط، وذرة الكربون تكوّن أربع روابط فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 4, 0, 'السلسلة الرئيسة خمس ذرات (بنت-) والرابطة الثلاثية بين الذرتين 1 و2 (CH≡C)، ثم الذرة 3 (CH₂)، ثم الذرة 4 وعليها مجموعة الميثيل CH(CH₃)، ثم الذرة 5 (CH₃): CH≡CCH₂CH(CH₃)CH₃.', '["","مجموعة الميثيل هنا على الذرة 3، فهذه صيغة 3-ميثيل-1-بنتاين.","الرابطة الثلاثية هنا بين الذرتين 2 و3، فهذه صيغة 4-ميثيل-2-بنتاين.","فيها رابطة ثنائية، فهي صيغة 4-ميثيل-1-بنتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 5, 1, 'ذرة الكربون 3 تشارك في الرابطة الثلاثية (ثلاث روابط) وترتبط بالذرة 4 (رابطة رابعة)، فلا مكان لذرة هيدروجين عليها؛ وكتابتها CH تجعلها تكوّن خمس روابط. الصحيح: CH₃C≡CCH(CH₃)CH₂CH₃.', '["الاسم 4-ميثيل يعني أن الميثيل على الذرة 4، وهذا ما رسمه الطالب صحيحًا.","","الرقم 2 في الاسم يعني أن الرابطة الثلاثية تبدأ عند الذرة 2، أي بين 2 و3 كما رُسمت.","«هكس» تعني ست ذرات في السلسلة الرئيسة، والسلسلة المرسومة ست ذرات فعلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 6, 2, 'الصيغة المكثفة CH₃CH(CH₃)C≡CCH(CH₃)CH₃: السلسلة الرئيسة 6 ذرات ومجموعتا ميثيل، فعدد ذرات الكربون 8. وهو ألكاين برابطة ثلاثية واحدة، فعدد ذرات الهيدروجين 2 × 8 − 2 = 14، والصيغة C₈H₁₄.', '["هذه صيغة ألكان (CₙH₂ₙ₊₂) لا ألكاين.","أُهملت ذرتا كربون مجموعتي الميثيل وما عليهما من هيدروجين.","","هذه صيغة ألكين (CₙH₂ₙ) لا ألكاين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('mcq', 7, 0, 'الإيثاين أبسط الألكاينات: ذرتا كربون بينهما رابطة ثلاثية وترتبط كل منهما بذرة هيدروجين واحدة، فصيغته المكثفة CH≡CH وصيغته الجزيئية C₂H₂.', '["","هاتان صيغتا الإيثين (ألكين).","هاتان صيغتا الإيثان (ألكان).","الصيغة المكثفة صحيحة، لكن عدد ذرات الهيدروجين فيها 2 لا 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.603Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) 1-بيوتاين: الصيغة الجزيئية C₄H₆. الصيغة البنائية الكاملة: H–C≡C–C–C–H حيث ترتبط بكل من ذرتي الكربون 3 و4 ذرتا هيدروجين إضافيتان (واحدة فوق وأخرى تحت). الصيغة المكثفة: CH≡CCH₂CH₃. (ب) 2-بيوتاين: الصيغة الجزيئية C₄H₆. الصيغة البنائية الكاملة: H–C–C≡C–C–H حيث ترتبط بكل من ذرتي الكربون الطرفيتين ذرتا هيدروجين إضافيتان، ولا ترتبط ذرتا الرابطة الثلاثية بأي هيدروجين. الصيغة المكثفة: CH₃C≡CCH₃. للمركبين الصيغة الجزيئية نفسها ويختلفان في موقع الرابطة الثلاثية.', '["C₄H₆ لكل منهما","صيغة بنائية كاملة صحيحة لـ 1-بيوتاين (الرابطة الثلاثية بين 1 و2)","صيغة بنائية كاملة صحيحة لـ 2-بيوتاين (الرابطة الثلاثية بين 2 و3)","CH≡CCH₂CH₃","CH₃C≡CCH₃"]'::jsonb, '["n = 4 ، عدد H = 2 × 4 − 2 = 6 ← C₄H₆","تحديد موقع الرابطة الثلاثية من الرقم في الاسم","إكمال التكافؤ الرباعي لكل ذرة كربون بذرات الهيدروجين"]'::jsonb, '[{"element":"الصيغتان الجزيئيتان","marks":1},{"element":"الصيغة البنائية الكاملة لـ 1-بيوتاين","marks":1},{"element":"الصيغة البنائية الكاملة لـ 2-بيوتاين","marks":1},{"element":"الصيغتان المكثفتان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة C₄H₈ بتطبيق صيغة الألكينات","وضع ذرة هيدروجين على ذرتي الرابطة الثلاثية في 2-بيوتاين","جعل الرابطة الثلاثية في 1-بيوتاين بين الذرتين 2 و3"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السلسلة الرئيسة خمس ذرات، والرابطة الثلاثية بين الذرتين 2 و3، ومجموعتا ميثيل على الذرة 4: CH₃C≡CC(CH₃)₂CH₃. عدد ذرات الكربون 5 + 2 = 7، فالصيغة الجزيئية C₇H₁₂. (ب) السلسلة الرئيسة ست ذرات، والرابطة الثلاثية بين الذرتين 1 و2، ومجموعة إيثيل على الذرة 3: CH≡CCH(CH₂CH₃)CH₂CH₂CH₃. عدد ذرات الكربون 6 + 2 = 8، فالصيغة الجزيئية C₈H₁₄.', '["CH₃C≡CC(CH₃)₂CH₃","C₇H₁₂","CH≡CCH(CH₂CH₃)CH₂CH₂CH₃","C₈H₁₄"]'::jsonb, '["(أ) رسم سلسلة من 5 ذرات، ووضع الرابطة الثلاثية بين 2 و3، ومجموعتي الميثيل على 4، ثم إكمال الهيدروجين: الذرة 4 لا هيدروجين عليها","(أ) C = 7 ، H = 2 × 7 − 2 = 12 ← C₇H₁₂","(ب) رسم سلسلة من 6 ذرات، والرابطة الثلاثية بين 1 و2، ومجموعة الإيثيل على 3، ثم إكمال الهيدروجين","(ب) C = 8 ، H = 2 × 8 − 2 = 14 ← C₈H₁₄"]'::jsonb, '[{"element":"الصيغة المكثفة (أ)","marks":1.5},{"element":"الصيغة الجزيئية (أ)","marks":1},{"element":"الصيغة المكثفة (ب)","marks":1.5},{"element":"الصيغة الجزيئية (ب)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الصيغ الأربع صحيحة"},{"level":"3–4 درجات","description":"صيغتا مركب واحد صحيحتان وخطأ في الآخر"},{"level":"1–2 درجة","description":"صيغة واحدة أو اثنتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع ذرة هيدروجين على ذرة الكربون 4 في (أ) رغم ارتباطها بمجموعتي ميثيل","إهمال ذرات كربون المجموعات البديلة عند كتابة الصيغة الجزيئية","كتابة الإيثيل CH₃ بدل CH₂CH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: كتب ذرة الكربون 4 على هيئة CH، وهي تشارك في الرابطة الثلاثية (ثلاث روابط) وترتبط بالذرة 5 (رابطة رابعة)، فإضافة الهيدروجين تجعلها تكوّن خمس روابط. الخطأ الثاني: الصيغة C₆H₁₂ صيغة ألكين (CₙH₂ₙ)، والهكساين ألكاين صيغته CₙH₂ₙ₋₂، فعدد ذرات الهيدروجين 2 × 6 − 2 = 10. الصيغتان الصحيحتان: CH₃CH₂C≡CCH₂CH₃ و C₆H₁₀.', '["تحديد خطأ ذرة الكربون 4 (خمس روابط)","تحديد خطأ الصيغة الجزيئية (صيغة ألكين)","CH₃CH₂C≡CCH₂CH₃","C₆H₁₀"]'::jsonb, '["ذرتا الرابطة الثلاثية في 3-هكساين (3 و4) ترتبط كل منهما بذرة كربون أخرى فقط، فلا هيدروجين عليهما","H = 2 × 6 − 2 = 10"]'::jsonb, '[{"element":"الخطأ في الصيغة المكثفة مع السبب","marks":1},{"element":"الخطأ في الصيغة الجزيئية مع السبب","marks":1},{"element":"الصيغة المكثفة الصحيحة","marks":1},{"element":"الصيغة الجزيئية الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بتصحيح الصيغة الجزيئية دون ملاحظة خطأ ذرة الكربون 4","تصحيح الصيغة إلى CH₃CH₂C≡CCH₃ بحذف ذرة كربون","عدّ ذرات الهيدروجين في صيغة الطالب الخاطئة وقبول C₆H₁₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
