insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L3-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل النموذجان الآتيان جزيء مركب تُستعمل مشاعله في لحام الفلزات. ما الاسم الشائع لهذا المركب؟', null, '[{"src":"qimg/chem22/c4-l3b-ethyne-models.svg","alt":"نموذجان لجزيء واحد. في اليسار صيغة بنائية: H–C≡C–H، أي ذرتا كربون بينهما رابطة ثلاثية، وترتبط كل منهما بذرة هيدروجين واحدة. وفي اليمين نموذج الكرة والعصا للجزيء نفسه: كرتان رماديتان كبيرتان (ذرتا الكربون) تصل بينهما ثلاث عصي متوازية، وكرة بيضاء صغيرة (ذرة هيدروجين) عند كل طرف متصلة بعصا واحدة، والذرات الأربع على خط مستقيم واحد."}]'::jsonb, '["الإيثيلين","الأسيتيلين","البروبيلين","الميثان"]'::jsonb, 'تذكر', 'تذكر اسم شائع', 'سهل', 'الكتاب ص 140–141 — الشكلان 4-15 و4-16'),
('mcq', 2, 'يُنتج الإيثاين ناتجًا ثانويًّا عن تنقية البترول، ويُنتج أيضًا بكميات كبيرة من تفاعل مادة صلبة مع الماء. ما هذه المادة؟', null, null, '["كربونات الكالسيوم CaCO₃","أكسيد الكالسيوم CaO","كلوريد الكالسيوم CaCl₂","كربيد الكالسيوم CaC₂"]'::jsonb, 'تذكر', 'تذكر طريقة تحضير', 'سهل', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('mcq', 3, 'عندما يُزوَّد الإيثاين بكمية كافية من الأكسجين يحترق منتجًا لهبًا ذا حرارة عالية جدًّا. ما أقصى درجة حرارة تقريبية قد يصل إليها هذا اللهب؟', null, null, '["3000 °C","300 °C","800 °C","30000 °C"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('mcq', 4, 'أيّ المعادلات الآتية تمثل الاحتراق الكامل للإيثاين في مشعل اللحام تمثيلًا موزونًا صحيحًا؟', null, null, '["C₂H₂ + O₂ → 2CO₂ + H₂O","C₂H₂ + 3O₂ → 2CO₂ + 2H₂O","2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O","2C₂H₂ + 3O₂ → 4CO + 2H₂O"]'::jsonb, 'فهم', 'اختيار معادلة موزونة', 'صعب', 'الكتاب ص 141 — الشكل 4-16'),
('mcq', 5, 'لماذا تُتخذ الألكاينات البسيطة كالإيثاين مواد أولية في صناعة البلاستيك وغيرها من المواد الكيميائية العضوية؟', null, null, '["لأنها أبسط الهيدروكربونات المشبعة وأكثرها ثباتًا","لأن روابطها أحادية فقط فيصعب كسرها","لأنها لا تتفاعل مع الأكسجين ولا تحترق","لأن رابطتها الثلاثية تجعلها أكثر نشاطًا فتتفاعل بسهولة"]'::jsonb, 'فهم', 'تفسير استعمال', 'متوسط', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('mcq', 6, 'تشبه الألكاينات الألكينات في خواصها الفيزيائية. أيّ مما يأتي يصف هذه الخواص؟', null, null, '["مواد غير قطبية، وذائبيتها في الماء قليلة","مواد قطبية تذوب بسهولة في الماء","مواد أيونية درجات انصهارها مرتفعة جدًّا","مواد موصلة للكهرباء في الحالة الصلبة"]'::jsonb, 'تذكر', 'تذكر خواص فيزيائية', 'سهل', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها؛ ص 139'),
('mcq', 7, 'ما الذي يميّز الخواص الكيميائية للألكاينات مقارنة بالألكينات؟', null, null, '["لا تخضع لأي تفاعل من تفاعلات الألكينات","تخضع لكثير من تفاعلات الألكينات لكنها أكثر نشاطًا عمومًا","تخضع لتفاعلات الألكينات نفسها لكن بنشاط أقل","خاملة كيميائيًّا فلا تتفاعل مع المواد الأخرى"]'::jsonb, 'تذكر', 'تذكر خواص كيميائية', 'متوسط', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('essay', 1, 'عدّد ثلاثًا من خواص الألكاينات (فيزيائية أو كيميائية)، واذكر استعمالين للإيثاين.', null, null, null, 'تذكر', 'تعداد خواص واستعمالات', 'متوسط', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('essay', 2, 'يُحضَّر الإيثاين بإضافة الماء إلى كربيد الكالسيوم CaC₂، فينتج غاز الإيثاين C₂H₂ ومعه هيدروكسيد الكالسيوم Ca(OH)₂. (أ) اكتب معادلة موزونة لتحضير الإيثاين. (ب) اكتب معادلة موزونة لاحتراقه الكامل في الأكسجين. (ج) فسّر لماذا تُستعمل مشاعل الأسيتيلين في لحام الفلزات.', null, null, null, 'تطبيق', 'معادلات وتفسير استعمال', 'صعب', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها (الشكل 4-16 وتجربة تحضير الإيثاين)'),
('essay', 3, 'قارن بين الإيثين والإيثاين من حيث: نوع الرابطة بين ذرتي الكربون، والاسم الشائع، ومصدر كل منهما، واستعمال مهم لكل منهما. ثم فسّر لماذا يفوق الإيثاين الإيثين نشاطًا.', null, null, null, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها؛ ص 136–139')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
