('mcq', 1, 1, 'النموذجان لجزيء H–C≡C–H وهو الإيثاين، واسمه الشائع الأسيتيلين، وتُستعمل مشاعل الأسيتيلين عادة في لحام الفلزات.', '["الإيثيلين الاسم الشائع للإيثين CH₂=CH₂، وفيه رابطة ثنائية.","","البروبيلين الاسم الشائع للبروبين، وفيه ثلاث ذرات كربون.","الميثان CH₄ فيه ذرة كربون واحدة وليس فيه رابطة ثلاثية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('mcq', 2, 3, 'ينتج الإيثاين (الأسيتيلين) بكميات كبيرة من تفاعل كربيد الكالسيوم CaC₂ مع الماء.', '["تفاعل كربونات الكالسيوم ليس مصدرًا للإيثاين؛ فهي تُنتج CO₂ عند تفاعلها مع الأحماض.","أكسيد الكالسيوم يتفاعل مع الماء مكوّنًا Ca(OH)₂ فقط دون غاز هيدروكربوني.","كلوريد الكالسيوم يذوب في الماء ولا يحتوي على كربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('mcq', 3, 0, 'يحترق الإيثاين مع كمية كافية من الأكسجين منتجًا لهبًا قد تصل حرارته إلى 3000 °C، وهي حرارة كافية لصهر الفلزات ولحامها.', '["","300 °C حرارة منخفضة لا تكفي لصهر الفلزات في اللحام.","800 °C أقل كثيرًا من حرارة لهب الأسيتيلين، ولا تكفي لصهر كثير من الفلزات كالحديد.","30000 °C قيمة مبالغ فيها كثيرًا (عشرة أضعاف القيمة الصحيحة)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('mcq', 4, 2, 'نواتج الاحتراق الكامل CO₂ وH₂O. في المعادلة 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O: الكربون 4 = 4، والهيدروجين 4 = 4، والأكسجين 10 = 8 + 2، فهي موزونة.', '["غير موزونة: الأكسجين ذرتان في المتفاعلات و5 ذرات في النواتج.","غير موزونة: الهيدروجين ذرتان في المتفاعلات و4 ذرات في النواتج.","","موزونة من حيث الذرات، لكن ناتجها CO لا CO₂، فهي لا تمثل الاحتراق الكامل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('mcq', 5, 3, 'الرابطة الثلاثية تجعل الألكاينات أكثر نشاطًا، فتتفاعل بسهولة لتكوين مواد جديدة؛ لذا تُتخذ الألكاينات البسيطة كالإيثاين مواد أولية في صناعة البلاستيك وغيره من المواد العضوية.', '["الألكاينات غير مشبعة، والثبات الكبير يقلل صلاحية المادة لتكوين مواد جديدة.","الألكاينات تحتوي على رابطة ثلاثية، لا روابط أحادية فقط.","الإيثاين يحترق بسهولة مع الأكسجين، وهذا أساس استعماله في اللحام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.604Z"}'::jsonb),
('mcq', 6, 0, 'للألكاينات خواص فيزيائية شبيهة بالألكينات: فهي مواد غير قطبية، ذائبيتها في الماء قليلة، ودرجات انصهارها وغليانها منخفضة نسبيًّا.', '["","الهيدروكربونات غير قطبية، فلا تذوب جيدًا في الماء القطبي.","الألكاينات مركبات جزيئية لا أيونية، ودرجات انصهارها منخفضة.","الألكاينات مركبات تساهمية جزيئية لا توصل الكهرباء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('mcq', 7, 1, 'تخضع الألكاينات لكثير من التفاعلات التي تخضع لها الألكينات، إلا أنها أكثر نشاطًا من الألكينات عمومًا؛ لأن رابطتها الثلاثية تشكّل كثافة إلكترونية أكبر.', '["للألكاينات خواص كيميائية شبيهة بالألكينات وتخضع لكثير من تفاعلاتها.","","الألكاينات أكثر نشاطًا من الألكينات لا أقل.","الألكاينات نشطة كيميائيًّا؛ فالإيثاين مثلًا يحترق بسرعة ويُستعمل مادة أولية في الصناعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من خواص الألكاينات: (1) مواد غير قطبية ذائبيتها في الماء قليلة، (2) لها خواص فيزيائية وكيميائية شبيهة بالألكينات وتخضع لكثير من تفاعلاتها، (3) أكثر نشاطًا من الألكينات عمومًا بسبب الكثافة الإلكترونية الكبيرة للرابطة الثلاثية، (4) تحترق مع الأكسجين مطلقة حرارة كبيرة. ومن استعمالات الإيثاين (الأسيتيلين): لحام الفلزات بمشاعل الأسيتيلين، ومادة أولية في صناعة البلاستيك وغيره من المواد الكيميائية العضوية.', '["خاصية أولى صحيحة","خاصية ثانية صحيحة","خاصية ثالثة صحيحة","لحام الفلزات","مادة أولية في صناعة البلاستيك والمواد العضوية"]'::jsonb, '[]'::jsonb, '[{"element":"الخواص الثلاث (درجة لكل خاصية)","marks":3},{"element":"الاستعمالان (درجة لكل استعمال)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ثلاث خواص صحيحة واستعمالان صحيحان"},{"level":"3–4 درجات","description":"نقص خاصية أو استعمال"},{"level":"1–2 درجة","description":"خاصية أو استعمال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر إنضاج الفاكهة استعمالًا للإيثاين (وهو للإيثين)","وصف الألكاينات بأنها قطبية أو تذوب في الماء","القول إن الألكاينات أقل نشاطًا من الألكينات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂ (الكالسيوم 1 = 1، الكربون 2 = 2، الهيدروجين 4 = 2 + 2، الأكسجين 2 = 2). (ب) 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O. (ج) عندما يُزوَّد الإيثاين بكمية كافية من الأكسجين يحترق بسرعة منتجًا لهبًا ذا حرارة عالية جدًّا قد تصل إلى 3000 °C، وهي حرارة تكفي لصهر الفلزات ووصلها، لذا تُستعمل مشاعل الأسيتيلين في اللحام.', '["CaC₂ + 2H₂O → C₂H₂ + Ca(OH)₂","2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O","الاحتراق مع كمية كافية من الأكسجين ينتج لهبًا حرارته قد تصل إلى 3000 °C","هذه الحرارة تكفي لصهر الفلزات ولحامها"]'::jsonb, '["(أ) موازنة الهيدروجين والأكسجين: يلزم جزيئا ماء لتكوين C₂H₂ وCa(OH)₂","(ب) موازنة الكربون: 2C₂H₂ → 4CO₂، والهيدروجين: 4 ذرات → 2H₂O، والأكسجين: 8 + 2 = 10 ذرات → 5O₂"]'::jsonb, '[{"element":"معادلة التحضير الموزونة","marks":2},{"element":"معادلة الاحتراق الموزونة","marks":2},{"element":"تفسير الاستعمال في اللحام","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المعادلتان موزونتان والتفسير كامل"},{"level":"4–5 درجات","description":"معادلتان صحيحتان مع تفسير ناقص، أو خطأ في موازنة إحداهما"},{"level":"1–3 درجات","description":"معادلة واحدة صحيحة أو تفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة جزيء ماء واحد في معادلة التحضير","كتابة C₂H₂ + O₂ → CO₂ + H₂O دون موازنة","تفسير اللحام بأن الإيثاين يذيب الفلزات كيميائيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الإيثين CH₂=CH₂: رابطة ثنائية، اسمه الشائع الإيثيلين، تنتجه النباتات طبيعيًّا، ويُستعمل في إنضاج الفاكهة صناعيًّا ومادة أولية لصناعة البولي إيثيلين. الإيثاين CH≡CH: رابطة ثلاثية، اسمه الشائع الأسيتيلين، يُنتج ناتجًا ثانويًّا عن تنقية البترول ومن تفاعل كربيد الكالسيوم CaC₂ مع الماء، ويُستعمل في لحام الفلزات ومادة أولية لصناعة البلاستيك والمواد العضوية. الإيثاين أنشط لأن رابطته الثلاثية تشكّل كثافة إلكترونية أكبر من الرابطة الثنائية، وهذا التجمع من الإلكترونات يحفّز تكوين أقطاب في الجزيئات المجاورة فتصبح غير متماثلة الشحنة.', '["نوع الرابطة: ثنائية / ثلاثية","الاسم الشائع: الإيثيلين / الأسيتيلين","المصدر: النباتات / تنقية البترول وتفاعل CaC₂ مع الماء","الاستعمال: إنضاج الفاكهة والبولي إيثيلين / لحام الفلزات والبلاستيك","تفسير النشاط بالكثافة الإلكترونية الأكبر للرابطة الثلاثية"]'::jsonb, '[]'::jsonb, '[{"element":"نوع الرابطة","marks":1},{"element":"الاسم الشائع","marks":1},{"element":"المصدر","marks":1},{"element":"الاستعمال","marks":1},{"element":"تفسير النشاط","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"المقارنة كاملة مع تفسير صحيح"},{"level":"4–5 درجات","description":"مقارنة كاملة دون تفسير دقيق، أو نقص بند واحد"},{"level":"1–3 درجات","description":"بند أو بندان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الاسمين الشائعين الإيثيلين والأسيتيلين","نسبة إنضاج الفاكهة إلى الإيثاين","تفسير النشاط بقلة عدد ذرات الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb)
