('mcq', 6, 'أيّ المركبين أكثر نشاطًا كيميائيًّا: 2-بيوتين CH₃CH=CHCH₃ أم 2-بيوتاين CH₃C≡CCH₃؟ وما السبب؟', null, null, '["2-بيوتاين؛ لأن الكثافة الإلكترونية لرابطته الثلاثية أكبر","2-بيوتين؛ لأنه يحتوي على عدد أكبر من ذرات الهيدروجين","2-بيوتاين؛ لأنه يحتوي على عدد أكبر من ذرات الهيدروجين","متساويان؛ لأن لهما عدد ذرات الكربون نفسه"]'::jsonb, 'فهم', 'مقارنة مع التعليل', 'متوسط', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('mcq', 7, 'قال طالب: «الألكاينات أقل نشاطًا من الألكينات؛ لأن عدد ذرات الهيدروجين فيها أقل». ما الحكم الصحيح على قوله؟', null, null, '["قوله صحيح؛ فقلة ذرات الهيدروجين تقلل مواقع التفاعل","قوله صحيح؛ لأن الرابطة الثلاثية أكثر ثباتًا من الثنائية","قوله خاطئ؛ فالألكاينات والألكينات متساوية في النشاط","قوله خاطئ؛ فالألكاينات أنشط لأن رابطتها الثلاثية أكبر كثافة إلكترونية"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 141 — خصائص الألكاينات واستعمالاتها'),
('essay', 1, 'تمثل الصيغ الآتية ثلاثة مركبات في كل منها ثلاث ذرات كربون. حدّد نوع الرابطة بين ذرتي الكربون الأولى والثانية في كل منها، وعدد روابط باي فيها، ثم رتّب المركبات حسب تزايد نشاطها الكيميائي.', null, '[{"src":"qimg/chem22/c4-l3b-c3-three.svg","alt":"ثلاث صيغ بنائية مكثفة لمركبات في كل منها ثلاث ذرات كربون. (أ): CH₃–CH₂–CH₃ وكل الروابط بين ذرات الكربون أحادية. (ب): CH₂=CH–CH₃ وفيها رابطة ثنائية بين ذرتي الكربون الأولى والثانية. (ج): CH≡C–CH₃ وفيها رابطة ثلاثية بين ذرتي الكربون الأولى والثانية."}]'::jsonb, null, 'فهم', 'تحليل صيغ ومقارنة', 'سهل', 'الكتاب ص 139–141'),
('essay', 2, 'فسّر: (أ) الألكينات أكثر نشاطًا كيميائيًّا من الألكانات. (ب) الألكاينات أكثر نشاطًا من الألكينات عمومًا.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 139، 141'),
('essay', 3, 'ثلاثة أنابيب متماثلة في الأول هكسان C₆H₁₄، وفي الثاني 1-هكسين C₆H₁₂، وفي الثالث 1-هكساين C₆H₁₀. أُضيفت إلى كل منها الكمية نفسها من مادة تتفاعل بجذب الإلكترونات. (أ) توقّع ترتيب المركبات حسب سرعة تفاعلها مع هذه المادة، وفسّر توقعك. (ب) اعتمادًا على طبيعة روابط الإيثاين، فسّر لماذا يتفاعل بسرعة عالية مع الأكسجين.', null, null, null, 'تحليل', 'توقع وتفسير', 'صعب', 'الكتاب ص 139–141 (ماذا قرأت ص 140)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
