insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تحتوي الألكانات على روابط أحادية فقط، فهي أقل نشاطًا من الألكينات والألكاينات التي تحتوي على روابط متعددة ذات كثافة إلكترونية كبيرة.', '["الألكاينات أنشط الأنواع الثلاثة لاحتوائها على رابطة ثلاثية.","الألكينات أنشط من الألكانات بسبب الرابطة الثنائية.","","الدايينات ألكينات فيها رابطتان ثنائيتان، فهي أنشط من الألكانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('mcq', 2, 0, '(أ) إيثان بروابط أحادية فهو الأقل نشاطًا، و(ب) إيثين برابطة ثنائية تزيد الكثافة الإلكترونية فهو أنشط، و(ج) إيثاين برابطة ثلاثية كثافتها الإلكترونية أكبر فهو الأنشط: (أ) < (ب) < (ج).', '["","هذا ترتيب تناقص النشاط لا تزايده.","الإيثين (ب) أنشط من الإيثان (أ) لا أقل.","الإيثاين (ج) أنشط من الإيثين (ب) لأن كثافة رابطته الثلاثية الإلكترونية أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('mcq', 3, 3, 'الرابطة الثنائية المشتركة تزيد الكثافة الإلكترونية بين ذرتي الكربون، فتكون موقعًا جيدًا للنشاط الكيميائي، وتستطيع المواد المتفاعلة جذب إلكترونات الرابطة باي بعيدًا عن الرابطة الثنائية.', '["روابط C–H موجودة في الألكانات أيضًا، وهي ليست مصدر النشاط الزائد للألكينات.","موقع النشاط يحدده موقع الرابطة الثنائية لا طرف السلسلة.","الكثافة الإلكترونية تتركز في الرابطة الثنائية، فالنشاط لا يتوزع بالتساوي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.605Z"}'::jsonb),
('mcq', 4, 1, 'الرابطة الأحادية في الإيثان رابطة سيجما فقط (صفر باي)، والثنائية في الإيثين سيجما وباي (1)، والثلاثية في الإيثاين سيجما ورابطتا باي (2). وتزايد روابط باي يرافقه تزايد الكثافة الإلكترونية والنشاط.', '["هذا عدد الروابط الكلي (سيجما وباي) بين ذرتي الكربون، لا عدد روابط باي.","","هذا عدد أزواج الإلكترونات في الرابطتين الثنائية والثلاثية، وأحد الأزواج يكوّن رابطة سيجما لا باي.","هذا الترتيب معكوس؛ فالإيثان ليس فيه رابطة باي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('mcq', 5, 2, 'تجمع الإلكترونات في الرابطة الثلاثية فعّال في تحفيز تكوين الأقطاب في الجزيئات المجاورة، مما يجعلها غير متماثلة الشحنة، فتكون الألكاينات أكثر نشاطًا.', '["تجمع الإلكترونات يجذب المواد المتفاعلة ويتفاعل معها، لا يمنعها من الاقتراب.","الألكاينات مركبات غير قطبية؛ فالتأثير في الجزيئات المجاورة لا في قطبية الألكاين نفسه.","","الرابطة الثلاثية لا تنكسر تلقائيًّا إلى ذرات حرة؛ والنشاط ناتج عن تحفيز الأقطاب في الجزيئات المجاورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('mcq', 6, 0, 'الألكاينات أنشط من الألكينات عمومًا؛ لأن الرابطة الثلاثية تشكّل كثافة إلكترونية أكبر من الرابطة الثنائية، فـ 2-بيوتاين أنشط.', '["","عدد ذرات الهيدروجين ليس سبب النشاط، والألكين أقل نشاطًا من الألكاين.","المركب صحيح لكن السبب خاطئ: 2-بيوتاين (C₄H₆) فيه ذرات هيدروجين أقل من 2-بيوتين (C₄H₈).","تساوي عدد ذرات الكربون لا يعني تساوي النشاط؛ فنوع الرابطة المتعددة هو المؤثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('mcq', 7, 3, 'الألكاينات أكثر نشاطًا من الألكينات عمومًا، والسبب أن الرابطة الثلاثية تشكّل كثافة إلكترونية أكبر من الرابطة الثنائية؛ فالقول خاطئ في الحكم وفي التعليل.', '["موقع النشاط هو الرابطة المتعددة لا ذرات الهيدروجين، والألكاينات أنشط.","الكثافة الإلكترونية الأكبر للرابطة الثلاثية تجعل الألكاينات أنشط لا أقل نشاطًا.","الألكاينات أنشط من الألكينات عمومًا، فليستا متساويتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) البروبان: رابطة أحادية، صفر رابطة باي. (ب) البروبين: رابطة ثنائية، رابطة باي واحدة. (ج) البروباين: رابطة ثلاثية، رابطتا باي. ترتيب تزايد النشاط: (أ) < (ب) < (ج)؛ لأن الكثافة الإلكترونية بين ذرتي الكربون تزداد من الرابطة الأحادية إلى الثنائية إلى الثلاثية.', '["(أ) أحادية، صفر باي","(ب) ثنائية، باي واحدة","(ج) ثلاثية، رابطتا باي","الترتيب (أ) < (ب) < (ج)"]'::jsonb, '[]'::jsonb, '[{"element":"المركب (أ)","marks":1},{"element":"المركب (ب)","marks":1},{"element":"المركب (ج)","marks":1},{"element":"ترتيب النشاط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ رابطة باي في الرابطة الأحادية","عدّ ثلاث روابط باي في الرابطة الثلاثية","عكس ترتيب النشاط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تحتوي الألكانات على روابط أحادية فقط، أما الألكينات فالرابطة الثنائية المشتركة فيها تزيد الكثافة الإلكترونية بين ذرتي الكربون، فتكون موقعًا جيدًا للنشاط الكيميائي، وتستطيع المواد المتفاعلة جذب إلكترونات الرابطة باي بعيدًا عن الرابطة الثنائية. (ب) الرابطة الثلاثية في الألكاينات تشكّل كثافة إلكترونية أكبر مما في الرابطة الثنائية، وهذا التجمع من الإلكترونات فعّال في تحفيز تكوين الأقطاب في الجزيئات المجاورة، فيجعلها غير متماثلة الشحنة، فتكون الألكاينات أكثر نشاطًا.', '["الرابطة الثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون","المواد المتفاعلة تجذب إلكترونات الرابطة باي","الرابطة الثلاثية كثافتها الإلكترونية أكبر","تحفيز تكوين الأقطاب في الجزيئات المجاورة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير (أ)","marks":2},{"element":"تفسير (ب)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير النشاط بعدد ذرات الهيدروجين","القول إن الرابطة الثنائية أقوى فتكون أنشط دون ذكر الكثافة الإلكترونية","الخلط بين الألكاينات والألكانات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.606Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الترتيب من الأسرع إلى الأبطأ: 1-هكساين ثم 1-هكسين ثم الهكسان. التفسير: الهكسان فيه روابط أحادية فقط فهو الأقل نشاطًا، و1-هكسين فيه رابطة ثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون فتجذب المادة المتفاعلة إلكترونات الرابطة باي، و1-هكساين فيه رابطة ثلاثية (رابطتا باي) كثافتها الإلكترونية أكبر فهو الأنشط. (ب) في الإيثاين رابطة ثلاثية من سيجما ورابطتي باي، تشكّل تجمعًا كبيرًا من الإلكترونات بين ذرتي الكربون، فيكون الجزيء نشطًا جدًّا ويتفاعل بسرعة مع الأكسجين محررًا حرارة كبيرة.', '["الترتيب: 1-هكساين > 1-هكسين > هكسان","ربط النشاط بنوع الرابطة والكثافة الإلكترونية","الرابطة الثلاثية في الإيثاين: سيجما ورابطتا باي","الكثافة الإلكترونية الكبيرة تجعل تفاعله مع الأكسجين سريعًا"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":1},{"element":"تفسير الترتيب","marks":2},{"element":"تفسير سرعة تفاعل الإيثاين مع الأكسجين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"ترتيب صحيح وتفسيران كاملان"},{"level":"3–4 درجات","description":"ترتيب صحيح مع تفسير ناقص لأحد الجزأين"},{"level":"1–2 درجة","description":"ترتيب صحيح فقط أو تفسير جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب بحجة أن الهكسان فيه هيدروجين أكثر","الاكتفاء بالقول «لأنه غير مشبع» دون ذكر الكثافة الإلكترونية","نسبة سرعة احتراق الإيثاين إلى صغر كتلته فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
