select (select id from public.objectives where code = 'K22-C4-L3-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ألكاين ذو سلسلة مفتوحة يحتوي على 14 ذرة هيدروجين ورابطة ثلاثية واحدة. كم ذرة كربون فيه؟', null, null, '["6 ذرات","7 ذرات","8 ذرات","16 ذرة"]'::jsonb, 'تطبيق', 'استعمال الصيغة العامة عكسيًّا', 'سهل', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('mcq', 2, 'ما الصيغة الجزيئية لألكين ذي سلسلة مفتوحة يحتوي على رابطة ثنائية واحدة و16 ذرة هيدروجين؟', null, null, '["C₁₆H₃₂","C₈H₁₆","C₇H₁₆","C₉H₁₆"]'::jsonb, 'تطبيق', 'استعمال الصيغة العامة عكسيًّا', 'سهل', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('mcq', 3, 'أيّ الأزواج الآتية يمثل على الترتيب ألكينًا برابطة ثنائية واحدة وألكاينًا برابطة ثلاثية واحدة لهما عدد ذرات الكربون نفسه؟', null, null, '["C₉H₂₀ و C₉H₁₈","C₉H₁₆ و C₉H₁₈","C₉H₁₈ و C₉H₁₄","C₉H₁₈ و C₉H₁₆"]'::jsonb, 'تطبيق', 'تطبيق الصيغتين العامتين', 'متوسط', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('mcq', 4, 'ما الصيغة الجزيئية للمركب الممثل بالصيغة الآتية؟', null, '[{"src":"qimg/chem22/c4-l3b-3m1hexyne.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH≡C–CH–CH₂–CH₂–CH₃، والرابطة الثلاثية بين المجموعة الأولى (CH) والثانية (C)، وتتفرع من المجموعة الثالثة (CH) مجموعة CH₃ إلى الأعلى."}]'::jsonb, '["C₇H₁₂","C₆H₁₀","C₇H₁₄","C₇H₁₆"]'::jsonb, 'تطبيق', 'صيغة جزيئية من صيغة بنائية', 'متوسط', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('mcq', 5, 'هيدروكربون ذو سلسلة مفتوحة يحتوي على رابطة ثلاثية واحدة، وكتلته المولية 54.09 g/mol. ما صيغته الجزيئية؟ (C = 12.01، H = 1.008)', null, null, '["C₄H₁₀","C₄H₈","C₅H₈","C₄H₆"]'::jsonb, 'تطبيق', 'الصيغة العامة والكتلة المولية', 'صعب', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات؛ الجدول الدوري'),
('mcq', 6, 'ألكان وألكاين برابطة ثلاثية واحدة لهما عدد ذرات الكربون نفسه. بكم يقل عدد ذرات الهيدروجين في الألكاين عنه في الألكان؟', null, null, '["ذرتان","4 ذرات","6 ذرات","ذرة واحدة"]'::jsonb, 'فهم', 'مقارنة الصيغ العامة', 'متوسط', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات؛ ص 162 س78'),
('mcq', 7, 'هيدروكربون ذو سلسلة مفتوحة غير متفرعة صيغته الجزيئية C₇H₁₂، ويحتوي على رابطة متعددة واحدة فقط. ما نوع هذه الرابطة؟', null, null, '["رابطة ثلاثية بين ذرتي كربون","رابطة ثنائية بين ذرتي كربون","روابط أحادية فقط بين ذرات الكربون","لا يمكن تحديدها من الصيغة الجزيئية"]'::jsonb, 'تحليل', 'استنتاج نوع الرابطة', 'صعب', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('essay', 1, 'استعمل الصيغتين العامتين للألكينات والألكاينات (برابطة متعددة واحدة) لإكمال الجدول الآتي بالصيغ الجزيئية.', '{"headers":["عدد ذرات الكربون (n)","الألكين (رابطة ثنائية واحدة)","الألكاين (رابطة ثلاثية واحدة)"],"rows":[["3","؟","؟"],["5","؟","؟"],["8","؟","؟"]]}'::jsonb, null, null, 'تطبيق', 'إكمال جدول', 'سهل', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات'),
('essay', 2, 'هيدروكربون ذو سلسلة مفتوحة يحتوي على رابطة ثلاثية واحدة، وكتلته المولية 82.14 g/mol. (أ) استعمل الصيغة العامة لإيجاد صيغته الجزيئية، موضحًا خطوات الحل. (ب) اكتب الصيغة البنائية المكثفة لأحد تراكيبه غير المتفرعة الممكنة واسمه. (C = 12.01، H = 1.008)', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات؛ الجدول الدوري'),
('essay', 3, 'ألكين برابطة ثنائية واحدة وألكاين برابطة ثلاثية واحدة، كلاهما ذو سلسلة مفتوحة، ويحتوي كل منهما على 10 ذرات هيدروجين. (أ) استعمل الصيغتين العامتين لإيجاد الصيغة الجزيئية لكل منهما، موضحًا خطوات الحل. (ب) أيهما يحتوي على عدد أكبر من ذرات الكربون؟ فسّر ذلك. (ج) استنتج قاعدة عامة: إذا تساوى عدد ذرات الهيدروجين في ألكين وألكاين، فبكم يزيد عدد ذرات الكربون في الألكاين؟', null, null, null, 'تحليل', 'تفسير وتطبيق', 'متوسط', 'الكتاب ص 136، 140 — الصيغتان العامتان للألكينات والألكاينات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الصيغة العامة للألكاينات CₙH₂ₙ₋₂، فعدد ذرات الهيدروجين 2n − 2 = 14، ومنه 2n = 16، أي n = 8 ذرات كربون (C₈H₁₄).', '["استُعملت صيغة الألكانات: 2n + 2 = 14 فكانت n = 6.","استُعملت صيغة الألكينات: 2n = 14 فكانت n = 7.","","هذه قيمة 2n، ولم تُقسم على 2 لإيجاد n."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb),
('mcq', 2, 1, 'الصيغة العامة للألكينات CₙH₂ₙ، فعدد ذرات الهيدروجين 2n = 16، ومنه n = 8، والصيغة C₈H₁₆.', '["عُدّ عدد ذرات الهيدروجين 16 عددًا لذرات الكربون.","","استُعملت صيغة الألكانات: 2n + 2 = 16 فكانت n = 7.","استُعملت صيغة الألكاينات: 2n − 2 = 16 فكانت n = 9."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb),
('mcq', 3, 3, 'عند n = 9: الألكين CₙH₂ₙ صيغته C₉H₁₈، والألكاين CₙH₂ₙ₋₂ صيغته C₉H₁₆ (2 × 9 − 2 = 16).', '["C₉H₂₀ ألكان (CₙH₂ₙ₊₂)، وC₉H₁₈ ألكين لا ألكاين.","الصيغتان صحيحتان لكن بترتيب معكوس: C₉H₁₆ للألكاين وC₉H₁₈ للألكين.","الألكين صحيح، لكن الألكاين ينقص ذرتي هيدروجين فقط عن الألكين: C₉H₁₆ لا C₉H₁₄.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb),
('mcq', 4, 0, 'عدد ذرات الكربون: ست في السلسلة وواحدة في مجموعة الميثيل، أي 7. وفيه رابطة ثلاثية واحدة، فبتطبيق CₙH₂ₙ₋₂: 2 × 7 − 2 = 12، والصيغة C₇H₁₂. (والعدّ المباشر: 1 + 0 + 1 + 2 + 2 + 3 + 3 = 12 ذرة هيدروجين.)', '["","أُهملت ذرة كربون مجموعة الميثيل وهيدروجينها.","استُعملت صيغة الألكينات CₙH₂ₙ مع أن الرابطة ثلاثية.","استُعملت صيغة الألكانات CₙH₂ₙ₊₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb),
('mcq', 5, 3, 'الصيغة CₙH₂ₙ₋₂ فالكتلة المولية = 12.01n + 1.008(2n − 2) = 14.026n − 2.016 = 54.09، ومنه n = 4، والصيغة C₄H₆ (4 × 12.01 + 6 × 1.008 = 54.09 g/mol).', '["C₄H₁₀ ألكان كتلته المولية 58.12 g/mol.","C₄H₈ ألكين كتلته المولية 56.10 g/mol.","C₅H₈ ألكاين فعلًا لكن كتلته المولية 68.11 g/mol.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.607Z"}'::jsonb),
('mcq', 6, 1, 'الألكان CₙH₂ₙ₊₂ والألكاين CₙH₂ₙ₋₂، والفرق (2n + 2) − (2n − 2) = 4 ذرات هيدروجين.', '["هذا الفرق بين الألكان والألكين، أو بين الألكين والألكاين.","","الفرق 4 ذرات فقط؛ فكل زوج إلكترونات إضافي بين ذرتي الكربون ينقص ذرتين، والرابطة الثلاثية فيها زوجان إضافيان.","عدد ذرات الهيدروجين في السلاسل المفتوحة زوجي دائمًا، والفرق 4 ذرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb),
('mcq', 7, 0, 'عند n = 7: الألكين C₇H₁₄ والألكاين C₇H₁₂ والألكان C₇H₁₆. الصيغة C₇H₁₂ تتفق مع CₙH₂ₙ₋₂ (2 × 7 − 2 = 12)، ولأن فيه رابطة متعددة واحدة فقط فهي رابطة ثلاثية.', '["","لو كانت ثنائية لكانت الصيغة C₇H₁₄ (CₙH₂ₙ).","لو كانت روابطه أحادية فقط لكانت الصيغة C₇H₁₆ (CₙH₂ₙ₊₂).","معلومة «سلسلة مفتوحة برابطة متعددة واحدة» مع الصيغة تكفي لتحديد نوع الرابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند n = 3: الألكين C₃H₆ والألكاين C₃H₄. عند n = 5: الألكين C₅H₁₀ والألكاين C₅H₈. عند n = 8: الألكين C₈H₁₆ والألكاين C₈H₁₄.', '["C₃H₆","C₃H₄","C₅H₁₀","C₅H₈","C₈H₁₆","C₈H₁₄"]'::jsonb, '["الألكين: عدد H = 2n ← 6، 10، 16","الألكاين: عدد H = 2n − 2 ← 4، 8، 14"]'::jsonb, '[{"element":"C₃H₆","marks":1},{"element":"C₃H₄","marks":1},{"element":"C₅H₁₀","marks":1},{"element":"C₅H₈","marks":1},{"element":"C₈H₁₆","marks":1},{"element":"C₈H₁₄","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"الصيغ الست صحيحة"},{"level":"3–5 درجات","description":"عمود واحد صحيح كاملًا أو أخطاء قليلة"},{"level":"1–2 درجة","description":"صيغة أو صيغتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل الصيغتين العامتين","كتابة الألكاين بطرح 4 ذرات من 2n","استعمال صيغة الألكانات للألكين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الصيغة العامة CₙH₂ₙ₋₂، فالكتلة المولية = 12.01n + 1.008(2n − 2) = 14.026n − 2.016. بمساواتها بـ 82.14: 14.026n = 84.156، ومنه n = 6.000 ≈ 6. الصيغة الجزيئية C₆H₁₀ (التحقق: 6 × 12.01 + 10 × 1.008 = 82.14 g/mol). (ب) مثلًا 1-هكساين CH≡CCH₂CH₂CH₂CH₃ (أو 2-هكساين CH₃C≡CCH₂CH₂CH₃ أو 3-هكساين CH₃CH₂C≡CCH₂CH₃).', '["كتابة الكتلة المولية بدلالة n","إيجاد n = 6","الصيغة C₆H₁₀ مع التحقق","صيغة مكثفة غير متفرعة صحيحة مع اسمها"]'::jsonb, '["M = 12.01n + 1.008(2n − 2) = 14.026n − 2.016","14.026n − 2.016 = 82.14 ← 14.026n = 84.156 ← n = 6","الصيغة C₆H₁₀ ، التحقق: 72.06 + 10.08 = 82.14 g/mol","تركيب ممكن: CH≡CCH₂CH₂CH₂CH₃ (1-هكساين)"]'::jsonb, '[{"element":"معادلة الكتلة المولية بدلالة n","marks":1},{"element":"حساب n","marks":1},{"element":"الصيغة الجزيئية","marks":1},{"element":"الصيغة المكثفة والاسم","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حل كامل صحيح وصيغة مكثفة صحيحة باسمها"},{"level":"3–4 درجات","description":"الصيغة الجزيئية صحيحة مع نقص في الخطوات أو في الجزء (ب)"},{"level":"1–2 درجة","description":"خطوة صحيحة واحدة أو تخمين الصيغة دون حل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال CₙH₂ₙ فلا يخرج n عددًا صحيحًا","إهمال ذرات الهيدروجين عند حساب الكتلة المولية","كتابة صيغة مكثفة فيها هيدروجين على ذرتي الرابطة الثلاثية الداخلية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الألكين CₙH₂ₙ: 2n = 10 ومنه n = 5، فالصيغة C₅H₁₀. الألكاين CₙH₂ₙ₋₂: 2n − 2 = 10 ومنه 2n = 12 وn = 6، فالصيغة C₆H₁₀. (ب) الألكاين يحتوي على ذرات كربون أكثر (6 مقابل 5)؛ لأن الرابطة الثلاثية تُنقص ذرتي هيدروجين أكثر مما تُنقصه الرابطة الثنائية في مركب له عدد ذرات الكربون نفسه، فلكي يصل الألكاين إلى العدد نفسه من ذرات الهيدروجين يلزمه ذرة كربون إضافية تُضيف ذرتي هيدروجين. (ج) يزيد بذرة كربون واحدة: إذا كان عدد ذرات الهيدروجين h فإن n للألكين = h ÷ 2، وn للألكاين = (h + 2) ÷ 2 = h ÷ 2 + 1.', '["C₅H₁₀ للألكين مع الخطوات","C₆H₁₀ للألكاين مع الخطوات","الألكاين أكثر ذرات كربون مع التفسير","القاعدة: يزيد الألكاين بذرة كربون واحدة"]'::jsonb, '["الألكين: 2n = 10 ← n = 5 ← C₅H₁₀","الألكاين: 2n − 2 = 10 ← n = 6 ← C₆H₁₀","التعميم: n(ألكاين) − n(ألكين) = (h + 2) ÷ 2 − h ÷ 2 = 1"]'::jsonb, '[{"element":"الصيغة الجزيئية للألكين","marks":1},{"element":"الصيغة الجزيئية للألكاين","marks":1},{"element":"المقارنة والتفسير","marks":2},{"element":"القاعدة العامة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الصيغتان صحيحتان مع الخطوات، وتفسير صحيح، وقاعدة صحيحة"},{"level":"3–4 درجات","description":"الصيغتان صحيحتان مع تفسير أو قاعدة ناقصة"},{"level":"1–2 درجة","description":"صيغة واحدة صحيحة أو الصيغتان دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال صيغة الألكانات فيكون n = 4","كتابة C₄H₁₀ للألكاين بطرح ذرتين من عدد الكربون بدل الهيدروجين","القول إن المركبين لهما عدد ذرات الكربون نفسه لتساوي الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O10') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L3-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تحتوي السلسلة الكربونية المستقيمة في الصيغة الآتية على رابطتين ثنائيتين غير متجاورتين. ما اسمها وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3b-14hexadiene.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₃–CH=CH–CH₂–CH=CH₂؛ سلسلة مستقيمة من ست ذرات كربون فيها رابطتان ثنائيتان: الأولى بين المجموعتين الثانية والثالثة من اليسار، والثانية بين المجموعتين الخامسة والسادسة من اليسار (عند الطرف الأيمن)."}]'::jsonb, '["2، 5-هكسادايين","1، 4-هكسين","1، 4-هكسادايين","1، 4-هكساترايين"]'::jsonb, 'تطبيق', 'تسمية من الصيغة', 'سهل', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('mcq', 2, 'ماذا يدل المقطع «دايين» في اسم المركب 2، 4-هبتادايين؟', null, null, '["احتواء السلسلة على رابطتين ثلاثيتين","احتواء السلسلة على رابطتين ثنائيتين","ارتباط مجموعتي ميثيل بالسلسلة","وجود سلسلتين رئيستين في الجزيء"]'::jsonb, 'فهم', 'دلالة البادئة', 'سهل', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('mcq', 3, 'ما اسم الهيدروكربون الممثل بالصيغة الآتية، وفيه ثلاث روابط ثنائية تتناوب مع روابط أحادية؟', null, '[{"src":"qimg/chem22/c4-l3b-135hexatriene.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₂=CH–CH=CH–CH=CH₂؛ سلسلة مستقيمة من ست ذرات كربون فيها ثلاث روابط ثنائية: بين المجموعتين الأولى والثانية، وبين الثالثة والرابعة، وبين الخامسة والسادسة، وبينها روابط أحادية."}]'::jsonb, '["2، 4، 6-هكساترايين","1، 3، 5-هكسادايين","1، 3، 5-هكسين","1، 3، 5-هكساترايين"]'::jsonb, 'تطبيق', 'تسمية من الصيغة', 'متوسط', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('mcq', 4, 'سلسلة من ثماني ذرات كربون فيها رابطتان ثنائيتان كما في الصيغة الآتية. ما اسمها النظامي الصحيح وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3b-25octadiene.svg","alt":"صيغة بنائية مكثفة من اليسار إلى اليمين: CH₃–CH₂–CH=CH–CH₂–CH=CH–CH₃؛ سلسلة مستقيمة من ثماني ذرات كربون فيها رابطتان ثنائيتان: الأولى بين المجموعتين الثالثة والرابعة من اليسار، والثانية بين المجموعتين السادسة والسابعة من اليسار."}]'::jsonb, '["2، 5-أوكتادايين","3، 6-أوكتادايين","2، 5-أوكتين","2، 5-هبتادايين"]'::jsonb, 'تطبيق', 'تسمية من الصيغة', 'متوسط', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('mcq', 5, 'يحتوي المركب الآتي على رابطتين ثنائيتين تفصل بينهما رابطة أحادية، وعلى مجموعة ميثيل. ما اسمه الصحيح وفق قواعد الأيوباك؟', null, '[{"src":"qimg/chem22/c4-l3b-4m13pentadiene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–C=CH–CH=CH₂، فيها رابطتان ثنائيتان: بين المجموعتين الثانية (C) والثالثة (CH)، وبين المجموعتين الرابعة (CH) والخامسة (CH₂). وتتفرع من المجموعة الثانية (C) مجموعة CH₃ إلى الأعلى."}]'::jsonb, '["2-ميثيل-2، 4-بنتادايين","4-ميثيل-1، 3-بنتين","4-ميثيل-1، 3-بنتادايين","4-ميثيل-1، 3-بيوتادايين"]'::jsonb, 'تطبيق', 'تسمية دايين متفرع', 'صعب', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)؛ ص 142 س22'),
('mcq', 6, 'أيّ الأسماء الآتية مكتوب كتابة صحيحة لمركب سلسلته أربع ذرات كربون وفيه رابطتان ثنائيتان؟', null, null, '["1، 3-بيوتين","1، 3-بيوتادايين","1-بيوتادايين","1، 2، 3-بيوتادايين"]'::jsonb, 'فهم', 'صحة كتابة الاسم', 'متوسط', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('mcq', 7, 'تتفرع من السلسلة الرئيسة في المركب الآتي مجموعتا ميثيل، وفيها رابطتان ثنائيتان. كيف يُسمّى وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c4-l3b-25dm14hexadiene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₂=C–CH₂–CH=C–CH₃، فيها رابطتان ثنائيتان: بين المجموعتين الأولى (CH₂) والثانية (C)، وبين المجموعتين الرابعة (CH) والخامسة (C). وتتفرع مجموعة CH₃ إلى الأسفل من المجموعة الثانية (C)، ومجموعة CH₃ أخرى إلى الأسفل من المجموعة الخامسة (C)."}]'::jsonb, '["2، 5-ثنائي ميثيل-2، 5-هكسادايين","2، 5-ميثيل-1، 4-هكسادايين","2، 5-ثنائي ميثيل-1، 4-هكسين","2، 5-ثنائي ميثيل-1، 4-هكسادايين"]'::jsonb, 'تطبيق', 'تسمية دايين متفرع', 'صعب', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('essay', 1, 'سمِّ المركب الممثل بالصيغة الآتية وفق نظام IUPAC، موضحًا خطوات التسمية.', null, '[{"src":"qimg/chem22/c4-l3b-3m13pentadiene.svg","alt":"صيغة بنائية مكثفة متفرعة. السلسلة الأفقية من اليسار إلى اليمين: CH₃–CH=C–CH=CH₂، فيها رابطتان ثنائيتان: بين المجموعتين الثانية (CH) والثالثة (C)، وبين المجموعتين الرابعة (CH) والخامسة (CH₂). وتتفرع من المجموعة الثالثة (C) مجموعة CH₃ إلى الأسفل."}]'::jsonb, null, 'تطبيق', 'تسمية بخطوات', 'متوسط', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('essay', 2, 'سمِّ المركبين (أ) و(ب) الممثلين بالصيغتين الآتيتين وفق نظام IUPAC، وبيّن في كل منهما عدد الروابط الثنائية والبادئة المستعملة.', null, '[{"src":"qimg/chem22/c4-l3b-two-polyenes.svg","alt":"صيغتان بنائيتان مكثفتان لسلسلتين مستقيمتين. (أ): من اليسار إلى اليمين CH₂=CH–CH=CH–CH=CH–CH₃؛ سبع ذرات كربون فيها ثلاث روابط ثنائية: بين المجموعتين الأولى والثانية، وبين الثالثة والرابعة، وبين الخامسة والسادسة. (ب): من اليسار إلى اليمين CH₂=CH–CH₂–CH₂–CH=CH₂؛ ست ذرات كربون فيها رابطتان ثنائيتان: بين المجموعتين الأولى والثانية، وبين الخامسة والسادسة، وبينهما مجموعتا CH₂."}]'::jsonb, null, 'تطبيق', 'تسمية مركبين', 'سهل', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)'),
('essay', 3, 'قوّم كلًّا من الأسماء الآتية: هل هو صحيح؟ إن لم يكن صحيحًا فبيّن سبب الخطأ واكتب الاسم الصحيح: (أ) 3، 5-هكسادايين، (ب) 1، 3-بنتين، (ج) 2، 4-هكسادايين.', null, null, null, 'تقويم', 'تقويم أسماء', 'صعب', 'الكتاب ص 137 — الألكينات ذات الروابط الثنائية المتعددة (الشكل 4-13b)؛ ص 162 س86')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O11') and x.type = v.type and x.number = v.number);
