from (values
('mcq', 1, 2, 'السلسلة ست ذرات (هكس) فيها رابطتان ثنائيتان فنستعمل «دايين». الترقيم من اليمين يعطي الرابطتين الرقمين 1 و4، ومن اليسار 2 و5؛ فنختار الأصغر: 1، 4-هكسادايين.', '["رُقّمت السلسلة من الطرف الذي يعطي مجموعة أرقام أكبر.","أُهملت البادئة «داي» مع وجود رابطتين ثنائيتين.","","البادئة «تراي» تعني ثلاث روابط ثنائية، وفي المركب رابطتان فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.608Z"}'::jsonb),
('mcq', 2, 1, 'يُظهر عدد الروابط الثنائية بإضافة بادئة (داي، تراي، …) قبل المقطع «ين»؛ فالمقطع «دايين» يدل على رابطتين ثنائيتين، موقعاهما هنا 2 و4.', '["الروابط الثلاثية يدل عليها المقطع «اين»، أما «ين» فللروابط الثنائية.","","مجموعتا الميثيل يدل عليهما «ثنائي ميثيل» قبل اسم السلسلة.","للمركب سلسلة رئيسة واحدة فقط من سبع ذرات (هبت)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('mcq', 3, 3, 'السلسلة ست ذرات فيها ثلاث روابط ثنائية تبدأ عند الذرات 1 و3 و5، فنستعمل البادئة «تراي» قبل «ين»: 1، 3، 5-هكساترايين.', '["الرابطة الثنائية الأولى تبدأ عند الذرة 1 فرقمها 1 لا 2؛ ولا توجد ذرة سابعة يُبدأ منها رقم 6.","ثلاثة أرقام مواقع تتطلب البادئة «تراي» لا «داي».","أُهملت البادئة التي تبين عدد الروابط الثنائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('mcq', 4, 0, 'السلسلة ثماني ذرات (أوكت) فيها رابطتان ثنائيتان. الترقيم من اليمين يعطيهما 2 و5، ومن اليسار 3 و6؛ فنرقّم من اليمين: 2، 5-أوكتادايين.', '["","رُقّمت السلسلة من اليسار فأعطت أرقامًا أكبر.","أُهملت البادئة «داي» مع وجود رابطتين ثنائيتين.","السلسلة ثماني ذرات كربون (أوكت) لا سبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('mcq', 5, 2, 'أطول سلسلة تحتوي على الرابطتين خمس ذرات (بنت). الترقيم من اليمين يعطي الرابطتين 1 و3، ومن اليسار 2 و4؛ فنرقّم من اليمين، فتقع مجموعة الميثيل على الذرة 4: 4-ميثيل-1، 3-بنتادايين.', '["رُقّمت السلسلة من اليسار؛ والترقيم يعطي الروابط الثنائية أصغر الأرقام قبل المجموعات البديلة.","أُهملت البادئة «داي» مع وجود رابطتين ثنائيتين.","","السلسلة الرئيسة خمس ذرات لا أربع؛ وفي سلسلة من أربع ذرات لا يمكن أن يقع ميثيل على الذرة الطرفية 4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('mcq', 6, 1, 'لكل رابطة ثنائية رقم موقع، فيلزم رقمان مع البادئة «داي» قبل «ين»: 1، 3-بيوتادايين.', '["رقمان للمواقع بلا البادئة «داي» تناقض؛ فالاسم يجب أن يبين عدد الروابط الثنائية.","","البادئة «داي» تتطلب رقمي موقعين، وهنا رقم واحد فقط.","ثلاثة أرقام مواقع لا تتفق مع «داي» التي تعني رابطتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('mcq', 7, 3, 'السلسلة الرئيسة ست ذرات فيها رابطتان ثنائيتان. الترقيم من اليسار يعطيهما 1 و4، ومن اليمين 2 و5؛ فنرقّم من اليسار، فتقع مجموعتا الميثيل على الذرتين 2 و5: 2، 5-ثنائي ميثيل-1، 4-هكسادايين.', '["رُقّمت السلسلة من اليمين فأعطت الروابط الثنائية أرقامًا أكبر (2 و5).","أُهملت البادئة «ثنائي» مع وجود مجموعتي ميثيل.","أُهملت البادئة «داي» مع وجود رابطتين ثنائيتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أطول سلسلة تحتوي على الرابطتين الثنائيتين خمس ذرات (بنت). الترقيم من اليمين يعطي الرابطتين الرقمين 1 و3، ومن اليسار 2 و4، فنرقّم من اليمين. وجود رابطتين ثنائيتين يتطلب «دايين»: 1، 3-بنتادايين. تقع مجموعة الميثيل على الذرة 3. الاسم: 3-ميثيل-1، 3-بنتادايين.', '["السلسلة الرئيسة خمس ذرات","الترقيم من اليمين: الرابطتان عند 1 و3","مجموعة الميثيل عند 3","الاسم 3-ميثيل-1، 3-بنتادايين"]'::jsonb, '["تحديد أطول سلسلة تحتوي على الرابطتين: 5 ذرات","المقارنة: من اليمين (1، 3) ومن اليسار (2، 4) ← من اليمين","المجموعة البديلة: ميثيل على الذرة 3","الاسم: 3-ميثيل-1، 3-بنتادايين"]'::jsonb, '[{"element":"السلسلة الرئيسة","marks":1},{"element":"اتجاه الترقيم ومواقع الروابط","marks":1},{"element":"موقع المجموعة البديلة","marks":1},{"element":"الاسم كاملًا بالبادئة داي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الترقيم من اليسار وكتابة 3-ميثيل-2، 4-بنتادايين","كتابة «بنتين» بدل «بنتادايين»","اختيار سلسلة تضم الميثيل وتستبعد إحدى الرابطتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) سلسلة من سبع ذرات (هبت) فيها ثلاث روابط ثنائية، فالبادئة «تراي». الترقيم من اليسار يعطي 1 و3 و5 (ومن اليمين 2 و4 و6): 1، 3، 5-هبتاترايين. (ب) سلسلة من ست ذرات (هكس) فيها رابطتان ثنائيتان، فالبادئة «داي»، والرابطتان عند 1 و5 من أي طرف: 1، 5-هكسادايين.', '["(أ) ثلاث روابط ثنائية ← تراي","(أ) 1، 3، 5-هبتاترايين","(ب) رابطتان ثنائيتان ← داي","(ب) 1، 5-هكسادايين"]'::jsonb, '[]'::jsonb, '[{"element":"عدد الروابط والبادئة في (أ)","marks":1},{"element":"اسم (أ)","marks":1},{"element":"عدد الروابط والبادئة في (ب)","marks":1},{"element":"اسم (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 2، 4، 6-هبتاترايين بالترقيم من اليمين","استعمال «داي» في (أ)","كتابة 2، 6-هكسادايين في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) خطأ: الاسم يصف سلسلة من ست ذرات فيها رابطتان ثنائيتان عند 3 و5، والترقيم من الطرف الآخر يعطيهما 1 و3، وهي أرقام أصغر؛ فالاسم الصحيح 1، 3-هكسادايين. (ب) خطأ: رقما الموقعين يدلان على رابطتين ثنائيتين، فيجب إضافة البادئة «داي»: 1، 3-بنتادايين. (ج) صحيح: السلسلة متماثلة، والترقيم من أي طرف يعطي الرابطتين 2 و4، والبادئة «داي» مستعملة: CH₃CH=CHCH=CHCH₃.', '["(أ) خاطئ لأن الترقيم لم يعطِ أصغر الأرقام","(أ) الصحيح 1، 3-هكسادايين","(ب) خاطئ لغياب البادئة داي","(ب) الصحيح 1، 3-بنتادايين","(ج) صحيح مع التبرير"]'::jsonb, '["(أ) إعادة الترقيم: 6−5 ← 1−2 ، 4−3 ← 3−4 ، فالمواقع 1 و3","(ب) رقمان ← رابطتان ← داي","(ج) الترقيم من الطرفين يعطي 2 و4"]'::jsonb, '[{"element":"الحكم على (أ) وسببه","marks":1},{"element":"تصحيح (أ)","marks":1},{"element":"الحكم على (ب) وسببه","marks":1},{"element":"تصحيح (ب)","marks":1},{"element":"الحكم على (ج) مع التبرير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأحكام الثلاثة صحيحة مع الأسباب والتصحيحات"},{"level":"4–5 درجات","description":"حكمان صحيحان مع تصحيحهما، أو الثلاثة دون تبرير كافٍ"},{"level":"1–3 درجات","description":"حكم واحد صحيح أو تصحيح دون سبب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بخطأ (ج) ظنًّا أن الترقيم يجب أن يبدأ من 1","تصحيح (أ) إلى 2، 4-هكسادايين","تصحيح (ب) إلى 1، 3-بنتاترايين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.609Z"}'::jsonb)
