select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الهرمون مادة كيميائية تُنتَج في جزء من المخلوق الحي وتُنقل إلى جزء آخر، وتؤدي إلى تغير فسيولوجي فيه؛ والإيثين تنتجه النباتات طبيعيًّا ويسبب نضج الفاكهة وتساقط الأوراق.', '["","الإيثين لا يُعرّف بأنه مادة بنائية؛ فعمله إحداث تغير فسيولوجي كالنضج.","الإيثين ليس غذاءً مخزّنًا، بل مادة تنظّم عمليات كالنضج.","الإيثين تنتجه النباتات نفسها، والغاز المستعمل في البناء الضوئي هو CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 2, 2, 'الإيثين هرمون مسؤول عن عملية النضج، والتفاح الناضج يطلقه في الصندوق المغلق فيتعرض له الموز، فيُسرع نضجه كما تنضج الفواكه صناعيًّا عند تعريضها للإيثين.', '["التفاح الناضج يُطلق الإيثين لا يمتصه، فيزيد تركيزه حول الموز.","الإيثين غاز ينتشر في الصندوق المغلق ويصل إلى الموز.","","الإيثين يُنضج الثمار ولا يتلفها فورًا؛ ولهذا يُستعمل في محلات البقالة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 3, 1, 'يُعد الإيثين، واسمه الشائع الإيثيلين، من المواد الأولية المستخدمة في تصنيع البولي إيثيلين.', '["الأسيتيلين (الإيثاين) يُستعمل في اللحام، واسم البولي إيثيلين مشتق من الإيثيلين.","","الأسيتيلين الاسم الشائع للإيثاين لا للإيثين.","الإيثان ألكان مشبع ليس له هذا الاسم الشائع، والإيثيلين هو الإيثين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 4, 3, 'يُستعمل الإيثين في إنضاج الفواكه صناعيًّا، ويُعد مادة أولية في صناعة البولي إيثيلين.', '["إنضاج الفاكهة وتساقط الأوراق دوران للإيثين لا للإيثاين؛ والإيثاين يُستعمل في اللحام.","صناعة البولي إيثيلين صحيحة للإيثين، لكن لحام الفلزات يتم بمشاعل الأسيتيلين (الإيثاين).","الهرمون المسؤول عن النضج والمادة الأولية للبولي إيثيلين هو الإيثين لا الميثان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 5, 0, 'تحتوي جزيئات الإيثين على رابطة ثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون فتجعله نشطًا كيميائيًّا، فيتفاعل لتكوين مواد جديدة كالبولي إيثيلين.', '["","الشكلان يُظهران رابطة ثنائية لا روابط أحادية فقط، والثبات الكبير لا يناسب تكوين مواد جديدة.","بين ذرتي الكربون في الشكلين خطان (رابطة ثنائية) لا ثلاثة.","الإيثين مركب غير قطبي قليل الذوبان في الماء وليس أيونيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 6, 2, 'الإيثين هرمون طبيعي مسؤول عن عملية النضج في الفواكه؛ فإذا غاب عن مكان التخزين تأخر النضج وبقيت الثمار خضراء مدة أطول.', '["دور الإيثين المذكور هو إحداث النضج لا الحماية من التلف.","غياب الإيثين يبطئ النضج لا يسرعه.","","الإيثين يُنضج الثمار فيغيّر لونها، لا يحافظ على اللون الأخضر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('mcq', 7, 1, 'الإيثين غاز تُنتجه النباتات وهو الهرمون المسؤول عن نضج الفاكهة، ويُعد أيضًا مادة أولية تُصنع منها مادة البولي إيثيلين البلاستيكية، وهي مادة جديدة خواصها مختلفة فلا تعمل عمل الهرمون. فقول الطالب خاطئ: إنضاج الفاكهة دور للإيثين نفسه، وصناعة الحقائب والحبال وعلب الحليب دور لمنتج صناعي يُصنع منه.', '["الإيثين يتحول في الصناعة إلى مادة جديدة هي البولي إيثيلين بخواص مختلفة، فالبلاستيك لا يُطلق الإيثين ولا يعمل عمل الهرمون.","","ليست كل مادة تُصنع من الألكينات هرمونًا؛ فالهرمون المسؤول عن النضج هو غاز الإيثين نفسه.","الحكم صحيح لكن السبب خاطئ: البولي إيثيلين يُصنع من الإيثين، أما الإيثاين (الأسيتيلين) فيُستعمل في لحام الفلزات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الهرمون مادة كيميائية تُنتَج في جزء من المخلوق الحي وتُنقل إلى جزء آخر، وتؤدي إلى تغير فسيولوجي فيه. والإيثين تُنتجه النباتات على نحو طبيعي ويُحدث فيها تغيرات فسيولوجية، فهو هرمون نباتي. من أدواره: (1) المسؤولية عن عملية النضج في الفواكه، (2) أداء دور في تساقط أوراق الأشجار إيذانًا بدخول فصل الشتاء.', '["تعريف الهرمون","الإيثين تنتجه النباتات طبيعيًّا ويُحدث تغيرًا فسيولوجيًّا","نضج الفواكه","تساقط أوراق الأشجار"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الهرمون","marks":1},{"element":"سبب عدّ الإيثين هرمونًا","marks":1},{"element":"الدور الأول","marks":1},{"element":"الدور الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة لكل المطلوب"},{"level":"2–3 درجات","description":"إجابة صحيحة لبعض المطلوب أو مع خطأ واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الهرمون بأنه أي مادة يُنتجها النبات","ذكر صناعة البولي إيثيلين دورًا للإيثين في النبات","الخلط بين الإيثين والإيثاين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يُعد الإيثين من المواد الأولية المستخدمة في تصنيع مادة البولي إيثيلين البلاستيكية، التي تُصنع منها منتجات كثيرة منها: الحقائب البلاستيكية، والحبال، وعلب الحليب. (ب) يحتوي الإيثين على رابطة ثنائية تزيد الكثافة الإلكترونية بين ذرتي الكربون، فتكون موقعًا للنشاط الكيميائي، فيتفاعل بسهولة لتكوين مواد جديدة كالبوليمرات؛ أما الإيثان فروابطه أحادية فقط فهو أقل نشاطًا، فيصعب تحويله إلى منتجات أخرى.', '["الإيثين مادة أولية لصناعة البولي إيثيلين","ثلاثة منتجات: الحقائب البلاستيكية، الحبال، علب الحليب","الرابطة الثنائية تجعل الإيثين نشطًا","الإيثان روابطه أحادية فهو أقل نشاطًا"]'::jsonb, '[]'::jsonb, '[{"element":"أهمية الإيثين الصناعية","marks":1},{"element":"المنتجات الثلاثة","marks":1.5},{"element":"تفسير نشاط الإيثين","marks":1.5},{"element":"المقارنة بالإيثان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة للجزأين"},{"level":"3–4 درجات","description":"الجزء (أ) كامل مع تفسير ناقص في (ب)، أو العكس"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر لحام الفلزات استعمالًا للإيثين","تفسير الفائدة بكثرة ذرات الهيدروجين","القول إن الإيثان أنشط لأنه مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.610Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المواد: ثمار موز خضراء متماثلة، ووعاءان مغلقان متماثلان، ومصدر للإيثين (أو ثمار ناضجة تطلقه). الخطوات: تُقسم الثمار إلى مجموعتين متساويتين؛ تُوضع الأولى في وعاء مغلق مع الإيثين، والثانية (المجموعة الضابطة) في وعاء مغلق دون إيثين. المتغير المستقل: وجود الإيثين أو غيابه. المتغيرات الثابتة: عدد الثمار وحجمها ودرجة نضجها الأولي، وحجم الوعاء، ودرجة الحرارة، والإضاءة، ومدة التجربة. الملاحظة: تغير لون القشرة من الأخضر إلى الأصفر وطراوة الثمار يوميًّا مدة عدة أيام. النتيجة المتوقعة: تنضج ثمار المجموعة المعرضة للإيثين أسرع من المجموعة الضابطة، مما يبين أن الإيثين هرمون مسؤول عن النضج.', '["مجموعتان متماثلتان من الموز الأخضر","مجموعة ضابطة دون إيثين","المتغير المستقل: وجود الإيثين","ثبات المتغيرات الأخرى (الحرارة، عدد الثمار، حجم الوعاء…)","الملاحظة والنتيجة المتوقعة: نضج أسرع مع الإيثين"]'::jsonb, '[]'::jsonb, '[{"element":"المواد وتقسيم المجموعتين","marks":1},{"element":"المجموعة الضابطة","marks":1},{"element":"المتغير المستقل والمتغيرات الثابتة","marks":1},{"element":"ما يُلاحَظ","marks":1},{"element":"النتيجة المتوقعة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم كامل بمجموعة ضابطة ومتغيرات محددة ونتيجة صحيحة"},{"level":"3–4 درجات","description":"تصميم مقبول ينقصه ضبط بعض المتغيرات أو تحديد الملاحظة"},{"level":"1–2 درجة","description":"وصف عام دون مجموعة ضابطة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال المجموعة الضابطة","تغيير أكثر من متغير في الوقت نفسه (مثل درجة الحرارة)","توقع أن الإيثين يؤخر النضج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C4-L3-O12') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L4-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالمتشكلات؟', null, null, '["اثنان أو أكثر من المركبات لها الصيغة البنائية نفسها، لكنها تختلف في صيغها الجزيئية","اثنان أو أكثر من المركبات لها الصيغة الجزيئية نفسها، لكنها تختلف في صيغها البنائية","مركبات في سلسلة واحدة يختلف كل منها عن الذي يليه بمجموعة CH₂ واحدة","مركبات لها الصيغة الجزيئية نفسها والخصائص الفيزيائية والكيميائية نفسها تمامًا"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 2, 'ما الذي تشترك فيه المركبات الثلاثة في الشكل الآتي، ويجعلها متشكلات؟', null, '[{"src":"qimg/chem22/c4-l4a-c5h12.svg","alt":"ثلاث صيغ بنائية مكثفة مرقمة. المركب (1): سلسلة مستقيمة CH₃–CH₂–CH₂–CH₂–CH₃. المركب (2): سلسلة CH₃–CH–CH₂–CH₃ ترتبط فيها مجموعة CH₃ فرعية بذرة الكربون الثانية. المركب (3): ذرة كربون مركزية C ترتبط بأربع مجموعات CH₃."}]'::jsonb, '["الصيغة البنائية للسلسلة","عدد ذرات الكربون في السلسلة الرئيسة","عدد مجموعات CH₃ في الجزيء","الصيغة الجزيئية C₅H₁₂"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 3, 'هل يُعدّ المركبان الممثلان في الشكل الآتي متشكلين؟', null, '[{"src":"qimg/chem22/c4-l4a-cyclo-vs-chain.svg","alt":"صيغتان هيكليتان مرقمتان (كل رأس أو طرف يمثل ذرة كربون مشبعة بذرات الهيدروجين). (1): حلقة خماسية مغلقة من خمسة رؤوس، كل ذرة كربون فيها مرتبطة بذرتي كربون. (2): خط متعرج مفتوح له خمسة رؤوس وأطراف، يمثل سلسلة مستقيمة من خمس ذرات كربون."}]'::jsonb, '["لا؛ لأن الصيغة الجزيئية لـ (1) C₅H₁₀ ولـ (2) C₅H₁₂","نعم؛ لأن في كل منهما خمس ذرات كربون","نعم؛ لأن صيغتيهما البنائيتين مختلفتان","لا؛ لأن (1) حلقي و(2) سلسلة مفتوحة"]'::jsonb, 'تطبيق', 'تطبيق تعريف على شكل', 'متوسط', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 4, 'أي أزواج الصيغ البنائية المكثفة الآتية يمثل متشكلين؟', null, null, '["CH₃CH₂CH₃ و CH₃CH₂CH₂CH₃","CH₃CH₂CH₂CH₂CH₃ و CH₂=CHCH₂CH₂CH₃","CH₃CH₂CH₂CH₃ و CH₃CH(CH₃)CH₃","CH₃CH₂CH₂CH₃ و CH₃CH₂CH₂CH₃"]'::jsonb, 'تطبيق', 'تصنيف أزواج', 'متوسط', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 5, 'ما المصطلح العلمي الذي يُطلق على المركبات التي لها الصيغة الجزيئية نفسها، لكنها تختلف في صيغها البنائية؟', null, null, '["السلسلة المتماثلة","الهيدروكربونات المشبعة","المجموعات البديلة","المتشكلات"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 6, 'كيف يتغير عدد المتشكلات البنائية المحتملة للألكانات بزيادة عدد ذرات الكربون في الصيغة الجزيئية؟', null, null, '["يقل عددها كلما زاد عدد ذرات الكربون","يزداد عددها كلما زاد عدد ذرات الكربون","لا يتغير عددها بتغير عدد ذرات الكربون","يساوي عددها عدد ذرات الكربون دائمًا"]'::jsonb, 'فهم', 'تفسير علاقة', 'متوسط', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 7, 'أي العبارات الآتية صحيحة بشأن المتشكلات؟', null, null, '["قد تختلف في خصائصها الفيزيائية والكيميائية رغم اشتراكها في الصيغة الجزيئية","لها دائمًا درجة الغليان نفسها؛ لأن كتلها المولية متساوية","تتفق في عدد ذرات الكربون وتختلف في عدد ذرات الهيدروجين","لا توجد إلا في الألكينات؛ لاحتوائها على رابطة ثنائية"]'::jsonb, 'فهم', 'حكم على عبارات', 'صعب', 'الكتاب ص 143 — المتشكلات البنائية'),
('essay', 1, 'عرّف المتشكلات، ثم بيّن فيمَ تتشابه المتشكلات وفيمَ تختلف، ومثّل لذلك بكتابة الصيغتين البنائيتين المكثفتين لمركبين صيغتهما الجزيئية C₄H₁₀.', null, null, null, 'فهم', 'تعريف ومقارنة ومثال', 'متوسط', 'الكتاب ص 143، 161 — المتشكلات (س64)'),
('essay', 2, 'قال طالب: «الهكسان الحلقي و1-هكسين CH₂=CHCH₂CH₂CH₂CH₃ ليسا متشكلين؛ لأن أحدهما حلقي والآخر سلسلة مفتوحة». قوّم هذه العبارة مع التعليل، ثم اكتب الصيغة البنائية المكثفة لمتشكل آخر غير حلقي للهكسان الحلقي.', null, null, null, 'تقويم', 'تقويم عبارة واقتراح مثال', 'صعب', 'الكتاب ص 143، 162 — المتشكلات (على نمط س81)'),
('essay', 3, 'حدّد من بين الصيغ الآتية المركبات التي تُعدّ متشكلات بعضها لبعض، مع كتابة الصيغة الجزيئية لكل صيغة:
(أ) CH₃CH₂CH₂CH₂CH₃
(ب) CH₃CH(CH₃)CH₂CH₃
(ج) CH₃CH₂CH₂CH₃
(د) C(CH₃)₄
(هـ) CH₃CH₂CH₂CH₂CH₂CH₃', null, null, null, 'تحليل', 'تصنيف وتعليل', 'صعب', 'الكتاب ص 143 — المتشكلات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L4-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المتشكلات اثنان أو أكثر من المركبات لها الصيغة الجزيئية نفسها، إلا أنها تختلف في صيغها البنائية؛ مثل البنتان و2-ميثيل بيوتان، وصيغة كل منهما C₅H₁₂.', '["عكسَ هذا البديل التعريف؛ فالمتشكلات تتفق في الصيغة الجزيئية وتختلف في الصيغة البنائية.","","هذا وصف السلسلة المتماثلة، ومركباتها تختلف في صيغها الجزيئية فليست متشكلات.","المتشكلات تختلف في صيغها البنائية، وتختلف غالبًا في خصائصها الفيزيائية والكيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 2, 3, 'في كل مركب 5 ذرات كربون و12 ذرة هيدروجين، فالصيغة الجزيئية واحدة C₅H₁₂، والصيغ البنائية مختلفة؛ لذا فهي متشكلات.', '["صيغها البنائية مختلفة: سلسلة مستقيمة، وسلسلة بفرع واحد، وكربون مركزي بأربعة فروع.","السلاسل الرئيسة مختلفة الطول (5 ثم 4 ثم 3 ذرات كربون).","عدد مجموعات CH₃ مختلف: 2 في (1)، و3 في (2)، و4 في (3).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 3, 0, 'المركب (1) بنتان حلقي: كل ذرة كربون ترتبط بذرتي هيدروجين، فصيغته C₅H₁₀. والمركب (2) بنتان صيغته C₅H₁₂. اختلاف الصيغة الجزيئية يعني أنهما ليسا متشكلين.', '["","تساوي عدد ذرات الكربون لا يكفي؛ يجب أن تتطابق الصيغة الجزيئية كاملة، وعدد ذرات الهيدروجين هنا مختلف.","اختلاف الصيغة البنائية لا يجعل المركبين متشكلين ما لم تكن صيغتاهما الجزيئيتان متطابقتين.","كون أحدهما حلقيًّا ليس هو المعيار؛ فقد يكون مركب حلقي متشكلًا لمركب مفتوح السلسلة إذا تطابقت الصيغة الجزيئية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 4, 2, 'صيغة كل من CH₃CH₂CH₂CH₃ (بيوتان) و CH₃CH(CH₃)CH₃ (2-ميثيل بروبان) هي C₄H₁₀، وصيغتاهما البنائيتان مختلفتان؛ فهما متشكلان.', '["الأول C₃H₈ والثاني C₄H₁₀؛ صيغتاهما الجزيئيتان مختلفتان (مركبان متتاليان في سلسلة متماثلة).","الأول C₅H₁₂ والثاني C₅H₁₀؛ عدد ذرات الهيدروجين مختلف.","","هاتان صيغتان متطابقتان لمركب واحد (البيوتان)، وليستا مركبين مختلفين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 5, 3, 'المتشكلات (isomers) هي اثنان أو أكثر من المركبات لها الصيغة الجزيئية نفسها وتختلف في صيغها البنائية.', '["السلسلة المتماثلة مركبات تختلف في صيغها الجزيئية بمقدار ثابت (CH₂).","الهيدروكربونات المشبعة هي التي تحتوي على روابط أحادية فقط، ولا علاقة لذلك بتطابق الصيغة الجزيئية.","المجموعة البديلة (الفرعية) جزء من الجزيء يتفرع من السلسلة الرئيسة، وليست مركبًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 6, 1, 'كلما زاد عدد ذرات الكربون زادت طرائق ترتيبها، فيزداد عدد المتشكلات البنائية المحتملة: 3 للصيغة C₅H₁₂، و9 للصيغة C₇H₁₆، وأكثر من 300000 للصيغة C₂₀H₄₂.', '["العكس صحيح؛ فللصيغة C₇H₁₆ تسعة متشكلات، وللصيغة C₂₀H₄₂ أكثر من 300000 متشكل.","","العدد يتغير؛ فللصيغة C₅H₁₂ ثلاثة متشكلات، وللصيغة C₇H₁₆ تسعة.","لا توجد هذه العلاقة؛ فللصيغة C₇H₁₆ تسعة متشكلات لا سبعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('mcq', 7, 0, 'المتشكلات تتفق في الصيغة الجزيئية وتختلف في الصيغة البنائية، واختلاف البناء يجعلها تختلف في خصائصها الفيزيائية والكيميائية؛ فبناء المادة يحدد خصائصها.', '["","تساوي الكتلة المولية لا يعني تساوي درجة الغليان؛ فدرجة غليان البنتان 36°C ودرجة غليان 2-ميثيل بيوتان 28°C.","إذا اختلف عدد ذرات الهيدروجين اختلفت الصيغة الجزيئية، فلا تكون المركبات متشكلات.","توجد المتشكلات في الألكانات أيضًا، مثل متشكلات C₅H₁₂ الثلاثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.611Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المتشكلات: اثنان أو أكثر من المركبات لها الصيغة الجزيئية نفسها، لكنها تختلف في صيغها البنائية. تتشابه في الصيغة الجزيئية (نوع الذرات وعددها)، وتختلف في الصيغة البنائية (ترتيب الذرات أو اتجاهاتها في الفراغ)، ولذلك تختلف في بعض خصائصها. مثال C₄H₁₀: البيوتان CH₃CH₂CH₂CH₃، و2-ميثيل بروبان CH₃CH(CH₃)CH₃.', '["تعريف المتشكلات","أوجه التشابه: الصيغة الجزيئية نفسها","أوجه الاختلاف: الصيغة البنائية (ومن ثم الخصائص)","صيغة البيوتان CH₃CH₂CH₂CH₃","صيغة 2-ميثيل بروبان CH₃CH(CH₃)CH₃"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المتشكلات","marks":1},{"element":"أوجه التشابه: الصيغة الجزيئية نفسها","marks":1},{"element":"أوجه الاختلاف: الصيغة البنائية (ومن ثم الخصائص)","marks":1},{"element":"صيغة البيوتان CH₃CH₂CH₂CH₃","marks":1},{"element":"صيغة 2-ميثيل بروبان CH₃CH(CH₃)CH₃","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف المتشكلات؛ أوجه التشابه: الصيغة الجزيئية نفسها؛ أوجه الاختلاف: الصيغة البنائية (ومن ثم الخصائص)؛ صيغة البيوتان CH₃CH₂CH₂CH₃؛ صيغة 2-ميثيل بروبان CH₃CH(CH₃)CH₃"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغتين للمركب نفسه (مثل CH₃CH₂CH₂CH₃ و CH₃–CH₂–CH₂–CH₃) على أنهما متشكلان","القول إن المتشكلات تختلف في الصيغة الجزيئية","كتابة CH₃CH₂CH₂CH₂CH₃ وهي C₅H₁₂ لا C₄H₁₀"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة خاطئة. الهكسان الحلقي صيغته C₆H₁₂ (كل ذرة كربون في الحلقة ترتبط بذرتي كربون وذرتي هيدروجين)، و1-هكسين صيغته C₆H₁₂ أيضًا؛ فلهما الصيغة الجزيئية نفسها وصيغتان بنائيتان مختلفتان، فهما متشكلان. المعيار هو تطابق الصيغة الجزيئية مع اختلاف الصيغة البنائية، لا كون السلسلة حلقية أو مفتوحة. من المتشكلات غير الحلقية الأخرى للهكسان الحلقي: 2-هكسين CH₃CH=CHCH₂CH₂CH₃ (صيغته C₆H₁₂).', '["الحكم بأن العبارة خاطئة","الصيغة الجزيئية للهكسان الحلقي C₆H₁₂","الصيغة الجزيئية لـ 1-هكسين C₆H₁₂","التعليل: المعيار تطابق الصيغة الجزيئية واختلاف الصيغة البنائية","صيغة مكثفة صحيحة لمتشكل آخر غير حلقي صيغته C₆H₁₂ (مثل CH₃CH=CHCH₂CH₂CH₃)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن العبارة خاطئة","marks":1},{"element":"الصيغة الجزيئية للهكسان الحلقي C₆H₁₂","marks":1},{"element":"الصيغة الجزيئية لـ 1-هكسين C₆H₁₂","marks":1},{"element":"التعليل: المعيار تطابق الصيغة الجزيئية واختلاف الصيغة البنائية","marks":1},{"element":"صيغة مكثفة صحيحة لمتشكل آخر غير حلقي صيغته C₆H₁₂ (مثل CH₃CH=CHCH₂CH₂CH₃)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم بأن العبارة خاطئة؛ الصيغة الجزيئية للهكسان الحلقي C₆H₁₂؛ الصيغة الجزيئية لـ 1-هكسين C₆H₁₂؛ التعليل: المعيار تطابق الصيغة الجزيئية واختلاف الصيغة البنائية؛ صيغة مكثفة صحيحة لمتشكل آخر غير حلقي صيغته C₆H₁₂ (مثل CH₃CH=CHCH₂CH₂CH₃)"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن أحد المركبين حلقي","كتابة صيغة الهكسان الحلقي C₆H₁₄","اقتراح ألكان غير حلقي (C₆H₁₄) أو كتابة 1-هكسين نفسه متشكلًا آخر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصيغ الجزيئية: (أ) C₅H₁₂، (ب) C₅H₁₂، (ج) C₄H₁₀، (د) C₅H₁₂، (هـ) C₆H₁₄. المتشكلات هي (أ) و(ب) و(د)؛ لأن لها الصيغة الجزيئية نفسها C₅H₁₂ مع اختلاف صيغها البنائية. أما (ج) و(هـ) فصيغتاهما الجزيئيتان مختلفتان عنها.', '["الصيغ الجزيئية الخمس صحيحة","تحديد (أ) و(ب) و(د) متشكلات","التعليل: الصيغة الجزيئية نفسها C₅H₁₂ وصيغ بنائية مختلفة"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغ الجزيئية الخمس صحيحة","marks":2},{"element":"تحديد (أ) و(ب) و(د) متشكلات","marks":1},{"element":"التعليل: الصيغة الجزيئية نفسها C₅H₁₂ وصيغ بنائية مختلفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الصيغ الجزيئية الخمس صحيحة؛ تحديد (أ) و(ب) و(د) متشكلات؛ التعليل: الصيغة الجزيئية نفسها C₅H₁₂ وصيغ بنائية مختلفة"},{"level":"2–3 درجات","description":"صيغ جزيئية صحيحة أغلبها مع تحديد المتشكلات دون تعليل كافٍ"},{"level":"1 درجة","description":"صيغ جزيئية صحيحة جزئيًّا دون تحديد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الهيدروجين في C(CH₃)₄ خطأً","إدراج (ج) أو (هـ) ضمن المتشكلات لأنها ألكانات","عدّ (أ) و(ب) مركبًا واحدًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb)
