from (values
('mcq', 1, 2, 'للمتشكلات البنائية الصيغة الجزيئية نفسها، إلا أن مواقع (ترتيب) الذرات فيها تختلف؛ أي تختلف في الذرات التي ترتبط بها كل ذرة.', '["هذا وصف المتشكلات الفراغية لا البنائية.","هذا وصف المتشكلات الضوئية، وهي نوع من المتشكلات الفراغية.","","هذا وصف المتشكلات الهندسية (سيس وترانس)، وهي متشكلات فراغية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 2, 0, 'صيغة كل منهما C₄H₁₀، لكن (1) سلسلة مستقيمة (بيوتان) و(2) سلسلة متفرعة (2-ميثيل بروبان)؛ أي يختلف ترتيب ارتباط الذرات، فهما متشكلان بنائيان.', '["","المتشكلات الهندسية تحتاج إلى رابطة ثنائية تُثبّت المجموعات، ولا توجد رابطة ثنائية في المركبين.","لا توجد في أي منهما ذرة كربون مرتبطة بأربع مجموعات مختلفة، والاختلاف هنا في ترتيب ارتباط الذرات.","في (1) سلسلة من أربع ذرات كربون، وفي (2) ذرة كربون مرتبطة بثلاث ذرات كربون؛ فترتيب الارتباط مختلف وهما مركبان مختلفان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 3, 3, 'درجة الغليان تنخفض من 36°C (سلسلة مستقيمة) إلى 28°C (فرع واحد) إلى 9°C (أكثرها تفرعًا)؛ فكلما زاد التفرع انخفضت درجة الغليان، أي أن المتشكلات البنائية تختلف في خصائصها الفيزيائية.', '["البيانات تدل على العكس: المركب الأكثر تفرعًا (3) أقلها درجة غليان 9°C.","درجات الغليان مختلفة (36 و28 و9°C) رغم تساوي الكتل المولية، فهي تتأثر بالبناء.","المتشكل ذو السلسلة المستقيمة (1) أعلاها درجة غليان 36°C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 4, 1, 'صيغة CH₃CH(CH₃)CH₂CH₂CH₃ (2-ميثيل بنتان) هي C₆H₁₄ مثل الهكسان، لكن ترتيب ارتباط ذراته مختلف (سلسلة متفرعة)؛ فهو متشكل بنائي للهكسان.', '["صيغته C₅H₁₂ (2-ميثيل بيوتان)، أما الهكسان فصيغته C₆H₁₄.","","صيغته C₇H₁₆ (هبتان)؛ يزيد بذرة كربون على الهكسان.","صيغته C₆H₁₂ (1-هكسين)؛ ينقص بذرتي هيدروجين عن الهكسان C₆H₁₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 5, 2, 'كلما زاد عدد ذرات الكربون زاد عدد المتشكلات البنائية المحتملة: للصيغة C₅H₁₂ ثلاثة متشكلات، وللصيغة C₇H₁₆ تسعة (9) ألكانات متشكلة.', '["3 هو عدد المتشكلات البنائية للصيغة C₅H₁₂ لا C₇H₁₆.","افترض أن عدد المتشكلات يساوي عدد ذرات الكربون، ولا توجد هذه العلاقة.","","5 هو عدد المتشكلات البنائية للصيغة C₆H₁₄؛ وعدد المتشكلات يزداد بزيادة عدد ذرات الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 6, 2, 'رغم اشتراك المتشكلات البنائية في الصيغة الجزيئية فإنها تختلف في خصائصها الكيميائية والفيزيائية، وهذا يدعم مبدأ أن بناء المادة يحدد خصائصها.', '["للمتشكلات البنائية الكتلة المولية نفسها، ومع ذلك تختلف خصائصها؛ فالكتلة المولية وحدها لا تحددها.","للمتشكلات البنائية الصيغة الجزيئية نفسها وخصائص مختلفة؛ فهي تنقض هذه العبارة.","","المتشكلات متساوية في عدد الذرات ونوعها، لكنها تختلف في درجات غليانها وخصائص أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.612Z"}'::jsonb),
('mcq', 7, 3, 'صيغة كل من 1-بيوتين (CH₂=CHCH₂CH₃) و2-بيوتين (CH₃CH=CHCH₃) هي C₄H₈، ويختلف فيهما موقع الرابطة الثنائية أي ترتيب ارتباط الذرات؛ فهما متشكلان بنائيان.', '["ترتيب ارتباط الذرات فيهما واحد، ويختلفان في الاتجاه الفراغي حول الرابطة الثنائية؛ فهما متشكلان هندسيان (فراغيان).","البيوتان C₄H₁₀ و1-بيوتين C₄H₈؛ صيغتاهما الجزيئيتان مختلفتان فليسا متشكلين.","هذان صورتا مرآة حول ذرة كربون غير متماثلة؛ فهما متشكلان ضوئيان (فراغيان) لا بنائيان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('essay', 1, null::int, null, null, 'للصيغة C₆H₁₄ خمسة متشكلات بنائية:
1) CH₃CH₂CH₂CH₂CH₂CH₃ هكسان.
2) CH₃CH(CH₃)CH₂CH₂CH₃ 2-ميثيل بنتان.
3) CH₃CH₂CH(CH₃)CH₂CH₃ 3-ميثيل بنتان.
4) CH₃C(CH₃)₂CH₂CH₃ 2، 2-ثنائي ميثيل بيوتان.
5) CH₃CH(CH₃)CH(CH₃)CH₃ 2، 3-ثنائي ميثيل بيوتان.', '["الهكسان","2-ميثيل بنتان","3-ميثيل بنتان","2، 2-ثنائي ميثيل بيوتان","2، 3-ثنائي ميثيل بيوتان"]'::jsonb, '[]'::jsonb, '[{"element":"الهكسان","marks":1},{"element":"2-ميثيل بنتان","marks":1},{"element":"3-ميثيل بنتان","marks":1},{"element":"2، 2-ثنائي ميثيل بيوتان","marks":1},{"element":"2، 3-ثنائي ميثيل بيوتان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الهكسان؛ 2-ميثيل بنتان؛ 3-ميثيل بنتان؛ 2، 2-ثنائي ميثيل بيوتان؛ 2، 3-ثنائي ميثيل بيوتان"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة متشكلات صحيحة بصيغها وأسمائها"},{"level":"1–2 درجة","description":"متشكل أو اثنان صحيحان، أو صيغ صحيحة بلا أسماء"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تكرار المتشكل نفسه بترقيم مختلف (مثل 4-ميثيل بنتان بدلًا من 2-ميثيل بنتان)","كتابة 1-ميثيل بنتان وهو في الحقيقة هكسان","كتابة متشكلات بعدد هيدروجين خاطئ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المتشكلات البنائية: متشكلات لها الصيغة الجزيئية نفسها، إلا أن مواقع (ترتيب) الذرات فيها تختلف. صيغة كل من المركبين C₅H₁₀ (5 ذرات كربون و10 ذرات هيدروجين)، لكن في الأول سلسلة مستقيمة من خمس ذرات كربون والرابطة الثنائية في طرفها، وفي الثاني سلسلة من أربع ذرات كربون تتفرع منها مجموعة ميثيل على ذرة الكربون الثانية والرابطة الثنائية بين ذرتي الكربون الثانية والثالثة؛ فترتيب ارتباط الذرات مختلف. الأول 1-بنتين، والثاني 2-ميثيل-2-بيوتين.', '["تعريف المتشكلات البنائية","الصيغة الجزيئية المشتركة C₅H₁₀","بيان اختلاف ترتيب ارتباط الذرات (سلسلة مستقيمة/متفرعة وموقع الرابطة الثنائية)","الاسمان 1-بنتين و2-ميثيل-2-بيوتين"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المتشكلات البنائية","marks":1},{"element":"الصيغة الجزيئية المشتركة C₅H₁₀","marks":1},{"element":"بيان اختلاف ترتيب ارتباط الذرات (سلسلة مستقيمة/متفرعة وموقع الرابطة الثنائية)","marks":1},{"element":"الاسمان 1-بنتين و2-ميثيل-2-بيوتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف المتشكلات البنائية؛ الصيغة الجزيئية المشتركة C₅H₁₀؛ بيان اختلاف ترتيب ارتباط الذرات (سلسلة مستقيمة/متفرعة وموقع الرابطة الثنائية)؛ الاسمان 1-بنتين و2-ميثيل-2-بيوتين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الكربون في المجموعة بين القوسين خطأً فتُكتب الصيغة C₄H₈","تسمية المركب الثاني 2-ميثيل-3-بيوتين بترقيم خاطئ","عدّ الاختلاف اختلافًا في الاتجاه الفراغي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصيغ الجزيئية: (أ) C₇H₁₆، (ب) C₆H₁₄، (ج) C₇H₁₆، (د) C₅H₁₂. زوج المتشكلات البنائية هو (أ) و(ج)؛ لأن لهما الصيغة الجزيئية نفسها C₇H₁₆، ويختلف فيهما ترتيب ارتباط الذرات: (أ) 2، 2-ثنائي ميثيل بنتان فيه مجموعتا ميثيل على ذرة الكربون الثانية، و(ج) 3-ميثيل هكسان فيه مجموعة ميثيل واحدة على ذرة الكربون الثالثة.', '["الصيغ الجزيئية الأربع صحيحة","تحديد (أ) و(ج)","التعليل: الصيغة الجزيئية نفسها وترتيب ارتباط مختلف"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغ الجزيئية الأربع صحيحة","marks":2},{"element":"تحديد (أ) و(ج)","marks":1},{"element":"التعليل: الصيغة الجزيئية نفسها وترتيب ارتباط مختلف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الصيغ الجزيئية الأربع صحيحة؛ تحديد (أ) و(ج)؛ التعليل: الصيغة الجزيئية نفسها وترتيب ارتباط مختلف"},{"level":"2–3 درجات","description":"تحديد صحيح مع صيغ جزيئية صحيحة جزئيًّا أو تعليل ناقص"},{"level":"1 درجة","description":"تحديد صحيح فقط أو صيغ جزيئية صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الكربون في المجموعات بين القوسين خطأً","اختيار (ب) و(د) لتشابه شكل التفرع رغم اختلاف صيغتيهما","عدم كتابة التعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb)
