insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C4-L4-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالمتشكلات الفراغية؟', null, null, '["متشكلات يختلف فيها ترتيب ارتباط الذرات بعضها ببعض","مركبات تختلف في صيغها الجزيئية وتتفق في اتجاهات ذراتها","مركبات تختلف في عدد الروابط الثنائية في جزيئاتها","متشكلات ترتبط فيها الذرات بالترتيب نفسه، لكنها تختلف في ترتيبها الفراغي"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 2, 'المتشكلات الفراغية نوعان، هما:', null, null, '["المتشكلات البنائية والمتشكلات الهندسية","المتشكلات الهندسية والمتشكلات الضوئية","المتشكلات البنائية والمتشكلات الضوئية","الألكانات المستقيمة والألكانات المتفرعة"]'::jsonb, 'تذكر', 'تذكر تصنيف', 'سهل', 'الكتاب ص 144–146 — المتشكلات الفراغية'),
('mcq', 3, 'ما الذي يجعل المركبين الممثلين في الشكل الآتي متشكلين فراغيين لا متشكلين بنائيين؟', null, '[{"src":"qimg/chem22/c4-l4a-2-butene.svg","alt":"صيغتان بنائيتان مرقمتان، في كل منهما ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا، وترتبط بكل ذرة كربون مجموعتان إحداهما إلى أعلى والأخرى إلى أسفل. في (1): ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وH في الأسفل، وذرة الكربون اليمنى ترتبط بـ CH₃ في الأعلى وH في الأسفل. في (2): ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وH في الأسفل، وذرة الكربون اليمنى ترتبط بـ H في الأعلى وCH₃ في الأسفل."}]'::jsonb, '["ترتبط ذراتهما بالترتيب نفسه، وتختلف اتجاهات مجموعتي CH₃ في الفراغ","تختلف صيغتاهما الجزيئيتان مع تشابه ترتيب ارتباط الذرات","يختلف موقع الرابطة الثنائية في سلسلة الكربون بينهما","يحتوي كل منهما على ذرة كربون مرتبطة بأربع مجموعات مختلفة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 4, 'ما العلاقة بين الصيغتين الممثلتين في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l4a-same-cis.svg","alt":"صيغتان بنائيتان مرقمتان، في كل منهما ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا. في (1): ترتبط كل من ذرتي الكربون بمجموعة CH₃ في الأعلى وذرة H في الأسفل. في (2): ترتبط كل من ذرتي الكربون بذرة H في الأعلى ومجموعة CH₃ في الأسفل."}]'::jsonb, '["متشكلا سيس وترانس","متشكلان بنائيان مختلفان","صيغتان للمركب نفسه","متشكلان ضوئيان مختلفان"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 5, 'أي العبارات الآتية تميّز المتشكلات الفراغية من المتشكلات البنائية؟', null, null, '["في الفراغية يختلف ترتيب ارتباط الذرات، وفي البنائية يبقى الترتيب نفسه","في الفراغية تبقى الذرات مرتبطة بالترتيب نفسه، وفي البنائية يختلف ترتيب ارتباطها","الفراغية تختلف في الصيغة الجزيئية، والبنائية تتفق فيها","البنائية توجد في الألكانات فقط، والفراغية في الألكينات فقط"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 148 — الخلاصة 4-4'),
('mcq', 6, 'أي الأزواج الآتية يمثل متشكلين فراغيين؟', null, null, '["البنتان و2، 2-ثنائي ميثيل بروبان","1-بنتين و2-بنتين","الإيثان والإيثين","L-ألانين وD-ألانين"]'::jsonb, 'تطبيق', 'تصنيف أزواج', 'سهل', 'الكتاب ص 146، 164 — المتشكلات الفراغية'),
('mcq', 7, 'يمثل الشكل الآتي جزيئين ترتبط فيهما المجموعات المختلفة W وX وY وZ بذرة الكربون نفسها. أي وصف ينطبق عليهما؟', null, '[{"src":"qimg/chem22/c4-l4a-wxyz.svg","alt":"صيغتا إسقاط مرقمتان لجزيئين، في كل منهما ذرة كربون C في الوسط ترتبط بأربع مجموعات مختلفة W وX وY وZ. في (1): W في الأعلى، وZ على اليسار، وX على اليمين، وY في الأسفل. في (2): W في الأعلى، وZ على اليسار، وY على اليمين، وX في الأسفل؛ أي أن موقعي X وY متبادلان. يفصل بين الصيغتين خط متقطع."}]'::jsonb, '["متشكلان فراغيان؛ فالمجموعات مرتبطة بذرة الكربون نفسها ومواقعها في الفراغ مختلفة","متشكلان بنائيان؛ لأن X وY ارتبطتا بذرتي كربون مختلفتين","جزيء واحد؛ لأن تدوير أحدهما يجعله مطابقًا للآخر تمامًا","ليسا متشكلين؛ لأن صيغتيهما الجزيئيتين مختلفتان"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 146 — المتشكلات الضوئية'),
('essay', 1, 'فسّر الفرق بين المتشكلات البنائية والمتشكلات الفراغية، ومثّل لكل نوع بزوج من المركبات.', null, null, null, 'فهم', 'مقارنة مع أمثلة', 'متوسط', 'الكتاب ص 148 — التقويم 4-4 (س26)'),
('essay', 2, 'قارن بين الإيثان والإيثين من حيث نوع الرابطة بين ذرتي الكربون وأثرها في المجموعات المرتبطة بهما، ثم فسّر وجود متشكلين فراغيين ثابتين لـ 2-بيوتين لا يتحول أحدهما إلى الآخر بسهولة.', null, null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 144 — الشكل 4-18 والمتشكلات الفراغية'),
('essay', 3, 'تمثل الصيغ الثلاث في الشكل الآتي متشكلات للصيغة الجزيئية C₅H₁₀. صنّف العلاقة بين كل زوج: (1) و(2)، و(1) و(3)، و(2) و(3) إلى متشكلات بنائية أو متشكلات فراغية، مع التعليل.', null, '[{"src":"qimg/chem22/c4-l4a-c5h10-three.svg","alt":"ثلاث صيغ بنائية مرقمة، في كل منها ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا. في (1): الكربون الأيسر يرتبط بـ CH₃ في الأعلى وH في الأسفل، والكربون الأيمن يرتبط بـ CH₂CH₃ في الأعلى وH في الأسفل. في (2): الكربون الأيسر يرتبط بـ CH₃ في الأعلى وH في الأسفل، والكربون الأيمن يرتبط بـ H في الأعلى وCH₂CH₃ في الأسفل. في (3): الكربون الأيسر يرتبط بذرتي H (أعلى وأسفل)، والكربون الأيمن يرتبط بـ CH₂CH₂CH₃ في الأعلى وH في الأسفل."}]'::jsonb, null, 'تحليل', 'تصنيف وتعليل من شكل', 'صعب', 'الكتاب ص 161 — تقويم الفصل (س71)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L4-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المتشكلات الفراغية متشكلات ترتبط فيها الذرات بالترتيب نفسه، ولكنها تختلف في ترتيبها الفراغي (الاتجاهات في الفراغ).', '["هذا تعريف المتشكلات البنائية.","المتشكلات جميعها تتفق في الصيغة الجزيئية، فهذه ليست متشكلات أصلًا.","اختلاف عدد الروابط الثنائية يغير الصيغة الجزيئية، فلا يُنتج متشكلات فراغية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 2, 1, 'من المتشكلات الفراغية: المتشكلات الهندسية (سيس وترانس) الناتجة عن اختلاف ترتيب المجموعات حول الرابطة الثنائية، والمتشكلات الضوئية الناتجة عن الترتيبات المختلفة لأربع مجموعات مختلفة على ذرة الكربون نفسها.', '["المتشكلات البنائية فئة مستقلة يختلف فيها ترتيب ارتباط الذرات، وليست من المتشكلات الفراغية.","","المتشكلات البنائية ليست نوعًا من المتشكلات الفراغية.","الألكانات المستقيمة والمتفرعة ذات الصيغة الجزيئية نفسها أمثلة على المتشكلات البنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 3, 0, 'في المركبين ترتبط كل ذرة كربون من الرابطة الثنائية بـ CH₃ وH، فترتيب ارتباط الذرات واحد، لكن مجموعتي CH₃ في (1) في الجهة نفسها وفي (2) في جهتين متقابلتين؛ أي يختلف الترتيب الفراغي فقط، فهما متشكلان فراغيان.', '["","صيغة كل منهما C₄H₈؛ الصيغتان الجزيئيتان متطابقتان.","الرابطة الثنائية في كليهما بين ذرتي الكربون الثانية والثالثة؛ وإن اختلف موقعها لكانا متشكلين بنائيين.","كل ذرة كربون في الرابطة الثنائية مرتبطة بثلاث مجموعات فقط، والاختلاف هنا حول الرابطة الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 4, 2, 'في (1) مجموعتا CH₃ كلتاهما في الأعلى، وفي (2) كلتاهما في الأسفل؛ أي في الجهة نفسها من الرابطة الثنائية في الحالتين. الصيغة (2) هي الصيغة (1) مقلوبة، فهما تمثلان المركب نفسه (سيس-2-بيوتين).', '["في الصيغتين تقع مجموعتا CH₃ في الجهة نفسها من الرابطة الثنائية، فكلتاهما سيس.","ترتيب ارتباط الذرات في الصيغتين واحد؛ كل ذرة كربون مرتبطة بـ CH₃ وH.","","لا توجد ذرة كربون مرتبطة بأربع مجموعات مختلفة، فلا مجال للتشكل الضوئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 5, 1, 'المتشكلات البنائية تختلف في الترتيب الذي ترتبط به الذرات معًا، أما المتشكلات الفراغية فترتبط فيها الذرات جميعها بالترتيب نفسه وتختلف في ترتيبها الفراغي.', '["هذه العبارة عكست التعريفين.","","النوعان كلاهما يتفقان في الصيغة الجزيئية؛ لأنهما متشكلات.","توجد متشكلات بنائية في الألكينات (مثل 1-بيوتين و2-بيوتين)، والمتشكلات الضوئية قد توجد في الألكانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 6, 3, 'في L-ألانين وD-ألانين ترتبط المجموعات الأربع نفسها بذرة الكربون نفسها (الترتيب نفسه)، ويختلف ترتيبها في الفراغ (صورتا مرآة)؛ فهما متشكلان فراغيان (ضوئيان).', '["يختلف فيهما ترتيب ارتباط ذرات الكربون (مستقيمة ومتفرعة)؛ فهما متشكلان بنائيان.","يختلف فيهما موقع الرابطة الثنائية أي ترتيب ارتباط الذرات؛ فهما متشكلان بنائيان.","الإيثان C₂H₆ والإيثين C₂H₄؛ صيغتاهما الجزيئيتان مختلفتان فليسا متشكلين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.613Z"}'::jsonb),
('mcq', 7, 0, 'ترتبط W وX وY وZ في الجزيئين بذرة الكربون نفسها، فترتيب الارتباط واحد، والفرق تبادل موقعي X وY في الفراغ، ولا يمكن مطابقة الشكلين بالتدوير؛ فهما متشكلان فراغيان.', '["","المجموعات الأربع في الجزيئين مرتبطة بذرة الكربون نفسها؛ فترتيب الارتباط واحد.","لا يمكن تدوير أحد الشكلين بأي طريقة ليصبحا متطابقين؛ يلزم نزع X وY وتبديل موقعيهما.","الجزيئان يحتويان على المجموعات نفسها وبالعدد نفسه، فصيغتاهما الجزيئيتان متطابقتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المتشكلات البنائية: لها الصيغة الجزيئية نفسها، لكن يختلف فيها ترتيب ارتباط الذرات بعضها ببعض، مثل البيوتان CH₃CH₂CH₂CH₃ و2-ميثيل بروبان CH₃CH(CH₃)CH₃. المتشكلات الفراغية: لها الصيغة الجزيئية نفسها، وترتبط فيها الذرات بالترتيب نفسه، لكنها تختلف في ترتيبها الفراغي (الاتجاهات في الفراغ)، مثل سيس-2-بيوتين وترانس-2-بيوتين، أو D-ألانين وL-ألانين.', '["وصف المتشكلات البنائية","مثال صحيح على متشكلين بنائيين","وصف المتشكلات الفراغية","مثال صحيح على متشكلين فراغيين"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المتشكلات البنائية","marks":1},{"element":"مثال صحيح على متشكلين بنائيين","marks":1},{"element":"وصف المتشكلات الفراغية","marks":1},{"element":"مثال صحيح على متشكلين فراغيين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: وصف المتشكلات البنائية؛ مثال صحيح على متشكلين بنائيين؛ وصف المتشكلات الفراغية؛ مثال صحيح على متشكلين فراغيين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التعريفين","التمثيل للمتشكلات الفراغية بالبنتان و2-ميثيل بيوتان","إغفال أن النوعين يتفقان في الصيغة الجزيئية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الإيثان ترتبط ذرتا الكربون برابطة تساهمية أحادية، فتكونان حرتي الدوران حول الرابطة، ولا تبقى المجموعات في مواقع ثابتة. أما في الإيثين فترتبط ذرتا الكربون برابطة تساهمية ثنائية تقاوم الدوران، فتبقى الذرات ثابتة في مواقعها. لذلك في 2-بيوتين تبقى مجموعتا الميثيل ثابتتين: إما في الجهة نفسها من الرابطة الثنائية (سيس) أو في جهتين متقابلتين (ترانس)، ولا يتحول أحد الترتيبين بسهولة إلى الآخر؛ فيوجد متشكلان فراغيان ثابتان.', '["الإيثان: رابطة أحادية وحرية دوران","الإيثين: رابطة ثنائية تمنع الدوران وتثبت الذرات","الربط: ثبات المجموعات في ترتيبين مختلفين (سيس/ترانس) في 2-بيوتين","عدم تحول أحد الترتيبين إلى الآخر بسهولة"]'::jsonb, '[]'::jsonb, '[{"element":"الإيثان: رابطة أحادية وحرية دوران","marks":1},{"element":"الإيثين: رابطة ثنائية تمنع الدوران وتثبت الذرات","marks":1},{"element":"الربط: ثبات المجموعات في ترتيبين مختلفين (سيس/ترانس) في 2-بيوتين","marks":1},{"element":"عدم تحول أحد الترتيبين إلى الآخر بسهولة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الإيثان: رابطة أحادية وحرية دوران؛ الإيثين: رابطة ثنائية تمنع الدوران وتثبت الذرات؛ الربط: ثبات المجموعات في ترتيبين مختلفين (سيس/ترانس) في 2-بيوتين؛ عدم تحول أحد الترتيبين إلى الآخر بسهولة"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الرابطة الأحادية هي التي تمنع الدوران","عدّ سيس وترانس متشكلين بنائيين","إغفال سبب ثبات الترتيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) و(2): متشكلان فراغيان (هندسيان)؛ لأن ترتيب ارتباط الذرات فيهما واحد (الرابطة الثنائية بين ذرتي الكربون 2 و3 في سلسلة من خمس ذرات)، والفرق اتجاه المجموعات: في (1) مجموعتا CH₃ وCH₂CH₃ في الجهة نفسها (سيس-2-بنتين)، وفي (2) في جهتين متقابلتين (ترانس-2-بنتين). (1) و(3): متشكلان بنائيان؛ لأن الرابطة الثنائية في (3) في طرف السلسلة (1-بنتين)، فترتيب ارتباط الذرات مختلف. (2) و(3): متشكلان بنائيان للسبب نفسه.', '["(1) و(2) متشكلان فراغيان (سيس/ترانس)","تعليل (1) و(2): الترتيب نفسه واتجاه فراغي مختلف","(1) و(3) متشكلان بنائيان","(2) و(3) متشكلان بنائيان","تعليل البنائية: اختلاف موقع الرابطة الثنائية"]'::jsonb, '[]'::jsonb, '[{"element":"(1) و(2) متشكلان فراغيان (سيس/ترانس)","marks":1},{"element":"تعليل (1) و(2): الترتيب نفسه واتجاه فراغي مختلف","marks":1},{"element":"(1) و(3) متشكلان بنائيان","marks":1},{"element":"(2) و(3) متشكلان بنائيان","marks":1},{"element":"تعليل البنائية: اختلاف موقع الرابطة الثنائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (1) و(2) متشكلان فراغيان (سيس/ترانس)؛ تعليل (1) و(2): الترتيب نفسه واتجاه فراغي مختلف؛ (1) و(3) متشكلان بنائيان؛ (2) و(3) متشكلان بنائيان؛ تعليل البنائية: اختلاف موقع الرابطة الثنائية"},{"level":"3–4 درجات","description":"تصنيف صحيح للأزواج الثلاثة مع تعليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لزوج أو زوجين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (3) متشكلًا فراغيًّا لأنه مرسوم بالشكل نفسه","عدّ (1) و(2) متشكلين بنائيين لاختلاف موضع CH₂CH₃ في الرسم","إغفال أن الصيغ الثلاث C₅H₁₀"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb)
