('mcq', 1, 0, 'تسمى المتشكلات الناتجة عن اختلاف ترتيب المجموعات واتجاهها حول الرابطة الثنائية المتشكلات الهندسية، ومنها متشكلا سيس وترانس.', '["","في المتشكلات البنائية يختلف ترتيب ارتباط الذرات، لا اتجاه المجموعات حول الرابطة الثنائية.","المتشكلات الضوئية تنتج عن ترتيب أربع مجموعات مختلفة حول ذرة كربون واحدة، لا حول رابطة ثنائية.","السلسلة المتماثلة مركبات تختلف في صيغها الجزيئية بمجموعة CH₂، فليست متشكلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('mcq', 2, 2, 'المصطلحان مشتقان من اللاتينية: «سيس» تعني الجهة نفسها، و«ترانس» تعني الجهة الأخرى؛ فالتركيب سيس تكون فيه المجموعتان في الجهة نفسها من الجزيء بالنسبة إلى الرابطة الثنائية.', '["هذا معنى البادئة «ترانس» (الجهة الأخرى).","في متشكلي سيس وترانس ترتبط كل مجموعة من المجموعتين بذرة كربون مختلفة من ذرتي الرابطة الثنائية.","","ذرة الكربون غير المتماثلة تخص المتشكلات الضوئية، لا الهندسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('mcq', 3, 1, 'في (2) ترتبط مجموعتا الإيثيل CH₃CH₂ وCH₂CH₃ بذرتي الرابطة الثنائية وكلتاهما في الأعلى، أي في الجهة نفسها؛ فهو سيس-3-هكسين، و(1) ترانس-3-هكسين.', '["في (1) تقع إحدى مجموعتي الإيثيل في الأعلى والأخرى في الأسفل، أي في جهتين متقابلتين.","","التركيب الذي تكون فيه المجموعتان في جهتين متقابلتين هو ترانس لا سيس.","اختيار (2) صحيح لكن التعليل خاطئ؛ فمجموعتا الإيثيل في (2) كلتاهما في الأعلى، أي في الجهة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('mcq', 4, 3, 'يلزم لوجود متشكلي سيس وترانس أن ترتبط كل ذرة من ذرتي الرابطة الثنائية بمجموعتين مختلفتين. في (4) يرتبط الكربون الأيسر بـ CH₃ وH، والأيمن بـ CH₂CH₃ وH؛ فيمكن أن تكون المجموعتان في الجهة نفسها (سيس) أو متقابلتين (ترانس).', '["إحدى ذرتي الرابطة الثنائية ترتبط بذرتي هيدروجين متماثلتين، فتبادل موقعيهما يعطي المركب نفسه.","ترتبط كل ذرة من ذرتي الرابطة الثنائية بمجموعتين متماثلتين (H وH، ثم CH₃ وCH₃)، فلا يوجد ترتيبان مختلفان.","ترتبط ذرة الكربون اليسرى بمجموعتي CH₃ متماثلتين، فقلب ترتيب المجموعات على الكربون الآخر يعطي المركب نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('mcq', 5, 2, 'الرابطة التساهمية الثنائية لا تسمح لذرتي الكربون بالدوران إحداهما حول الأخرى، فتبقى مجموعتا الميثيل ثابتتين في أحد الترتيبين؛ لذا لا يتحول التركيب سيس بسهولة إلى ترانس.', '["صيغة كل منهما C₄H₈؛ فالاختلاف في الترتيب الفراغي فقط.","الرابطة الأحادية تسمح بالدوران الحر (كما في الإيثان)، والرابطة الثنائية هي التي تمنعه.","","كل مجموعة ميثيل ترتبط بذرة كربون مختلفة من ذرتي الرابطة الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.614Z"}'::jsonb),
('mcq', 6, 0, 'المتشكلان لهما الصيغة الجزيئية نفسها C₄H₈ والترتيب نفسه للارتباط، ومع ذلك تختلف درجتا انصهارهما وغليانهما؛ فاختلاف الترتيب الهندسي يؤثر في الخصائص الفيزيائية.', '["","البيانات تبين اختلاف درجتي الانصهار (−139°C و−106°C) ودرجتي الغليان (3.7°C و0.8°C).","صيغة كل منهما C₄H₈؛ وسبب الاختلاف هو الترتيب الهندسي لا الصيغة الجزيئية.","درجة غليان ترانس 0.8°C وهي أقل من درجة غليان سيس 3.7°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('mcq', 7, 1, 'المركب سلسلة من أربع ذرات كربون والرابطة الثنائية عند ذرة الكربون الثانية (2-بيوتين)، ومجموعتا CH₃ في جهتين متقابلتين؛ فاسمه ترانس-2-بيوتين.', '["في (2) مجموعتا CH₃ في جهتين متقابلتين من الرابطة الثنائية، فهو ترانس لا سيس.","","الرابطة الثنائية بين ذرتي الكربون الثانية والثالثة في السلسلة، و1-بيوتين لا يوجد له متشكلا سيس وترانس.","في الجزيء أربع ذرات كربون فقط (CH₃ وC وC وCH₃)، فالاسم ينتهي بـ «بيوتين» لا «بنتين»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الجزيء 2-هكسين C₆H₁₂. سيس-2-هكسين: ذرتا الكربون C=C، ترتبط الأولى بـ CH₃ وH، والثانية بـ CH₂CH₂CH₃ وH، وتكون مجموعتا CH₃ وCH₂CH₂CH₃ في الجهة نفسها من الرابطة الثنائية (كلتاهما في الأعلى) وذرتا H في الجهة الأخرى. ترانس-2-هكسين: المجموعات نفسها، لكن CH₃ في الأعلى على أحد الكربونين وCH₂CH₂CH₃ في الأسفل على الآخر، أي في جهتين متقابلتين. التمييز: في سيس تكون مجموعتا الألكيل في الجهة نفسها، وفي ترانس في جهتين متقابلتين، ولا يتحول أحدهما إلى الآخر بسهولة لعدم قدرة ذرتي الرابطة الثنائية على الدوران.', '["صيغة سيس صحيحة","صيغة ترانس صحيحة","الاسمان سيس-2-هكسين وترانس-2-هكسين","التمييز بموقع مجموعتي الألكيل بالنسبة إلى الرابطة الثنائية"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة سيس صحيحة","marks":1},{"element":"صيغة ترانس صحيحة","marks":1},{"element":"الاسمان سيس-2-هكسين وترانس-2-هكسين","marks":1},{"element":"التمييز بموقع مجموعتي الألكيل بالنسبة إلى الرابطة الثنائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: صيغة سيس صحيحة؛ صيغة ترانس صحيحة؛ الاسمان سيس-2-هكسين وترانس-2-هكسين؛ التمييز بموقع مجموعتي الألكيل بالنسبة إلى الرابطة الثنائية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعتين على ذرة الكربون نفسها","تبديل معنى سيس وترانس","تسمية المركب 4-هكسين بدل 2-هكسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في سيس-2-بيوتين تقع مجموعتا الميثيل في الجهة نفسها من الرابطة الثنائية (وذرتا الهيدروجين في الجهة الأخرى)، وفي ترانس-2-بيوتين تقع مجموعتا الميثيل في جهتين متقابلتين. فرضية مقترحة (تُقبل أي فرضية منطقية تربط النسبة بالفرق في ترتيب المجموعات): في التركيب سيس تكون مجموعتا الميثيل قريبتين إحداهما من الأخرى في الجهة نفسها، أما في ترانس فتكونان متباعدتين؛ فقد يكون تكوّن الترتيب الذي تتباعد فيه المجموعات الكبيرة أسهل، فيتكون ترانس بنسبة أكبر. ويمكن اختبار الفرضية بتكرار التفاعل على ألكينات أخرى ومقارنة نسب المتشكلين.', '["وصف ترتيب سيس","وصف ترتيب ترانس","فرضية منطقية تربط النسبة بترتيب المجموعات (مثل قرب مجموعتي الميثيل في سيس وتباعدهما في ترانس)","صياغة الفرضية تفسيرًا قابلًا للاختبار لزيادة نسبة ترانس"]'::jsonb, '[]'::jsonb, '[{"element":"وصف ترتيب سيس","marks":1},{"element":"وصف ترتيب ترانس","marks":1},{"element":"فرضية منطقية تربط النسبة بترتيب المجموعات (مثل قرب مجموعتي الميثيل في سيس وتباعدهما في ترانس)","marks":1},{"element":"صياغة الفرضية تفسيرًا قابلًا للاختبار لزيادة نسبة ترانس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: وصف ترتيب سيس؛ وصف ترتيب ترانس؛ فرضية منطقية تربط النسبة بترتيب المجموعات (مثل قرب مجموعتي الميثيل في سيس وتباعدهما في ترانس)؛ صياغة الفرضية تفسيرًا قابلًا للاختبار لزيادة نسبة ترانس"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ترانس يتكون أكثر لأن صيغته الجزيئية أبسط","تبديل وصف سيس وترانس","فرضية لا تتصل ببناء المتشكلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتشكلات الهندسية: متشكلات ناتجة عن اختلاف ترتيب المجموعات واتجاهها حول الرابطة الثنائية. في 2-بيوتين ترتبط كل ذرة من ذرتي الرابطة الثنائية بمجموعتين مختلفتين (CH₃ وH)، والرابطة الثنائية تمنع الدوران، فيمكن أن تكون مجموعتا الميثيل في الجهة نفسها (سيس) أو في جهتين متقابلتين (ترانس). أما في 1-بيوتين فترتبط ذرة الكربون الطرفية في الرابطة الثنائية بذرتي هيدروجين متماثلتين، فأي ترتيب للمجموعات على الكربون الآخر يعطي المركب نفسه؛ فلا يوجد له متشكلات هندسية.', '["تعريف المتشكلات الهندسية","2-بيوتين: مجموعتان مختلفتان على كل ذرة من ذرتي الرابطة الثنائية","دور الرابطة الثنائية في منع الدوران وتكوين سيس وترانس","1-بيوتين: ذرتا هيدروجين متماثلتان على الكربون الطرفي فلا ترتيبان مختلفان"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المتشكلات الهندسية","marks":1},{"element":"2-بيوتين: مجموعتان مختلفتان على كل ذرة من ذرتي الرابطة الثنائية","marks":1},{"element":"دور الرابطة الثنائية في منع الدوران وتكوين سيس وترانس","marks":1},{"element":"1-بيوتين: ذرتا هيدروجين متماثلتان على الكربون الطرفي فلا ترتيبان مختلفان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف المتشكلات الهندسية؛ 2-بيوتين: مجموعتان مختلفتان على كل ذرة من ذرتي الرابطة الثنائية؛ دور الرابطة الثنائية في منع الدوران وتكوين سيس وترانس؛ 1-بيوتين: ذرتا هيدروجين متماثلتان على الكربون الطرفي فلا ترتيبان مختلفان"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن 1-بيوتين لا يحتوي على رابطة ثنائية","تعليل ذلك باختلاف الصيغة الجزيئية","إغفال شرط وجود مجموعتين مختلفتين على كل ذرة كربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
