('mcq', 1, 'ما المقصود بالكيرالية؟', null, null, '["خاصية وجود الجزيء في صورتين تختلفان في ترتيب ارتباط الذرات بعضها ببعض","خاصية وجود الجزيء في صورتين إحداهما تشبه صورة اليد اليمنى والأخرى تشبه صورة اليد اليسرى","خاصية وجود الجزيء في صورتين تختلفان في اتجاه المجموعات حول الرابطة الثنائية","قدرة ذرتي الكربون المرتبطتين برابطة أحادية على الدوران الحر"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 145–146 — الكيرالية'),
('mcq', 2, 'ذرة الكربون غير المتماثلة هي ذرة الكربون التي ترتبط بـ:', null, null, '["أربع ذرات أو مجموعات ذرات متماثلة","ذرة كربون أخرى برابطة ثنائية","أربع ذرات أو مجموعات ذرات مختلفة","مجموعتين متماثلتين على الأقل"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 146 — المتشكلات الضوئية'),
('mcq', 3, 'تمثل صيغ الإسقاط الآتية أربع ذرات كربون ترتبط كل منها بأربع ذرات أو مجموعات. في أي منها تكون ذرة الكربون المركزية غير متماثلة؟', null, '[{"src":"qimg/chem22/c4-l4a-four-centers.svg","alt":"أربع صيغ إسقاط مرقمة، في كل منها ذرة كربون C مركزية ترتبط بأربع ذرات أو مجموعات. (1): H في الأعلى، وCH₃ على اليسار، وCH₂CH₃ على اليمين، وH في الأسفل. (2): H في الأعلى، وCH₃ على اليسار، وCH₂CH₂CH₃ على اليمين، وCH₂CH₃ في الأسفل. (3): CH₃ في الأعلى، وCH₃ على اليسار، وCH₂CH₃ على اليمين، وH في الأسفل. (4): H في الأعلى، وCH₂CH₃ على اليسار، وCH₂CH₃ على اليمين، وCH₃ في الأسفل."}]'::jsonb, '["(1)","(3)","(4)","(2)"]'::jsonb, 'تطبيق', 'تطبيق تعريف على شكل', 'متوسط', 'الكتاب ص 146 — المتشكلات الضوئية'),
('mcq', 4, 'يمثل الشكل الآتي جزيء ألكان رُقمت ذرات الكربون فيه. ما رقم ذرة الكربون غير المتماثلة؟', null, '[{"src":"qimg/chem22/c4-l4a-numbered-chain.svg","alt":"صيغة بنائية مكثفة لسلسلة من سبع مجموعات: CH₃–CH₂–CH–CH₂–CH₂–CH₂–CH₃، وترتبط مجموعة CH₃ فرعية بالمجموعة الثالثة CH. ذرات الكربون مرقمة بدوائر: 1 تحت CH₃ الطرفية اليسرى، و2 تحت CH₂ التالية، و3 تحت CH، و4 و5 و6 تحت مجموعات CH₂ الثلاث التالية، و7 تحت CH₃ الطرفية اليمنى، والرقم 8 بجانب مجموعة CH₃ الفرعية."}]'::jsonb, '["3","2","4","8"]'::jsonb, 'تطبيق', 'تحديد من شكل', 'متوسط', 'الكتاب ص 146 — المتشكلات الضوئية'),
('mcq', 5, 'كم ذرة كربون غير متماثلة في جزيء 3-ميثيل بنتان الممثل بالصيغة الآتية؟', null, '[{"src":"qimg/chem22/c4-l4a-methylpentane.svg","alt":"صيغة بنائية مكثفة لجزيء: CH₃–CH₂–CH–CH₂–CH₃ مرسومة أفقيًّا، وترتبط بالمجموعة الوسطى CH مجموعة CH₃ فرعية مرسومة إلى أعلى."}]'::jsonb, '["1","2","3","0"]'::jsonb, 'تحليل', 'تحليل صيغة', 'صعب', 'الكتاب ص 146 — المتشكلات الضوئية'),
('mcq', 6, 'أي المواد الآتية من المواد الكيرالية الموجودة في المخلوقات الحية؟', null, null, '["جزيئات الماء في سوائل الجسم","الأحماض الأمينية المكوّنة للبروتينات","غاز الميثان الناتج عن الهضم","غاز ثاني أكسيد الكربون في الزفير"]'::jsonb, 'تذكر', 'تذكر أمثلة', 'سهل', 'الكتاب ص 146 — الكيرالية'),
('mcq', 7, 'اكتشف باستور وجود بلورات حمض الطرطريك في صورتين، العلاقة بينهما كالعلاقة بين:', null, null, '["جسمين متطابقين تمامًا يمكن وضع أحدهما فوق الآخر","مركبين يختلفان في ترتيب ارتباط الذرات","جسم وصورته في المرآة","متشكلي سيس وترانس حول رابطة ثنائية"]'::jsonb, 'فهم', 'تفسير تشبيه', 'متوسط', 'الكتاب ص 145 — الكيرالية'),
('essay', 1, 'عرّف كلًّا من الكيرالية وذرة الكربون غير المتماثلة، ثم ارسم صيغتي إسقاط لذرة كربون ترتبط بأربع مجموعات مختلفة W وX وY وZ، ووضّح بهما لماذا يكون الجزيء المحتوي على ذرة كربون غير متماثلة كيراليًّا.', null, null, null, 'فهم', 'تعريف وتفسير شكل', 'متوسط', 'الكتاب ص 146 — المتشكلات الضوئية'),
('essay', 2, 'ابتداءً بذرة كربون واحدة، اربط بها الذرات أو المجموعات الآتية: ‎−H، ‎−CH₃، ‎−CH₂CH₃، ‎−CH₂CH₂CH₃، ثم أجب:
(أ) هل ذرة الكربون هذه غير متماثلة؟ ولماذا؟
