from (values
('mcq', 1, 1, 'الكيرالية هي الخاصية التي يوجد فيها الجزيء في صورتين إحداهما تشبه صورة اليد اليمنى والأخرى تشبه صورة اليد اليسرى، أي كل منهما صورة مرآة للأخرى.', '["اختلاف ترتيب ارتباط الذرات يميز المتشكلات البنائية، لا الكيرالية.","","هذا وصف التشكل الهندسي (سيس وترانس).","حرية الدوران حول الرابطة الأحادية لا علاقة لها بتعريف الكيرالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('mcq', 2, 2, 'ذرة الكربون غير المتماثلة هي التي ترتبط بأربع ذرات أو مجموعات ذرات مختلفة، ويمكن ترتيب هذه المجموعات حولها بطريقتين مختلفتين.', '["ارتباط ذرة الكربون بمجموعات متماثلة يجعلها متماثلة، كما في ذرة الكربون في الميثان CH₄.","ذرة الكربون في الرابطة الثنائية ترتبط بثلاث ذرات أو مجموعات فقط، ويرتبط بها التشكل الهندسي.","","وجود مجموعتين متماثلتين يمنع أن تكون ذرة الكربون غير متماثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.615Z"}'::jsonb),
('mcq', 3, 3, 'في (2) ترتبط ذرة الكربون بأربع مجموعات مختلفة: H وCH₃ وCH₂CH₃ وCH₂CH₂CH₃؛ فهي ذرة كربون غير متماثلة، أما بقية الذرات فترتبط كل منها بمجموعتين متماثلتين على الأقل.', '["ترتبط ذرة الكربون بذرتي هيدروجين متماثلتين، فليست مرتبطة بأربع مجموعات مختلفة.","ترتبط ذرة الكربون بمجموعتي CH₃ متماثلتين.","ترتبط ذرة الكربون بمجموعتي CH₂CH₃ متماثلتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('mcq', 4, 0, 'ذرة الكربون 3 ترتبط بأربع مجموعات مختلفة: H، وCH₃ (الكربون 8)، وCH₂CH₃ (الكربونان 1 و2)، وCH₂CH₂CH₂CH₃ (الكربونات 4 إلى 7)؛ فهي غير متماثلة.', '["","ذرة الكربون 2 (CH₂) ترتبط بذرتي هيدروجين متماثلتين.","ذرة الكربون 4 (CH₂) ترتبط بذرتي هيدروجين متماثلتين.","ذرة الكربون 8 (CH₃) ترتبط بثلاث ذرات هيدروجين متماثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('mcq', 5, 3, 'ذرة الكربون الوحيدة المرشحة هي الكربون 3، لكنها ترتبط بـ H وCH₃ ومجموعتي CH₂CH₃ متماثلتين؛ وبقية الذرات CH₃ أو CH₂. فلا توجد ذرة كربون غير متماثلة (العدد صفر).', '["ذرة الكربون 3 ترتبط بمجموعتي إيثيل CH₂CH₃ متماثلتين (يمينًا ويسارًا) إضافة إلى H وCH₃، فليست غير متماثلة.","ذرتا الكربون 2 و4 (CH₂) ترتبط كل منهما بذرتي هيدروجين متماثلتين.","لا ترتبط أي ذرة كربون في الجزيء بأربع مجموعات مختلفة، فالعدد ليس 3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('mcq', 6, 1, 'يتمتع الكثير من المواد الموجودة في المخلوقات الحية بالكيرالية، ومنها الأحماض الأمينية المكوّنة للبروتينات، مثل الألانين الذي يوجد في صورتي L وD.', '["جزيء الماء H₂O لا يحتوي على ذرة كربون غير متماثلة، وصورته في المرآة مطابقة له.","","ذرة الكربون في CH₄ ترتبط بأربع ذرات هيدروجين متماثلة، فهو غير كيرالي.","ذرة الكربون في CO₂ ترتبط بذرتي أكسجين متماثلتين، فهو غير كيرالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('mcq', 7, 2, 'أعلن باستور عن وجود بلورات حمض الطرطريك في صورتين، العلاقة بينهما كعلاقة جسم وصورته في المرآة، كاليدين اليمنى واليسرى؛ ولذلك سُميتا نموذج اليد اليمنى ونموذج اليد اليسرى.', '["الصورتان غير متطابقتين، كاليد اليمنى واليد اليسرى.","لحمض الطرطريك في الصورتين ترتيب الارتباط نفسه، والاختلاف في الترتيب الفراغي.","","الصورتان ناتجتان عن الكيرالية (صورة مرآة)، لا عن اختلاف الاتجاه حول رابطة ثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيرالية: الخاصية التي يوجد فيها الجزيء في صورتين إحداهما تشبه صورة اليد اليمنى والأخرى تشبه صورة اليد اليسرى. ذرة الكربون غير المتماثلة: ذرة كربون ترتبط بأربع ذرات أو مجموعات ذرات مختلفة. الرسم: الصيغة (1): C في الوسط، W في الأعلى، وZ على اليسار، وX على اليمين، وY في الأسفل. الصيغة (2): مثلها مع تبديل موقعي X وY. التوضيح: المجموعات الأربع المختلفة يمكن ترتيبها حول ذرة الكربون بطريقتين، ولا يمكن تدوير أحد الشكلين ليطابق الآخر إلا بنزع X وY وتبديل موقعيهما، فيوجد الجزيء في صورتين غير متطابقتين كاليدين؛ أي أنه كيرالي.', '["تعريف الكيرالية","تعريف ذرة الكربون غير المتماثلة","رسم صيغتي إسقاط تختلفان بتبديل موقعي مجموعتين","تعذر المطابقة بالتدوير فيوجد الجزيء في صورتين"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكيرالية","marks":1},{"element":"تعريف ذرة الكربون غير المتماثلة","marks":1},{"element":"رسم صيغتي إسقاط تختلفان بتبديل موقعي مجموعتين","marks":1},{"element":"تعذر المطابقة بالتدوير فيوجد الجزيء في صورتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف الكيرالية؛ تعريف ذرة الكربون غير المتماثلة؛ رسم صيغتي إسقاط تختلفان بتبديل موقعي مجموعتين؛ تعذر المطابقة بالتدوير فيوجد الجزيء في صورتين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف ذرة الكربون غير المتماثلة بأنها المرتبطة برابطة ثنائية","رسم الصيغة الثانية بتدوير الأولى فقط دون تبديل مجموعتين","الخلط بين الكيرالية والتشكل الهندسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نعم؛ لأنها ترتبط بأربع ذرات أو مجموعات مختلفة: H وCH₃ وCH₂CH₃ وCH₂CH₂CH₃. (ب) أطول سلسلة تمر بذرة الكربون هذه: CH₃CH₂–CH(CH₃)–CH₂CH₂CH₃، أي CH₃CH₂CH(CH₃)CH₂CH₂CH₃، وهي ست ذرات كربون والميثيل على الكربون 3، فالاسم 3-ميثيل هكسان (C₇H₁₆). (ج) المتشكل الأول: ذرة الكربون في الوسط، H في الأعلى، CH₃ في الأسفل، CH₂CH₃ على اليسار، CH₂CH₂CH₃ على اليمين. المتشكل الثاني: مثله مع تبديل موقعي CH₂CH₃ وCH₂CH₂CH₃ (صورة مرآة للأول).', '["الحكم بأنها غير متماثلة مع التعليل","الصيغة المكثفة CH₃CH₂CH(CH₃)CH₂CH₂CH₃","الاسم 3-ميثيل هكسان","صيغة إسقاط للمتشكل الأول","صيغة المتشكل الثاني بتبديل مجموعتين"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأنها غير متماثلة مع التعليل","marks":1},{"element":"الصيغة المكثفة CH₃CH₂CH(CH₃)CH₂CH₂CH₃","marks":1},{"element":"الاسم 3-ميثيل هكسان","marks":1},{"element":"صيغة إسقاط للمتشكل الأول","marks":1},{"element":"صيغة المتشكل الثاني بتبديل مجموعتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم بأنها غير متماثلة مع التعليل؛ الصيغة المكثفة CH₃CH₂CH(CH₃)CH₂CH₂CH₃؛ الاسم 3-ميثيل هكسان؛ صيغة إسقاط للمتشكل الأول؛ صيغة المتشكل الثاني بتبديل مجموعتين"},{"level":"3–4 درجات","description":"حكم وتعليل صحيحان مع صيغة واسم صحيحين وخطأ في صيغتي الإسقاط، أو العكس"},{"level":"1–2 درجة","description":"الحكم مع التعليل فقط، أو الصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية المركب 2-إيثيل بنتان دون اختيار أطول سلسلة","تسمية المركب 4-ميثيل هكسان بترقيم خاطئ","رسم المتشكل الثاني بتدوير الأول فقط دون تبديل مجموعتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.616Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصيغة: CH₃CH₂CH(CH₃)CH₂CH(CH₃)CH₂CH₂CH₂CH₃ (C₁₁H₂₄). ذرة الكربون 3 ترتبط بـ H وCH₃ وCH₂CH₃ والجزء CH₂CH(CH₃)CH₂CH₂CH₂CH₃ (أربع مجموعات مختلفة) فهي غير متماثلة. ذرة الكربون 5 ترتبط بـ H وCH₃ والجزء CH₂CH(CH₃)CH₂CH₃ والمجموعة CH₂CH₂CH₂CH₃ (أربع مجموعات مختلفة) فهي غير متماثلة. بقية ذرات الكربون CH₂ أو CH₃ ترتبط بذرتي هيدروجين متماثلتين على الأقل. إذن n = 2، وعدد المتشكلات الفراغية = 2² = 4.', '["الصيغة البنائية المكثفة الصحيحة","تحديد الكربون 3 غير متماثل مع التعليل","تحديد الكربون 5 غير متماثل مع التعليل","استبعاد بقية الذرات","الحساب 2² = 4"]'::jsonb, '["رسم سلسلة من تسع ذرات كربون (نونان) وإضافة CH₃ إلى الكربونين 3 و5","فحص كل ذرة كربون: هل ترتبط بأربع مجموعات مختلفة؟","الكربونان 3 و5 فقط غير متماثلين، إذن n = 2","عدد المتشكلات الفراغية = 2ⁿ = 2² = 4"]'::jsonb, '[{"element":"الصيغة البنائية المكثفة الصحيحة","marks":1},{"element":"تحديد الكربون 3 غير متماثل مع التعليل","marks":1},{"element":"تحديد الكربون 5 غير متماثل مع التعليل","marks":1},{"element":"استبعاد بقية الذرات","marks":1},{"element":"الحساب 2² = 4","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الصيغة البنائية المكثفة الصحيحة؛ تحديد الكربون 3 غير متماثل مع التعليل؛ تحديد الكربون 5 غير متماثل مع التعليل؛ استبعاد بقية الذرات؛ الحساب 2² = 4"},{"level":"3–4 درجات","description":"صيغة صحيحة وتحديد ذرة واحدة صحيحة أو حساب دون تعليل كافٍ"},{"level":"1–2 درجة","description":"صيغة صحيحة فقط أو حساب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الكربون في مجموعتي الميثيل الفرعيتين غير متماثلة","حساب العدد بالعلاقة 2n بدل 2ⁿ (يتساوى الناتجان هنا مصادفة لأن n = 2، لكن الطريقة خاطئة)","وضع مجموعتي الميثيل على الكربونين 3 و4"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
