from (values
('mcq', 1, 2, 'المتشكلات الضوئية متشكلات فراغية ناتجة عن الترتيبات المختلفة للمجموعات الأربع المختلفة والموجودة على ذرة الكربون نفسها (ذرة الكربون غير المتماثلة).', '["اختلاف موقع الرابطة الثنائية يُنتج متشكلات بنائية لا ضوئية.","هذا تعريف المتشكلات الهندسية (سيس وترانس).","","المتشكلات جميعها لها الصيغة الجزيئية نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 2, 3, 'ترتبط ذرة الكربون المركزية بأربع مجموعات مختلفة (COOH وNH₂ وH وCH₃)، والصيغتان صورتا مرآة إحداهما للأخرى (تبادل موقعي NH₂ وH)؛ فهما متشكلان ضوئيان: L-ألانين وD-ألانين.', '["المجموعات الأربع نفسها مرتبطة بذرة الكربون نفسها في الصورتين؛ فترتيب الارتباط واحد.","لا توجد رابطة ثنائية بين ذرتي كربون؛ والاختلاف حول ذرة كربون واحدة غير متماثلة.","الصورتان صورتا مرآة لا يمكن مطابقتهما بالتدوير، فهما مركبان مختلفان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 3, 0, 'للمتشكلات الضوئية الخصائص الفيزيائية والكيميائية نفسها، إلا أن تفاعلاتها الكيميائية تعتمد على الكيرالية في التفاعلات التي تكون فيها الكيرالية مهمة، مثل التفاعلات المحفزة بالإنزيمات.', '["","ترتيب ارتباط الذرات واحد، ولهما درجة الانصهار نفسها.","لا يمكن تحويل أحدهما إلى الآخر إلا بنزع مجموعتين من ذرة الكربون وتبديل موقعيهما.","المتشكلات الضوئية لها الصيغة الجزيئية نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 4, 1, 'L-ميثول وD-ميثول متشكلان ضوئيان (صورتا مرآة)، واختلاف تأثيرهما يبين أن الكيرالية مهمة في الأنظمة الحيوية، فقد يكون متشكل واحد فقط فعالًا.', '["صورة المرآة متشكل ضوئي (فراغي) له ترتيب الارتباط نفسه، لا متشكل بنائي.","","صورتا المرآة لهما الصيغة الجزيئية نفسها.","المثال يدل على العكس؛ فاختلاف الشكل الكيرالي غيّر التأثير الحيوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 5, 2, 'الفرق بين الشكلين هو تبادل موقعي X وY، ولا توجد طريقة لتحويل أحدهما إلى الآخر دون إزالة X وY من ذرة الكربون وتبديل موقعيهما؛ لذا فالجزيئان مختلفان.', '["لا يمكن تدوير أحد الشكلين بأي طريقة ليطابق الآخر تمامًا.","القلب نوع من التدوير، ولا يجعل الشكلين متطابقين.","","نقل مجموعة إلى ذرة كربون أخرى يغير ترتيب الارتباط فيُنتج متشكلًا بنائيًّا لا الجزيء (2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 6, 0, 'في 3-ميثيل هكسان ترتبط ذرة الكربون الثالثة بأربع مجموعات مختلفة: H وCH₃ وCH₂CH₃ وCH₂CH₂CH₃؛ فهي غير متماثلة، فيوجد المركب في صورة متشكلين ضوئيين.', '["","ذرة الكربون الثالثة ترتبط بمجموعتي إيثيل متماثلتين، فلا توجد ذرة كربون غير متماثلة.","ذرة الكربون الثانية ترتبط بثلاث مجموعات CH₃ متماثلة، وبقية الذرات CH₂ أو CH₃.","ذرة الكربون الثانية ترتبط بمجموعتي CH₃ متماثلتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.617Z"}'::jsonb),
('mcq', 7, 3, 'تستفيد المخلوقات الحية من شكل كيرالي واحد؛ لأن هذا الشكل وحده يتلاءم مع الموقع النشط في الإنزيم، كما أن الخلايا البشرية تسمح بدخول الأحماض الأمينية من نوع L فقط في بناء البروتينات.', '["الشكلان الكيراليان لهما الصيغة الجزيئية نفسها.","للمتشكلين الضوئيين الذائبية نفسها في الماء.","المتشكل الضوئي لا يتحول تلقائيًّا إلى متشكل هندسي؛ فهما نوعان مختلفان من التشكل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المتشكلات الضوئية: متشكلات فراغية ناتجة عن الترتيبات المختلفة للمجموعات الأربع المختلفة الموجودة على ذرة الكربون نفسها. (أ) ذرة الكربون 3 ترتبط بأربع مجموعات مختلفة: H وCH₃ وCH₂CH₃ وCH(CH₃)₂، فهي غير متماثلة. أما ذرة الكربون 2 فترتبط بمجموعتي CH₃ متماثلتين، وبقية الذرات CH₂ أو CH₃. (ب) الصيغة الأولى: C في الوسط، H في الأعلى، وCH₃ في الأسفل، وCH₂CH₃ على اليسار، وCH(CH₃)₂ على اليمين؛ والثانية مثلها مع تبديل موقعي CH₂CH₃ وCH(CH₃)₂ (صورة مرآة للأولى). لا توجد طريقة لتدوير إحداهما لتطابق الأخرى دون نزع مجموعتين وتبديل موقعيهما، كما لا تنطبق اليد اليمنى على اليسرى.', '["تعريف المتشكلات الضوئية","تحديد ذرة الكربون 3 غير المتماثلة مع ذكر مجموعاتها الأربع المختلفة","رسم صيغتي إسقاط هما صورتا مرآة (تبديل مجموعتين)","تعذر المطابقة بالتدوير دون كسر روابط"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المتشكلات الضوئية","marks":1},{"element":"تحديد ذرة الكربون 3 غير المتماثلة مع ذكر مجموعاتها الأربع المختلفة","marks":1},{"element":"رسم صيغتي إسقاط هما صورتا مرآة (تبديل مجموعتين)","marks":1},{"element":"تعذر المطابقة بالتدوير دون كسر روابط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف المتشكلات الضوئية؛ تحديد ذرة الكربون 3 غير المتماثلة مع ذكر مجموعاتها الأربع المختلفة؛ رسم صيغتي إسقاط هما صورتا مرآة (تبديل مجموعتين)؛ تعذر المطابقة بالتدوير دون كسر روابط"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرة الكربون 2 غير متماثلة رغم ارتباطها بمجموعتي CH₃","رسم الصيغة الثانية بتدوير الأولى فقط","إغفال ذكر المجموعات الأربع المختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('essay', 2, null::int, null, null, 'زوج المتشكلات الضوئية. ففي المتشكلات الضوئية ترتبط الذرات بالترتيب نفسه، ويكون كل منهما صورة مرآة للآخر؛ لذا لهما الخصائص الفيزيائية نفسها (مثل درجة الانصهار والكثافة والذائبية في الماء، كما في شكلي حمض الطرطريك)، ويختلفان في تأثيرهما في الضوء المستقطب وفي التفاعلات التي تكون فيها الكيرالية مهمة. أما المتشكلات البنائية فيختلف فيها ترتيب ارتباط الذرات، فتختلف خصائصها الفيزيائية، مثل البنتان (درجة غليانه 36°C) و2-ميثيل بيوتان (28°C).', '["الاختيار: المتشكلات الضوئية","التفسير: الترتيب نفسه وصورتا مرآة","مثال على تشابه الخصائص في المتشكلات الضوئية","تفسير اختلاف المتشكلات البنائية مع مثال"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار: المتشكلات الضوئية","marks":1},{"element":"التفسير: الترتيب نفسه وصورتا مرآة","marks":1},{"element":"مثال على تشابه الخصائص في المتشكلات الضوئية","marks":1},{"element":"تفسير اختلاف المتشكلات البنائية مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الاختيار: المتشكلات الضوئية؛ التفسير: الترتيب نفسه وصورتا مرآة؛ مثال على تشابه الخصائص في المتشكلات الضوئية؛ تفسير اختلاف المتشكلات البنائية مع مثال"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المتشكلات البنائية لأن لها الصيغة الجزيئية نفسها","القول إن المتشكلات الضوئية لا تختلف في أي شيء","إغفال المثال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الهندسية: اختلاف ترتيب المجموعات واتجاهها حول الرابطة الثنائية. الضوئية: الترتيبات المختلفة لأربع مجموعات مختلفة حول ذرة كربون واحدة. (ب) الهندسية: رابطة ثنائية C=C تمنع الدوران، وكل ذرة من ذرتيها مرتبطة بمجموعتين مختلفتين. الضوئية: ذرة كربون غير متماثلة مرتبطة بأربع ذرات أو مجموعات مختلفة. (ج) الهندسية: سيس-2-بيوتين وترانس-2-بيوتين. الضوئية: L-ألانين وD-ألانين (أو L-ميثول وD-ميثول). (د) كلاهما متشكلات فراغية؛ لأن الذرات فيهما ترتبط بالترتيب نفسه وتختلف في الترتيب الفراغي.', '["سبب نشوء كل نوع","الشرط البنائي لكل نوع","مثال صحيح لكل نوع","كلاهما فراغية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"سبب نشوء كل نوع","marks":2},{"element":"الشرط البنائي لكل نوع","marks":2},{"element":"مثال صحيح لكل نوع","marks":1},{"element":"كلاهما فراغية مع التعليل","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: سبب نشوء كل نوع؛ الشرط البنائي لكل نوع؛ مثال صحيح لكل نوع؛ كلاهما فراغية مع التعليل"},{"level":"4–5 درجات","description":"مقارنة صحيحة في أغلب الجوانب مع نقص في أحدها"},{"level":"1–3 درجات","description":"مقارنة صحيحة في جانب أو جانبين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المتشكلات الهندسية متشكلات بنائية","اشتراط الرابطة الثنائية للمتشكلات الضوئية","التمثيل للضوئية بسيس وترانس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
