('mcq', 2, 'ما المقصود بالضوء المستقطب؟', null, null, '["الضوء الذي تقع موجاته جميعها في المستوى نفسه","الضوء الذي تتحرك موجاته في المستويات المحتملة جميعها","الضوء الذي له طول موجي واحد فقط","الضوء الذي ينعكس كليًّا عن سطح المحلول"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 147 — الدوران الضوئي'),
('mcq', 3, 'في المخطط الآتي، ما الذي يحدث لمستوى الضوء المستقطب عند مروره خلال أنبوب العينة؟', null, '[{"src":"qimg/chem22/c4-l4a-polarimeter.svg","alt":"مخطط مبسط يسير فيه الضوء من اليسار إلى اليمين: مصدر ضوء عادي تهتز موجاته في مستويات عديدة (رُسمت خطوطًا بعدة اتجاهات)، ثم مرشح استقطاب، يخرج منه ضوء مستقطب يهتز في مستوى رأسي واحد (سهم رأسي مزدوج)، ثم أنبوب عينة يحتوي على محلول متشكل ضوئي، وبعده مستوى الاستقطاب عند خروج الضوء مرسوم سهمًا مزدوجًا مائلًا عن خط رأسي متقطع، وبينهما قوس مكتوب عليه «زاوية الدوران»."}]'::jsonb, '["يتحول إلى ضوء عادي يهتز في مستويات عديدة","يُمتص كليًّا فلا يخرج من الأنبوب","يدور مستواه بزاوية معينة","يبقى مستواه رأسيًّا دون تغير"]'::jsonb, 'فهم', 'تفسير مخطط', 'متوسط', 'الكتاب ص 147 — الشكل 4-23'),
('mcq', 4, 'مُرِّر ضوء مستقطب في محلولين، يحتوي كل منهما على أحد متشكلين ضوئيين لمادة واحدة، أحدهما صورة مرآة للآخر. ماذا يُتوقع؟', null, null, '["يدير المحلولان مستوى الاستقطاب في الاتجاه نفسه","يدير المحلولان مستوى الاستقطاب في اتجاهين متعاكسين","يدير أحدهما مستوى الاستقطاب ولا يؤثر الآخر فيه","لا يؤثر أي منهما في مستوى الاستقطاب"]'::jsonb, 'تطبيق', 'توقع', 'متوسط', 'الكتاب ص 147 — الدوران الضوئي'),
('mcq', 5, 'مُرِّر ضوء مستقطب خلال محلول مادة، فدار مستوى استقطابه نحو اليسار. ماذا يسمى هذا التأثير؟', null, null, '["الاستقطاب","الكيرالية","التشكل الهندسي","الدوران الضوئي"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 147 — الدوران الضوئي'),
('mcq', 6, 'يُعرف محلول الجلوكوز بأنه dextrorotatory؛ ولذلك يُسمى الجلوكوز أحيانًا dextrose. ماذا تعني هذه التسمية؟', null, null, '["يدير الجلوكوز مستوى الضوء المستقطب نحو اليسار (عكس عقارب الساعة)","يحول الجلوكوز الضوء العادي إلى ضوء مستقطب","يدير الجلوكوز مستوى الضوء المستقطب نحو اليمين (مع عقارب الساعة)","لا يؤثر الجلوكوز في الضوء المستقطب لأنه غير كيرالي"]'::jsonb, 'تطبيق', 'تحليل مصطلح', 'متوسط', 'الكتاب ص 145–147، 162 — الدوران الضوئي (س88)'),
('mcq', 7, 'مُرِّر ضوء مستقطب خلال محلولين (أ) و(ب)، فخرج الضوء من المحلول (أ) ومستوى استقطابه مائل بزاوية 15° عن مستواه الأصلي، وخرج من المحلول (ب) ومستوى استقطابه لم يتغير. أي الاستنتاجات الآتية تدعمها هذه الملاحظات؟', null, null, '["يدل المحلول (أ) على وجود متشكل ضوئي فيه، ولا يدل (ب) على ذلك","يدل المحلول (ب) على وجود متشكل ضوئي فيه، ولا يدل (أ) على ذلك","المحلولان يحتويان على متشكلين ضوئيين أحدهما صورة مرآة للآخر","المحلول (أ) حوّل الضوء المستقطب إلى ضوء عادي يهتز في مستويات عديدة"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 147 — الدوران الضوئي'),
('essay', 1, 'أجب عما يأتي:
(أ) كيف يختلف الضوء المستقطب عن الضوء العادي، ومنه ضوء الشمس؟
(ب) كيف تؤثر المتشكلات الضوئية في الضوء المستقطب؟
(ج) فسّر سبب تسمية المتشكلات الضوئية بهذا الاسم.', null, null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 161 — تقويم الفصل (س67، س68)'),
('essay', 2, 'صِف ما يحدث للضوء في كل مرحلة من مراحل المخطط الآتي، ثم توقّع ما يُشاهَد في الحالتين: (أ) استبدال محلول يحتوي على المتشكل الآخر (صورة المرآة) بالمحلول في الأنبوب. (ب) وضع ماء نقي في الأنبوب بدلًا من المحلول.', null, '[{"src":"qimg/chem22/c4-l4a-polarimeter.svg","alt":"مخطط مبسط يسير فيه الضوء من اليسار إلى اليمين: مصدر ضوء عادي تهتز موجاته في مستويات عديدة (رُسمت خطوطًا بعدة اتجاهات)، ثم مرشح استقطاب، يخرج منه ضوء مستقطب يهتز في مستوى رأسي واحد (سهم رأسي مزدوج)، ثم أنبوب عينة يحتوي على محلول متشكل ضوئي، وبعده مستوى الاستقطاب عند خروج الضوء مرسوم سهمًا مزدوجًا مائلًا عن خط رأسي متقطع، وبينهما قوس مكتوب عليه «زاوية الدوران»."}]'::jsonb, null, 'تحليل', 'تحليل مخطط وتوقع', 'صعب', 'الكتاب ص 147 — الشكل 4-23'),
('essay', 3, 'أُعطي طالب محلولين لمتشكلين ضوئيين لمادة واحدة دون ملصقات، ووجد أن لهما درجة الانصهار والكثافة والذائبية في الماء نفسها. اقترح طريقة للتمييز بين المحلولين، وفسّر علاقة طريقتك بتسمية هذه المتشكلات «ضوئية».', null, null, null, 'إبداع', 'تصميم طريقة', 'صعب', 'الكتاب ص 146–147 — المتشكلات الضوئية والدوران الضوئي')
