from (values
('mcq', 1, 3, 'تسمى المتشكلات التي يكون كل منها صورة مرآة للآخر المتشكلات الضوئية؛ لأنها تؤثر في الضوء المار خلالها، إذ يدور مستوى الضوء المستقطب عند مروره خلال محلولها.', '["المتشكلات الضوئية لا تُعرف بإصدار الضوء، بل بتأثيرها في الضوء المستقطب المار خلالها.","التسمية لا ترتبط بامتصاص الضوء أو اللون، بل بإدارة مستوى الضوء المستقطب.","المتشكلات الضوئية مركبات موجودة بغض النظر عن الضوء، كالأحماض الأمينية في الخلايا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('mcq', 2, 0, 'عادة تتحرك الأمواج الضوئية في حزمة الضوء الصادرة عن الشمس أو المصباح في المستويات المحتملة جميعها، ويمكن تصفية الضوء بحيث تقع الأمواج الناتجة جميعها في المستوى نفسه، ويسمى هذا الضوء الضوء المستقطب.', '["","هذا وصف الضوء العادي الصادر عن الشمس أو المصباح.","الاستقطاب يتعلق بمستوى اهتزاز الموجات، لا بعدد الأطوال الموجية.","الضوء المستقطب ينفذ خلال المحلول، ولا يُعرّف بالانعكاس الكلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('mcq', 3, 2, 'يدخل الضوء المستقطب أنبوب العينة في مستوى رأسي، ويخرج منه في مستوى مائل بزاوية الدوران؛ لأن المتشكل الضوئي في المحلول يدير مستوى الاستقطاب، وهذا هو الدوران الضوئي.', '["يبقى الضوء الخارج مستقطبًا في مستوى واحد، لكن هذا المستوى يكون قد دار.","الضوء ينفذ خلال المحلول ويخرج منه بمستوى استقطاب مائل.","","المخطط يبين أن مستوى الاستقطاب بعد الخروج مائل عن الخط الرأسي بزاوية الدوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.618Z"}'::jsonb),
('mcq', 4, 1, 'يدور مستوى الاستقطاب إلى اليمين (مع عقارب الساعة) بتأثير أحد المتشكلين، وإلى اليسار (عكس عقارب الساعة) بتأثير الآخر؛ فالمتشكلان يؤديان إلى دوران الضوء في اتجاهين مختلفين.', '["المتشكلان صورتا مرآة، فيؤديان إلى دوران الضوء في اتجاهين مختلفين.","","كلا المتشكلين يؤثر في الضوء المستقطب؛ ولهذا سُميا متشكلين ضوئيين.","المتشكلات الضوئية تؤثر في الضوء المستقطب المار خلالها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('mcq', 5, 3, 'عندما يمر الضوء المستقطب خلال محلول يحتوي على متشكل ضوئي يدور مستوى الاستقطاب إلى اليمين أو إلى اليسار، ويسمى هذا التأثير الدوران الضوئي.', '["الاستقطاب هو جعل موجات الضوء في مستوى واحد بالمرشح، لا إدارة هذا المستوى.","الكيرالية خاصية للجزيء (وجوده في صورتين كاليدين)، لا اسم التأثير في الضوء.","التشكل الهندسي اختلاف ترتيب المجموعات حول الرابطة الثنائية، ولا يتعلق بالضوء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('mcq', 6, 2, 'الكلمة مكونة من dextro (جهة اليمين) وrotatory (مُدير)؛ فمحلول الجلوكوز يدير مستوى الضوء المستقطب نحو اليمين، أي مع عقارب الساعة عند النظر نحو مصدر الضوء.', '["البادئة dextro تعني جهة اليمين، أما جهة اليسار فبادئتها levo.","تحويل الضوء العادي إلى مستقطب وظيفة مرشح الاستقطاب، لا المحلول.","","الكلمة rotatory تعني أنه يدير مستوى الضوء، فهو مادة نشطة ضوئيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('mcq', 7, 0, 'المتشكل الضوئي يؤثر في الضوء المستقطب المار خلال محلوله فيدير مستوى استقطابه (الدوران الضوئي). المحلول (أ) أدار المستوى بزاوية 15°، فهذا يدل على وجود متشكل ضوئي فيه، أما (ب) فلم يتغير مستوى الاستقطاب فيه فلا يدل على ذلك.', '["","المتشكل الضوئي يدير مستوى الاستقطاب، والذي أداره هو المحلول (أ) لا (ب).","صورتا المرآة كلتاهما تديران مستوى الاستقطاب (في اتجاهين متعاكسين)، أما المحلول (ب) فلم يُدره أصلًا.","الضوء الخارج من (أ) بقي مستقطبًا في مستوى واحد، لكن هذا المستوى دار بزاوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في الضوء العادي (ضوء الشمس أو المصباح) تتحرك الأمواج الضوئية في المستويات المحتملة جميعها، أما الضوء المستقطب فتقع أمواجه جميعها في المستوى نفسه، ويُنتَج بتمرير الضوء العادي خلال مرشح استقطاب. (ب) عندما يمر الضوء المستقطب خلال محلول يحتوي على متشكل ضوئي يدور مستوى الاستقطاب إلى اليمين (مع عقارب الساعة) بتأثير أحد المتشكلين، أو إلى اليسار (عكس عقارب الساعة) بتأثير الآخر، ويسمى ذلك الدوران الضوئي. (ج) سُميت متشكلات ضوئية لأنها تؤثر في الضوء المار خلالها فتدير مستوى الضوء المستقطب.', '["الضوء العادي: مستويات عديدة","الضوء المستقطب: مستوى واحد","تأثير المتشكلات: إدارة مستوى الاستقطاب","المتشكلان يديرانه في اتجاهين مختلفين (الدوران الضوئي)","سبب التسمية: تأثيرها في الضوء المار خلالها"]'::jsonb, '[]'::jsonb, '[{"element":"الضوء العادي: مستويات عديدة","marks":1},{"element":"الضوء المستقطب: مستوى واحد","marks":1},{"element":"تأثير المتشكلات: إدارة مستوى الاستقطاب","marks":1},{"element":"المتشكلان يديرانه في اتجاهين مختلفين (الدوران الضوئي)","marks":1},{"element":"سبب التسمية: تأثيرها في الضوء المار خلالها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الضوء العادي: مستويات عديدة؛ الضوء المستقطب: مستوى واحد؛ تأثير المتشكلات: إدارة مستوى الاستقطاب؛ المتشكلان يديرانه في اتجاهين مختلفين (الدوران الضوئي)؛ سبب التسمية: تأثيرها في الضوء المار خلالها"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتشكلات الضوئية تبعث الضوء","القول إن المتشكلات الضوئية تحول الضوء العادي إلى مستقطب","عدّ الضوء المستقطب ضوءًا ذا طول موجي واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المراحل: يصدر عن المصدر ضوء عادي تهتز أمواجه في مستويات عديدة، ثم يمر خلال مرشح الاستقطاب فيخرج ضوء مستقطب تقع أمواجه في مستوى واحد (رأسي)، ثم يمر خلال أنبوب العينة الذي يحتوي على محلول متشكل ضوئي، فيخرج ومستوى استقطابه قد دار بزاوية الدوران. (أ) المتشكل الآخر (صورة المرآة) يدير مستوى الاستقطاب في الاتجاه المعاكس. (ب) الماء ليس متشكلًا ضوئيًّا (لا يحتوي على ذرة كربون غير متماثلة)، فيخرج الضوء المستقطب دون أن يدور مستواه (يبقى رأسيًّا).', '["وصف الضوء العادي قبل المرشح","وصف الضوء المستقطب بعد المرشح","دوران مستوى الاستقطاب في أنبوب العينة","توقع (أ): الدوران في الاتجاه المعاكس","توقع (ب): لا دوران"]'::jsonb, '[]'::jsonb, '[{"element":"وصف الضوء العادي قبل المرشح","marks":1},{"element":"وصف الضوء المستقطب بعد المرشح","marks":1},{"element":"دوران مستوى الاستقطاب في أنبوب العينة","marks":1},{"element":"توقع (أ): الدوران في الاتجاه المعاكس","marks":1},{"element":"توقع (ب): لا دوران","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: وصف الضوء العادي قبل المرشح؛ وصف الضوء المستقطب بعد المرشح؛ دوران مستوى الاستقطاب في أنبوب العينة؛ توقع (أ): الدوران في الاتجاه المعاكس؛ توقع (ب): لا دوران"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحلول يحول الضوء المستقطب إلى ضوء عادي","توقع الدوران في الاتجاه نفسه للمتشكل الآخر","توقع دوران الضوء مع الماء النقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخصائص الفيزيائية المذكورة متساوية للمتشكلين الضوئيين فلا تصلح للتمييز. الطريقة: يُمرَّر ضوء عادي خلال مرشح استقطاب للحصول على ضوء مستقطب في مستوى واحد، ثم يُمرَّر خلال كل محلول على حدة، ويُلاحظ اتجاه دوران مستوى الاستقطاب: أحد المتشكلين يديره إلى اليمين (مع عقارب الساعة) والآخر إلى اليسار (عكس عقارب الساعة). العلاقة بالتسمية: الخاصية التي تميزهما هي تأثيرهما في الضوء المستقطب المار خلالهما (الدوران الضوئي)، ولهذا سُميت متشكلات ضوئية.', '["بيان أن الخصائص الفيزيائية المذكورة لا تميزهما","استعمال ضوء مستقطب (مرشح استقطاب)","ملاحظة اتجاه دوران مستوى الاستقطاب لكل محلول","الاتجاهان متعاكسان","ربط الطريقة بسبب التسمية"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن الخصائص الفيزيائية المذكورة لا تميزهما","marks":1},{"element":"استعمال ضوء مستقطب (مرشح استقطاب)","marks":1},{"element":"ملاحظة اتجاه دوران مستوى الاستقطاب لكل محلول","marks":1},{"element":"الاتجاهان متعاكسان","marks":1},{"element":"ربط الطريقة بسبب التسمية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: بيان أن الخصائص الفيزيائية المذكورة لا تميزهما؛ استعمال ضوء مستقطب (مرشح استقطاب)؛ ملاحظة اتجاه دوران مستوى الاستقطاب لكل محلول؛ الاتجاهان متعاكسان؛ ربط الطريقة بسبب التسمية"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح درجة لكل عنصر صحيح من عناصر الإجابة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح قياس درجة الغليان أو الكثافة للتمييز","اقتراح تمرير ضوء عادي دون استقطاب","القول إن أحد المحلولين فقط يؤثر في الضوء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.619Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
