('mcq', 3, 'يبين الشكل الآتي أربعة من المتشكلات البنائية للصيغة الجزيئية C₆H₁₄. أيّ الصيغ البنائية المكثفة الآتية تمثل متشكلًا آخر لهذه الصيغة غير مرسوم في الشكل؟', null, '[{"src":"qimg/chem22/c4-l4b-c6h14-missing.svg","alt":"أربع صيغ بنائية مكثفة مرقمة. (1): سلسلة مستقيمة CH₃–CH₂–CH₂–CH₂–CH₂–CH₃. (2): سلسلة CH₃–CH–CH₂–CH₂–CH₃ ترتبط فيها مجموعة CH₃ فرعية بذرة الكربون الثانية. (3): سلسلة CH₃–CH₂–CH–CH₂–CH₃ ترتبط فيها مجموعة CH₃ فرعية بذرة الكربون الثالثة. (4): سلسلة CH₃–C–CH₂–CH₃ ترتبط فيها مجموعتا CH₃ فرعيتان بذرة الكربون الثانية."}]'::jsonb, '["CH₃CH₂CH₂CH(CH₃)CH₃","CH₃CH(CH₃)CH₂CH₂CH₂CH₃","CH₃CH₂CH(CH₂CH₃)CH₃","CH₃CH(CH₃)CH(CH₃)CH₃"]'::jsonb, 'تطبيق', 'إكمال قائمة المتشكلات', 'متوسط', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 4, 'رسم طالب الصيغ الأربع في الشكل الآتي على أنها متشكلات للصيغة الجزيئية C₅H₁₂. كم مركبًا مختلفًا تمثل هذه الصيغ فعلًا؟', null, '[{"src":"qimg/chem22/c4-l4b-c5h12-drawings.svg","alt":"أربع صيغ بنائية مكثفة مرقمة. (1): سلسلة مستقيمة أفقية CH₃–CH₂–CH₂–CH₂–CH₃. (2): سلسلة أفقية CH₃–CH₂–CH₂–CH₂ ترتبط بذرة الكربون الأخيرة فيها (CH₂) مجموعة CH₃ مرسومة إلى الأسفل. (3): سلسلة CH₃–CH–CH₂–CH₃ ترتبط فيها مجموعة CH₃ مرسومة إلى الأعلى بذرة الكربون الثانية من اليسار. (4): سلسلة CH₃–CH₂–CH–CH₃ ترتبط فيها مجموعة CH₃ مرسومة إلى الأسفل بذرة الكربون الثالثة من اليسار."}]'::jsonb, '["مركبين فقط","ثلاثة مركبات","أربعة مركبات","مركبًا واحدًا"]'::jsonb, 'تحليل', 'اكتشاف التكرار في المتشكلات', 'صعب', 'الكتاب ص 143 — المتشكلات البنائية'),
('mcq', 5, 'أيّ الصيغ البنائية المكثفة الآتية تمثل متشكلًا بنائيًّا للمركب 1-بيوتين CH₂=CHCH₂CH₃؟', null, null, '["CH₃CH₂CH₂CH₃","CH₂=C(CH₃)CH₃","CH≡CCH₂CH₃","CH₂=CHCH₂CH₂CH₃"]'::jsonb, 'تطبيق', 'تحديد متشكل بنائي', 'سهل', 'الكتاب ص 143، 161 — المتشكلات البنائية (س70)'),
('mcq', 6, 'يبين الشكل الآتي هياكل كربونية (تظهر فيها ذرات الكربون فقط) كتبها طالب على أنها متشكلات للصيغة الجزيئية C₆H₁₄. أيّ هيكل منها لا يمثل متشكلًا لهذه الصيغة؟', null, '[{"src":"qimg/chem22/c4-l4b-skeletons.svg","alt":"أربعة هياكل كربونية مرقمة تظهر فيها ذرات الكربون (C) والروابط بينها فقط. (1): سلسلة أفقية من خمس ذرات كربون، ترتبط بذرة الكربون الثانية ذرة كربون فرعية واحدة في الأعلى. (2): سلسلة أفقية من أربع ذرات كربون، ترتبط بكل من ذرتي الكربون الثانية والثالثة ذرة كربون فرعية في الأعلى. (3): سلسلة أفقية من ست ذرات كربون، ترتبط بذرة الكربون الثالثة ذرة كربون فرعية في الأعلى. (4): سلسلة أفقية من أربع ذرات كربون، ترتبط بذرة الكربون الثانية ذرتا كربون فرعيتان، إحداهما في الأعلى والأخرى في الأسفل."}]'::jsonb, '["(1)","(2)","(3)","(4)"]'::jsonb, 'تطبيق', 'التحقق من الصيغة الجزيئية لهيكل', 'سهل', 'الكتاب ص 148 — التقويم 4-4 (س25)'),
('mcq', 7, 'عند كتابة متشكلات C₆H₁₄ التي سلسلتها الرئيسة خمس ذرات كربون وفيها مجموعة ميثيل فرعية واحدة، على أيّ ذرات الكربون في السلسلة الرئيسة يمكن وضع مجموعة الميثيل للحصول على متشكلات مختلفة؟', null, null, '["على ذرة الكربون 2 أو 3 فقط","على ذرة الكربون 1 أو 2 أو 3","على ذرة الكربون 2 أو 3 أو 4","على ذرة الكربون 3 فقط"]'::jsonb, 'تحليل', 'استراتيجية كتابة المتشكلات', 'صعب', 'الكتاب ص 143 — المتشكلات البنائية'),
('essay', 1, 'اكتب الصيغ البنائية المكثفة للمتشكلات البنائية المحتملة جميعها للصيغة الجزيئية C₅H₁₂، وسمِّ كلًّا منها، ثم فسّر لماذا لا تمثل الصيغة CH₃CH₂CH(CH₃)CH₃ متشكلًا رابعًا.', null, null, null, 'تطبيق', 'كتابة المتشكلات وتسميتها', 'متوسط', 'الكتاب ص 143 — المتشكلات البنائية'),
('essay', 2, 'اكتب صيغًا بنائية مكثفة لأربعة متشكلات مختلفة تحمل الصيغة الجزيئية C₄H₈، وصنّف كلًّا منها إلى: ألكين غير متفرع، أو ألكين متفرع، أو ألكان حلقي.', null, null, null, 'تطبيق', 'كتابة المتشكلات', 'متوسط', 'الكتاب ص 161 — تقويم الفصل (س70)'),
('essay', 3, 'كتب طالب الصيغ في الشكل الآتي على أنها المتشكلات البنائية المحتملة جميعها للصيغة الجزيئية C₆H₁₄. قوّم عمله: حدّد الصيغة المكررة، والصيغة التي لا تنتمي إلى هذه الصيغة الجزيئية مع التعليل، ثم اكتب الصيغ الناقصة وسمّها.', null, '[{"src":"qimg/chem22/c4-l4b-student-list.svg","alt":"خمس صيغ بنائية مكثفة مرقمة. (1): سلسلة مستقيمة CH₃–CH₂–CH₂–CH₂–CH₂–CH₃. (2): سلسلة CH₃–CH₂–CH–CH₂–CH₃ ترتبط فيها مجموعة CH₃ في الأعلى بذرة الكربون الثالثة. (3): سلسلة CH₃–CH–CH–CH₃ ترتبط فيها مجموعة CH₃ في الأعلى بكل من ذرتي الكربون الثانية والثالثة. (4): سلسلة CH₃–CH₂–CH–CH₂–CH₃ ترتبط فيها مجموعة CH₃ مرسومة إلى الأسفل بذرة الكربون الثالثة. (5): سلسلة CH₃–C–CH₂–CH₂–CH₃ ترتبط فيها مجموعتا CH₃ (في الأعلى وفي الأسفل) بذرة الكربون الثانية."}]'::jsonb, null, 'تقويم', 'تقويم قائمة متشكلات', 'صعب', 'الكتاب ص 143، 148 — المتشكلات البنائية (س25)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
