select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في (1) السلسلة الأطول خمس ذرات كربون ومجموعة الميثيل على ذرة الكربون الثانية. وفي (3) تقع مجموعة الميثيل على ذرة الكربون الرابعة من اليسار، وهي الثانية عند الترقيم من اليمين؛ فكلتاهما 2-ميثيل بنتان، أي إن (1) و(3) تمثلان المركب نفسه.', '["(1) هي 2-ميثيل بنتان، و(2) مجموعة الميثيل فيها على ذرة الكربون الوسطى (3-ميثيل بنتان)؛ فهما متشكلان مختلفان.","(2) هي 3-ميثيل بنتان، و(4) فيها مجموعتا ميثيل على ذرة كربون واحدة (2، 2-ثنائي ميثيل بيوتان)؛ فهما مختلفان.","","(2) مجموعة الميثيل فيها على ذرة الكربون الوسطى، أما (3) فهي على ذرة الكربون الثانية من الطرف الأيمن؛ فهما مختلفان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 2, 1, 'متشكلات C₆H₁₄ خمسة: الهكسان، و2-ميثيل بنتان، و3-ميثيل بنتان، و2، 2-ثنائي ميثيل بيوتان، و2، 3-ثنائي ميثيل بيوتان.', '["يُنسى عادة أحد المتشكلين ثنائيي الميثيل (2، 2- أو 2، 3-ثنائي ميثيل بيوتان) فيُعدّ أربعة فقط.","","يحدث هذا عند عدّ 2-ميثيل بنتان مرتين، مرة بالميثيل على الكربون 2 ومرة على الكربون 4، وهما المركب نفسه.","ثلاثة هو عدد متشكلات C₅H₁₂ لا C₆H₁₄؛ فعدد المتشكلات يزداد بزيادة عدد ذرات الكربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 3, 3, 'المتشكلات المرسومة: الهكسان، و2-ميثيل بنتان، و3-ميثيل بنتان، و2، 2-ثنائي ميثيل بيوتان. والصيغة CH₃CH(CH₃)CH(CH₃)CH₃ (2، 3-ثنائي ميثيل بيوتان) فيها 6 ذرات كربون و14 ذرة هيدروجين وترتيب مختلف عن الأربعة؛ فهي متشكل آخر غير مرسوم.', '["هذه الصيغة هي 2-ميثيل بنتان مكتوبًا من الطرف الآخر، وهو المركب (2) المرسوم في الشكل.","في هذه الصيغة 7 ذرات كربون (2-ميثيل هكسان C₇H₁₆)؛ فليست متشكلًا لـ C₆H₁₄.","السلسلة الأطول هنا CH₃CH₂CH–CH₂CH₃ (خمس ذرات) والميثيل على الكربون 3؛ فهي 3-ميثيل بنتان، أي المركب (3) المرسوم في الشكل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 4, 0, '(1) و(2) سلسلة متصلة من خمس ذرات كربون دون تفرع؛ فكلتاهما بنتان، وانحناء السلسلة في الرسم لا يغير ترتيب ارتباط الذرات. و(3) و(4) سلسلة من أربع ذرات بفرع ميثيل على الكربون الثاني من أحد الطرفين؛ فكلتاهما 2-ميثيل بيوتان. إذن تمثل الصيغ مركبين فقط.', '["","ثلاثة مركبات تنتج عند عدّ (2) متشكلًا جديدًا متفرعًا، مع أن سلسلتها متصلة من خمس ذرات كربون بلا فرع (بنتان).","الصيغ الأربع ليست مختلفة؛ فاختلاف طريقة الرسم أو اتجاه الفرع لا يعني اختلاف المركب.","الصيغ ليست كلها مركبًا واحدًا؛ ففي (3) و(4) فرع ميثيل وسلسلة رئيسة من أربع ذرات، وهذا ترتيب يختلف عن البنتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 5, 1, 'صيغة 1-بيوتين الجزيئية C₄H₈. والمركب CH₂=C(CH₃)CH₃ (2-ميثيل بروبين) صيغته الجزيئية C₄H₈ أيضًا، لكن ذراته مرتبة في سلسلة متفرعة؛ فهو متشكل بنائي لـ 1-بيوتين.', '["هذا البيوتان C₄H₁₀؛ فيه ذرتا هيدروجين أكثر، فليس له الصيغة الجزيئية نفسها.","","هذا 1-بيوتاين C₄H₆؛ فيه رابطة ثلاثية وذرتا هيدروجين أقل.","هذا 1-بنتين C₅H₁₀؛ فيه خمس ذرات كربون، فهو من السلسلة المتماثلة نفسها وليس متشكلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 6, 2, 'في الهيكل (3) سلسلة من ست ذرات كربون وفرع من ذرة كربون واحدة، أي 7 ذرات كربون؛ فصيغته C₇H₁₆ (3-ميثيل هكسان)، وليس متشكلًا لـ C₆H₁₄.', '["الهيكل (1) فيه 5 + 1 = 6 ذرات كربون (2-ميثيل بنتان)؛ فهو متشكل لـ C₆H₁₄.","الهيكل (2) فيه 4 + 2 = 6 ذرات كربون (2، 3-ثنائي ميثيل بيوتان)؛ فهو متشكل لـ C₆H₁₄.","","الهيكل (4) فيه 4 + 2 = 6 ذرات كربون (2، 2-ثنائي ميثيل بيوتان)؛ فهو متشكل لـ C₆H₁₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('mcq', 7, 0, 'الميثيل على الكربون 2 يعطي 2-ميثيل بنتان، وعلى الكربون 3 يعطي 3-ميثيل بنتان. أما وضعه على الكربون 4 فيعطي 2-ميثيل بنتان نفسه عند الترقيم من الطرف الآخر، ووضعه على الكربون 1 يطيل السلسلة إلى ست ذرات (هكسان). إذن الكربون 2 أو 3 فقط.', '["","الميثيل على ذرة الكربون الطرفية 1 يجعل السلسلة الأطول ست ذرات، فينتج الهكسان لا متشكل سلسلته خمس ذرات.","الميثيل على الكربون 4 يعطي 2-ميثيل بنتان نفسه بالترقيم من الطرف الآخر، فهو تكرار.","الاقتصار على الكربون 3 يُسقط المتشكل 2-ميثيل بنتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.620Z"}'::jsonb),
('essay', 1, null::int, null, null, 'للصيغة C₅H₁₂ ثلاثة متشكلات: CH₃CH₂CH₂CH₂CH₃ (بنتان)، وCH₃CH(CH₃)CH₂CH₃ (2-ميثيل بيوتان)، وCH₃C(CH₃)₂CH₃ (2، 2-ثنائي ميثيل بروبان). أما CH₃CH₂CH(CH₃)CH₃ فسلسلتها الأطول أربع ذرات كربون، ومجموعة الميثيل فيها على الكربون الثالث من اليسار، وهو الثاني عند الترقيم من اليمين؛ فهي 2-ميثيل بيوتان نفسه مكتوبًا من الطرف الآخر، وليست متشكلًا جديدًا.', '["صيغة البنتان واسمه","صيغة 2-ميثيل بيوتان واسمه","صيغة 2، 2-ثنائي ميثيل بروبان واسمه","تحديد أن الصيغة المعطاة هي 2-ميثيل بيوتان","التعليل بالترقيم من الطرف الأقرب إلى الفرع"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة البنتان واسمه","marks":1},{"element":"صيغة 2-ميثيل بيوتان واسمه","marks":1},{"element":"صيغة 2، 2-ثنائي ميثيل بروبان واسمه","marks":1},{"element":"تحديد أن الصيغة المعطاة هي 2-ميثيل بيوتان","marks":1},{"element":"التعليل بالترقيم من الطرف الأقرب إلى الفرع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: صيغة البنتان واسمه؛ صيغة 2-ميثيل بيوتان واسمه؛ صيغة 2، 2-ثنائي ميثيل بروبان واسمه؛ تحديد أن الصيغة المعطاة هي 2-ميثيل بيوتان؛ التعليل بالترقيم من الطرف الأقرب إلى الفرع"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الصيغة المعطاة متشكلًا رابعًا","كتابة 3-ميثيل بيوتان اسمًا للصيغة المعطاة","كتابة صيغة فيها ست ذرات كربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من متشكلات C₄H₈: (1) CH₂=CHCH₂CH₃ (1-بيوتين) ألكين غير متفرع. (2) CH₃CH=CHCH₃ (2-بيوتين) ألكين غير متفرع. (3) CH₂=C(CH₃)CH₃ (2-ميثيل بروبين) ألكين متفرع. (4) بيوتان حلقي: حلقة من أربع مجموعات CH₂ مرتبطة بروابط أحادية، وهو ألكان حلقي. ويُقبل أيضًا ميثيل بروبان حلقي (حلقة من ثلاث ذرات كربون ترتبط بإحداها مجموعة CH₃) ألكانًا حلقيًّا. وفي كل منها 4 ذرات كربون و8 ذرات هيدروجين.', '["المتشكل الأول صحيح","المتشكل الثاني صحيح","المتشكل الثالث صحيح","المتشكل الرابع صحيح","تصنيف المتشكلات الأربعة تصنيفًا صحيحًا"]'::jsonb, '["حساب درجة عدم التشبع: C₄H₈ تطابق CₙH₂ₙ، فالمركب ألكين أو ألكان حلقي","تحريك موقع الرابطة الثنائية في السلسلة غير المتفرعة (1-بيوتين، 2-بيوتين)","تفريع السلسلة مع رابطة ثنائية (2-ميثيل بروبين)","إغلاق السلسلة في حلقة (بيوتان حلقي، ميثيل بروبان حلقي)"]'::jsonb, '[{"element":"المتشكل الأول صحيح","marks":1},{"element":"المتشكل الثاني صحيح","marks":1},{"element":"المتشكل الثالث صحيح","marks":1},{"element":"المتشكل الرابع صحيح","marks":1},{"element":"تصنيف المتشكلات الأربعة تصنيفًا صحيحًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: المتشكل الأول صحيح؛ المتشكل الثاني صحيح؛ المتشكل الثالث صحيح؛ المتشكل الرابع صحيح؛ تصنيف المتشكلات الأربعة تصنيفًا صحيحًا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة البيوتان C₄H₁₀ ضمن المتشكلات","كتابة CH₃CH₂CH=CH₂ و CH₂=CHCH₂CH₃ على أنهما متشكلان مختلفان وهما المركب نفسه","نسيان أن الألكانات الحلقية لها الصيغة العامة CₙH₂ₙ مثل الألكينات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) هكسان، و(2) 3-ميثيل بنتان، و(3) 2، 3-ثنائي ميثيل بيوتان صحيحة. (4) مكررة: هي 3-ميثيل بنتان نفسه، ورسم الميثيل إلى الأسفل لا يغير المركب. (5) فيها 5 + 2 = 7 ذرات كربون، فهي 2، 2-ثنائي ميثيل بنتان C₇H₁₆ وليست من متشكلات C₆H₁₄. الناقصتان: CH₃CH(CH₃)CH₂CH₂CH₃ (2-ميثيل بنتان)، وCH₃C(CH₃)₂CH₂CH₃ (2، 2-ثنائي ميثيل بيوتان).', '["تحديد (4) مكررة لـ (2) مع التعليل","تحديد (5) أنها C₇H₁₆ مع التعليل","كتابة صيغة 2-ميثيل بنتان","كتابة صيغة 2، 2-ثنائي ميثيل بيوتان","تسمية الصيغتين الناقصتين"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد (4) مكررة لـ (2) مع التعليل","marks":1},{"element":"تحديد (5) أنها C₇H₁₆ مع التعليل","marks":1},{"element":"كتابة صيغة 2-ميثيل بنتان","marks":1},{"element":"كتابة صيغة 2، 2-ثنائي ميثيل بيوتان","marks":1},{"element":"تسمية الصيغتين الناقصتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد (4) مكررة لـ (2) مع التعليل؛ تحديد (5) أنها C₇H₁₆ مع التعليل؛ كتابة صيغة 2-ميثيل بنتان؛ كتابة صيغة 2، 2-ثنائي ميثيل بيوتان؛ تسمية الصيغتين الناقصتين"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (4) متشكلًا مختلفًا لأن الفرع مرسوم إلى الأسفل","عدم عدّ ذرات الكربون في (5) والاكتفاء بشكلها","إضافة 4-ميثيل بنتان متشكلًا ناقصًا وهو 2-ميثيل بنتان نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
