select (select id from public.objectives where code = 'K22-C4-L4-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما اسم المتشكل (1) في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l4b-4-octene.svg","alt":"صيغتان بنائيتان مرقمتان، في كل منهما ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا. في (1): ذرة الكربون اليسرى ترتبط بـ CH₃CH₂CH₂ في الأعلى وH في الأسفل، وذرة الكربون اليمنى ترتبط بـ CH₂CH₂CH₃ في الأعلى وH في الأسفل. في (2): ذرة الكربون اليسرى ترتبط بـ CH₃CH₂CH₂ في الأعلى وH في الأسفل، وذرة الكربون اليمنى ترتبط بـ H في الأعلى وCH₂CH₂CH₃ في الأسفل."}]'::jsonb, '["ترانس-4-أوكتين","سيس-4-أوكتين","سيس-3-أوكتين","ترانس-3-أوكتين"]'::jsonb, 'تطبيق', 'تسمية متشكل من شكل', 'متوسط', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 2, 'أيّ الصيغ الهيكلية في الشكل الآتي يمثل سيس-2-هكسين؟', null, '[{"src":"qimg/chem22/c4-l4b-hexene-skeletal.svg","alt":"أربع صيغ هيكلية مرقمة لسلاسل من ست ذرات كربون (كل رأس أو طرف خط يمثل ذرة كربون، وذرات الهيدروجين غير مرسومة). (1): رابطة ثنائية بين ذرتي الكربون الثانية والثالثة، وذرة الكربون الأولى وذرة الكربون الرابعة كلتاهما في الجهة نفسها من الرابطة الثنائية، فتنحني السلسلة عندها. (2): رابطة ثنائية بين ذرتي الكربون الثانية والثالثة، وذرة الكربون الأولى وذرة الكربون الرابعة في جهتين متقابلتين منها، والسلسلة متعرجة ممتدة. (3): رابطة ثنائية بين ذرتي الكربون الأولى والثانية في طرف السلسلة. (4): رابطة ثنائية بين ذرتي الكربون الثالثة والرابعة، وذرتا الكربون الثانية والخامسة في جهتين متقابلتين منها."}]'::jsonb, '["(1)","(2)","(3)","(4)"]'::jsonb, 'تطبيق', 'تمييز من صيغة هيكلية', 'صعب', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 3, 'يريد طالب رسم المتشكل سيس-3-هبتين CH₃CH₂CH=CHCH₂CH₂CH₃. أيّ وصف يمثل الترتيب الصحيح للمجموعات حول الرابطة الثنائية في رسمه؟', null, null, '["مجموعة الإيثيل في جهة من الرابطة الثنائية، ومجموعة البروبيل في الجهة المقابلة لها","مجموعتا الإيثيل والبروبيل مرتبطتان بذرة الكربون نفسها من ذرتي الرابطة الثنائية","مجموعتا الإيثيل والبروبيل في جهة واحدة من الرابطة الثنائية، وذرتا الهيدروجين في الجهة الأخرى","ترتيب المجموعات غير مهم؛ لأن ذرتي الرابطة الثنائية تدوران بحرية فيتحول سيس إلى ترانس"]'::jsonb, 'تطبيق', 'رسم متشكل سيس', 'سهل', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 4, 'يمثل الشكل الآتي جزءًا من صيغة جزيء 2-هكسين، وفيه مجموعتان مجهولتان X وY. ما المجموعتان X وY اللتان تجعلان الصيغة تمثل ترانس-2-هكسين؟', null, '[{"src":"qimg/chem22/c4-l4b-complete-trans.svg","alt":"صيغة بنائية فيها ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا. ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وH في الأسفل. ذرة الكربون اليمنى ترتبط بمجموعة مجهولة X في الأعلى ومجموعة مجهولة Y في الأسفل."}]'::jsonb, '["X = CH₂CH₂CH₃ و Y = H","X = H و Y = CH₂CH₃","X = CH₃ و Y = CH₂CH₂CH₃","X = H و Y = CH₂CH₂CH₃"]'::jsonb, 'تطبيق', 'إكمال صيغة متشكل ترانس', 'متوسط', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 5, 'أيّ المركبات الآتية يمكن رسمه في صورة متشكلين: سيس وترانس؟', null, null, '["CH₂=CHCH₂CH₂CH₃","(CH₃)₂C=CHCH₃","CH₃CH=CHCH₂CH₂CH₂CH₃","CH₂=C(CH₃)CH₂CH₃"]'::jsonb, 'تطبيق', 'تمييز الألكين الذي له متشكلا سيس وترانس', 'سهل', 'الكتاب ص 144–145 — المتشكلات الهندسية'),
('mcq', 6, 'رُسمت الرابطة الثنائية في الصيغة الآتية رأسيًّا. ما اسم هذا المتشكل؟', null, '[{"src":"qimg/chem22/c4-l4b-vertical.svg","alt":"صيغة بنائية فيها ذرتا كربون بينهما رابطة ثنائية مرسومة رأسيًّا (ذرة كربون في الأعلى وأخرى في الأسفل). ذرة الكربون العليا ترتبط بـ CH₃ إلى اليسار وH إلى اليمين. ذرة الكربون السفلى ترتبط بـ CH₂CH₃ إلى اليسار وH إلى اليمين."}]'::jsonb, '["سيس-2-بنتين؛ لأن مجموعتي CH₃ وCH₂CH₃ في الجهة نفسها (اليسرى) من الرابطة الثنائية","ترانس-2-بنتين؛ لأن إحدى مجموعتي الألكيل في الأعلى والأخرى في الأسفل","سيس-3-بنتين؛ لأن مجموعتي الألكيل في الجهة نفسها من الرابطة الثنائية","ترانس-2-بنتين؛ لأن ذرتي الهيدروجين في الجهة اليمنى من الرابطة الثنائية"]'::jsonb, 'تحليل', 'تمييز متشكل مرسوم باتجاه غير مألوف', 'صعب', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 7, 'عند رسم متشكلي سيس-2-هكسين وترانس-2-هكسين، أيّ مما يأتي يبقى كما هو في الرسمين؟', null, null, '["اتجاه مجموعتي الألكيل في الفراغ بالنسبة إلى الرابطة الثنائية","الصيغة الجزيئية فقط، أما ترتيب ارتباط الذرات بعضها ببعض فيختلف","موقع الرابطة الثنائية فقط، أما الصيغة الجزيئية فتختلف","الصيغة الجزيئية C₆H₁₂ وترتيب ارتباط الذرات بعضها ببعض"]'::jsonb, 'فهم', 'المقارنة بين رسمي متشكلين', 'سهل', 'الكتاب ص 144، 148 — المتشكلات الفراغية'),
('essay', 1, 'اكتب الصيغتين البنائيتين لمتشكلي سيس وترانس للمركب 4-ميثيل-2-بنتين CH₃CH=CHCH(CH₃)CH₃، وسمِّ كلًّا منهما، ثم بيّن كيف تميّز بينهما من الرسم.', null, null, null, 'تطبيق', 'رسم متشكلين وتسميتهما', 'متوسط', 'الكتاب ص 144، 161 — المتشكلات الفراغية (س72)'),
('essay', 2, 'حدّد نوع المتشكل الممثل في الشكل الآتي (سيس أم ترانس) مع التعليل، ثم ارسم متشكله الهندسي الآخر، واكتب اسم كل منهما، ثم فسّر لماذا لا يتحول أحدهما إلى الآخر بسهولة.', null, '[{"src":"qimg/chem22/c4-l4b-trans-2-hexene.svg","alt":"صيغة بنائية فيها ذرتا كربون بينهما رابطة ثنائية C=C مرسومة أفقيًّا. ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وH في الأسفل، وذرة الكربون اليمنى ترتبط بـ H في الأعلى وCH₂CH₂CH₃ في الأسفل."}]'::jsonb, null, 'تطبيق', 'تمييز متشكل ورسم الآخر', 'متوسط', 'الكتاب ص 144 — المتشكلات الفراغية'),
('essay', 3, 'عيّن زوج المتشكلات الهندسية من بين الصيغ الثلاث في الشكل الآتي، مبيّنًا سبب اختيارك، ثم فسّر علاقة الصيغة الثالثة بالصيغتين الأخريين، وبيّن لماذا لا يوجد لها متشكل هندسي.', null, '[{"src":"qimg/chem22/c4-l4b-q71.svg","alt":"ثلاث صيغ بنائية مرقمة، في كل منها رابطة ثنائية C=C أفقية. (1): ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وCH₃ في الأسفل، وذرة الكربون اليمنى ترتبط بـ CH₃ في الأعلى وCH₂CH₂CH₃ في الأسفل. (2): ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وCH₃CH₂ في الأسفل، وذرة الكربون اليمنى ترتبط بـ CH₂CH₃ في الأعلى وCH₃ في الأسفل. (3): ذرة الكربون اليسرى ترتبط بـ CH₃ في الأعلى وCH₃CH₂ في الأسفل، وذرة الكربون اليمنى ترتبط بـ CH₃ في الأعلى وCH₂CH₃ في الأسفل."}]'::jsonb, null, 'تحليل', 'تمييز المتشكلات الهندسية من البنائية', 'صعب', 'الكتاب ص 161 — تقويم الفصل (س71)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
