select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'السلسلة ثماني ذرات كربون والرابطة الثنائية بين ذرتي الكربون الرابعة والخامسة (4-أوكتين). وفي (1) مجموعتا البروبيل CH₃CH₂CH₂ وCH₂CH₂CH₃ كلتاهما في الأعلى، أي في الجهة نفسها من الرابطة الثنائية؛ فهو سيس-4-أوكتين.', '["ترانس تعني أن مجموعتي الألكيل في جهتين متقابلتين، وهذا وصف المتشكل (2) لا (1).","","الرابطة الثنائية بين الكربونين 4 و5 من أي طرف رُقّمت السلسلة؛ لأن على كل جانب ثلاث ذرات كربون، فالرقم 3 خاطئ.","الرقم 3 خاطئ لموقع الرابطة الثنائية، وترانس لا تصف (1) لأن مجموعتي الألكيل فيه في الجهة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('mcq', 2, 0, 'في (1) الرابطة الثنائية بين ذرتي الكربون الثانية والثالثة، وذرتا الكربون الأولى والرابعة (بداية مجموعتي الألكيل) في الجهة نفسها من الرابطة الثنائية فتنحني السلسلة عندها؛ فهو سيس-2-هكسين.', '["","في (2) الرابطة الثنائية في الموقع 2، لكن مجموعتي الألكيل في جهتين متقابلتين؛ فهو ترانس-2-هكسين.","في (3) الرابطة الثنائية في طرف السلسلة (1-هكسين)، وذرة الكربون الطرفية ترتبط بذرتي هيدروجين فلا يكون لها متشكل سيس أو ترانس.","في (4) الرابطة الثنائية بين الكربونين 3 و4 ومجموعتا الإيثيل متقابلتان؛ فهو ترانس-3-هكسين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('mcq', 3, 2, 'في سيس تكون المجموعتان المتشابهتان (مجموعتا الألكيل: الإيثيل على إحدى ذرتي الرابطة الثنائية والبروبيل على الأخرى) في الجهة نفسها من الرابطة الثنائية، فتقع ذرتا الهيدروجين معًا في الجهة الأخرى.', '["هذا وصف المتشكل ترانس-3-هبتين؛ فمجموعتا الألكيل فيه في جهتين متقابلتين.","كل ذرة من ذرتي الرابطة الثنائية في 3-هبتين ترتبط بمجموعة ألكيل واحدة وذرة هيدروجين واحدة، فلا تجتمع المجموعتان على ذرة واحدة.","","ذرتا الكربون المرتبطتان برابطة ثنائية لا تستطيعان الدوران، فلا يتحول سيس بسهولة إلى ترانس، والترتيب هو ما يميز المتشكلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('mcq', 4, 3, '2-هكسين CH₃CH=CHCH₂CH₂CH₃: ذرة الكربون اليمنى في الرابطة الثنائية ترتبط بذرة H ومجموعة بروبيل CH₂CH₂CH₃. ولأن CH₃ في الأعلى على ذرة الكربون اليسرى، يجب أن تكون مجموعة البروبيل في الأسفل ليكون المتشكل ترانس؛ إذن X = H وY = CH₂CH₂CH₃.', '["بهذا تصبح مجموعتا CH₃ وCH₂CH₂CH₃ كلتاهما في الأعلى، فيكون المتشكل سيس-2-هكسين.","المجموعة CH₂CH₃ تجعل عدد ذرات الكربون خمسًا، فينتج ترانس-2-بنتين لا 2-هكسين.","ترتبط ذرة الكربون اليمنى في 2-هكسين بذرة هيدروجين واحدة؛ ووضع CH₃ وCH₂CH₂CH₃ معًا يغير المركب إلى مركب آخر صيغته C₇H₁₄.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.621Z"}'::jsonb),
('mcq', 5, 2, 'في CH₃CH=CHCH₂CH₂CH₂CH₃ (2-هبتين) ترتبط كل ذرة من ذرتي الرابطة الثنائية بمجموعتين مختلفتين (H ومجموعة ألكيل: CH₃ على إحداهما وCH₂CH₂CH₂CH₃ على الأخرى)، فيمكن أن تكون مجموعتا الألكيل في الجهة نفسها (سيس) أو في جهتين متقابلتين (ترانس).', '["ذرة الكربون الطرفية في الرابطة الثنائية (CH₂=) ترتبط بذرتي هيدروجين متماثلتين، فلا يوجد ترتيبان مختلفان.","إحدى ذرتي الرابطة الثنائية ترتبط بمجموعتي CH₃ متماثلتين، فتبديلهما لا ينتج مركبًا جديدًا.","","ذرة الكربون CH₂= ترتبط بذرتي هيدروجين متماثلتين، فلا يكون للمركب متشكلا سيس وترانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('mcq', 6, 0, 'الرابطة الثنائية رأسية، فجهتاها هما اليسار واليمين. مجموعتا CH₃ وCH₂CH₃ كلتاهما إلى اليسار، وذرتا H إلى اليمين؛ فالمجموعتان في الجهة نفسها، والمركب CH₃CH=CHCH₂CH₃ هو سيس-2-بنتين.', '["","الأعلى والأسفل هنا على امتداد الرابطة الثنائية نفسها لا على جانبيها؛ فالمهم أن المجموعتين كلتيهما إلى اليسار.","ترقيم السلسلة يبدأ من الطرف الأقرب إلى الرابطة الثنائية فيكون موقعها 2 لا 3.","وقوع ذرتي الهيدروجين معًا في جهة واحدة يعني أن مجموعتي الألكيل معًا في الجهة الأخرى، وهذا سيس لا ترانس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('mcq', 7, 3, 'سيس وترانس متشكلات فراغية: ترتبط فيها الذرات بالترتيب نفسه ولها الصيغة الجزيئية نفسها C₆H₁₂، ولا يختلف الرسمان إلا في اتجاه المجموعات في الفراغ حول الرابطة الثنائية.', '["اتجاه مجموعتي الألكيل هو ما يتغير بين الرسمين: في الجهة نفسها في سيس، وفي جهتين متقابلتين في ترانس.","اختلاف ترتيب ارتباط الذرات يميز المتشكلات البنائية، أما في سيس وترانس فالترتيب واحد.","الصيغة الجزيئية واحدة في المتشكلين C₆H₁₂؛ فالمتشكلات لها الصيغة الجزيئية نفسها دائمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ذرتا الرابطة الثنائية: الأولى ترتبط بـ CH₃ وH، والثانية ترتبط بـ CH(CH₃)₂ وH. سيس-4-ميثيل-2-بنتين: CH₃ في الأعلى على ذرة الكربون اليسرى وCH(CH₃)₂ في الأعلى على ذرة الكربون اليمنى، وذرتا H في الأسفل. ترانس-4-ميثيل-2-بنتين: CH₃ في الأعلى على اليسرى وCH(CH₃)₂ في الأسفل على اليمنى، وذرتا H متقابلتان. التمييز: في سيس تكون مجموعتا الألكيل في الجهة نفسها من الرابطة الثنائية، وفي ترانس في جهتين متقابلتين.', '["رسم متشكل سيس صحيحًا","رسم متشكل ترانس صحيحًا","الاسمان صحيحان","التمييز بموقع مجموعتي الألكيل"]'::jsonb, '[]'::jsonb, '[{"element":"رسم متشكل سيس صحيحًا","marks":1},{"element":"رسم متشكل ترانس صحيحًا","marks":1},{"element":"الاسمان صحيحان","marks":1},{"element":"التمييز بموقع مجموعتي الألكيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: رسم متشكل سيس صحيحًا؛ رسم متشكل ترانس صحيحًا؛ الاسمان صحيحان؛ التمييز بموقع مجموعتي الألكيل"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعة CH(CH₃)₂ وCH₃ على ذرة الكربون نفسها","رسم الرابطة الثنائية بين الكربونين 3 و4","تبديل معنى سيس وترانس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الشكل يمثل 2-هكسين CH₃CH=CHCH₂CH₂CH₃، ومجموعة CH₃ في الأعلى ومجموعة CH₂CH₂CH₃ في الأسفل، أي في جهتين متقابلتين من الرابطة الثنائية؛ فهو ترانس-2-هكسين. المتشكل الآخر: CH₃ في الأعلى على ذرة الكربون اليسرى، وCH₂CH₂CH₃ في الأعلى على ذرة الكربون اليمنى، وذرتا H في الأسفل؛ وهو سيس-2-هكسين. ولا يتحول أحدهما إلى الآخر بسهولة لأن ذرتي الكربون المرتبطتين برابطة ثنائية لا تستطيعان الدوران حولها، فيبقى ترتيب المجموعات ثابتًا.', '["تحديد أنه ترانس","التعليل بموقع مجموعتي الألكيل","رسم متشكل سيس صحيحًا","الاسمان ترانس-2-هكسين وسيس-2-هكسين","التفسير بعدم الدوران حول الرابطة الثنائية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أنه ترانس","marks":1},{"element":"التعليل بموقع مجموعتي الألكيل","marks":1},{"element":"رسم متشكل سيس صحيحًا","marks":1},{"element":"الاسمان ترانس-2-هكسين وسيس-2-هكسين","marks":1},{"element":"التفسير بعدم الدوران حول الرابطة الثنائية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد أنه ترانس؛ التعليل بموقع مجموعتي الألكيل؛ رسم متشكل سيس صحيحًا؛ الاسمان ترانس-2-هكسين وسيس-2-هكسين؛ التفسير بعدم الدوران حول الرابطة الثنائية"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بالسيس لأن ذرة H في الأسفل على كل من الطرفين","رسم المتشكل الآخر بنقل المجموعة إلى ذرة الكربون الأخرى","تسميته 4-هكسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الزوج: (2) و(3). في كل منهما ترتبط كل ذرة من ذرتي الرابطة الثنائية بـ CH₃ ومجموعة إيثيل، فترتيب ارتباط الذرات واحد والصيغة الجزيئية C₈H₁₆؛ لكن مجموعتي CH₃ في (3) في الجهة نفسها (الأعلى) ومجموعتي الإيثيل في الأسفل، أما في (2) فمجموعتا CH₃ في جهتين متقابلتين. أما (1) فصيغتها الجزيئية C₈H₁₆ أيضًا لكن ترتيب ارتباط الذرات فيها مختلف (ذرة كربون ترتبط بمجموعتي CH₃، والأخرى بـ CH₃ وبروبيل)؛ فهي متشكل بنائي لـ (2) و(3). ولا يوجد لها متشكل هندسي لأن إحدى ذرتي الرابطة الثنائية ترتبط بمجموعتين متماثلتين (CH₃ وCH₃)، فتبديل موقعيهما لا ينتج مركبًا مختلفًا.', '["تحديد الزوج (2) و(3)","التعليل: ترتيب الارتباط نفسه مع اختلاف الاتجاه في الفراغ","(1) متشكل بنائي للصيغتين مع ذكر الصيغة الجزيئية المشتركة","سبب عدم وجود متشكل هندسي لـ (1): مجموعتان متماثلتان على ذرة واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الزوج (2) و(3)","marks":1},{"element":"التعليل: ترتيب الارتباط نفسه مع اختلاف الاتجاه في الفراغ","marks":1},{"element":"(1) متشكل بنائي للصيغتين مع ذكر الصيغة الجزيئية المشتركة","marks":1},{"element":"سبب عدم وجود متشكل هندسي لـ (1): مجموعتان متماثلتان على ذرة واحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد الزوج (2) و(3)؛ التعليل: ترتيب الارتباط نفسه مع اختلاف الاتجاه في الفراغ؛ (1) متشكل بنائي للصيغتين مع ذكر الصيغة الجزيئية المشتركة؛ سبب عدم وجود متشكل هندسي لـ (1): مجموعتان متماثلتان على ذرة واحدة"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (1) و(3) متشكلين هندسيين لأن مجموعتي CH₃ في الأعلى في كليهما","عدّ (1) مركبًا ليس له الصيغة الجزيئية نفسها","الخلط بين المتشكلات البنائية والهندسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb)
