('mcq', 1, 'يمثل الشكل الآتي رسمين لجزيء البيوتان CH₃CH₂CH₂CH₃ حول الرابطة الأحادية بين ذرتي الكربون الوسطيين. ما العلاقة بين الرسمين؟', null, '[{"src":"qimg/chem22/c4-l4b-butane-rot.svg","alt":"رسمان مرقمان لجزيء البيوتان حول الرابطة الأحادية بين ذرتي الكربون الوسطيين C–C المرسومة أفقيًّا. في كل رسم ترتبط ذرة الكربون اليسرى بـ CH₃ في الأعلى وH في الأسفل وH إلى اليسار. في (1): ذرة الكربون اليمنى ترتبط بـ CH₃ في الأعلى وH في الأسفل وH إلى اليمين. في (2): ذرة الكربون اليمنى ترتبط بـ H في الأعلى وCH₃ في الأسفل وH إلى اليمين."}]'::jsonb, '["يمثلان المركب نفسه؛ لأن الدوران حر حول الرابطة الأحادية فيتحول أحد الترتيبين إلى الآخر","متشكلان هندسيان: (1) سيس و(2) ترانس؛ لاختلاف موقعي مجموعتي CH₃","متشكلان بنائيان؛ لأن ترتيب ارتباط الذرات بعضها ببعض مختلف فيهما","متشكلان ضوئيان؛ لأن كلًّا منهما صورة مرآة للآخر لا تنطبق عليه"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('mcq', 2, 'يختلف 2-بيوتين CH₃CH=CHCH₃ عن البيوتان CH₃CH₂CH₂CH₃ في إمكانية وجود متشكلات هندسية له. ما سبب هذا الاختلاف؟', null, null, '["لأن الصيغة الجزيئية للبيوتان C₄H₁₀ لا تسمح إلا بصيغة بنائية واحدة","لأن الدوران حر حول الرابطة الأحادية في البيوتان، وغير ممكن حول الرابطة الثنائية في 2-بيوتين","لأن ذرات الكربون في البيوتان لا ترتبط بعدد كافٍ من ذرات الهيدروجين لتكوين ترتيبين","لأن ذرتي الرابطة الثنائية في 2-بيوتين تدوران بحرية فتنتجان ترتيبين مختلفين ثابتين"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 144 — المتشكلات الفراغية'),
('mcq', 3, 'ماذا يحدث لترتيب المجموعات المرتبطة بذرتي كربون بينهما رابطة تساهمية أحادية في جزيء ألكان؟', null, null, '["يبقى ثابتًا؛ لأن الرابطة الأحادية تمنع ذرتي الكربون من الدوران","يتغير مرة واحدة فقط عند تسخين الألكان إلى درجة غليانه","يتغير باستمرار؛ لأن ذرتي الكربون تدوران حول الرابطة فلا يثبت ترتيب واحد","يبقى ثابتًا ما لم تُكسر الرابطة الأحادية ثم يُعاد تكوينها"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('mcq', 4, 'رُقمت الروابط بين ذرات الكربون في جزيء 2-هكسين في الشكل الآتي. حول أيّ رابطة يكون الدوران غير ممكن، فينشأ عن ذلك متشكلا سيس وترانس؟', null, '[{"src":"qimg/chem22/c4-l4b-hexene-bonds.svg","alt":"صيغة بنائية مكثفة أفقية لجزيء 2-هكسين: CH₃–CH=CH–CH₂–CH₂–CH₃، وتحت كل رابطة بين ذرتي كربون رقم في دائرة: الرابطة 1 بين CH₃ الأولى وCH، والرابطة 2 هي الرابطة الثنائية بين CH وCH، والرابطة 3 بين CH الثانية وCH₂، والرابطة 4 بين CH₂ وCH₂، والرابطة 5 بين CH₂ الأخيرة وCH₃."}]'::jsonb, '["الرابطة 1","الرابطة 3","الرابطة 4","الرابطة 2"]'::jsonb, 'فهم', 'تحديد موقع التشكل الهندسي', 'متوسط', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('mcq', 5, 'يمثل الشكل الآتي جزيئي الإيثان (1) والإيثين (2)، ويمثل السهم المنحني محاولة تدوير ذرة الكربون اليمنى حول محور الرابطة بين ذرتي الكربون. ماذا يحدث في كل منهما؟', null, '[{"src":"qimg/chem22/c4-l4b-ethane-ethene.svg","alt":"صيغتان بنائيتان مرقمتان. (1): الإيثان؛ ذرتا كربون بينهما رابطة أحادية C–C، وترتبط كل ذرة كربون بثلاث ذرات هيدروجين. (2): الإيثين؛ ذرتا كربون بينهما رابطة ثنائية C=C، وترتبط كل ذرة كربون بذرتي هيدروجين. بجانب ذرة الكربون اليمنى في كل جزيء سهم منحنٍ يمثل محاولة تدويرها حول محور الرابطة بين ذرتي الكربون."}]'::jsonb, '["في (1) تدور ذرة الكربون بحرية، وفي (2) تبقى ذرتا الكربون ثابتتين في موقعهما","في (1) و(2) تدور ذرة الكربون بحرية؛ لأن ذرات الهيدروجين صغيرة الحجم","في (1) تبقى ذرتا الكربون ثابتتين، وفي (2) تدور ذرة الكربون بحرية","في (1) و(2) لا تدور ذرة الكربون؛ لأن كل رابطة تساهمية تمنع الدوران"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('mcq', 6, 'ادّعى طالب أنه فصل مادتين من البيوتان، سمّى إحداهما «سيس-بيوتان» والأخرى «ترانس-بيوتان». ما التقويم الصحيح لادعائه؟', null, null, '["ادعاء صحيح؛ لأن مجموعتي CH₃ يمكن أن تكونا في جهة واحدة أو في جهتين متقابلتين","ادعاء خاطئ؛ لأن البيوتان لا يحتوي على مجموعتي CH₃ يمكن مقارنة موقعيهما","ادعاء خاطئ؛ لأن الدوران الحر حول الروابط الأحادية يحول أي ترتيب إلى الآخر فلا يثبت ترتيبان","ادعاء صحيح؛ لأن كل ألكان فيه أربع ذرات كربون أو أكثر له متشكلات هندسية"]'::jsonb, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('mcq', 7, 'أيّ المركبين الآتيين يمكن أن يوجد في صورة متشكلين هندسيين ثابتين يمكن فصلهما: الهكسان CH₃CH₂CH₂CH₂CH₂CH₃ أم 3-هكسين CH₃CH₂CH=CHCH₂CH₃؟', null, null, '["الهكسان فقط؛ لأن سلسلته مشبعة وتحتوي على عدد أكبر من الروابط","كلاهما؛ لأن في كل منهما ست ذرات كربون في سلسلة غير متفرعة","لا أحد منهما؛ لأن ذرات الكربون في كليهما تدور بحرية حول الروابط","3-هكسين فقط؛ لأن الرابطة الثنائية تثبت ترتيب المجموعات، وروابط الهكسان أحادية حرة الدوران"]'::jsonb, 'تطبيق', 'مقارنة وتطبيق', 'متوسط', 'الكتاب ص 144–145 — المتشكلات الفراغية'),
('essay', 1, 'وضّح مستعينًا بالشكل الآتي لماذا يمثل الرسمان (1) و(2) جزيء البيوتان نفسه وليس متشكلين هندسيين، ثم بيّن ما الذي يتغير لو كانت الرابطة بين ذرتي الكربون الوسطيين رابطة ثنائية كما في 2-بيوتين CH₃CH=CHCH₃.', null, '[{"src":"qimg/chem22/c4-l4b-butane-rot.svg","alt":"رسمان مرقمان لجزيء البيوتان حول الرابطة الأحادية بين ذرتي الكربون الوسطيين C–C المرسومة أفقيًّا. في كل رسم ترتبط ذرة الكربون اليسرى بـ CH₃ في الأعلى وH في الأسفل وH إلى اليسار. في (1): ذرة الكربون اليمنى ترتبط بـ CH₃ في الأعلى وH في الأسفل وH إلى اليمين. في (2): ذرة الكربون اليمنى ترتبط بـ H في الأعلى وCH₃ في الأسفل وH إلى اليمين."}]'::jsonb, null, 'فهم', 'تفسير بالاستعانة بشكل', 'متوسط', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('essay', 2, 'قال طالب: «لا يوجد متشكلات هندسية لكل من الإيثان C₂H₆ والإيثين C₂H₄، والسبب واحد في الحالتين وهو حرية الدوران». قوّم هذه العبارة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 144 — الشكل 4-18: حرية الدوران'),
('essay', 3, 'فسّر لماذا يمكن فصل متشكلين لـ 2-بنتين CH₃CH=CHCH₂CH₃ لكل منهما درجة غليان مختلفة، في حين يتخذ جزيء البنتان أشكالًا فراغية كثيرة بالدوران حول روابطه دون أن يكون له متشكلات هندسية يمكن فصلها.', null, null, null, 'فهم', 'تفسير ومقارنة', 'صعب', 'الكتاب ص 144–145 — المتشكلات الفراغية والهندسية')
