from (values
('mcq', 1, 0, 'ذرتا الكربون المرتبطتان برابطة تساهمية أحادية حرتا الدوران حول الرابطة؛ فبتدوير ذرة الكربون اليمنى في (1) تنتقل مجموعة CH₃ من الأعلى إلى الأسفل فنحصل على (2). إذن هما رسمان للمركب نفسه وليسا متشكلين.', '["","سيس وترانس يتطلبان ترتيبًا ثابتًا لا يتغير، وهذا يحدث حول الرابطة الثنائية؛ أما هنا فالرابطة أحادية والدوران حر.","ترتيب ارتباط الذرات واحد في الرسمين: CH₃–CH₂–CH₂–CH₃، فليسا متشكلين بنائيين.","لا توجد في البيوتان ذرة كربون غير متماثلة، والرسمان يتحولان أحدهما إلى الآخر بالدوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.622Z"}'::jsonb),
('mcq', 2, 1, 'حول الرابطة الأحادية في البيوتان تدور ذرتا الكربون بسهولة، فيتحول أي ترتيب للمجموعات إلى الآخر ولا يثبت ترتيب منفصل. أما الرابطة الثنائية في 2-بيوتين فلا تسمح بالدوران، فيبقى ترتيبا سيس وترانس ثابتين ومنفصلين.', '["للبيوتان متشكل بنائي هو 2-ميثيل بروبان؛ ثم إن السؤال عن المتشكلات الهندسية لا البنائية.","","عدد ذرات الهيدروجين ليس السبب؛ فالسبب هو حرية الدوران حول الروابط الأحادية.","الرابطة الثنائية لا تسمح بالدوران، وهذا بالضبط ما يجعل الترتيبين ثابتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('mcq', 3, 2, 'في الألكانات تكون ذرتا الكربون المرتبطتان برابطة أحادية قادرتين على الدوران بسهولة إحداهما حول الأخرى؛ لذا يتغير ترتيب المجموعات حول الرابطة باستمرار ولا يثبت ترتيب واحد.', '["الرابطة الأحادية لا تمنع الدوران؛ الرابطة الثنائية هي التي تمنعه.","الدوران حول الرابطة الأحادية يحدث باستمرار في الظروف العادية، ولا يرتبط بالغليان.","","لا حاجة إلى كسر الرابطة الأحادية لتغيير الترتيب؛ فالدوران حولها حر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('mcq', 4, 3, 'الرابطة 2 هي الرابطة الثنائية بين ذرتي الكربون الثانية والثالثة، وهي لا تسمح بالدوران؛ فيثبت ترتيب المجموعات حولها وينشأ متشكلا سيس وترانس. أما بقية الروابط فأحادية حرة الدوران.', '["الرابطة 1 أحادية، وتدور حولها مجموعة CH₃ بحرية فلا تنشأ عنها متشكلات.","الرابطة 3 أحادية، والدوران حولها حر فلا يثبت ترتيب المجموعات حولها.","الرابطة 4 أحادية بين مجموعتي CH₂، والدوران حولها حر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('mcq', 5, 0, 'في الإيثان ترتبط ذرتا الكربون برابطة تساهمية أحادية فهما حرتا الدوران حول الرابطة، أما في الإيثين فترتبطان برابطة تساهمية ثنائية تجعل ذرتي الكربون ثابتتين في موقعهما وتجعل الدوران غير ممكن.', '["","حجم ذرات الهيدروجين لا يحدد إمكانية الدوران؛ فنوع الرابطة بين ذرتي الكربون هو الذي يحددها.","هذا عكس الصحيح؛ فالرابطة الأحادية في الإيثان هي التي تسمح بالدوران.","الرابطة الأحادية تسمح بالدوران؛ والذي يمنعه هو الرابطة الثنائية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('mcq', 6, 2, 'جميع الروابط بين ذرات الكربون في البيوتان أحادية، والدوران حولها حر؛ فالترتيبان اللذان تظهر فيهما مجموعتا CH₃ في جهة واحدة أو في جهتين متقابلتين يتحول كل منهما إلى الآخر باستمرار، فلا يمكن فصل مادتين مختلفتين.', '["الترتيبان ممكنان في الرسم لكنهما غير ثابتين؛ فالدوران حول الرابطة الأحادية يحول أحدهما إلى الآخر.","في البيوتان مجموعتا CH₃ طرفيتان فعلًا؛ وسبب خطأ الادعاء هو حرية الدوران لا غياب المجموعتين.","","المتشكلات الهندسية تحتاج إلى رابطة ثنائية تمنع الدوران، والألكانات روابطها أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('mcq', 7, 3, 'في 3-هكسين رابطة ثنائية لا تسمح بالدوران، وكل من ذرتيها ترتبط بـ H ومجموعة إيثيل، فيثبت ترتيبا سيس وترانس. أما الهكسان فكل روابطه أحادية حرة الدوران، فلا يثبت فيه ترتيب يمكن فصله.', '["كثرة الروابط الأحادية لا تنتج متشكلات هندسية؛ لأن الدوران حولها حر.","عدد ذرات الكربون لا يكفي؛ فالمتشكلات الهندسية تحتاج إلى رابطة ثنائية تمنع الدوران.","ذرتا الرابطة الثنائية في 3-هكسين لا تدوران، فله متشكلان هندسيان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الرابطة بين ذرتي الكربون الوسطيين في البيوتان أحادية، وذرتا الكربون حرتا الدوران حولها؛ فبتدوير ذرة الكربون اليمنى في (1) تنتقل مجموعة CH₃ من الأعلى إلى الأسفل فنحصل على (2)، ويتحول الترتيبان أحدهما إلى الآخر باستمرار، فهما الجزيء نفسه ولا يمكن فصلهما. أما لو كانت الرابطة ثنائية (2-بيوتين، وكل ذرة من ذرتيها ترتبط بـ CH₃ وH) فإن ذرتي الكربون لا تستطيعان الدوران وتبقيان ثابتتين في موقعهما، فيثبت ترتيبان مختلفان: سيس (مجموعتا CH₃ في الجهة نفسها) وترانس (في جهتين متقابلتين)، وهما مركبان مختلفان لا يتحول أحدهما إلى الآخر بسهولة.', '["حرية الدوران حول الرابطة الأحادية","تحول الرسمين أحدهما إلى الآخر فهما جزيء واحد","الرابطة الثنائية تمنع الدوران","ثبات ترتيبي سيس وترانس مركبين مختلفين"]'::jsonb, '[]'::jsonb, '[{"element":"حرية الدوران حول الرابطة الأحادية","marks":1},{"element":"تحول الرسمين أحدهما إلى الآخر فهما جزيء واحد","marks":1},{"element":"الرابطة الثنائية تمنع الدوران","marks":1},{"element":"ثبات ترتيبي سيس وترانس مركبين مختلفين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: حرية الدوران حول الرابطة الأحادية؛ تحول الرسمين أحدهما إلى الآخر فهما جزيء واحد؛ الرابطة الثنائية تمنع الدوران؛ ثبات ترتيبي سيس وترانس مركبين مختلفين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الرسمين سيس وترانس للبيوتان","القول إن الرابطة الثنائية تدور ببطء فقط","نسيان أن كل ذرة في رابطة 2-بيوتين الثنائية ترتبط بمجموعتين مختلفتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الشق الأول صحيح: لا يوجد متشكلات هندسية للإيثان ولا للإيثين. لكن التعليل صحيح للإيثان وحده؛ فذرتا الكربون فيه مرتبطتان برابطة أحادية وحرتا الدوران، فلا يثبت أي ترتيب. أما الإيثين ففيه رابطة ثنائية تجعل ذرتي الكربون ثابتتين لا تدوران، وسبب عدم وجود متشكلات هندسية له أن كل ذرة كربون ترتبط بذرتي هيدروجين متماثلتين، فأي ترتيب يعطي الجزيء نفسه. إذن السببان مختلفان، والعبارة خاطئة في جعل السبب واحدًا.', '["الحكم بأن الإيثان والإيثين لا متشكلات هندسية لهما","تعليل الإيثان بحرية الدوران حول الرابطة الأحادية","بيان أن ذرتي الإيثين لا تدوران","تعليل الإيثين بتماثل المجموعتين على كل ذرة كربون"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن الإيثان والإيثين لا متشكلات هندسية لهما","marks":1},{"element":"تعليل الإيثان بحرية الدوران حول الرابطة الأحادية","marks":1},{"element":"بيان أن ذرتي الإيثين لا تدوران","marks":1},{"element":"تعليل الإيثين بتماثل المجموعتين على كل ذرة كربون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم بأن الإيثان والإيثين لا متشكلات هندسية لهما؛ تعليل الإيثان بحرية الدوران حول الرابطة الأحادية؛ بيان أن ذرتي الإيثين لا تدوران؛ تعليل الإيثين بتماثل المجموعتين على كل ذرة كربون"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول العبارة كما هي","القول إن الإيثين حر الدوران","القول إن للإيثين متشكلين سيس وترانس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.623Z"}'::jsonb),
('essay', 3, null::int, null, null, 'البنتان روابطه بين ذرات الكربون جميعها أحادية، وذرات الكربون حرة الدوران حولها، فتتحول أشكاله الفراغية بعضها إلى بعض باستمرار ولا يثبت شكل منها، فهي أشكال لمادة واحدة لا يمكن فصلها. أما 2-بنتين ففيه رابطة ثنائية تمنع الدوران، وكل ذرة من ذرتيها ترتبط بذرة هيدروجين ومجموعة ألكيل مختلفة عنها (CH₃ على إحداهما وCH₂CH₃ على الأخرى)، فيثبت ترتيبان: سيس وترانس، وهما مركبان مختلفان لهما خصائص فيزيائية مختلفة مثل درجة الغليان؛ لذا يمكن فصلهما.', '["الدوران الحر في البنتان يجعل أشكاله تتحول بعضها إلى بعض","الرابطة الثنائية في 2-بنتين تمنع الدوران فيثبت ترتيبان","المتشكلان مركبان مختلفان بخصائص فيزيائية مختلفة فيمكن فصلهما"]'::jsonb, '[]'::jsonb, '[{"element":"الدوران الحر في البنتان يجعل أشكاله تتحول بعضها إلى بعض","marks":1},{"element":"الرابطة الثنائية في 2-بنتين تمنع الدوران فيثبت ترتيبان","marks":1},{"element":"المتشكلان مركبان مختلفان بخصائص فيزيائية مختلفة فيمكن فصلهما","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل: الدوران الحر في البنتان يجعل أشكاله تتحول بعضها إلى بعض؛ الرابطة الثنائية في 2-بنتين تمنع الدوران فيثبت ترتيبان؛ المتشكلان مركبان مختلفان بخصائص فيزيائية مختلفة فيمكن فصلهما"},{"level":"1–2 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ أشكال البنتان الفراغية متشكلات منفصلة","نسيان شرط وجود مجموعتين مختلفتين على كل ذرة من ذرتي الرابطة الثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb)
