('mcq', 1, 2, 'ذرة الكربون 3 ترتبط بأربع مجموعات مختلفة: H وCH₂CH₃ (الفرع) وCH(CH₃)CH₃ وCH₂CH₂CH₃؛ فهي غير متماثلة. أما ذرة الكربون 2 فترتبط بمجموعتي CH₃ متماثلتين (الفرع وذرة الكربون 1).', '["ذرة الكربون 2 ترتبط بمجموعتي CH₃ متماثلتين (ذرة الكربون 1 والفرع)، فليست غير متماثلة.","ذرة الكربون 4 مجموعة CH₂ ترتبط بذرتي هيدروجين متماثلتين.","","ذرة الكربون 3 وحدها غير متماثلة؛ فالكربون 2 يرتبط بمجموعتي ميثيل متماثلتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb),
('mcq', 2, 0, 'ذرة الكربون 3 ترتبط بأربع مجموعات مختلفة: H وCH₃ وCH=CH₂ وCH₂CH₃؛ فهي غير متماثلة.', '["","ذرة الكربون 2 طرف في الرابطة الثنائية، فهي مرتبطة بثلاث مجموعات فقط (H و=CH₂ وذرة الكربون 3) لا بأربع مجموعات مختلفة.","ذرة الكربون 1 (=CH₂) ترتبط بذرتي هيدروجين متماثلتين وطرف في رابطة ثنائية.","ذرة الكربون 4 مجموعة CH₂ ترتبط بذرتي هيدروجين متماثلتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb),
('mcq', 3, 1, 'ذرة الكربون 3 ترتبط بـ H وCH₃ وCH₂CH₃ والمجموعة CH(CH₃)CH₂CH₃؛ أربع مجموعات مختلفة. وذرة الكربون 4 ترتبط بالمجموعات نفسها بالمقابل؛ فهي غير متماثلة أيضًا. إذن في الجزيء ذرتا كربون غير متماثلتين.', '["تماثل نصفي الجزيء لا يمنع أن تكون كل من ذرتي الكربون 3 و4 مرتبطة بأربع مجموعات مختلفة؛ فهما ذرتان لا ذرة واحدة.","","تماثل الجزيء ككل لا يعني أن ذراته متماثلة؛ فكل من الكربونين 3 و4 ترتبط بأربع مجموعات مختلفة.","مجموعات CH₃ (الفرعية والطرفية) ترتبط كل منها بثلاث ذرات هيدروجين متماثلة، فلا تكون غير متماثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb),
('mcq', 4, 3, 'ذرات الكربون المتفرعة 3 و5 و7 تحمل كل منها ذرة H واحدة. الكربون 3: H وCH₃ وCH₂CH₃ وبقية السلسلة؛ مختلفة. الكربون 5: H وCH₂CH₃ والجزء CH₂CH(CH₃)CH₂CH₃ والجزء CH₂CH(CH₃)CH₂CH₂CH₂CH₃؛ مختلفة. الكربون 7: H وCH₃ وCH₂CH₂CH₂CH₃ وبقية السلسلة؛ مختلفة. إذن ثلاث ذرات غير متماثلة.', '["الاقتصار على ذرة الكربون 5 الوسطى يُغفل الكربونين 3 و7 وكل منهما يرتبط بأربع مجموعات مختلفة.","يحدث هذا عند استبعاد الكربون 5 بظن أن جزأي السلسلة على جانبيه متماثلان، مع أن أحدهما أطول من الآخر.","لا توجد ذرة رابعة؛ فبقية ذرات الكربون CH₂ أو CH₃ ترتبط بذرتي هيدروجين متماثلتين على الأقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb),
('mcq', 5, 0, 'في 2، 4-ثنائي ميثيل هكسان CH₃CH(CH₃)CH₂CH(CH₃)CH₂CH₃ ترتبط ذرة الكربون 4 بـ H وCH₃ وCH₂CH₃ وCH₂CH(CH₃)CH₃، وهي أربع مجموعات مختلفة؛ فهي ذرة كربون غير متماثلة.', '["","في 2-ميثيل هكسان ترتبط ذرة الكربون 2 بمجموعتي CH₃ متماثلتين، وبقية الذرات CH₂ أو CH₃.","في 3-إيثيل بنتان ترتبط ذرة الكربون 3 بثلاث مجموعات إيثيل متماثلة.","في 2، 2-ثنائي ميثيل بيوتان لا ترتبط ذرة الكربون 2 بأي ذرة هيدروجين، لكنها ترتبط بثلاث مجموعات CH₃ متماثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-14T13:39:20.624Z"}'::jsonb),
('mcq', 6, 1, 'ذرة الكربون في مجموعة CH₂ ترتبط بذرتي هيدروجين متماثلتين، فلا يمكن أن تكون مرتبطة بأربع ذرات أو مجموعات مختلفة؛ لذا لا تكون غير متماثلة أبدًا.', '["ذرة H وثلاث مجموعات مختلفة تعني أربع مجموعات مختلفة؛ فهي غير متماثلة.","","هذه ذرة الكربون في الألانين، وترتبط بأربع مجموعات مختلفة؛ فهي غير متماثلة.","H وCH₃ وCH₂CH₃ وCH₂CH₂CH₃ أربع مجموعات مختلفة؛ فهي غير متماثلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-14T13:39:20.625Z"}'::jsonb),
('mcq', 7, 2, 'ترتبط ذرة الكربون 4 بذرة H، ومجموعة الميثيل الفرعية CH₃، والجزء CH₂CH₂CH₃ (الكربونات 1 إلى 3)، والجزء CH₂CH₂CH₂CH₃ (الكربونات 5 إلى 8). المجموعات الأربع مختلفة؛ فهي ذرة كربون غير متماثلة.', '["الجزء الأيمن من السلسلة بعد الكربون 4 فيه أربع ذرات كربون (CH₂CH₂CH₂CH₃) لا ثلاث؛ فالمجموعتان مختلفتان.","على يسار الكربون 4 مجموعة بروبيل CH₂CH₂CH₃ لا ميثيل؛ فلا ترتبط به مجموعتا CH₃.","","ذرة الكربون 4 ترتبط بذرة H، وCH₂ ليست مجموعة مستقلة بل جزء من السلسلة؛ فهذا التقسيم خاطئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.625Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ذرة الكربون 2 ترتبط بـ H وCH₃ (الفرع) وCH₃ (ذرة الكربون 1) وبقية السلسلة؛ فيها مجموعتان متماثلتان فليست غير متماثلة. ذرة الكربون 3 ترتبط بـ H وCH₃ وCH(CH₃)CH₃ وCH₂CH₂CH₃؛ أربع مجموعات مختلفة فهي غير متماثلة. بقية الذرات CH₂ أو CH₃. إذن n = 1، والعدد الكلي للمتشكلات الفراغية = 2¹ = 2.', '["مجموعات الكربون 2 والحكم بأنه ليس غير متماثل","مجموعات الكربون 3 الأربع","الحكم بأن الكربون 3 غير متماثل","الحساب 2¹ = 2"]'::jsonb, '["فحص الذرات المتفرعة (CH) فقط لأن ذرات CH₂ وCH₃ فيها ذرتا هيدروجين متماثلتان","الكربون 2: مجموعتا CH₃ متماثلتان ← ليس غير متماثل","الكربون 3: H وCH₃ وCH(CH₃)CH₃ وCH₂CH₂CH₃ ← غير متماثل، n = 1","عدد المتشكلات الفراغية = 2ⁿ = 2¹ = 2"]'::jsonb, '[{"element":"مجموعات الكربون 2 والحكم بأنه ليس غير متماثل","marks":1},{"element":"مجموعات الكربون 3 الأربع","marks":1},{"element":"الحكم بأن الكربون 3 غير متماثل","marks":1},{"element":"الحساب 2¹ = 2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: مجموعات الكربون 2 والحكم بأنه ليس غير متماثل؛ مجموعات الكربون 3 الأربع؛ الحكم بأن الكربون 3 غير متماثل؛ الحساب 2¹ = 2"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكربون 2 غير متماثل","عدّ مجموعة الميثيل الفرعية ذرة كربون غير متماثلة","حساب 2² = 4 بعدّ الكربون 2 غير متماثل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.625Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) 2-ميثيل بنتان: ذرة الكربون 2 ترتبط بمجموعتي CH₃ متماثلتين، وبقية الذرات CH₂ أو CH₃. (2) 3-ميثيل بنتان: ذرة الكربون 3 ترتبط بمجموعتي إيثيل متماثلتين. (3) 2، 2-ثنائي ميثيل بيوتان: ذرة الكربون 2 ترتبط بثلاث مجموعات CH₃ متماثلة. إذن لا توجد في أي منها ذرة كربون غير متماثلة. متشكل C₇H₁₆ مناسب: CH₃CH₂CH(CH₃)CH₂CH₂CH₃ (3-ميثيل هكسان)، ذرة الكربون 3 فيه ترتبط بـ H وCH₃ وCH₂CH₃ وCH₂CH₂CH₃. (ويُقبل 2، 3-ثنائي ميثيل بنتان وذرة الكربون 3 فيه.)', '["(1): الكربون 2 يرتبط بمجموعتي CH₃ متماثلتين فلا ذرة غير متماثلة","(2): الكربون 3 يرتبط بمجموعتي إيثيل متماثلتين","(3): الكربون 2 يرتبط بثلاث مجموعات CH₃ متماثلة","كتابة متشكل C₇H₁₆ صحيح فيه ذرة كربون غير متماثلة","تحديد الذرة ومجموعاتها الأربع"]'::jsonb, '[]'::jsonb, '[{"element":"(1): الكربون 2 يرتبط بمجموعتي CH₃ متماثلتين فلا ذرة غير متماثلة","marks":1},{"element":"(2): الكربون 3 يرتبط بمجموعتي إيثيل متماثلتين","marks":1},{"element":"(3): الكربون 2 يرتبط بثلاث مجموعات CH₃ متماثلة","marks":1},{"element":"كتابة متشكل C₇H₁₆ صحيح فيه ذرة كربون غير متماثلة","marks":1},{"element":"تحديد الذرة ومجموعاتها الأربع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (1): الكربون 2 يرتبط بمجموعتي CH₃ متماثلتين فلا ذرة غير متماثلة؛ (2): الكربون 3 يرتبط بمجموعتي إيثيل متماثلتين؛ (3): الكربون 2 يرتبط بثلاث مجموعات CH₃ متماثلة؛ كتابة متشكل C₇H₁₆ صحيح فيه ذرة كربون غير متماثلة؛ تحديد الذرة ومجموعاتها الأربع"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكربون 3 في 3-ميثيل بنتان غير متماثل وهو يرتبط بمجموعتي إيثيل","اقتراح صيغة فيها ست ذرات كربون أو ثماني","اقتراح 2-ميثيل هكسان وفيه مجموعتا CH₃ على الكربون 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%