from (values
('mcq', 1, 'تستعمل الخلايا البشرية في بناء البروتينات نوعًا واحدًا من الأحماض الأمينية، هو:', null, null, '["النوع D فقط","النوع L فقط","النوعان D وL معًا","مزيج غير محدد منهما"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 147، 164 — المتشكلات الضوئية'),
('mcq', 2, 'يمثل الشكل الآتي نموذجًا مبسطًا لموقع نشط في إنزيم، وجزيئين (1) و(2) كل منهما صورة مرآة للآخر. أيّ العبارات الآتية تفسر الشكل تفسيرًا صحيحًا؟', null, '[{"src":"qimg/chem22/c4-l4b-enzyme.svg","alt":"نموذج مبسط في لوحتين مرقمتين. في كل لوحة كتلة رمادية تمثل الموقع النشط في الإنزيم، في حافتها العليا ثلاث فجوات من اليسار إلى اليمين: فجوة نصف دائرية، ثم فجوة مربعة، ثم فجوة مثلثة. فوق كل كتلة جزيء له ذرة مركزية ترتبط بمجموعة صغيرة إلى الأعلى وبثلاث مجموعات إلى الأسفل. في (1): المجموعات من اليسار إلى اليمين دائرة زرقاء ثم مربع أخضر ثم مثلث أحمر، فتقع كل مجموعة فوق الفجوة المطابقة لشكلها. في (2): الجزيء صورة مرآة للجزيء (1)؛ المجموعات من اليسار إلى اليمين مثلث أحمر ثم مربع أخضر ثم دائرة زرقاء، فيقع المثلث فوق الفجوة الدائرية والدائرة فوق الفجوة المثلثة."}]'::jsonb, '["يتلاءم الجزيء (1) وحده مع الموقع النشط؛ لأن ترتيب مجموعاته في الفراغ يطابق شكل الموقع","يتلاءم الجزيئان مع الموقع النشط؛ لأن لهما المجموعات نفسها والصيغة الجزيئية نفسها","يتلاءم الجزيء (2) وحده مع الموقع النشط؛ لأن مجموعاته أكبر حجمًا من مجموعات (1)","لا يتلاءم أي منهما؛ لأن الموقع النشط يتفاعل مع المتشكلات البنائية فقط"]'::jsonb, 'فهم', 'تفسير نموذج', 'متوسط', 'الكتاب ص 146–147 — الكيرالية والمتشكلات الضوئية'),
('mcq', 3, 'أيّ مما يأتي مثال صحيح على أهمية الكيرالية في المخلوقات الحية؟', null, null, '["يستعمل جسم الإنسان النوعين D وL من الأحماض الأمينية في بناء البروتينات بالتساوي","يكون المتشكلان الضوئيان لأي دواء متساويين دائمًا في فاعليتهما وأمانهما","النوع L من حمض الإسكوربيك هو الفعال بوصفه فيتامين C","يختلف شكلا حمض الطرطريك في درجة الانصهار، فيختلف تأثيرهما في البكتيريا"]'::jsonb, 'فهم', 'تمييز مثال صحيح', 'سهل', 'الكتاب ص 146–147 — الكيرالية والمتشكلات الضوئية'),
('mcq', 4, 'دواء له متشكلان ضوئيان، أحدهما فعال علاجيًّا والآخر ضار. ما الذي يفسر اختلاف تأثيرهما في الجسم مع أن لهما الخصائص الفيزيائية نفسها؟', null, null, '["يختلفان في الصيغة الجزيئية، فيختلف عدد الذرات التي تتفاعل في الجسم","يختلفان في ترتيب ارتباط الذرات، فهما متشكلان بنائيان مختلفان","أحدهما يذوب في الماء والآخر لا يذوب، فلا يصل إلى الدم","تفاعلاتهما في الجسم تحفزها إنزيمات يتلاءم موقعها النشط مع شكل كيرالي واحد"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 146–147 — الكيرالية والمتشكلات الضوئية'),
('mcq', 5, 'في دواء متشكله L فعال ومتشكله D ضار، ما الإجراء الأنسب عند تصنيعه؟', null, null, '["خلط المتشكلين بكميتين متساويتين؛ لأن لهما الخصائص الكيميائية نفسها","تصنيع المتشكل L وحده، أو فصله من المتشكل D قبل استعمال الدواء","استعمال المتشكل D بجرعة أكبر؛ لأن له الصيغة الجزيئية نفسها","الاكتفاء بقياس درجة انصهار الدواء للتأكد من خلوه من المتشكل D"]'::jsonb, 'تطبيق', 'اتخاذ قرار مبني على مفهوم', 'متوسط', 'الكتاب ص 147 — الكيرالية في الأدوية'),
('mcq', 6, 'وُجد أن أحد شكلي حمض الطرطريك (شكل اليد اليسرى) ينتج عن عملية التخمير، ويسبب تكاثر البكتيريا بعد تغذيها عليه. ماذا يدل ذلك؟', null, null, '["المخلوقات الحية تميز بين المتشكلات الضوئية، فتستفيد من شكل كيرالي دون الآخر","الشكلان يختلفان في الصيغة الجزيئية، فلا تتغذى البكتيريا إلا على أحدهما","شكل اليد اليسرى له درجة انصهار وذائبية تختلفان عن شكل اليد اليمنى","البكتيريا تحول شكل اليد اليمنى إلى شكل اليد اليسرى في أثناء التخمير"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 145 — الكيرالية'),
('mcq', 7, 'ما نوع المتشكلات الذي يفسر اختلاف التأثير الحيوي لـ L-حمض الإسكوربيك وD-حمض الإسكوربيك؟', null, null, '["متشكلات بنائية","متشكلات هندسية (سيس وترانس)","مركبات من سلسلة متماثلة","متشكلات ضوئية"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 146–147 — الكيرالية والمتشكلات الضوئية'),
('essay', 1, 'استنتج مستعينًا بالشكل الآتي لماذا تستفيد المخلوقات الحية من شكل كيرالي واحد فقط من المادة، ثم اذكر مثالين على ذلك من جسم الإنسان.', null, '[{"src":"qimg/chem22/c4-l4b-enzyme.svg","alt":"نموذج مبسط في لوحتين مرقمتين. في كل لوحة كتلة رمادية تمثل الموقع النشط في الإنزيم، في حافتها العليا ثلاث فجوات من اليسار إلى اليمين: فجوة نصف دائرية، ثم فجوة مربعة، ثم فجوة مثلثة. فوق كل كتلة جزيء له ذرة مركزية ترتبط بمجموعة صغيرة إلى الأعلى وبثلاث مجموعات إلى الأسفل. في (1): المجموعات من اليسار إلى اليمين دائرة زرقاء ثم مربع أخضر ثم مثلث أحمر، فتقع كل مجموعة فوق الفجوة المطابقة لشكلها. في (2): الجزيء صورة مرآة للجزيء (1)؛ المجموعات من اليسار إلى اليمين مثلث أحمر ثم مربع أخضر ثم دائرة زرقاء، فيقع المثلث فوق الفجوة الدائرية والدائرة فوق الفجوة المثلثة."}]'::jsonb, null, 'فهم', 'استنتاج بالاستعانة بنموذج', 'متوسط', 'الكتاب ص 146–148 — الكيرالية (س28)'),
('essay', 2, 'تُنتج إحدى الشركات دواءً على صورة خليط من متشكلين ضوئيين بكميتين متساويتين، أحدهما فعال علاجيًّا والآخر قد يكون ضارًّا. (أ) فسّر لماذا يختلف تأثير المتشكلين في الجسم مع تشابه خصائصهما الفيزيائية والكيميائية. (ب) ما التوصية التي تقدمها للشركة؟ ولماذا؟', null, null, null, 'تطبيق', 'تفسير وتوصية', 'صعب', 'الكتاب ص 146–147 — الكيرالية في الأدوية'),
('essay', 3, 'لـ L-حمض الإسكوربيك وD-حمض الإسكوربيك درجة الانصهار والكثافة والذائبية في الماء نفسها، لكن أحدهما فقط فعال بوصفه فيتامين C. (أ) ما نوع العلاقة بين المركبين؟ (ب) فسّر كيف يتشابهان في هذه الخصائص ويختلفان في التأثير الحيوي. (ج) أيّهما الفعال بوصفه فيتامين C؟ واستنتج هل يؤدي تناول الآخر وحده وظيفة فيتامين C.', null, null, null, 'تحليل', 'تحليل حالة', 'صعب', 'الكتاب ص 146–147 — الكيرالية والمتشكلات الضوئية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L4-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تسمح الخلايا البشرية بدخول الأحماض الأمينية من النوع L فقط في بناء البروتينات، وتوجد الأحماض الأمينية جميعها تقريبًا في المخلوقات الحية على هيئة L.', '["النوع D ليس النوع الذي تستعمله الخلايا البشرية في بناء البروتينات.","","الخلايا لا تستعمل النوعين معًا؛ فهي تستفيد من شكل كيرالي واحد فقط.","الاستعمال ليس عشوائيًّا؛ فالخلايا انتقائية وتستعمل النوع L وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 2, 0, 'في (1) تقع كل مجموعة فوق الفجوة المطابقة لشكلها، فيتلاءم الجزيء مع الموقع النشط. أما (2) فمجموعاته نفسها لكن ترتيبها في الفراغ معكوس، فلا يتلاءم. وهذا يفسر استفادة المخلوقات الحية من شكل كيرالي واحد يتلاءم مع الموقع النشط في الإنزيم.', '["","تشابه المجموعات والصيغة الجزيئية لا يكفي؛ فالموقع النشط يميز ترتيب المجموعات في الفراغ.","مجموعات الجزيئين متماثلة في الحجم والنوع، ويختلفان في ترتيبها فقط؛ و(2) لا يتلاءم.","الجزيء (1) يتلاءم مع الموقع؛ والإنزيمات تميز المتشكلات الضوئية بحسب شكلها الكيرالي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 3, 2, 'من أمثلة أهمية الكيرالية في المخلوقات الحية أن النوع L من حمض الإسكوربيك هو الفعال بوصفه فيتامين C، مع أن له وللنوع D الصيغة البنائية نفسها.', '["الخلايا البشرية تستعمل الأحماض الأمينية من النوع L فقط في بناء البروتينات.","في بعض الأدوية يكون متشكل واحد فقط فعالًا، وقد يكون الآخر ضارًّا.","","لشكلي حمض الطرطريك درجة الانصهار نفسها؛ واختلاف تأثيرهما الحيوي سببه الكيرالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 4, 3, 'للمتشكلين الضوئيين الخصائص الفيزيائية والكيميائية نفسها، لكن التفاعلات التي تكون فيها الكيرالية مهمة، ومنها التفاعلات المحفزة بالإنزيمات، تميز بينهما؛ لأن الموقع النشط يتلاءم مع شكل كيرالي واحد فقط.', '["المتشكلات الضوئية لها الصيغة الجزيئية نفسها.","الذرات في المتشكلين الضوئيين مرتبطة بالترتيب نفسه؛ فهما متشكلان فراغيان لا بنائيان.","للمتشكلين الضوئيين الذائبية نفسها في الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 5, 1, 'لأن المتشكل D في هذا الدواء ضار والمتشكل L وحده فعال، فالأنسب تصنيع المتشكل L وحده أو فصله من المتشكل D؛ فيحصل المريض على الفائدة دون الضرر.', '["الخلط يعطي المريض المتشكل الضار مع الفعال، وتشابه الخصائص الكيميائية لا يعني تشابه التأثير الحيوي.","","المتشكل D ضار، وزيادة جرعته تزيد الضرر؛ وتشابه الصيغة الجزيئية لا يجعله فعالًا.","للمتشكلين درجة الانصهار نفسها، فلا يكشف قياسها وجود المتشكل D."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 6, 0, 'لشكلي حمض الطرطريك الخصائص الكيميائية ودرجة الانصهار والكثافة والذائبية نفسها، ومع ذلك يرتبط شكل اليد اليسرى وحده بنشاط البكتيريا؛ وهذا يدل على أن المخلوقات الحية تميز بين الشكلين الكيراليين.', '["","الشكلان صورتا مرآة لهما الصيغة الجزيئية نفسها.","لشكلي حمض الطرطريك درجة الانصهار والذائبية في الماء نفسها.","لا يذكر الوصف أي تحول بين الشكلين؛ وإنما ينتج شكل اليد اليسرى عن التخمير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.626Z"}'::jsonb),
('mcq', 7, 3, 'النوعان L وD صورتا مرآة لا تنطبق إحداهما على الأخرى، فهما متشكلان ضوئيان، والكيرالية هي سبب اختلاف تأثيرهما الحيوي.', '["المتشكلات البنائية تختلف في ترتيب ارتباط الذرات، أما L وD فالترتيب فيهما واحد.","المتشكلات الهندسية تنشأ حول رابطة ثنائية بالبادئتين سيس وترانس، لا بالحرفين D وL.","مركبات السلسلة المتماثلة تختلف في صيغها الجزيئية، والنوعان L وD لهما الصيغة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.627Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الموقع النشط في الإنزيم له شكل فراغي محدد، والمتشكلان الضوئيان لهما المجموعات نفسها لكن ترتيبها في الفراغ معكوس (صورتا مرآة لا تنطبقان). لذا يتلاءم شكل كيرالي واحد فقط مع الموقع النشط كما في الجزيء (1)، ولا يتلاءم الآخر (2)؛ فيستفيد المخلوق الحي من الشكل الذي يتلاءم وحده. مثالان: الخلايا البشرية تستعمل الأحماض الأمينية من النوع L فقط في بناء البروتينات؛ والنوع L من حمض الإسكوربيك هو الفعال بوصفه فيتامين C.', '["الموقع النشط له شكل فراغي محدد","شكل كيرالي واحد يتلاءم معه لأن الآخر صورة مرآة لا تنطبق","المثال الأول","المثال الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"الموقع النشط له شكل فراغي محدد","marks":1},{"element":"شكل كيرالي واحد يتلاءم معه لأن الآخر صورة مرآة لا تنطبق","marks":1},{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الموقع النشط له شكل فراغي محدد؛ شكل كيرالي واحد يتلاءم معه لأن الآخر صورة مرآة لا تنطبق؛ المثال الأول؛ المثال الثاني"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتشكلين يختلفان في الصيغة الجزيئية","ذكر مثال ليس من الكيرالية مثل دهون ترانس","القول إن الإنزيم يحول الشكل الآخر إلى الشكل المناسب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.627Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) للمتشكلين الضوئيين الخصائص الفيزيائية والكيميائية نفسها، لكن تفاعلاتهما في الأنظمة البيولوجية تعتمد على الكيرالية؛ فالتفاعلات المحفزة بالإنزيمات تميز بينهما لأن الموقع النشط يتلاءم مع شكل كيرالي واحد، فيؤدي أحدهما التأثير العلاجي ولا يؤديه الآخر، وقد يسبب ضررًا. (ب) أوصي بإنتاج المتشكل الفعال وحده أو فصله من الخليط؛ لتجنب ضرر المتشكل الآخر، ولأن نصف الخليط لا يفيد علاجيًّا.', '["تشابه الخصائص عدا التفاعلات المعتمدة على الكيرالية","دور الإنزيم وموقعه النشط في تمييز الشكل الكيرالي","التوصية بإنتاج المتشكل الفعال وحده أو فصله","تعليل التوصية بتجنب الضرر ورفع الفاعلية"]'::jsonb, '[]'::jsonb, '[{"element":"تشابه الخصائص عدا التفاعلات المعتمدة على الكيرالية","marks":1},{"element":"دور الإنزيم وموقعه النشط في تمييز الشكل الكيرالي","marks":1},{"element":"التوصية بإنتاج المتشكل الفعال وحده أو فصله","marks":1},{"element":"تعليل التوصية بتجنب الضرر ورفع الفاعلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تشابه الخصائص عدا التفاعلات المعتمدة على الكيرالية؛ دور الإنزيم وموقعه النشط في تمييز الشكل الكيرالي؛ التوصية بإنتاج المتشكل الفعال وحده أو فصله؛ تعليل التوصية بتجنب الضرر ورفع الفاعلية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المتشكلين يختلفان في الذائبية أو درجة الانصهار","التوصية بزيادة الجرعة لتعويض المتشكل غير الفعال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.627Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) متشكلان ضوئيان: كل منهما صورة مرآة للآخر لا تنطبق عليه. (ب) الذرات فيهما مرتبطة بالترتيب نفسه، فلهما الخصائص الفيزيائية والكيميائية نفسها؛ لكنهما يختلفان في ترتيب المجموعات في الفراغ، والتفاعلات البيولوجية المحفزة بالإنزيمات تعتمد على الكيرالية، فيتلاءم شكل واحد فقط مع الموقع النشط. (ج) L-حمض الإسكوربيك هو الفعال بوصفه فيتامين C؛ لذا لا يؤدي تناول D-حمض الإسكوربيك وحده وظيفة فيتامين C.', '["تحديد أنهما متشكلان ضوئيان","سبب تشابه الخصائص: الترتيب نفسه لارتباط الذرات","سبب اختلاف التأثير: اعتماد التفاعلات الحيوية على الكيرالية","تحديد النوع L فعالًا والاستنتاج الصحيح في (ج)"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد أنهما متشكلان ضوئيان","marks":1},{"element":"سبب تشابه الخصائص: الترتيب نفسه لارتباط الذرات","marks":1},{"element":"سبب اختلاف التأثير: اعتماد التفاعلات الحيوية على الكيرالية","marks":1},{"element":"تحديد النوع L فعالًا والاستنتاج الصحيح في (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد أنهما متشكلان ضوئيان؛ سبب تشابه الخصائص: الترتيب نفسه لارتباط الذرات؛ سبب اختلاف التأثير: اعتماد التفاعلات الحيوية على الكيرالية؛ تحديد النوع L فعالًا والاستنتاج الصحيح في (ج)"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيفهما متشكلين بنائيين أو هندسيين","القول إن D يؤدي الوظيفة نفسها لتشابه الخصائص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.627Z"}'::jsonb)
