('mcq', 1, 2, 'تُسمى الدهون ذات متشكلات ترانس دهون ترانس.', '["دهون سيس هي التي تكون فيها المجموعتان في الجهة نفسها من الرابطة الثنائية، لا في جهتين متقابلتين.","الدهون المشبعة لا تحتوي على روابط ثنائية، فلا يكون لها متشكلات سيس أو ترانس.","","هذه التسمية لا تصف ترتيب المجموعات حول الرابطة الثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.627Z"}'::jsonb),
('mcq', 2, 0, 'تُحضَّر كثير من الأطعمة المغلفة باستعمال دهون ترانس لأن لها فترة حفظ أطول.', '["","دهون ترانس تزيد الكولسترول الضار ولا تقلله.","دهون ترانس دهون غير مشبعة تحتوي على رابطة ثنائية بترتيب ترانس.","دهون ترانس تقلل الكولسترول النافع ولا تزيده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('mcq', 3, 3, 'تشير الدلائل إلى أن دهون ترانس تزيد الكولسترول من النوع الضار، وتقلل الكولسترول من النوع النافع.', '["هذا عكس التأثير الفعلي لدهون ترانس.","دهون ترانس تقلل الكولسترول النافع ولا تزيده.","طول فترة الحفظ خاصية تجارية، ولا تعني عدم التأثير في الكولسترول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('mcq', 4, 1, 'تشير الدلائل إلى أن دهون ترانس تزيد الكولسترول الضار وتقلل الكولسترول النافع؛ وهذا يزيد احتمالية الإصابة بأمراض القلب.', '["ثبات ترتيب ترانس لا يعني أنها غير ضارة؛ فالدلائل تشير إلى أنها تزيد الكولسترول الضار، مما يزيد احتمالية الإصابة بأمراض القلب.","","ترتيب ترانس حول الرابطة الثنائية ثابت ولا يتحول بسهولة إلى سيس، وسبب الضرر هو أثرها في الكولسترول.","دهون ترانس تزيد الكولسترول الضار ولا تخفضه، فهي تزيد احتمالية الإصابة بأمراض القلب لا تقللها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('mcq', 5, 2, 'في (2) تقع ذرتا الكربون المرتبطتان بذرتي الرابطة الثنائية (امتداد السلسلة) في جهتين متقابلتين منها، فهو ترتيب ترانس، وتبقى السلسلة ممتدة. أما (1) ففيها ترتيب سيس.', '["في (1) ذرتا الكربون المجاورتان للرابطة الثنائية في الجهة نفسها منها، فهو ترتيب سيس.","انحناء السلسلة عند الرابطة الثنائية ناتج عن ترتيب سيس لا ترانس.","","في (2) رابطة ثنائية واضحة في وسط السلسلة؛ فهي غير مشبعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('mcq', 6, 3, 'المنتج الثاني أفضل لصحة القلب؛ لأن دهون ترانس تزيد الكولسترول الضار وتقلل النافع، مما يزيد احتمالية الإصابة بأمراض القلب.', '["طول فترة الحفظ ميزة للتخزين، لا دليل على الفائدة الصحية.","هذا عكس الصحيح؛ فدهون ترانس تزيد الكولسترول الضار وتقلل النافع.","المتشكلات الهندسية قد تختلف تأثيراتها الحيوية اختلافًا واضحًا، ودهون ترانس مرتبطة بزيادة الكولسترول الضار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('mcq', 7, 0, 'الدهون غير المشبعة تحتوي على رابطة ثنائية C=C لا تسمح بالدوران، وترتبط كل ذرة من ذرتيها بمجموعتين مختلفتين (H وجزء من السلسلة)؛ فيمكن أن يكون جزءا السلسلة في جهتين متقابلتين (ترانس) أو في الجهة نفسها (سيس).', '["","الروابط الأحادية حرة الدوران، فلا ينشأ حولها متشكلات هندسية؛ وهذا وصف الدهون المشبعة.","ذرة الكربون المرتبطة بأربع مجموعات مختلفة تنتج متشكلات ضوئية لا متشكلات ترانس.","حلقة البنزين تميز المركبات الأروماتية، ولا علاقة لها بمتشكلات ترانس في الدهون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('essay', 1, null::int, null, null, 'دهون ترانس هي الدهون التي تحتوي على متشكلات ترانس، أي إن جزأي السلسلة الكربونية فيها يقعان في جهتين متقابلتين من الرابطة الثنائية. وتستعملها الشركات في كثير من الأطعمة المغلفة لأن لها فترة حفظ أطول. وتشير الدلائل إلى أنها تزيد الكولسترول من النوع الضار وتقلل الكولسترول من النوع النافع، مما يزيد احتمالية الإصابة بأمراض القلب.', '["تعريف دهون ترانس","سبب استعمالها: فترة حفظ أطول","زيادة الكولسترول الضار وتقليل النافع","زيادة احتمالية أمراض القلب"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف دهون ترانس","marks":1},{"element":"سبب استعمالها: فترة حفظ أطول","marks":1},{"element":"زيادة الكولسترول الضار وتقليل النافع","marks":1},{"element":"زيادة احتمالية أمراض القلب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف دهون ترانس؛ سبب استعمالها: فترة حفظ أطول؛ زيادة الكولسترول الضار وتقليل النافع؛ زيادة احتمالية أمراض القلب"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنها تزيد الكولسترول النافع","عدّ دهون ترانس دهونًا مشبعة","القول إن طول فترة الحفظ يعني أنها صحية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('essay', 2, null::int, null, null, 'السلسلة (2) تمثل متشكل ترانس؛ لأن ذرتي الكربون المجاورتين للرابطة الثنائية (امتداد السلسلة) تقعان في جهتين متقابلتين منها، فتبقى السلسلة ممتدة، أما (1) فترتيب سيس منحنٍ. ويبقى ترتيب ترانس ثابتًا لأن ذرتي الكربون المرتبطتين برابطة ثنائية لا تستطيعان الدوران حولها، فلا يتحول ترانس إلى سيس بسهولة. وأثر دهون ترانس في الصحة أنها تزيد الكولسترول الضار وتقلل الكولسترول النافع، مما يزيد احتمالية الإصابة بأمراض القلب.', '["تحديد السلسلة (2)","التعليل بموقع امتداد السلسلة حول الرابطة الثنائية","عدم الدوران حول الرابطة الثنائية","الأثر الصحي"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد السلسلة (2)","marks":1},{"element":"التعليل بموقع امتداد السلسلة حول الرابطة الثنائية","marks":1},{"element":"عدم الدوران حول الرابطة الثنائية","marks":1},{"element":"الأثر الصحي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد السلسلة (2)؛ التعليل بموقع امتداد السلسلة حول الرابطة الثنائية؛ عدم الدوران حول الرابطة الثنائية؛ الأثر الصحي"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار السلسلة المنحنية على أنها ترانس","القول إن الرابطة الثنائية تدور بحرية","إغفال الأثر في الكولسترول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول المستهلك خاطئ؛ فدهون ترانس دهون غير مشبعة، ومع ذلك تشير الدلائل إلى أنها تزيد الكولسترول من النوع الضار وتقلل الكولسترول من النوع النافع، مما يزيد احتمالية الإصابة بأمراض القلب؛ فكون الدهون غير مشبعة لا يكفي للحكم بأنها مفيدة، والمهم أيضًا ترتيبها حول الرابطة الثنائية (ترانس). النصيحة: قراءة بطاقة مكونات المنتج، والتقليل من الأطعمة المغلفة التي تحتوي على دهون ترانس، واختيار البدائل الخالية منها.', '["الحكم بأن القول خاطئ","بيان أن دهون ترانس غير مشبعة ومع ذلك ضارة؛ فعدم التشبع وحده لا يدل على الفائدة","أثر دهون ترانس في الكولسترول وأمراض القلب","نصيحة غذائية مناسبة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم بأن القول خاطئ","marks":1},{"element":"بيان أن دهون ترانس غير مشبعة ومع ذلك ضارة؛ فعدم التشبع وحده لا يدل على الفائدة","marks":1},{"element":"أثر دهون ترانس في الكولسترول وأمراض القلب","marks":1},{"element":"نصيحة غذائية مناسبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم بأن القول خاطئ؛ بيان أن دهون ترانس غير مشبعة ومع ذلك ضارة؛ فعدم التشبع وحده لا يدل على الفائدة؛ أثر دهون ترانس في الكولسترول وأمراض القلب؛ نصيحة غذائية مناسبة"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وحدها وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول قول المستهلك","القول إن دهون ترانس دهون مشبعة","الخلط بين الكولسترول الضار والنافع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.628Z"}'::jsonb)
