('mcq', 4, 'يُصنَّف المركب الذي صيغته البنائية في الشكل الآتي ضمن المركبات الأروماتية؛ لأنه:', null, '[{"src":"qimg/chem22/c4-l5a-naphthalene.svg","alt":"حلقتان سداسيتان متلاصقتان جنبًا إلى جنب تشتركان في ضلع واحد، وبداخل كل حلقة دائرة."}]'::jsonb, '["يحتوي على حلقتين مشبعتين كل روابطهما أحادية","يتكون من سلسلة مفتوحة فيها روابط ثنائية متعددة","يحتوي على حلقة بنزين واحدة ترتبط بها سلسلة جانبية","يحتوي على حلقتي بنزين ملتحمتين تتشاركان في ضلع واحد"]'::jsonb, 'فهم', 'تفسير تصنيف مركب', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 5, 'أيّ المركبات الآتية يُعدّ مركبًا أروماتيًّا؟', null, null, '["ميثيل بنزين","الهكسان الحلقي","الإيثاين","البروبين"]'::jsonb, 'تذكر', 'تمييز مثال', 'سهل', 'الكتاب ص 152 — تسمية المركبات العضوية الأروماتية'),
('mcq', 6, 'يوصف المركب الأروماتي علميًّا بأنه مركب عضوي ثابت التركيب. ما سبب هذا الثبات؟', null, null, '["الروابط الثنائية الثلاث في الحلقة متمركزة بين ذرات كربون محددة","إلكترونات الحلقة غير متمركزة تتشارك فيها ذرات الكربون الست","ذرات الكربون في الحلقة مشبعة بأكبر عدد ممكن من ذرات الهيدروجين","رائحته القوية تمنع تفاعله مع المواد الأخرى في الوسط المحيط"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 150 — المفردات: أروماتي، ونموذج البنزين الحديث'),
('mcq', 7, 'قال طالب: «كل مركب ذي رائحة قوية مركب أروماتي». ما التقويم الصحيح لعبارته؟', null, null, '["صحيحة؛ لأن كلمة «أروماتي» تعني في العلم ذا رائحة قوية","صحيحة؛ لأن المركبات الأروماتية وحدها هي التي لها روائح","غير صحيحة؛ فالمعيار العلمي هو وجود حلقة البنزين في البناء","غير صحيحة؛ لأن المركبات الأروماتية جميعها عديمة الرائحة"]'::jsonb, 'تحليل', 'تقويم عبارة', 'صعب', 'الكتاب ص 150 — الاستعمال العلمي مقابل الاستعمال الشائع'),
('essay', 1, 'عرّف المركبات الأروماتية، واذكر مثالين عليها، ثم وضّح سبب تسميتها بهذا الاسم.', null, null, null, 'فهم', 'تعريف وأمثلة وتفسير', 'سهل', 'الكتاب ص 151 — المركبات الأروماتية'),
('essay', 2, 'صنّف المركبات الأربعة في الشكل الآتي إلى أروماتية وغير أروماتية، مع تعليل تصنيف كل مركب.', null, '[{"src":"qimg/chem22/c4-l5a-classify4.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقة سداسية كل أضلاعها روابط أحادية دون أي دائرة أو روابط ثنائية. (2) حلقة سداسية بداخلها دائرة ترتبط بأحد رؤوسها مجموعة CH₂CH₃. (3) صيغة هيكلية متعرجة (زجزاج) لسلسلة مستقيمة من ست ذرات كربون كل روابطها أحادية. (4) صيغة هيكلية متعرجة لسلسلة مستقيمة من ست ذرات كربون فيها رابطة ثنائية واحدة بين ذرتي الكربون الأولى والثانية، والبقية روابط أحادية."}]'::jsonb, null, 'تحليل', 'تصنيف وتعليل', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('essay', 3, 'تحتوي المركبات (1) و(2) و(3) في الشكل الآتي على أكثر من حلقة. فسّر لماذا تُعدّ جميعها مركبات أروماتية، ووضّح المقصود بنظام الحلقات الملتحمة مستعينًا بالمركب (1)، ثم بيّن هل يُعدّ المركب (4) أروماتيًّا أيضًا.', null, '[{"src":"qimg/chem22/c4-l5a-fused3.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقتان سداسيتان ملتحمتان جنبًا إلى جنب تشتركان في ضلع، وبداخل كل منهما دائرة. (2) ثلاث حلقات سداسية ملتحمة على خط مستقيم، تشترك الوسطى في ضلع مع كل من الحلقتين الأخريين، وبداخل كل حلقة دائرة. (3) ثلاث حلقات سداسية ملتحمة بترتيب منحنٍ (زاوي): حلقتان متجاورتان أفقيًّا، والثالثة ملتحمة بالحلقة اليمنى من ضلعها العلوي الأيمن، وبداخل كل حلقة دائرة. (4) حلقة سداسية واحدة بداخلها دائرة ترتبط بها مجموعتا CH₃ في رأسين متقابلين (أعلى الحلقة وأسفلها)."}]'::jsonb, null, 'تحليل', 'تفسير وتطبيق', 'صعب', 'الكتاب ص 151 — المركبات الأروماتية')
