from (values
('mcq', 1, 0, 'المركبات الأروماتية هي المركبات العضوية التي تحتوي على حلقات البنزين جزءًا من بنائها، مثل البنزين والتولوين والنفثالين.', '["","هذا وصف الهيدروكربونات المشبعة مثل الألكانات، وهي لا تحتوي على حلقة بنزين.","هذا وصف الألكينات، وهي مركبات أليفاتية لا تحتوي على حلقة بنزين.","هذا هو الاستعمال الشائع لكلمة «أروماتي»؛ أما علميًّا فالمعيار هو وجود حلقة البنزين في البناء لا الرائحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 2, 1, 'المركب (2) يحتوي على حلقة بنزين (حلقة سداسية بداخلها دائرة) ترتبط بها مجموعة إيثيل، فهو إيثيل بنزين، وكل مركب يحتوي على حلقة بنزين جزءًا من بنائه مركب أروماتي.', '["المركب (1) حلقة سداسية كل روابطها أحادية (هكسان حلقي)، وهي حلقة مشبعة وليست حلقة بنزين، فهو أليفاتي.","","المركب (3) سلسلة مفتوحة كل روابطها أحادية (هكسان)، أي ألكان أليفاتي.","المركب (4) سلسلة مفتوحة فيها رابطة ثنائية واحدة (ألكين)، وهو مركب أليفاتي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 3, 2, 'استُخدم المصطلح «أروماتي» في الأصل لأن الكثير من المركبات المرتبطة بالبنزين المعروفة في القرن التاسع عشر وُجدت في الزيوت ذات الرائحة الطيبة الموجودة في البهارات والفواكه وغيرها من أجزاء النباتات.', '["تسخين دهون الحيوانات وشحومها هو أصل تسمية المركبات الأليفاتية (أليفاتي تعني الدهن)، لا الأروماتية.","الغاز الحيوي خليط من الميثان وثاني أكسيد الكربون، ولا علاقة له بأصل تسمية المركبات الأروماتية.","","الأملاح المعدنية مواد غير عضوية، ولا ترتبط بأصل المصطلح «أروماتي»."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 4, 3, 'المركب المرسوم هو النفثالين، وهو حلقتا بنزين ملتحمتان تشتركان في ضلع (نظام الحلقات الملتحمة)، وتتشارك ذرات الكربون فيه بالإلكترونات كما في البنزين؛ وبما أنه يحتوي على حلقات بنزين جزءًا من بنائه فهو مركب أروماتي.', '["الدائرة داخل كل حلقة تدل على حلقة بنزين بإلكترونات غير متمركزة، لا على حلقة مشبعة؛ والحلقة المشبعة لا تجعل المركب أروماتيًّا.","المركب المرسوم حلقي وليس سلسلة مفتوحة، والسلاسل المفتوحة ذات الروابط الثنائية ألكينات أليفاتية.","المركب يحتوي على حلقتين ملتحمتين وليس حلقة واحدة، ولا توجد فيه أي سلسلة جانبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 5, 0, 'ميثيل بنزين (التولوين) يتكون من حلقة بنزين ترتبط بها مجموعة ميثيل، فهو يحتوي على حلقة بنزين جزءًا من بنائه، ولذلك هو مركب أروماتي.', '["","الهكسان الحلقي ألكان حلقي حلقته مشبعة بروابط أحادية، ولا يحتوي على حلقة بنزين، فهو أليفاتي.","الإيثاين ألكاين (رابطة ثلاثية) سلسلته مفتوحة، فهو أليفاتي.","البروبين ألكين (رابطة ثنائية) سلسلته مفتوحة، فهو أليفاتي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 6, 1, 'المركب الأروماتي ثابت التركيب لأن إلكترونات الروابط في حلقة البنزين لا تبقى في مكان واحد؛ فهي غير متمركزة تتشارك فيها ذرات الكربون الست، ويصعب سحبها لأنها مشتركة مع ست نوى كربون.', '["لو كانت الروابط الثنائية متمركزة بين ذرات محددة لكان المركب نشطًا كالألكينات؛ فالتمركز يفسر النشاط لا الثبات.","","البنزين غير مشبع؛ فعدد ذرات الهيدروجين فيه C₆H₆ أقل من الهيدروكربون المشبع C₆H₁₄، فليس التشبع سبب ثباته.","الرائحة خاصية فيزيائية لا تفسر الثبات الكيميائي؛ فالثبات يعود إلى توزع إلكترونات الحلقة لا إلى الرائحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('mcq', 7, 2, 'المعنى الشائع لكلمة «أروماتي» هو «ذو رائحة قوية»، أما المعنى العلمي فهو مركب عضوي يحتوي على حلقة بنزين جزءًا من بنائه؛ لذا فالعبارة غير صحيحة لأن التصنيف يعتمد على البناء لا على الرائحة.', '["هذا هو الاستعمال الشائع للكلمة لا الاستعمال العلمي؛ فالمعيار العلمي هو حلقة البنزين.","مركبات كثيرة غير أروماتية لها روائح، فالرائحة ليست مقصورة على المركبات الأروماتية ولا تحددها.","","التعليل خاطئ؛ فالكثير من المركبات المرتبطة بالبنزين وُجد في زيوت ذات رائحة طيبة، فليست كلها عديمة الرائحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المركبات الأروماتية: مركبات عضوية تحتوي على حلقات البنزين جزءًا من بنائها. مثالان: البنزين C₆H₆، والتولوين (ميثيل بنزين)، ويقبل النفثالين أو الزايلين. سبب التسمية: استُخدم المصطلح «أروماتي» في الأصل لأن كثيرًا من المركبات المرتبطة بالبنزين التي عُرفت في القرن التاسع عشر وُجدت في الزيوت ذات الرائحة الطيبة في البهارات والفواكه وأجزاء النباتات.', '["تعريف المركبات الأروماتية بوجود حلقات البنزين في البناء","مثالان صحيحان","سبب التسمية: وجودها في الزيوت ذات الرائحة الطيبة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثالان (نصف درجة لكل مثال)","marks":1},{"element":"سبب التسمية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف دقيق، ومثالان صحيحان، وسبب التسمية"},{"level":"2 درجتان","description":"تعريف صحيح مع نقص في الأمثلة أو سبب التسمية"},{"level":"1 درجة","description":"تعريف ناقص أو أمثلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المركب الأروماتي بأنه المركب ذو الرائحة القوية","ذكر الهكسان الحلقي مثالًا على المركبات الأروماتية لأنه حلقي","الخلط بين سبب تسمية الأروماتية وسبب تسمية الأليفاتية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المركب (2) أروماتي؛ لأنه يحتوي على حلقة بنزين (حلقة سداسية بداخلها دائرة) ترتبط بها مجموعة إيثيل، فهو إيثيل بنزين. المركب (1) غير أروماتي؛ فهو حلقة سداسية مشبعة كل روابطها أحادية (هكسان حلقي) وليس فيه حلقة بنزين. المركب (3) غير أروماتي؛ فهو سلسلة مفتوحة من ست ذرات كربون بروابط أحادية (ألكان). المركب (4) غير أروماتي؛ فهو سلسلة مفتوحة فيها رابطة ثنائية (ألكين). والمركبات (1) و(3) و(4) هيدروكربونات أليفاتية.', '["(2) أروماتي لاحتوائه على حلقة بنزين","(1) غير أروماتي: حلقة مشبعة لا حلقة بنزين","(3) غير أروماتي: ألكان سلسلته مفتوحة","(4) غير أروماتي: ألكين سلسلته مفتوحة"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (2) وتعليله","marks":1},{"element":"تصنيف (1) وتعليله","marks":1},{"element":"تصنيف (3) وتعليله","marks":1},{"element":"تصنيف (4) وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح للمركبات الأربعة مع تعليل كل منها"},{"level":"2–3 درجات","description":"تصنيف صحيح لمعظم المركبات أو تعليل ناقص"},{"level":"1 درجة","description":"تصنيف صحيح لمركب واحد مع تعليله"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الهكسان الحلقي أروماتيًّا لأنه حلقة سداسية","تصنيف الألكين أروماتيًّا لاحتوائه على رابطة ثنائية","التعليل بالرائحة بدلًا من البناء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُعدّ المركبات (1) و(2) و(3) أروماتية لأن كل حلقة فيها حلقة بنزين (حلقة سداسية بداخلها دائرة تدل على إلكترونات غير متمركزة)، والمركب الأروماتي هو كل مركب عضوي يحتوي على حلقات البنزين جزءًا من بنائه. نظام الحلقات الملتحمة: أن يحتوي المركب العضوي على حلقتين أو أكثر تشتركان في الضلع نفسه، كما في المركب (1) (النفثالين) الذي تبدو صيغته كحلقتي بنزين متلاصقتين جنبًا إلى جنب، وتتشارك ذرات الكربون المكوّنة للحلقات بالإلكترونات كما في البنزين. والمركب (4) أروماتي أيضًا؛ لأنه يحتوي على حلقة بنزين واحدة ترتبط بها مجموعتا ميثيل (1، 4-ثنائي ميثيل بنزين).', '["كل حلقة في (1) و(2) و(3) حلقة بنزين، فالمركبات أروماتية","تعريف نظام الحلقات الملتحمة: حلقتان أو أكثر تشتركان في ضلع","تطبيق التعريف على المركب (1) وتشارك الإلكترونات","المركب (4) أروماتي لاحتوائه على حلقة بنزين"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير كون (1) و(2) و(3) أروماتية","marks":1},{"element":"تعريف الحلقات الملتحمة","marks":1},{"element":"التطبيق على المركب (1)","marks":1},{"element":"الحكم على المركب (4) مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير وتعريف وتطبيق وحكم صحيح على (4)"},{"level":"2–3 درجات","description":"تفسير صحيح مع نقص في التعريف أو التطبيق أو الحكم على (4)"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن المركب الأروماتي يجب أن يحتوي على حلقة واحدة فقط","تعريف الحلقات الملتحمة بأنها حلقات متصلة برابطة أحادية بينها","إخراج المركب (4) من الأروماتية لوجود مجموعتي ميثيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.629Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
