('mcq', 5, 'لا تُكتب ذرات الهيدروجين عادةً في التمثيل الحديث للبنزين. ما عدد ذرات الهيدروجين المرتبطة فعلًا بكل ذرة كربون في الحلقة؟', null, null, '["ذرتا هيدروجين","لا ترتبط بأي ذرة هيدروجين","ثلاث ذرات هيدروجين","ذرة هيدروجين واحدة"]'::jsonb, 'فهم', 'استنتاج من الصيغة', 'متوسط', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
('mcq', 6, 'يحتوي الهيدروكربون المشبع ذو ذرات الكربون الست على 14 ذرة هيدروجين. كم ذرة هيدروجين ينقصها جزيء البنزين مقارنةً به؟', null, null, '["ذرتان","8 ذرات","6 ذرات","4 ذرات"]'::jsonb, 'تطبيق', 'مقارنة صيغ جزيئية', 'صعب', 'الكتاب ص 149 — الصيغة البنائية للبنزين'),
('mcq', 7, 'اقتُرحت عام 1860م الصيغة CH₂=C=CH−CH=C=CH₂ للبنزين. في أيّ مما يأتي تتفق هذه الصيغة مع البنزين؟', null, null, '["البناء الحلقي السداسي لذرات الكربون","توزع الإلكترونات بالتساوي على ذرات الكربون الست","الصيغة الجزيئية C₆H₆","ضعف النشاط الكيميائي مقارنةً بالألكينات"]'::jsonb, 'فهم', 'مقارنة صيغتين', 'صعب', 'الكتاب ص 149 — الصيغة البنائية للبنزين'),
('essay', 1, 'اكتب الصيغة الجزيئية للبنزين، ثم صف صيغتين بنائيتين له: صيغة الروابط المتناوبة مع ذرات الهيدروجين، والتمثيل الحديث.', null, null, null, 'تذكر', 'كتابة صيغ', 'سهل', 'الكتاب ص 149–150 — الصيغة البنائية للبنزين'),
('essay', 2, 'يمثّل الشكلان (1) و(2) الآتيان جزيء البنزين. قارن بين الصيغتين من حيث: توزيع إلكترونات الروابط، وإظهار ذرات الهيدروجين، ومدى تمثيل كل منهما للبناء الفعلي للجزيء.', null, '[{"src":"qimg/chem22/c4-l5a-two-reps.svg","alt":"صيغتان بنائيتان متجاورتان: الصيغة (1) حلقة سداسية تتناوب فيها ثلاث روابط ثنائية مع ثلاث روابط أحادية، وترتبط بكل رأس من رؤوسها الستة ذرة هيدروجين H. والصيغة (2) حلقة سداسية بداخلها دائرة، دون كتابة أي ذرات هيدروجين."}]'::jsonb, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
