from (values
('mcq', 1, 3, 'جزيء البنزين يتكون من ست ذرات كربون وست ذرات هيدروجين، فصيغته الجزيئية C₆H₆.', '["C₆H₁₂ صيغة هيدروكربون سداسي الكربون فيه حلقة واحدة مشبعة أو رابطة ثنائية واحدة، كالهكسان الحلقي، لا البنزين.","C₆H₁₄ صيغة الهيدروكربون المشبع ذي ذرات الكربون الست (الهكسان)، وفيه ثماني ذرات هيدروجين أكثر من البنزين.","C₆H₁₀ فيها ذرات هيدروجين أكثر من البنزين بأربع، فهي ليست صيغته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 2, 2, 'يُمثَّل البنزين حديثًا بحلقة سداسية بداخلها دائرة، والدائرة ترمز إلى سحابة أزواج الإلكترونات الثلاثة غير المتمركزة؛ وهذا ما تظهره الصيغة (3).', '["الصيغة (1) حلقة سداسية كل روابطها أحادية، وهي الهكسان الحلقي C₆H₁₂ المشبع، لا البنزين.","الصيغة (2) فيها رابطة ثنائية واحدة فقط، فهي هكسين حلقي وليست بنزينًا.","","الصيغة (4) فيها رابطتان ثنائيتان فقط، فعدد ذرات الهيدروجين فيها أكبر من البنزين، وليست تمثيلًا له."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 3, 0, 'في التمثيل الحديث للبنزين ترمز الدائرة في منتصف الشكل السداسي إلى الغيمة (السحابة) المكوّنة من أزواج الإلكترونات الثلاثة غير المتمركزة التي تتشارك فيها ذرات الكربون الست.', '["","ذرات الهيدروجين لا تُكتب عادةً في هذا التمثيل لكنها موجودة، والدائرة لا ترمز إليها.","الدائرة تعني أن الإلكترونات غير متمركزة، فهي عكس فكرة الروابط الثنائية الثابتة في مواقع محددة.","الدائرة تمثل ثلاثة أزواج من الإلكترونات موزعة على الحلقة كلها، لا زوجًا واحدًا بين ذرتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 4, 1, 'في هذه الصيغة تتناوب الروابط الأحادية والثنائية حول الحلقة السداسية؛ فمن أضلاعها الستة ثلاثة أضلاع روابط ثنائية وثلاثة روابط أحادية.', '["الحلقة فيها ستة أضلاع، نصفها فقط روابط ثنائية لأن الروابط متناوبة.","","عدد الروابط الثنائية في الصيغة المتناوبة ثلاث لا اثنتان؛ فالحلقة سداسية تتناوب فيها ثلاث ثنائية مع ثلاث أحادية.","الصيغة فيها أكثر من رابطة ثنائية؛ إذ تتناوب ثلاث روابط ثنائية مع ثلاث أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 5, 3, 'صيغة البنزين C₆H₆ فيها ست ذرات كربون وست ذرات هيدروجين، فترتبط بكل ذرة كربون في الحلقة ذرة هيدروجين واحدة، وهي موجودة وإن لم تُكتب في التمثيل الحديث.', '["ذرتا هيدروجين لكل كربون تعطيان C₆H₁₂ (الهكسان الحلقي)، لا البنزين.","عدم كتابة ذرات الهيدروجين في هذا التمثيل لا يعني غيابها؛ فهي موجودة والصيغة C₆H₆.","ثلاث ذرات هيدروجين لكل ذرة كربون تعطي 18 ذرة هيدروجين، وهذا غير ممكن لذرة كربون في حلقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 6, 1, 'صيغة الهيدروكربون المشبع C₆H₁₄ وصيغة البنزين C₆H₆؛ فالفرق 14 − 6 = 8 ذرات هيدروجين، ولهذا استنتج الكيميائيون أن البنزين غير مشبع.', '["2 هي الفرق بين C₆H₁₄ وC₆H₁₂؛ أي استُخدمت صيغة الهكسان الحلقي بدلًا من صيغة البنزين C₆H₆.","","6 هي عدد ذرات الهيدروجين في البنزين نفسه، لا الفرق بينه وبين C₆H₁₄.","4 هي الفرق بين C₆H₁₄ وC₆H₁₀، أي استُخدمت صيغة خاطئة للبنزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('mcq', 7, 2, 'بعدّ ذرات الصيغة CH₂=C=CH−CH=C=CH₂: ست ذرات كربون، وذرات الهيدروجين 2 + 0 + 1 + 1 + 0 + 2 = 6، فصيغتها الجزيئية C₆H₆ مثل البنزين؛ لكنها سلسلة مفتوحة كثيرة الروابط الثنائية.', '["الصيغة المقترحة سلسلة مفتوحة وليست حلقة، فهي تختلف عن البنزين في البناء.","في هذه الصيغة إلكترونات الروابط الثنائية متمركزة بين ذرات محددة، وليست موزعة بالتساوي.","","مركب بهذه الصيغة يكون غير مستقر وشديد التفاعل لكثرة روابطه الثنائية، بخلاف البنزين قليل النشاط؛ ولهذا رُفضت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الصيغة الجزيئية: C₆H₆. الصيغة الأولى (الروابط المتناوبة): حلقة سداسية من ست ذرات كربون تتناوب فيها ثلاث روابط ثنائية مع ثلاث روابط أحادية، وترتبط بكل ذرة كربون ذرة هيدروجين واحدة متجهة إلى خارج الحلقة. الصيغة الثانية (التمثيل الحديث): شكل سداسي بداخله دائرة، لا تُكتب فيه ذرات الكربون ولا ذرات الهيدروجين مع أنها موجودة، والدائرة ترمز إلى سحابة أزواج الإلكترونات الثلاثة غير المتمركزة.', '["الصيغة الجزيئية C₆H₆","صيغة الروابط المتناوبة مع ست ذرات هيدروجين","التمثيل الحديث: سداسي بداخله دائرة ودلالة الدائرة"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغة الجزيئية","marks":1},{"element":"صيغة الروابط المتناوبة","marks":1},{"element":"التمثيل الحديث ودلالة الدائرة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الصيغة الجزيئية صحيحة والصيغتان البنائيتان موصوفتان بدقة"},{"level":"2 درجتان","description":"الصيغة الجزيئية وصيغة بنائية واحدة صحيحتان"},{"level":"1 درجة","description":"الصيغة الجزيئية فقط أو صيغة بنائية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة C₆H₁₂ للبنزين","رسم ست روابط ثنائية في الحلقة","ربط ذرتي هيدروجين بكل ذرة كربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('essay', 2, null::int, null, null, 'توزيع الإلكترونات: في الصيغة (1) إلكترونات الروابط الثنائية متمركزة بين أزواج محددة من ذرات الكربون (ثلاث روابط ثنائية متناوبة مع ثلاث أحادية)، وفي الصيغة (2) الإلكترونات غير متمركزة تتشارك فيها ذرات الكربون الست، والدائرة ترمز إلى سحابة أزواج الإلكترونات الثلاثة. ذرات الهيدروجين: تظهر في (1) ذرة هيدروجين على كل ذرة كربون، ولا تُكتب في (2) مع أنها موجودة. تمثيل البناء الفعلي: الصيغة (2) أدق؛ لأنها تفسر ثبات البنزين وضعف نشاطه الكيميائي، أما (1) فتفسر الشكل السداسي المسطح لكنها لا تفسر ضعف نشاطه، إذ تتوقع تفاعله كالألكينات.', '["المقارنة في توزيع الإلكترونات: متمركزة في (1) وغير متمركزة في (2)","المقارنة في إظهار ذرات الهيدروجين","الصيغة (2) أدق تمثيلًا مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"توزيع الإلكترونات","marks":2},{"element":"إظهار ذرات الهيدروجين","marks":1},{"element":"مدى تمثيل البناء الفعلي مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في المعايير الثلاثة مع تعليل"},{"level":"2–3 درجات","description":"مقارنة صحيحة في معيارين"},{"level":"1 درجة","description":"مقارنة صحيحة في معيار واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الصيغة (2) لا تحتوي على ذرات هيدروجين","عدّ الصيغتين لمركبين مختلفين","القول إن الدائرة تمثل ست روابط ثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.630Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدّ الذرات: ذرات الكربون C في CH₂ وC وCH وCH وC وCH₂ = 6 ذرات؛ وذرات الهيدروجين 2 + 0 + 1 + 1 + 0 + 2 = 6 ذرات؛ فالصيغة الجزيئية C₆H₆ وهي صيغة البنزين نفسها. سبب الرفض: هذه الصيغة تحتوي على أربع روابط ثنائية، ومثل هذا الهيدروكربون يكون غير مستقر وشديد التفاعل لكثرة روابطه الثنائية، في حين أن البنزين مادة غير نشطة كيميائيًّا ولا تتفاعل بالطرائق التي تتفاعل بها الألكينات والألكاينات عادة؛ لذا استنتج العلماء أن هذه الصيغة غير صحيحة.', '["عدد ذرات الكربون 6","عدد ذرات الهيدروجين 6 والصيغة C₆H₆","الصيغة المقترحة كثيرة الروابط الثنائية فيُتوقع أن تكون شديدة التفاعل","البنزين قليل النشاط لا يتفاعل كالألكينات، فرُفضت الصيغة"]'::jsonb, '["عدّ ذرات الكربون: 6","عدّ ذرات الهيدروجين: 2 + 0 + 1 + 1 + 0 + 2 = 6","الصيغة الجزيئية C₆H₆ = صيغة البنزين","مقارنة النشاط المتوقع بالنشاط الفعلي للبنزين"]'::jsonb, '[{"element":"عدّ ذرات الكربون والهيدروجين","marks":2},{"element":"توقع شدة التفاعل لكثرة الروابط الثنائية","marks":1},{"element":"ضعف نشاط البنزين وبالتالي رفض الصيغة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عدّ صحيح وتفسير كامل لسبب الرفض"},{"level":"2–3 درجات","description":"عدّ صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"عدّ صحيح فقط أو تفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الهيدروجين خطأً بإهمال ذرتي الكربون اللتين لا تحملان هيدروجين","القول إن الصيغة رُفضت لأن صيغتها الجزيئية تختلف عن البنزين","عدم الربط بين كثرة الروابط الثنائية وشدة النشاط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb)
