('mcq', 4, 'يُروى أن كيكولي توصّل إلى صيغته للبنزين بعد حلم رأى فيه ثعبانًا يعض ذيله. بماذا ارتبطت هذه الصورة بصيغته؟', null, null, '["بالسلسلة المفتوحة ذات الروابط الثنائية المتجاورة","بتوزع الإلكترونات غير المتمركزة على الحلقة كلها","بعدد ذرات الهيدروجين المرتبطة بكل ذرة كربون","بالشكل الحلقي الذي تتصل فيه ذرات الكربون الست"]'::jsonb, 'فهم', 'ربط قصة علمية بمفهوم', 'متوسط', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
('mcq', 5, 'أيّ الصيغ في الشكل الآتي تمثّل الصيغة البنائية التي اقترحها كيكولي للبنزين عام 1865م؟', null, '[{"src":"qimg/chem22/c4-l5a-proposals4.svg","alt":"أربع صيغ مرقمة: (1) حلقة سداسية بداخلها دائرة دون رموز ذرات. (2) صيغة سلسلة مفتوحة مكتوبة CH₂=C=CH−CH=C=CH₂. (3) حلقة سداسية تتناوب فيها ثلاث روابط ثنائية مع ثلاث روابط أحادية، وترتبط بكل رأس من رؤوسها الستة ذرة هيدروجين H. (4) حلقة سداسية كل أضلاعها روابط أحادية دون دائرة أو روابط ثنائية."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'فهم', 'تفسير قصور نموذج', 'صعب', 'الكتاب ص 149–150 — الصيغة البنائية للبنزين وحلم كيكولي'),
('mcq', 6, 'يبين الجدول الآتي أربعة أحداث في دراسة البنزين. أيّ صف يصف إسهام كيكولي؟', '{"headers":["الصف","العام","الحدث"],"rows":[["(1)","1825م","عزل البنزين أول مرة من الغازات المنبعثة عند تسخين زيوت الحيتان أو الفحم"],["(2)","1865م","اقتراح صيغة حلقية سداسية تتناوب فيها الروابط الأحادية والثنائية"],["(3)","1860م","اقتراح صيغة السلسلة CH₂=C=CH−CH=C=CH₂"],["(4)","1930م","اقتراح نظرية المجالات المهجنة وتفسير عدم تمركز الإلكترونات"]]}'::jsonb, null, '["الصف (1)","الصف (2)","الصف (3)","الصف (4)"]'::jsonb, 'تذكر', 'قراءة جدول وتمييز إسهام', 'متوسط', 'الكتاب ص 149–150 — الصيغة البنائية للبنزين'),
('mcq', 7, 'قال طالب: «مايكل فاراداي هو الذي اقترح الصيغة الحلقية للبنزين؛ لأنه أول من عزله». ما التقويم الصحيح لعبارته؟', null, null, '["صحيحة؛ لأن العالم الذي يعزل المادة أول مرة هو الذي يقترح صيغتها البنائية","غير صحيحة؛ لأن الصيغة الحلقية اقترحها باولنج عام 1930م بنظرية المجالات المهجنة","غير صحيحة؛ ففاراداي عزل البنزين عام 1825م، والصيغة الحلقية اقترحها كيكولي عام 1865م","غير صحيحة؛ لأن الصيغة الحلقية اقتُرحت عام 1860م قبل كيكولي بخمسة أعوام"]'::jsonb, 'تقويم', 'مقارنة نموذجين', 'صعب', 'الكتاب ص 149–150 — الصيغة البنائية للبنزين وحلم كيكولي'),
('essay', 1, 'اذكر اسم العالم الذي اقترح الصيغة البنائية الحلقية للبنزين، وجنسيته، وعام اقتراحه، ثم صف صيغته.', null, null, null, 'تذكر', 'تذكر حقائق ووصف', 'سهل', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
