from (values
('mcq', 1, 0, 'في عام 1865م اقترح الكيميائي الألماني فريدريك أوجست كيكولي صيغة بنائية للبنزين على شكل سداسي تتناوب فيه الروابط الأحادية والثنائية.', '["","فاراداي هو الذي عزل البنزين أول مرة عام 1825م، ولم يقترح صيغته الحلقية.","باولنج اقترح نظرية المجالات المهجنة عام 1930م التي فسّرت عدم تمركز الإلكترونات، بعد كيكولي بعقود.","فوهلر عالم ارتبط اسمه بتحضير اليوريا، لا بصيغة البنزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 2, 3, 'الصيغة المرسومة حلقة سداسية تتناوب فيها الروابط الأحادية والثنائية، وهي الصيغة التي اقترحها كيكولي عام 1865م، وتُعرف باسمه.', '["فاراداي عزل البنزين ولم يقترح له صيغة بنائية.","نموذج باولنج الحديث يمثَّل بدائرة داخل الحلقة لا بروابط ثنائية متناوبة.","دالتون صاحب النظرية الذرية، ولم يقترح صيغة للبنزين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 3, 2, 'كيكولي كيميائي ألماني (1829–1896م) اقترح صيغته الحلقية للبنزين عام 1865م.', '["هذه جنسية فاراداي وعام عزله للبنزين، لا كيكولي.","الجنسية صحيحة، لكن عام 1825م هو عام عزل فاراداي للبنزين.","","العام صحيح، لكن كيكولي ألماني لا بريطاني؛ والبريطاني هو فاراداي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 4, 3, 'صورة الثعبان الذي يعض ذيله (شعار الأوروبوروس) جعلت كيكولي يفكر في الشكل الحلقي؛ أي أن تتصل ذرات الكربون الست بعضها ببعض في حلقة مغلقة بدلًا من سلسلة مفتوحة.', '["الثعبان الذي يعض ذيله شكل مغلق، وهذا عكس السلسلة المفتوحة.","عدم تمركز الإلكترونات فكرة جاءت لاحقًا مع نظرية المجالات المهجنة عام 1930م، لا مع حلم كيكولي.","صورة الحلم ارتبطت بشكل الهيكل الكربوني لا بعدد ذرات الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 5, 2, 'اقترح كيكولي عام 1865م أن البنزين حلقة سداسية من ست ذرات كربون تتناوب فيها الروابط الأحادية والثنائية، وعلى كل ذرة كربون ذرة هيدروجين؛ وهذا ما تمثله الصيغة (3).', '["الصيغة (1) سداسي بداخله دائرة، وهو التمثيل الحديث الذي يعبّر عن الإلكترونات غير المتمركزة، لا صيغة كيكولي ذات الروابط المتناوبة.","الصيغة (2) سلسلة مفتوحة اقتُرحت عام 1860م قبل كيكولي ثم رُفضت، وليست حلقة.","","الصيغة (4) حلقة كل روابطها أحادية (حلقة مشبعة)، وصيغة كيكولي تتناوب فيها الروابط الأحادية والثنائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 6, 1, 'إسهام كيكولي عام 1865م هو اقتراح صيغة البنزين حلقة سداسية تتناوب فيها الروابط الأحادية والثنائية، وهو ما يصفه الصف (2).', '["الصف (1) يصف عزل البنزين أول مرة عام 1825م، وهو إسهام فاراداي.","","الصف (3) يصف صيغة السلسلة المفتوحة المقترحة عام 1860م، قبل كيكولي، وقد ثبت خطؤها.","الصف (4) يصف نظرية المجالات المهجنة عام 1930م التي اقترحها باولنج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.631Z"}'::jsonb),
('mcq', 7, 2, 'عزل الفيزيائي البريطاني مايكل فاراداي البنزين أول مرة عام 1825م، لكن الصيغة البنائية الحلقية (حلقة سداسية تتناوب فيها الروابط الأحادية والثنائية) اقترحها الكيميائي الألماني كيكولي عام 1865م؛ فالعبارة غير صحيحة لأنها نسبت إسهام كيكولي إلى فاراداي.', '["عزل المادة لا يعني اقتراح صيغتها؛ فقد عُزل البنزين عام 1825م وبقي بناؤه غامضًا حتى اقترح كيكولي الحلقة عام 1865م.","باولنج لم يقترح الحلقة السداسية؛ بل فسّر عام 1930م عدم تمركز الإلكترونات في حلقة اقترحها كيكولي قبله.","","الصيغة المقترحة عام 1860م سلسلة مفتوحة CH₂=C=CH−CH=C=CH₂ لا حلقة، ورُفضت؛ والحلقة اقترحها كيكولي عام 1865م."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العالم: فريدريك أوجست كيكولي (1829–1896م)، كيميائي ألماني، اقترح صيغته عام 1865م. وصف الصيغة: حلقة سداسية من ست ذرات كربون تتناوب فيها الروابط الأحادية والثنائية (ثلاث روابط ثنائية وثلاث أحادية)، وترتبط بكل ذرة كربون ذرة هيدروجين واحدة.', '["اسم العالم: كيكولي","الجنسية: ألماني","العام: 1865م","وصف الحلقة السداسية بروابط أحادية وثنائية متناوبة"]'::jsonb, '[]'::jsonb, '[{"element":"اسم العالم","marks":1},{"element":"الجنسية","marks":1},{"element":"العام","marks":1},{"element":"وصف الصيغة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاسم والجنسية والعام ووصف الصيغة صحيحة"},{"level":"2–3 درجات","description":"الاسم صحيح مع خطأ أو نقص في عنصر أو عنصرين"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الصيغة الحلقية إلى فاراداي","كتابة عام 1825م بدلًا من 1865م","وصف الصيغة بست روابط ثنائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الرسم: حلقة سداسية من ست ذرات كربون تتناوب فيها ثلاث روابط ثنائية مع ثلاث روابط أحادية، وعلى كل ذرة كربون ذرة هيدروجين. سبب القصور: لو كانت في البنزين ثلاث روابط ثنائية متمركزة بين ذرات كربون محددة لكان نشطًا كيميائيًّا يتفاعل كالألكينات، لكن البنزين ضعيف النشاط؛ فصيغة كيكولي تفسر الشكل السداسي المسطح لكنها لا تفسر ضعف نشاطه. معالجة النموذج الحديث: بيّنت نظرية المجالات المهجنة (باولنج 1930م) أن أزواج إلكترونات الروابط الثنائية لا تتجمع بين ذرتي كربون محددتين، بل هي غير متمركزة تتشارك فيها ذرات الكربون الست، فيصعب سحبها لأنها مشتركة مع ست نوى، فيكون الجزيء ثابتًا؛ ويُرمز إلى ذلك بدائرة داخل السداسي.', '["رسم صحيح لحلقة سداسية بروابط متناوبة وذرات الهيدروجين","القصور: لا تفسر ضعف النشاط الكيميائي","التعليل: الروابط الثنائية المتمركزة تقتضي نشاطًا كالألكينات","النموذج الحديث: إلكترونات غير متمركزة تتشارك فيها الذرات الست"]'::jsonb, '[]'::jsonb, '[{"element":"الرسم","marks":1},{"element":"بيان القصور","marks":1},{"element":"تعليل القصور","marks":1},{"element":"معالجة النموذج الحديث","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح وتفسير كامل للقصور ومعالجته"},{"level":"2–3 درجات","description":"رسم صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"رسم صحيح فقط أو تفسير فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الروابط الثنائية متجاورة لا متناوبة","القول إن صيغة كيكولي خاطئة لأنها لا تحتوي على ست ذرات هيدروجين","نسيان أن الإلكترونات غير المتمركزة سبب الثبات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الترتيب: (1) عزل البنزين عام 1825م على يد فاراداي. (2) اقتراح صيغة السلسلة CH₂=C=CH−CH=C=CH₂ عام 1860م. (3) اقتراح الحلقة السداسية ذات الروابط الأحادية والثنائية المتناوبة عام 1865م على يد كيكولي. (4) نظرية المجالات المهجنة عام 1930م على يد لينوس باولنج. ما أضافه كيكولي: الشكل الحلقي السداسي المسطح لذرات الكربون الست بدلًا من السلسلة المفتوحة، وهو ما ثبت صحته لاحقًا ويفسر بعض خصائص البنزين. ما بقي دون تفسير: ضعف النشاط الكيميائي للبنزين، إلى أن فسّرته نظرية المجالات المهجنة بعدم تمركز الإلكترونات.', '["ترتيب زمني صحيح للمراحل الأربع","الأعوام والعلماء صحيحة","إضافة كيكولي: الشكل الحلقي السداسي","ما بقي دون تفسير: ضعف النشاط الكيميائي"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الزمني","marks":1},{"element":"الأعوام والعلماء","marks":1},{"element":"ما أضافه كيكولي","marks":1},{"element":"ما بقي دون تفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب وأعوام وعلماء صحيحة، وبيان الإضافة والقصور"},{"level":"2–3 درجات","description":"ترتيب صحيح مع خطأ في عام أو عالم أو نقص في البيان"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع اقتراح كيكولي قبل صيغة 1860م","نسبة عزل البنزين إلى كيكولي","القول إن كيكولي فسّر ضعف نشاط البنزين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb)
