('mcq', 5, 0, 'فاراداي عزل البنزين أول مرة عام 1825م، وكيكولي اقترح صيغته الحلقية السداسية عام 1865م.', '["","هذا عكس الإسهامين؛ ففاراداي هو الذي عزل البنزين، وكيكولي اقترح الحلقة.","نظرية المجالات المهجنة لباولنج لا لفاراداي، وكيكولي لم يعزل البنزين.","الشق الأول صحيح، لكن نظرية المجالات المهجنة اقترحها باولنج لا كيكولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb),
('mcq', 6, 1, 'عزل فاراداي البنزين عام 1825م، واقترح كيكولي الصيغة الحلقية عام 1865م؛ والفرق 1865 − 1825 = 40 عامًا.', '["كيكولي لم يعزل البنزين؛ بل اقترح صيغته البنائية بعد عزله بعقود.","","العازل صحيح لكن الترتيب خاطئ؛ فنظرية باولنج (1930م) جاءت بعد العزل (1825م) بأكثر من قرن.","المصدر صحيح لكن العازل خاطئ؛ فالذي عزل البنزين هو فاراداي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.632Z"}'::jsonb),
('mcq', 7, 3, 'عُزل البنزين أول مرة عام 1825م على يد الفيزيائي البريطاني مايكل فاراداي، وهذا ما يصفه الصف (4).', '["كيكولي الكيميائي الألماني اقترح الصيغة الحلقية للبنزين عام 1865م، ولم يعزله.","العالم وتخصصه وجنسيته صحيحة، لكن عام العزل 1825م؛ أما 1865م فعام اقتراح كيكولي صيغته.","العام صحيح، لكن الذي عزل البنزين فاراداي لا كيكولي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العالم: مايكل فاراداي (1791–1867م). تخصصه: فيزيائي. جنسيته: بريطاني. عام العزل: 1825م. المصدر: الغازات الزيتية المنبعثة عند تسخين زيوت الحيتان أو الفحم.', '["الاسم: فاراداي","التخصص والجنسية: فيزيائي بريطاني","العام: 1825م","المصدر: الغازات المنبعثة عند تسخين زيوت الحيتان أو الفحم"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم","marks":1},{"element":"التخصص والجنسية","marks":1},{"element":"العام","marks":1},{"element":"المصدر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"الاسم صحيح مع خطأ أو نقص في عنصر أو عنصرين"},{"level":"1 درجة","description":"الاسم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة العزل إلى كيكولي","وصف فاراداي بأنه كيميائي ألماني","كتابة عام 1865م"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('essay', 2, null::int, null, null, 'فاراداي: نوع الإسهام عزل البنزين أول مرة من الغازات المنبعثة عند تسخين زيوت الحيتان أو الفحم؛ العام 1825م؛ فيزيائي بريطاني. كيكولي: نوع الإسهام اقتراح الصيغة البنائية للبنزين حلقة سداسية تتناوب فيها الروابط الأحادية والثنائية؛ العام 1865م؛ كيميائي ألماني. أي إن فاراداي حصل على المادة نفسها، وكيكولي اقترح بناءها بعد نحو 40 عامًا.', '["إسهام فاراداي: العزل","إسهام كيكولي: الصيغة الحلقية","العامان 1825م و1865م","فاراداي فيزيائي بريطاني وكيكولي كيميائي ألماني"]'::jsonb, '[]'::jsonb, '[{"element":"نوع إسهام كل عالم","marks":2},{"element":"العامان","marks":1},{"element":"التخصص والجنسية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في المعايير الثلاثة"},{"level":"2–3 درجات","description":"نوع الإسهامين صحيح مع خطأ في العام أو الجنسية"},{"level":"1 درجة","description":"إسهام عالم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل الإسهامين بين العالمين","الخلط بين عامي 1825م و1865م","وصف العالمين بالجنسية نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأخطاء وتصحيحها: (1) العالم: الذي عزل البنزين أول مرة هو مايكل فاراداي، وهو فيزيائي بريطاني، لا الكيميائي الألماني كيكولي. (2) العام: عُزل البنزين عام 1825م؛ أما 1865م فهو عام اقتراح كيكولي صيغته الحلقية. (3) المصدر: عزله فاراداي من الغازات المنبعثة عند تسخين زيوت الحيتان أو الفحم، لا من زيوت البهارات (الزيوت العطرية مرتبطة بأصل تسمية المركبات الأروماتية). (4) الفعل: البنزين عُزل (فُصل من مصدره) ولم يُحضَّر. الفرق: العزل هو فصل المادة من مصدرها والحصول عليها، وقام به فاراداي عام 1825م؛ أما اقتراح الصيغة البنائية فهو تحديد كيفية ارتباط ذرات المادة بعضها ببعض، وقام به كيكولي عام 1865م حين اقترح حلقة سداسية تتناوب فيها الروابط الأحادية والثنائية، أي بعد العزل بنحو 40 عامًا.', '["تصحيح العالم: فاراداي الفيزيائي البريطاني","تصحيح العام: 1825م","تصحيح المصدر: الغازات المنبعثة عند تسخين زيوت الحيتان أو الفحم","الفرق بين العزل (فاراداي 1825م) واقتراح الصيغة (كيكولي 1865م)"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح العالم وتخصصه وجنسيته","marks":1},{"element":"تصحيح العام","marks":1},{"element":"تصحيح المصدر","marks":1},{"element":"الفرق بين العزل واقتراح الصيغة وصاحب كل منهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصحيح العالم والعام والمصدر، وبيان الفرق مع صاحب كل إسهام"},{"level":"2–3 درجات","description":"تصحيح العالم مع نقص في تصحيح العام أو المصدر أو في بيان الفرق"},{"level":"1 درجة","description":"تصحيح خطأ واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الإبقاء على كيكولي عازلًا للبنزين","تصحيح العالم دون تصحيح العام 1865م","عدّ زيوت البهارات مصدر عزل البنزين","الخلط بين عزل المادة واقتراح صيغتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
