from (values
('mcq', 1, 'ما المقصود بالمركبات الأليفاتية؟', null, null, '["هيدروكربونات كالألكانات والألكينات والألكاينات، لا حلقات بنزين فيها","مركبات عضوية تحتوي على حلقات البنزين جزءًا من بنائها","هيدروكربونات تحتوي على روابط ثنائية أو ثلاثية فقط، ولا تشمل الألكانات","مركبات عضوية استُخلصت أول مرة من الزيوت ذات الرائحة الطيبة"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 2, 'ما معنى كلمة «أليفاتي» (aliphatic) في أصلها اليوناني؟', null, null, '["الرائحة","الدهن","السلسلة","الحلقة"]'::jsonb, 'تذكر', 'تذكر أصل المصطلح', 'سهل', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 3, 'سُمّيت المركبات الأليفاتية بهذا الاسم لأن الكيميائيين القدامى حصلوا عليها:', null, null, '["من الزيوت العطرية للبهارات والفواكه","بالتقطير التجزيئي للنفط الخام","بتسخين دهون الحيوانات وشحومها","من الأصباغ الطبيعية للأنسجة"]'::jsonb, 'فهم', 'تفسير التسمية', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 4, 'كم مركبًا أليفاتيًّا يظهر في الشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l5a-classify4.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقة سداسية كل أضلاعها روابط أحادية دون أي دائرة أو روابط ثنائية. (2) حلقة سداسية بداخلها دائرة ترتبط بأحد رؤوسها مجموعة CH₂CH₃. (3) صيغة هيكلية متعرجة (زجزاج) لسلسلة مستقيمة من ست ذرات كربون كل روابطها أحادية. (4) صيغة هيكلية متعرجة لسلسلة مستقيمة من ست ذرات كربون فيها رابطة ثنائية واحدة بين ذرتي الكربون الأولى والثانية، والبقية روابط أحادية."}]'::jsonb, '["مركبان","أربعة مركبات","مركب واحد","ثلاثة مركبات"]'::jsonb, 'فهم', 'تصنيف مركبات من صيغها', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 5, 'أيّ مجموعات المركبات الآتية كلها أليفاتية؟', null, null, '["البروبان، والإيثين، والإيثاين","البنزين، والإيثان، والبروبين","الهكسان، والتولوين، والإيثاين","النفثالين، والميثان، والبيوتين"]'::jsonb, 'تذكر', 'تمييز أمثلة', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 6, 'تتكون ذرات الكربون في الهكسان الحلقي C₆H₁₂ من حلقة سداسية. كيف يُصنَّف هذا المركب؟', null, null, '["أروماتي؛ لأن ذرات الكربون فيه تكوّن حلقة سداسية","أليفاتي؛ لأنه ألكان حلقي لا يحتوي على حلقة بنزين","أروماتي؛ لأن إلكتروناته غير متمركزة على الحلقة","ليس هيدروكربونًا؛ لأنه لا يحتوي على سلسلة مفتوحة"]'::jsonb, 'تحليل', 'تصنيف وتعليل', 'صعب', 'الكتاب ص 151 — المركبات الأروماتية والأليفاتية'),
('mcq', 7, 'ما الذي يميّز المركبات الأليفاتية من المركبات الأروماتية؟', null, null, '["احتواؤها على ذرات أكسجين إضافةً إلى الكربون والهيدروجين","احتواؤها على روابط ثنائية في جميع أنواعها","خلوّها من حلقات البنزين ذات الإلكترونات غير المتمركزة","كونها مركبات غير عضوية مصدرها الصخور والمعادن"]'::jsonb, 'فهم', 'تمييز بين فئتين', 'صعب', 'الكتاب ص 151 وص 158 — المركبات الأليفاتية'),
('essay', 1, 'عرّف المركبات الأليفاتية، واذكر ثلاثة أنواع منها مع مثال على كل نوع، ثم بيّن أصل تسميتها.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'سهل', 'الكتاب ص 151 — المركبات الأروماتية'),
('essay', 2, 'فسّر كيف تختلف الهيدروكربونات الأروماتية عن الهيدروكربونات الأليفاتية من حيث البناء والثبات، مع ذكر مثال على كل منهما.', null, null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 150–151 وص 154 (س 34)'),
('essay', 3, 'يبين الشكل الآتي أربع حلقات سداسية من ذرات الكربون. صنّف كلًّا منها إلى أليفاتي أو أروماتي مع التعليل، ثم فسّر لماذا لا يكفي وجود حلقة في المركب لعدّه أروماتيًّا.', null, '[{"src":"qimg/chem22/c4-l5a-four-rings.svg","alt":"أربع حلقات سداسية من ذرات الكربون مرسومة بالصيغ الهيكلية (الخطية) ومرقمة: (1) حلقة سداسية كل أضلاعها روابط أحادية. (2) حلقة سداسية فيها رابطة ثنائية واحدة والباقي روابط أحادية. (3) حلقة سداسية بداخلها دائرة. (4) حلقة سداسية فيها رابطتان ثنائيتان بينهما رابطة أحادية واحدة، والأضلاع الأخرى روابط أحادية."}]'::jsonb, null, 'تحليل', 'تصنيف وتفسير', 'صعب', 'الكتاب ص 150–151 — المركبات الأروماتية والأليفاتية')
