from (values
('mcq', 1, 0, 'تسمى الهيدروكربونات مثل الألكانات والألكينات والألكاينات المركبات الأليفاتية، لتمييزها عن المركبات الأروماتية التي تحتوي على حلقات البنزين.', '["","هذا تعريف المركبات الأروماتية لا الأليفاتية.","الألكانات ذات الروابط الأحادية من المركبات الأليفاتية أيضًا، فلا تقتصر الأليفاتية على غير المشبعة.","الزيوت ذات الرائحة الطيبة ارتبطت بأصل تسمية المركبات الأروماتية لا الأليفاتية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 2, 1, 'كلمة أليفاتي (aliphatic) يونانية الأصل تعني الدهن؛ لأن الكيميائيين القدامى حصلوا على المركبات الأليفاتية بتسخين دهون الحيوانات وشحومها.', '["الرائحة مرتبطة بالمصطلح «أروماتي» لا «أليفاتي».","","مع أن كثيرًا من المركبات الأليفاتية سلاسل، فهذا ليس معنى الكلمة في أصلها.","الحلقة لا تعبّر عن معنى الكلمة، وبعض المركبات الأليفاتية حلقية وبعضها غير حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 3, 2, 'كلمة أليفاتي تعني الدهن؛ وذلك لأن الكيميائيين القدامى حصلوا على المركبات الأليفاتية بتسخين دهون الحيوانات وشحومها.', '["الزيوت العطرية ارتبطت بتسمية المركبات الأروماتية.","التقطير التجزيئي طريقة لفصل مكونات النفط، ولا علاقة له بأصل التسمية.","","الأصباغ الطبيعية تحتوي على صيغ حلقية أروماتية، ولا علاقة لها بتسمية الأليفاتية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 4, 3, 'المركب (1) ألكان حلقي (هكسان حلقي)، والمركب (3) ألكان (هكسان)، والمركب (4) ألكين؛ وهذه الثلاثة أليفاتية لأنها لا تحتوي على حلقة بنزين. أما المركب (2) فيحتوي على حلقة بنزين فهو أروماتي. إذن عدد المركبات الأليفاتية ثلاثة.', '["هذا العدد يُهمل المركب (1)؛ فالحلقة المشبعة ليست حلقة بنزين، والألكان الحلقي أليفاتي.","المركب (2) يحتوي على حلقة بنزين، فهو أروماتي وإن كانت فيه مجموعة إيثيل.","المركبات (1) و(3) و(4) كلها أليفاتية، لا الألكين وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 5, 0, 'البروبان ألكان، والإيثين ألكين، والإيثاين ألكاين؛ وكلها هيدروكربونات لا تحتوي على حلقات بنزين، فهي أليفاتية.', '["","البنزين أروماتي، فالمجموعة ليست كلها أليفاتية.","التولوين (ميثيل بنزين) أروماتي، فالمجموعة ليست كلها أليفاتية.","النفثالين حلقتا بنزين ملتحمتان، فهو أروماتي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 6, 1, 'الهكسان الحلقي ألكان حلقي كل روابطه أحادية، وليس فيه حلقة بنزين؛ والألكانات (ومنها الحلقية) من المركبات الأليفاتية. فوجود حلقة لا يكفي، والمعيار هو حلقة البنزين.', '["الحلقة السداسية المشبعة ليست حلقة بنزين؛ فالشكل الحلقي وحده لا يجعل المركب أروماتيًّا.","","إلكترونات الروابط في الهكسان الحلقي أحادية متمركزة، وعدم التمركز صفة حلقة البنزين.","الهكسان الحلقي يتكون من الكربون والهيدروجين فقط، فهو هيدروكربون وإن كان حلقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.633Z"}'::jsonb),
('mcq', 7, 2, 'المركبات الأروماتية تحتوي على حلقات بنزين تتوزع فيها الإلكترونات على الحلقة كاملة بالتساوي، أما الأليفاتية (الألكانات والألكينات والألكاينات) فلا تحتوي على حلقات بنزين.', '["المركبات الأليفاتية المقصودة هنا هيدروكربونات تتكون من الكربون والهيدروجين فقط.","الألكانات أليفاتية وليس فيها روابط ثنائية، فليست الروابط الثنائية صفة مميزة لها.","","المركبات الأليفاتية مركبات عضوية، وقد حصل عليها الكيميائيون القدامى من دهون الحيوانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المركبات الأليفاتية: هيدروكربونات مثل الألكانات والألكينات والألكاينات، وتسمى بذلك لتمييزها عن المركبات الأروماتية التي تحتوي على حلقات البنزين. الأنواع والأمثلة: الألكانات مثل الميثان أو البروبان، والألكينات مثل الإيثين أو البروبين، والألكاينات مثل الإيثاين. أصل التسمية: كلمة أليفاتي يونانية الأصل تعني الدهن؛ لأن الكيميائيين القدامى حصلوا على هذه المركبات بتسخين دهون الحيوانات وشحومها.', '["التعريف","ثلاثة أنواع مع مثال لكل نوع","أصل التسمية: الدهن وتسخين دهون الحيوانات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الأنواع والأمثلة","marks":2},{"element":"أصل التسمية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح، وثلاثة أنواع بأمثلتها، وأصل التسمية"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الأمثلة أو أصل التسمية"},{"level":"1 درجة","description":"تعريف فقط أو أمثلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر البنزين أو التولوين مثالًا على المركبات الأليفاتية","القول إن أليفاتي تعني الرائحة","إخراج الألكانات من المركبات الأليفاتية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('essay', 2, null::int, null, null, 'البناء: الهيدروكربونات الأروماتية تحتوي على حلقة بنزين أو أكثر جزءًا من بنائها، أما الأليفاتية (الألكانات والألكينات والألكاينات) فلا تحتوي على حلقات بنزين؛ فقد تكون سلاسل مستقيمة أو متفرعة أو حلقات مشبعة كالألكانات الحلقية. الثبات: الأروماتية ثابتة بدرجة عالية؛ لأن أزواج الإلكترونات في حلقة البنزين غير متمركزة تتوزع على الحلقة كاملة بالتساوي ويصعب سحبها لأنها مشتركة مع ست نوى كربون، أما الألكينات والألكاينات الأليفاتية فروابطها الثنائية أو الثلاثية متمركزة فتكون أنشط كيميائيًّا. مثالان: البنزين أو التولوين (أروماتي)، والإيثين أو الهكسان (أليفاتي).', '["الفرق في البناء: وجود حلقة البنزين أو عدمه","الفرق في الثبات: الإلكترونات غير المتمركزة تجعل الأروماتية أثبت","مثال أروماتي","مثال أليفاتي"]'::jsonb, '[]'::jsonb, '[{"element":"الفرق في البناء","marks":1},{"element":"الفرق في الثبات مع التعليل","marks":1},{"element":"مثال أروماتي","marks":1},{"element":"مثال أليفاتي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"فرق البناء والثبات مفسران، ومثالان صحيحان"},{"level":"2–3 درجات","description":"أحد الفرقين مفسر مع مثالين أو الفرقان دون أمثلة"},{"level":"1 درجة","description":"مثالان فقط أو فرق واحد دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كل مركب حلقي أروماتي","تعليل ثبات البنزين بتشبعه","ذكر الهكسان الحلقي مثالًا أروماتيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) حلقة سداسية كل روابطها أحادية (هكسان حلقي، ألكان حلقي): أليفاتي. (2) حلقة فيها رابطة ثنائية واحدة (ألكين حلقي): أليفاتي. (3) حلقة سداسية بداخلها دائرة (بنزين): أروماتي؛ لأنها حلقة بنزين إلكتروناتها غير متمركزة. (4) حلقة فيها رابطتان ثنائيتان متمركزتان فقط (ألكين حلقي): أليفاتي؛ لأنها ليست حلقة بنزين. التفسير: المعيار في تعريف المركب الأروماتي هو احتواؤه على حلقة بنزين، أي حلقة سداسية تتشارك فيها ذرات الكربون الست بإلكترونات غير متمركزة؛ أما الحلقات المشبعة أو الحلقات ذات الروابط الثنائية المتمركزة فتسلك سلوك الألكانات أو الألكينات، فهي أليفاتية.', '["(1) أليفاتي: ألكان حلقي","(2) أليفاتي: ألكين حلقي","(3) أروماتي: حلقة بنزين","(4) أليفاتي: رابطتان ثنائيتان متمركزتان","التفسير: المعيار حلقة البنزين لا مجرد الحلقة"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الحلقات الأربع مع التعليل (نصف درجة لكل حلقة)","marks":2},{"element":"تفسير عدم كفاية الحلقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تصنيف صحيح للحلقات الأربع وتفسير صحيح"},{"level":"2 درجتان","description":"تصنيف صحيح دون تفسير، أو تصنيف بخطأ واحد مع تفسير"},{"level":"1 درجة","description":"تصنيف صحيح لحلقتين على الأقل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الحلقة (4) أروماتية لاحتوائها على روابط ثنائية","تصنيف الحلقات كلها أروماتية لأنها سداسية","عدم ذكر أن المعيار هو حلقة البنزين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb)
