('mcq', 4, 'يبين الشكل الآتي ترقيمين لحلقة البنزين في المركب نفسه. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/chem22/c4-l5a-dipropyl-two-numberings.svg","alt":"رسمان للمركب نفسه: حلقة سداسية بداخلها دائرة، ترتبط مجموعة CH₂CH₂CH₃ بالرأس العلوي، ومجموعة CH₂CH₂CH₃ أخرى بالرأس السفلي الأيمن. في الرسم (1) رُقّمت ذرات الحلقة بدءًا من الرأس العلوي بالرقم 1 ثم مع اتجاه حركة عقارب الساعة 2 و3 و4 و5 و6، فتقع المجموعتان على الذرتين 1 و3. وفي الرسم (2) رُقّمت بدءًا من الرأس السفلي الأيمن بالرقم 1 ثم 2 للرأس السفلي و3 و4 حتى الرأس العلوي الذي أخذ الرقم 5، ثم 6 للرأس العلوي الأيمن؛ فتقع المجموعتان على الذرتين 1 و5."}]'::jsonb, '["الترقيم (2) هو الصحيح؛ لأنه يبدأ من المجموعة البديلة السفلى","الترقيمان صحيحان؛ لأن اتجاه الترقيم لا يؤثر في الاسم","الترقيمان خاطئان؛ لأن الترقيم يبدأ من ذرة بلا مجموعة بديلة","الترقيم (1) هو الصحيح؛ لأنه يعطي المجموعتين البديلتين الرقمين 1 و3"]'::jsonb, 'فهم', 'تقويم ترقيم الحلقة', 'متوسط', 'الكتاب ص 153 — مثال 4-4 تسمية المركبات الأروماتية'),
('mcq', 5, 'أيّ الصيغ البنائية في الشكل الآتي تمثّل المركب 1، 2، 4-ثلاثي ميثيل بنزين؟', null, '[{"src":"qimg/chem22/c4-l5a-trimethyl4.svg","alt":"أربع صيغ بنائية مرقمة، كل منها حلقة سداسية بداخلها دائرة: (1) ثلاث مجموعات CH₃ على الرأس العلوي، والرأس العلوي الأيمن المجاور له، والرأس السفلي المقابل للرأس العلوي. (2) ثلاث مجموعات CH₃ على الرأس العلوي، والرأس السفلي الأيمن، والرأس السفلي الأيسر؛ أي بين كل مجموعتين ذرة كربون لا تحمل مجموعة. (3) ثلاث مجموعات CH₃ على ثلاثة رؤوس متتالية: العلوي، والعلوي الأيمن، والسفلي الأيمن. (4) مجموعة CH₃ على الرأس العلوي، ومجموعة CH₃ على الرأس العلوي الأيمن، ومجموعة CH₂CH₃ على الرأس السفلي."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'تطبيق', 'تمييز صيغة من اسم', 'صعب', 'الكتاب ص 152 — تسمية المركبات العضوية الأروماتية'),
('mcq', 6, 'أيّ الأسماء الآتية لا يمكن أن يكون اسمًا صحيحًا وفق نظام IUPAC؟', null, null, '["1، 3-ثنائي ميثيل بنزين","1، 5-ثنائي ميثيل بنزين","1، 2-ثنائي إيثيل بنزين","1، 3، 5-ثلاثي ميثيل بنزين"]'::jsonb, 'تحليل', 'تقويم أسماء', 'صعب', 'الكتاب ص 162 (س 87) — تسمية المركبات الأروماتية'),
('mcq', 7, 'ما الصيغة الجزيئية للمركب 1، 3، 5-ثلاثي إيثيل بنزين؟', null, null, '["C₁₂H₂₁","C₉H₁₂","C₁₂H₁₈","C₈H₁₀"]'::jsonb, 'تطبيق', 'استنتاج صيغة جزيئية من الاسم', 'صعب', 'الكتاب ص 152 — تسمية المركبات العضوية الأروماتية'),
('essay', 1, 'سمِّ المركب الآتي وفق نظام IUPAC، موضحًا خطوات التسمية: ترقيم الحلقة، وتحديد أسماء المجموعات البديلة، وترتيبها في الاسم.', null, '[{"src":"qimg/chem22/c4-l5a-2-ethyl-13-dimethyl.svg","alt":"حلقة سداسية بداخلها دائرة، ترتبط بالرأس العلوي مجموعة CH₂CH₃، وترتبط بكل من الرأسين المجاورين له (العلوي الأيمن والعلوي الأيسر) مجموعة CH₃؛ فتقع مجموعة الإيثيل بين مجموعتي الميثيل، والرؤوس الثلاثة السفلية لا تحمل مجموعات بديلة."}]'::jsonb, null, 'تطبيق', 'تسمية بخطوات', 'متوسط', 'الكتاب ص 153 — مثال 4-4 تسمية المركبات الأروماتية'),
