from (values
('mcq', 1, 3, 'تُرقَّم الحلقة لإعطاء المجموعات البديلة أصغر أرقام ممكنة: بالبدء من مجموعة الميثيل العليا (1) ثم الميثيل المجاورة (2) نصل إلى الإيثيل عند الموقع 4، فالأرقام 1 و2 و4 وهي أصغر من 1 و3 و4. ثم تُرتَّب المجموعات هجائيًّا (إيثيل قبل ميثيل) مع البادئة ثنائي للميثيل: 4-إيثيل-1، 2-ثنائي ميثيل بنزين.', '["بدء الترقيم من الإيثيل يعطي 1 و3 و4، وهي أكبر من 1 و2 و4؛ فلم تُعطَ المجموعات أصغر أرقام.","تكرر مجموعة الميثيل مرتين يتطلب البادئة «ثنائي».","الترقيم صحيح لكن المجموعات لم تُرتَّب هجائيًّا؛ فالإيثيل يُكتب قبل الميثيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 2, 1, 'مجموعتا الإيثيل يفصل بينهما في الحلقة ذرة كربون واحدة؛ فالترقيم الذي يعطي أصغر أرقام هو 1 و3، ومع البادئة ثنائي يكون الاسم 1، 3-ثنائي إيثيل بنزين.', '["الترقيم في الاتجاه المعاكس يعطي 1 و5، وهي ليست أصغر أرقام ممكنة.","","الموقعان 1 و2 يعنيان مجموعتين على ذرتي كربون متجاورتين، وهما هنا تفصل بينهما ذرة كربون.","كل مجموعة في الصيغة CH₂CH₃ فيها ذرتا كربون، فهي إيثيل لا ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 3, 2, 'المجموعتان على ذرتي كربون متقابلتين (الموقعان 1 و4)، وهما مجموعة إيثيل CH₂CH₃ ومجموعة بروبيل CH₂CH₂CH₃، وتُكتبان بالترتيب الهجائي (إيثيل قبل بروبيل)، فالاسم 1-إيثيل-4-بروبيل بنزين.', '["المواقع صحيحة لكن الترتيب الهجائي يقتضي كتابة الإيثيل قبل البروبيل.","المجموعتان متقابلتان في الحلقة (1 و4)، لا يفصل بينهما ذرة كربون واحدة (1 و3).","","إحدى المجموعتين إيثيل (ذرتا كربون) لا بروبيل، فلا تصح البادئة ثنائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 4, 3, 'تُرقَّم حلقات البنزين المتفرعة لإعطاء المجموعات البديلة أصغر أرقام ممكنة؛ والرقمان 1 و3 في الترقيم (1) أصغر من 1 و5 في الترقيم (2)، فالترقيم (1) صحيح والاسم 1، 3-ثنائي بروبيل بنزين.', '["البدء من المجموعة السفلى في هذا الاتجاه أعطى 1 و5، وهي أكبر من 1 و3.","اتجاه الترقيم يؤثر في الأرقام؛ فأحدهما يعطي 1 و3 والآخر 1 و5، ويُختار الأصغر.","يبدأ الترقيم من ذرة كربون تحمل مجموعة بديلة لتأخذ الرقم 1، لا من ذرة بلا مجموعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 5, 0, 'في الصيغة (1) ثلاث مجموعات ميثيل: اثنتان على ذرتين متجاورتين (1 و2) والثالثة على الذرة المقابلة للأولى (4)؛ فأصغر أرقام هي 1 و2 و4، والاسم 1، 2، 4-ثلاثي ميثيل بنزين.', '["","الصيغة (2) مجموعاتها الثلاث يفصل بين كل اثنتين ذرة كربون، فاسمها 1، 3، 5-ثلاثي ميثيل بنزين.","الصيغة (3) مجموعاتها على ثلاث ذرات متتالية، فاسمها 1، 2، 3-ثلاثي ميثيل بنزين.","الصيغة (4) إحدى مجموعاتها إيثيل، فهي 4-إيثيل-1، 2-ثنائي ميثيل بنزين وليست ثلاثي ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 6, 1, 'مجموعتان على الموقعين 1 و5 يفصل بينهما ذرة كربون واحدة إذا رُقّمت الحلقة في الاتجاه المعاكس فتأخذان 1 و3؛ ولأن القاعدة تقتضي أصغر أرقام ممكنة فالاسم 1، 5-ثنائي ميثيل بنزين غير صحيح، وصحيحه 1، 3-ثنائي ميثيل بنزين.', '["1 و3 هما أصغر رقمين لمجموعتين يفصل بينهما ذرة كربون، فالاسم صحيح.","","مجموعتا إيثيل على ذرتين متجاورتين تأخذان 1 و2، فالاسم صحيح.","ثلاث مجموعات يفصل بين كل اثنتين ذرة كربون تأخذ 1 و3 و5 في أي اتجاه، فالاسم صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.634Z"}'::jsonb),
('mcq', 7, 2, 'حلقة البنزين C₆H₆ تفقد ثلاث ذرات هيدروجين لتحل محلها ثلاث مجموعات إيثيل C₂H₅: الكربون 6 + 3 × 2 = 12، والهيدروجين (6 − 3) + 3 × 5 = 18؛ فالصيغة C₁₂H₁₈.', '["أُضيفت مجموعات الإيثيل إلى C₆H₆ دون حذف ذرات الهيدروجين الثلاث التي حلت محلها.","هذه صيغة ثلاثي ميثيل بنزين؛ أي عُدّت مجموعة الإيثيل كأنها ميثيل.","","هذه صيغة إيثيل بنزين (مجموعة إيثيل واحدة)، أي أُهملت البادئة ثلاثي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.635Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخطوة 1 (الترقيم): تُرقَّم ذرات الحلقة لإعطاء المجموعات البديلة أصغر أرقام ممكنة؛ فبالبدء من إحدى مجموعتي الميثيل (1) ثم ذرة الإيثيل (2) ثم الميثيل الأخرى (3) نحصل على 1 و2 و3، أما البدء من الإيثيل فيعطي 1 و2 و6 وهي أكبر. الخطوة 2 (أسماء المجموعات): مجموعة CH₂CH₃ إيثيل على الموقع 2، ومجموعتا CH₃ ميثيل على الموقعين 1 و3؛ ولأن الميثيل تكرر مرتين تُضاف البادئة ثنائي. الخطوة 3 (الترتيب والكتابة): تُرتَّب المجموعات هجائيًّا (إيثيل قبل ميثيل)، وتُستخدم الفواصل بين الأرقام والشرطات بين الأرقام والكلمات، فالاسم: 2-إيثيل-1، 3-ثنائي ميثيل بنزين.', '["ترقيم يعطي أصغر أرقام 1 و2 و3","تحديد الإيثيل على 2 والميثيل على 1 و3 مع البادئة ثنائي","الترتيب الهجائي: إيثيل قبل ميثيل","الاسم الصحيح: 2-إيثيل-1، 3-ثنائي ميثيل بنزين"]'::jsonb, '["ترقيم الحلقة: 1 و2 و3 (أصغر من 1 و2 و6)","تحديد المجموعات: 2-إيثيل، و1، 3-ثنائي ميثيل","الترتيب الهجائي وكتابة الاسم: 2-إيثيل-1، 3-ثنائي ميثيل بنزين"]'::jsonb, '[{"element":"الترقيم الصحيح مع المقارنة","marks":1},{"element":"تحديد المجموعات والبادئة","marks":1},{"element":"الترتيب الهجائي","marks":1},{"element":"الاسم النهائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات صحيحة كاملة واسم صحيح"},{"level":"2–3 درجات","description":"اسم صحيح مع نقص في توضيح الخطوات، أو خطوات صحيحة مع خطأ في الكتابة"},{"level":"1 درجة","description":"تحديد المجموعات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترقيم يبدأ من الإيثيل فيعطي 1-إيثيل-2، 6-ثنائي ميثيل بنزين","نسيان البادئة ثنائي","كتابة الميثيل قبل الإيثيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-14T13:39:20.635Z"}'::jsonb),
('essay', 2, null::int, null, null, '1، 4-ثنائي ميثيل بنزين: حلقة بنزين (سداسي بداخله دائرة) ترتبط بها مجموعتا ميثيل CH₃ على ذرتي الكربون 1 و4، وهما ذرتان متقابلتان في الحلقة يفصل بينهما ذرتا كربون من كل جهة. 1، 3-ثنائي بروبيل بنزين: حلقة بنزين ترتبط بها مجموعتا بروبيل CH₂CH₂CH₃ على ذرتي الكربون 1 و3، أي يفصل بينهما ذرة كربون واحدة في الحلقة.', '["حلقة بنزين في المركبين","مجموعتا CH₃ على ذرتين متقابلتين (1 و4)","مجموعتا CH₂CH₂CH₃ على الموقعين 1 و3 يفصل بينهما ذرة كربون"]'::jsonb, '[]'::jsonb, '[{"element":"حلقة البنزين والمجموعتان في المركب الأول","marks":2},{"element":"حلقة البنزين والمجموعتان في المركب الثاني","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"الصيغتان صحيحتان بالمواقع والمجموعات"},{"level":"2–3 درجات","description":"صيغة صحيحة وأخرى فيها خطأ في الموقع أو المجموعة"},{"level":"1 درجة","description":"حلقة البنزين صحيحة مع أخطاء في المواقع"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع مجموعتي 1، 4 على ذرتين متجاورتين","كتابة البروبيل CH₂CH₃","رسم حلقة مشبعة دون دائرة أو روابط متناوبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.635Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الخطأ: الأرقام ليست أصغر أرقام ممكنة؛ فالترقيم في الاتجاه المعاكس يعطي 1 و3. الاسم الصحيح: 1، 3-ثنائي إيثيل بنزين. (ب) الخطأ: المجموعات لم تُرتَّب هجائيًّا؛ فالإيثيل يأتي قبل الميثيل. الاسم الصحيح: 1-إيثيل-2-ميثيل بنزين. (ج) الخطأ: تكررت مجموعة الميثيل مرتين دون البادئة الدالة على عددها. الاسم الصحيح: 1، 4-ثنائي ميثيل بنزين.', '["(أ) خطأ الترقيم والاسم 1، 3-ثنائي إيثيل بنزين","(ب) خطأ الترتيب الهجائي والاسم 1-إيثيل-2-ميثيل بنزين","(ج) نقص البادئة والاسم 1، 4-ثنائي ميثيل بنزين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) بيان الخطأ","marks":1},{"element":"(أ) الاسم الصحيح","marks":1},{"element":"(ب) بيان الخطأ","marks":1},{"element":"(ب) الاسم الصحيح","marks":1},{"element":"(ج) بيان الخطأ","marks":1},{"element":"(ج) الاسم الصحيح","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"بيان الأخطاء الثلاثة وتصحيحها"},{"level":"3–5 درجات","description":"بيان وتصحيح اسمين، أو بيان الأخطاء الثلاثة دون تصحيح كامل"},{"level":"1–2 درجة","description":"بيان أو تصحيح اسم واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح (أ) إلى 1، 6-ثنائي إيثيل بنزين","ترك (ب) دون تغيير لاعتقاد أن ترتيب المجموعات لا يهم","تصحيح (ج) إلى 1، 4-ميثيل ثنائي بنزين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.635Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
