('mcq', 4, 'أيّ الصيغ في الشكل الآتي تمثّل الأنثراسين؟', null, '[{"src":"qimg/chem22/c4-l5a-fused3.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقتان سداسيتان ملتحمتان جنبًا إلى جنب تشتركان في ضلع، وبداخل كل منهما دائرة. (2) ثلاث حلقات سداسية ملتحمة على خط مستقيم، تشترك الوسطى في ضلع مع كل من الحلقتين الأخريين، وبداخل كل حلقة دائرة. (3) ثلاث حلقات سداسية ملتحمة بترتيب منحنٍ (زاوي): حلقتان متجاورتان أفقيًّا، والثالثة ملتحمة بالحلقة اليمنى من ضلعها العلوي الأيمن، وبداخل كل حلقة دائرة. (4) حلقة سداسية واحدة بداخلها دائرة ترتبط بها مجموعتا CH₃ في رأسين متقابلين (أعلى الحلقة وأسفلها)."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'فهم', 'تمييز صيغة من اسم شائع', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 5, 'أيّ المركبات الأروماتية الآتية يُستخدم في صناعة ألياف البوليستر والأنسجة؟', null, null, '["الزايلين","الفينانثرين","النفثالين","الأنثراسين"]'::jsonb, 'تذكر', 'تذكر استخدام', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
('mcq', 6, 'التولوين اسم شائع لأحد مشتقات البنزين. ما اسمه النظامي، وما الذي يرتبط بحلقة البنزين فيه؟', null, null, '["إيثيل بنزين؛ ترتبط بالحلقة مجموعة إيثيل واحدة بدلًا من ذرة هيدروجين","1، 4-ثنائي ميثيل بنزين؛ ترتبط بالحلقة مجموعتا ميثيل على الموقعين 1 و4","ميثيل بنزين؛ ترتبط بالحلقة مجموعة ميثيل إضافةً إلى ذرات الهيدروجين الست","ميثيل بنزين؛ ترتبط بالحلقة مجموعة ميثيل واحدة بدلًا من ذرة هيدروجين"]'::jsonb, 'فهم', 'ربط اسم شائع ببنائه', 'صعب', 'الكتاب ص 152 — تسمية المركبات العضوية الأروماتية'),
('mcq', 7, 'يكثر المركب الآتي في الجو بسبب الاحتراق غير الكامل للهيدروكربونات. ما اسمه، وكيف تترتب حلقاته؟', null, '[{"src":"qimg/chem22/c4-l5a-phenanthrene.svg","alt":"ثلاث حلقات سداسية ملتحمة بداخل كل منها دائرة: حلقتان متجاورتان أفقيًّا تشتركان في ضلع، وحلقة ثالثة ملتحمة بالحلقة اليمنى من ضلعها العلوي الأيمن، فتكوّن الحلقات الثلاث ترتيبًا منحنيًا (زاويًّا) لا خطًّا مستقيمًا."}]'::jsonb, '["الأنثراسين؛ ثلاث حلقات بنزين ملتحمة على خط مستقيم","النفثالين؛ حلقتا بنزين ملتحمتان جنبًا إلى جنب","الفينانثرين؛ ثلاث حلقات بنزين ملتحمة بترتيب منحنٍ","الفينانثرين؛ ثلاث حلقات بنزين منفصلة لا تشترك في أضلاع"]'::jsonb, 'فهم', 'تمييز اسم شائع وبنائه', 'صعب', 'الكتاب ص 151 — المركبات الأروماتية'),
('essay', 1, 'اذكر الاسم الشائع لكل من المركبين: ميثيل بنزين، و1، 4-ثنائي ميثيل بنزين، واذكر استخدامًا لكل منهما.', null, null, null, 'تذكر', 'تذكر أسماء واستخدامات', 'سهل', 'الكتاب ص 151–152 — المركبات الأروماتية'),
('essay', 2, 'اكتب الاسم الشائع لكل مركب في الشكل الآتي، واذكر استخدامًا أو مصدرًا في البيئة لكل منها.', null, '[{"src":"qimg/chem22/c4-l5a-fused3.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقتان سداسيتان ملتحمتان جنبًا إلى جنب تشتركان في ضلع، وبداخل كل منهما دائرة. (2) ثلاث حلقات سداسية ملتحمة على خط مستقيم، تشترك الوسطى في ضلع مع كل من الحلقتين الأخريين، وبداخل كل حلقة دائرة. (3) ثلاث حلقات سداسية ملتحمة بترتيب منحنٍ (زاوي): حلقتان متجاورتان أفقيًّا، والثالثة ملتحمة بالحلقة اليمنى من ضلعها العلوي الأيمن، وبداخل كل حلقة دائرة. (4) حلقة سداسية واحدة بداخلها دائرة ترتبط بها مجموعتا CH₃ في رأسين متقابلين (أعلى الحلقة وأسفلها)."}]'::jsonb, null, 'فهم', 'تسمية واستخدامات', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية'),
