from (values
('mcq', 1, 0, 'المركب حلقة بنزين ترتبط بها مجموعة ميثيل واحدة، أي ميثيل بنزين، واسمه الشائع التولوين.', '["","الزايلين (بارا-زايلين) فيه مجموعتا ميثيل على الحلقة، لا مجموعة واحدة.","النفثالين حلقتا بنزين ملتحمتان، وليس فيه مجموعة ميثيل.","الأنثراسين ثلاث حلقات بنزين ملتحمة على خط مستقيم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 2, 3, 'المركب حلقتا بنزين ملتحمتان تشتركان في ضلع، وهو النفثالين الذي يُستخدم في عمل الأصباغ ويُتخذ طاردًا للعث.', '["الأنثراسين ثلاث حلقات ملتحمة على خط مستقيم، والمركب المرسوم فيه حلقتان فقط.","الفينانثرين ثلاث حلقات ملتحمة بترتيب منحنٍ، والمركب المرسوم فيه حلقتان فقط.","التولوين حلقة بنزين واحدة ترتبط بها مجموعة ميثيل، لا حلقتان ملتحمتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 3, 2, 'المركب 1، 4-ثنائي ميثيل بنزين حلقة بنزين عليها مجموعتا ميثيل في الموقعين 1 و4، ويُعرف باسم بارا-زايلين (para-xylene).', '["التولوين ميثيل بنزين، فيه مجموعة ميثيل واحدة لا اثنتان.","الفينانثرين ثلاث حلقات بنزين ملتحمة، وليس فيه مجموعات ميثيل.","","الأنثراسين ثلاث حلقات بنزين ملتحمة على خط مستقيم، وليس فيه مجموعات ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 4, 1, 'الأنثراسين ثلاث حلقات بنزين ملتحمة على خط مستقيم، تشترك الحلقة الوسطى في ضلع مع كل من الحلقتين الأخريين، وهذا ما تمثله الصيغة (2).', '["الصيغة (1) حلقتان ملتحمتان فقط، وهي النفثالين.","","الصيغة (3) ثلاث حلقات ملتحمة بترتيب منحنٍ لا مستقيم، وهي الفينانثرين.","الصيغة (4) حلقة واحدة عليها مجموعتا ميثيل متقابلتان، وهي بارا-زايلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 5, 0, 'يُستخدم الزايلين (ومنه بارا-زايلين، 1، 4-ثنائي ميثيل بنزين) في عمل ألياف البوليستر والأنسجة.', '["","الفينانثرين يكثر في الجو بسبب الاحتراق غير الكامل للهيدروكربونات، ولم يُذكر استخدامه في ألياف البوليستر.","النفثالين يُستخدم في عمل الأصباغ ويُتخذ طاردًا للعث.","الأنثراسين يُستخدم في إنتاج الأصباغ والدهان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 6, 3, 'يتألف ميثيل البنزين، المعروف أيضًا بالتولوين، من مجموعة ميثيل مرتبطة مع حلقة البنزين بدلًا من ذرة هيدروجين واحدة؛ فيبقى على الحلقة خمس ذرات هيدروجين.', '["إيثيل بنزين مركب آخر فيه مجموعة إيثيل من ذرتي كربون، وليس هو التولوين.","هذا هو بارا-زايلين، فيه مجموعتا ميثيل لا مجموعة واحدة.","الاسم صحيح لكن الوصف خاطئ؛ فمجموعة الميثيل تحل محل ذرة هيدروجين، فلا تبقى ست ذرات هيدروجين على الحلقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('mcq', 7, 2, 'المركب المرسوم ثلاث حلقات بنزين ملتحمة، ترتبط الثالثة بالثانية من جانبها فتكوّن ترتيبًا منحنيًا (زاويًّا)، وهو الفينانثرين الذي يكثر في الجو بسبب الاحتراق غير الكامل للهيدروكربونات.', '["الأنثراسين حلقاته الثلاث على خط مستقيم، أما حلقات المركب المرسوم فترتيبها منحنٍ.","المركب المرسوم فيه ثلاث حلقات لا حلقتان، فليس نفثالين.","","الاسم صحيح لكن الحلقات في المركب المرسوم ملتحمة تشترك في أضلاع، لا منفصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ميثيل بنزين: اسمه الشائع التولوين، ويوجد طبيعيًّا في النفط الخام، ويُستخدم في صناعة الطلاء ومخففات الطلاء والمناكير والمواد اللاصقة والنايلون، وفي بعض مراحل الطباعة والدباغة (يكفي استخدام واحد). 1، 4-ثنائي ميثيل بنزين: اسمه الشائع بارا-زايلين، ويُستخدم الزايلين في عمل ألياف البوليستر والأنسجة.', '["التولوين","استخدام للتولوين","بارا-زايلين","استخدام للزايلين: ألياف البوليستر والأنسجة"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم الشائع لميثيل بنزين","marks":1},{"element":"استخدام التولوين","marks":1},{"element":"الاسم الشائع لـ1، 4-ثنائي ميثيل بنزين","marks":1},{"element":"استخدام الزايلين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الاسمان والاستخدامان صحيحة"},{"level":"2–3 درجات","description":"الاسمان صحيحان مع استخدام واحد أو دون استخدامات"},{"level":"1 درجة","description":"اسم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية ميثيل بنزين زايلين","تسمية 1، 4-ثنائي ميثيل بنزين تولوين","نسبة استخدام طارد العث إلى التولوين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) النفثالين: يُستخدم في عمل الأصباغ ويُتخذ طاردًا للعث. (2) الأنثراسين: يُستخدم في إنتاج الأصباغ والدهان. (3) الفينانثرين: يكثر في الجو بسبب الاحتراق غير الكامل للهيدروكربونات. (4) بارا-زايلين (1، 4-ثنائي ميثيل بنزين): يُستخدم الزايلين في عمل ألياف البوليستر والأنسجة.', '["(1) النفثالين واستخدامه","(2) الأنثراسين واستخدامه","(3) الفينانثرين ومصدره","(4) بارا-زايلين واستخدامه"]'::jsonb, '[]'::jsonb, '[{"element":"(1) الاسم والاستخدام","marks":1},{"element":"(2) الاسم والاستخدام","marks":1},{"element":"(3) الاسم والمصدر","marks":1},{"element":"(4) الاسم والاستخدام","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأسماء الأربعة مع استخداماتها أو مصادرها صحيحة"},{"level":"2–3 درجات","description":"اسمان أو ثلاثة مع استخداماتها"},{"level":"1 درجة","description":"اسم واحد مع استخدامه، أو أسماء دون استخدامات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الأنثراسين والفينانثرين","تسمية المركب (4) تولوين","نسبة استخدام طارد العث إلى الأنثراسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عدد الحلقات: كلاهما يتكون من ثلاث حلقات بنزين ملتحمة. طريقة الالتحام: في الأنثراسين تلتحم الحلقات الثلاث على خط مستقيم، فتشترك الحلقة الوسطى في ضلعين متقابلين مع الحلقتين الأخريين؛ وفي الفينانثرين تلتحم الحلقة الثالثة بجانب الحلقة الثانية فيكون الترتيب منحنيًا (زاويًّا). الاستخدام أو المصدر: يُستخدم الأنثراسين في إنتاج الأصباغ والدهان، ويكثر الفينانثرين في الجو بسبب الاحتراق غير الكامل للهيدروكربونات. التفسير: المركبان لهما العدد نفسه من الحلقات، لكنهما يختلفان في ترتيب التحامها، أي في الصيغة البنائية، فهما مركبان مختلفان؛ لذا يلزم معرفة طريقة ترتيب الحلقات لا عددها فقط.', '["كلاهما ثلاث حلقات بنزين","الأنثراسين خطي والفينانثرين منحنٍ","استخدام الأنثراسين ومصدر الفينانثرين","التفسير: الاختلاف في ترتيب الحلقات (البناء)"]'::jsonb, '[]'::jsonb, '[{"element":"عدد الحلقات","marks":1},{"element":"طريقة الالتحام","marks":1},{"element":"الاستخدام أو المصدر","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في المعايير الثلاثة وتفسير صحيح"},{"level":"2–3 درجات","description":"مقارنة صحيحة في معيارين أو دون تفسير"},{"level":"1 درجة","description":"معيار واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأنثراسين حلقتان","عكس ترتيب الالتحام بين المركبين","نسبة الاحتراق غير الكامل إلى الأنثراسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.636Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
