from (values
('mcq', 1, 'تتوزع أزواج إلكترونات الروابط في البنزين بالتساوي على الحلقة كاملة بدلًا من بقائها بين ذرتي كربون محددتين. ما أثر ذلك في الجزيء؟', null, null, '["يصبح الجزيء ثابتًا ضعيف النشاط الكيميائي","يصبح الجزيء شديد التفاعل كالألكينات","يصبح الجزيء مشبعًا كالألكانات","تنفتح الحلقة فيصبح الجزيء سلسلة مستقيمة"]'::jsonb, 'فهم', 'أثر عدم تمركز الإلكترونات في الثبات', 'سهل', 'الكتاب ص 150 — نموذج البنزين الحديث'),
('mcq', 2, 'يُطلق على الإلكترونات غير المتمركزة (delocalized) في حلقة البنزين وصفٌ آخر، هو:', null, null, '["إلكترونات متمركزة","إلكترونات مشبعة","إلكترونات متحركة","إلكترونات منفردة"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 150 — نموذج البنزين الحديث'),
('mcq', 3, 'ما المقصود بأن أزواج إلكترونات الروابط في البنزين غير متمركزة؟', null, null, '["أنها تتجمع بين كل ذرتي كربون متجاورتين بالتناوب","أنها تشترك فيها جميع ذرات الكربون الست في الحلقة","أنها تنتقل من ذرات الكربون إلى ذرات الهيدروجين","أنها تستقر حول نواة ذرة كربون واحدة فقط"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 150 — نموذج البنزين الحديث'),
('mcq', 4, 'في أيّ الحالات الآتية يكون سحب زوج الإلكترونات بعيدًا أصعب؟', null, null, '["زوج في رابطة ثنائية بين نواتي كربون في الإيثين","زوج في رابطة ثلاثية بين نواتي كربون في الإيثاين","زوج في رابطة ثنائية بين نواتي كربون في الهكسين الحلقي","زوج مشترك بين ست نوى كربون في حلقة البنزين"]'::jsonb, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 150 — نموذج البنزين الحديث'),
('mcq', 5, 'يقارن الشكل الآتي بين توزع إلكترونات الرابطة الثنائية في الإيثين (1) وتوزع إلكترونات الحلقة في البنزين (2). أيّ استنتاج يدعمه الشكل؟', null, '[{"src":"qimg/chem22/c4-l5b-local-vs-deloc.svg","alt":"شكلان مرقمان: (1) جزيء الإيثين: ذرتا كربون (C) بينهما رابطة ثنائية (خطان متوازيان)، وترتبط بكل ذرة كربون ذرتا هيدروجين (H)، وتحيط بالرابطة بين ذرتي الكربون فقط سحابة زرقاء بيضاوية صغيرة. (2) جزيء البنزين: ست ذرات كربون في حلقة سداسية ترتبط كل منها بذرة هيدروجين واحدة، وأضلاع الحلقة خطوط مفردة، وتمتد سحابة زرقاء على شكل حلقة فوق ذرات الكربون الست جميعها على طول الحلقة."}]'::jsonb, '["المركب (2) أنشط؛ لأن سحابته الإلكترونية أكبر امتدادًا","المركب (2) أقل نشاطًا؛ لأن إلكتروناته مشتركة بين ست نوى","المركبان متساويان في النشاط؛ لأن كليهما غير مشبع","المركب (1) أقل نشاطًا؛ لأن إلكتروناته قريبة من نواتين"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 150 — نموذج البنزين الحديث'),
('mcq', 6, 'قال طالب: «البنزين ضعيف النشاط الكيميائي لأن جميع الروابط بين ذرات الكربون فيه أحادية مثل الألكانات». ما التقويم الصحيح لعبارته؟', null, null, '["صحيحة؛ لأن الحلقة السداسية لا تُرسم فيها روابط ثنائية","صحيحة؛ لأن صيغته الجزيئية C₆H₆ تشبه صيغ الألكانات","خاطئة؛ فالبنزين غير مشبع، وضعف نشاطه سببه عدم تمركز إلكتروناته","خاطئة؛ لأن البنزين في الحقيقة شديد النشاط كالألكينات"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 149–150 — بناء البنزين'),
('mcq', 7, 'يمثّل الشكل الآتي نموذجًا لجزيء البنزين. ماذا تمثّل السحابتان الزرقاوان فوق مستوى الحلقة وتحته؟', null, '[{"src":"qimg/chem22/c4-l5b-electron-rings.svg","alt":"نموذج لجزيء البنزين مرسوم بمنظور مائل: ست ذرات كربون (C) في حلقة سداسية مسطحة، ترتبط كل ذرة كربون بذرة هيدروجين (H) واحدة متجهة نحو الخارج، وترتبط ذرات الكربون المتجاورة بخطوط مفردة. فوق مستوى الحلقة وتحته سحابتان زرقاوان على شكل حلقتين (كعكتين)، تمتد كل منهما فوق ذرات الكربون الست جميعها حول الحلقة كاملة، ولا تتركز بين ذرتين بعينهما."}]'::jsonb, '["أزواج إلكترونات غير متمركزة موزعة بالتساوي حول الحلقة","ثلاث روابط ثنائية ثابتة بين ذرات كربون محددة","ذرات الهيدروجين الست المرتبطة بذرات الكربون","أزواج إلكترونات حرة يخص كل منها ذرة كربون واحدة"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 150 — الشكل 4-25'),
('essay', 1, 'فسّر الشكل البنائي للبنزين، وكيف يجعله عالي الثبات وضعيف النشاط الكيميائي، مقارنًا إلكترونات حلقته بإلكترونات الرابطة الثنائية في الألكينات.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 150 وص 154 (س 33)'),
('essay', 2, 'ينقص جزيء البنزين C₆H₆ ثماني ذرات هيدروجين مقارنةً بالهيدروكربون المشبع C₆H₁₄، ومع ذلك فهو ضعيف النشاط الكيميائي ولا يتفاعل بالطرائق التي تتفاعل بها الألكينات عادة. حلّل هذا التناقض الظاهري وفسّره.', null, null, null, 'تحليل', 'تحليل تناقض ظاهري', 'صعب', 'الكتاب ص 149–150 — الصيغة البنائية للبنزين'),
('essay', 3, 'في النفثالين تتشارك ذرات الكربون المكوِّنة لحلقتي البنزين الملتحمتين بالإلكترونات كما في البنزين. توقّع هل يكون النفثالين نشطًا كالألكينات أم ثابتًا كالبنزين، وفسّر توقعك، ثم بيّن لماذا لا يكفي عدّ الروابط الثنائية في صيغته المرسومة بروابط متناوبة للحكم على نشاطه.', null, null, null, 'تطبيق', 'توقع وتفسير', 'صعب', 'الكتاب ص 150–151 — نموذج البنزين الحديث والحلقات الملتحمة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L5-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'عندما تتوزع أزواج الإلكترونات على الحلقة كاملة تصبح مشتركة مع ست نوى كربون، فيصعب سحبها بعيدًا مقارنةً بالإلكترونات الثابتة حول نواتين فقط؛ لذا يصبح جزيء البنزين ثابتًا كيميائيًّا ضعيف النشاط.', '["","توزع الإلكترونات على ست نوى يجعل سحبها أصعب، فيقل النشاط ولا يزيد كما في الألكينات.","توزع الإلكترونات لا يغيّر عدد ذرات الهيدروجين؛ فالبنزين C₆H₆ يبقى غير مشبع.","عدم التمركز يحدث في الحلقة السداسية نفسها ولا يفتحها؛ فالبنزين يبقى حلقيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 2, 2, 'توصف الإلكترونات غير المتمركزة بأنها متحركة؛ لأنها لا تتقيد بذرتي كربون محددتين، بل تتحرك وتشترك فيها جميع ذرات الكربون الست في الحلقة. إذن الوصف الآخر هو «إلكترونات متحركة».', '["المتمركزة عكس غير المتمركزة؛ فهي ثابتة بين ذرتين محددتين كما في الألكينات.","التشبع وصف للمركب الذي روابطه أحادية فقط، لا للإلكترونات، والبنزين غير مشبع.","","الإلكترونات غير المتمركزة ليست منفردة على ذرة واحدة، بل تشترك فيها ذرات الكربون الست."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 3, 1, 'وفق نظرية المجالات المهجنة لا تتجمع أزواج إلكترونات الروابط الثنائية للبنزين بين ذرتي كربون محددتين كما في الألكينات، بل تكون غير متمركزة؛ أي تشترك فيها جميع ذرات الكربون الست في الحلقة.', '["تجمع الأزواج بين ذرتين محددتين بالتناوب هو وصف صيغة كيكولي، أي إلكترونات متمركزة.","","لا تنتقل إلكترونات الحلقة إلى ذرات الهيدروجين؛ فهي تبقى موزعة على ذرات الكربون الست.","استقرارها حول نواة واحدة يعني تمركزًا، وهو عكس المقصود بعدم التمركز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 4, 3, 'الإلكترونات المشتركة مع ست نوى كربون يصعب سحبها بعيدًا مقارنةً بالإلكترونات الثابتة حول نواتين فقط. وفي الإيثين والإيثاين والهكسين الحلقي تكون إلكترونات الرابطة حول نواتين فقط، أما في البنزين فيشترك الزوج بين ست نوى؛ لذا فسحبه هو الأصعب.', '["إلكترونات الرابطة الثنائية في الإيثين ثابتة حول نواتين فقط، فسحبها أسهل منه في البنزين.","إلكترونات الرابطة الثلاثية متمركزة حول نواتين فقط، والألكاينات نشطة كيميائيًّا.","وجود الحلقة لا يكفي؛ فالرابطة الثنائية في الهكسين الحلقي متمركزة حول نواتين فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 5, 1, 'في الإيثين (1) تبقى إلكترونات الرابطة الثنائية حول نواتين فقط فيسهل سحبها، أما في البنزين (2) فتتوزع الإلكترونات على ذرات الكربون الست وتشترك فيها ست نوى، فيصعب سحبها ويكون الجزيء ثابتًا. إذن المركب (2) أقل نشاطًا لأن إلكتروناته مشتركة بين ست نوى.', '["امتداد السحابة على ست نوى يجعل سحب الإلكترونات أصعب، فيقل النشاط لا يزيد.","","عدم التشبع لا يكفي للحكم؛ فتوزع الإلكترونات مختلف، والبنزين أثبت من الألكينات.","الإلكترونات الثابتة حول نواتين فقط أسهل سحبًا، لذا يكون الإيثين أنشط لا أقل نشاطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 6, 2, 'البنزين C₆H₆ غير مشبع (ينقصه ثماني ذرات هيدروجين عن C₆H₁₄)، فليست روابطه كلها أحادية. وضعف نشاطه سببه أن أزواج إلكترونات روابطه غير متمركزة تشترك فيها ذرات الكربون الست فيصعب سحبها. إذن العبارة خاطئة وسبب ضعف النشاط هو عدم تمركز الإلكترونات.', '["الدائرة داخل الحلقة ترمز إلى أزواج إلكترونات غير متمركزة، لا إلى غياب الروابط الثنائية.","صيغة الألكان ذي ست ذرات كربون C₆H₁₄، والبنزين ينقصه ثماني ذرات هيدروجين فهو غير مشبع.","","البنزين غير نشط كيميائيًّا ولا يتفاعل بالطرائق التي تتفاعل بها الألكينات، فهذا التصحيح خاطئ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('mcq', 7, 0, 'تتوزع إلكترونات روابط البنزين بالتساوي في صورة كعكة ثنائية حول الحلقة بدلًا من البقاء قريبة من الذرات المنفردة؛ فالسحابتان تمثلان أزواج الإلكترونات غير المتمركزة الموزعة بالتساوي حول الحلقة.', '["","الروابط الثابتة بين ذرات محددة تُمثَّل بخطوط مزدوجة بين ذرتين، لا بسحابة تمتد على الحلقة كلها.","ذرات الهيدروجين ظاهرة في الشكل متجهة نحو خارج الحلقة، والسحابتان تمثلان إلكترونات.","السحابة متصلة فوق الذرات الست جميعها، فهي ليست إلكترونات تخص كل ذرة على حدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البنزين حلقة سداسية مسطحة من ست ذرات كربون، ترتبط كل منها بذرة هيدروجين واحدة. وفق نظرية المجالات المهجنة لا تتجمع أزواج إلكترونات روابطه الثنائية بين ذرتي كربون محددتين، بل تكون غير متمركزة (متحركة) تشترك فيها ذرات الكربون الست، وتتوزع بالتساوي على الحلقة كاملة. ولأن هذه الإلكترونات مشتركة مع ست نوى كربون يصعب سحبها بعيدًا، فيكون الجزيء ثابتًا وضعيف النشاط. أما في الألكينات فإلكترونات الرابطة الثنائية متمركزة ثابتة حول نواتين فقط، فيسهل سحبها، لذا تكون الألكينات أنشط كيميائيًّا من البنزين.', '["وصف البناء: حلقة سداسية مسطحة من ست ذرات كربون","الإلكترونات غير متمركزة تشترك فيها ذرات الكربون الست","المشاركة مع ست نوى تجعل سحب الإلكترونات صعبًا فيثبت الجزيء","في الألكينات الإلكترونات حول نواتين فقط فيسهل سحبها وتكون أنشط"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البناء الحلقي","marks":1},{"element":"عدم تمركز الإلكترونات","marks":1},{"element":"ربط المشاركة مع ست نوى بالثبات","marks":1},{"element":"المقارنة بالألكينات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة ومترابطة"},{"level":"2–3 درجات","description":"عدم التمركز والثبات مفسران مع نقص في وصف البناء أو المقارنة"},{"level":"1 درجة","description":"ذكر أن البنزين ثابت دون تفسير صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعليل الثبات بأن البنزين مشبع","القول إن الروابط الثنائية في البنزين ثابتة بين ذرات محددة","عدّ البنزين أنشط من الألكينات لأن فيه روابط ثنائية أكثر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.637Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نقص الهيدروجين يدل على أن البنزين غير مشبع؛ لذا توقع الكيميائيون أن يحتوي روابط ثنائية أو ثلاثية وأن يكون نشطًا كالألكينات. لكن عدم التشبع وحده لا يحدد النشاط؛ فالمهم هو كيف تتوزع إلكترونات الروابط. في الألكينات تكون إلكترونات الرابطة الثنائية متمركزة بين ذرتين ثابتتين حول نواتين فقط، فيسهل سحبها وتتفاعل بسهولة. أما في البنزين فأزواج الإلكترونات غير متمركزة تشترك فيها ذرات الكربون الست وتتوزع على الحلقة كاملة بالتساوي، فيصعب سحبها لأنها مشتركة مع ست نوى، فيكون الجزيء ثابتًا. إذن البنزين غير مشبع لكنه ثابت؛ ولا تناقض في ذلك لأن الثبات يعود إلى عدم تمركز الإلكترونات لا إلى التشبع.', '["نقص الهيدروجين يعني أن البنزين غير مشبع","التوقع المبني على عدم التشبع: نشاط كالألكينات","إلكترونات الألكين متمركزة حول نواتين فيسهل سحبها","إلكترونات البنزين غير متمركزة مشتركة مع ست نوى فيصعب سحبها","الاستنتاج: الثبات مرتبط بتوزع الإلكترونات لا بالتشبع"]'::jsonb, '[]'::jsonb, '[{"element":"دلالة نقص الهيدروجين","marks":1},{"element":"التوقع المبني عليه","marks":1},{"element":"حال إلكترونات الألكين","marks":1},{"element":"حال إلكترونات البنزين","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل يبين دلالة عدم التشبع ويحل التناقض بعدم التمركز"},{"level":"3–4 درجات","description":"تفسير الثبات بعدم التمركز مع نقص في بيان التوقع أو المقارنة"},{"level":"1–2 درجة","description":"ذكر عدم التمركز دون ربطه بالتناقض"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إنكار أن البنزين غير مشبع","تفسير الثبات بعدد ذرات الهيدروجين","الخلط بين التشبع والثبات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُتوقع أن يكون النفثالين ثابتًا وضعيف النشاط مثل البنزين، لا نشطًا كالألكينات؛ لأن إلكترونات روابطه غير متمركزة تتشارك فيها ذرات الكربون في الحلقتين، فهي مشتركة مع عدة نوى ويصعب سحبها. أما رسمه بروابط ثنائية متناوبة فيوحي بروابط ثنائية متمركزة بين ذرات محددة كما في الألكينات، وهذا لا يمثل التوزيع الفعلي للإلكترونات؛ فالحكم على النشاط يعتمد على عدم تمركز الإلكترونات لا على عدد الخطوط المزدوجة في الصيغة.', '["التوقع: النفثالين ثابت ضعيف النشاط","التعليل: إلكترونات غير متمركزة مشتركة مع عدة نوى فيصعب سحبها","الروابط المتناوبة في الرسم لا تمثل التوزيع الفعلي للإلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع الصحيح","marks":1},{"element":"التعليل بعدم التمركز","marks":2},{"element":"نقد الاعتماد على عدّ الروابط الثنائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توقع صحيح بتعليل كامل ونقد سليم للصيغة المتناوبة"},{"level":"2–3 درجات","description":"توقع صحيح بتعليل ناقص أو دون نقد الصيغة"},{"level":"1 درجة","description":"توقع صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع أن يكون النفثالين أنشط لأنه يحتوي روابط ثنائية أكثر من البنزين","عدّ الحلقتين الملتحمتين سببًا لعدم الثبات","إغفال أن الإلكترونات مشتركة بين ذرات الحلقتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
