('mcq', 1, 'شاع سابقًا استخدام البنزين والتولوين والزايلين مذيباتٍ صناعية ومختبرية، ثم ظهرت ضرورة الحد من استخدامها. ما السبب؟', null, null, '["أنها لا تذيب المواد العضوية إذابة جيدة","أنها تؤثر في صحة الأشخاص المعرّضين لها بصورة متكررة","أنها تتفاعل بشدة مع المواد المذابة فيها","أنها نادرة الوجود ومرتفعة الثمن جدًّا"]'::jsonb, 'فهم', 'تفسير سبب', 'سهل', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 2, 'أيّ المجموعات الآتية تضم أجزاء الجسم التي ترتبط بها المخاطر الصحية للمركبات الأروماتية؟', null, null, '["العظام، والأسنان، والجلد","العضلات، والمفاصل، والعظام","الشعر، والأظافر، والأسنان","الجهاز التنفسي، والكبد، والجهاز العصبي"]'::jsonb, 'تذكر', 'استرجاع حقائق', 'سهل', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 3, 'ظهرت على عامل تعرّض لكميات ضئيلة من التولوين أعراض: التعب، وفقدان الذاكرة، والغثيان، وفقدان السمع والبصر. أيّ أجهزة الجسم يتأثر بالتولوين مسببًا هذه الأعراض؟', null, null, '["الجهاز العصبي","الجهاز الهيكلي","الجهاز الدوري","الجهاز الإخراجي"]'::jsonb, 'فهم', 'ربط أعراض بسببها', 'متوسط', 'الكتاب ص 152 — الربط مع الصحة (التولوين)'),
('mcq', 4, 'أيّ الفئات الآتية أكثر عرضة لخطر التولوين بحكم طبيعة عملها؟', null, null, '["العاملون في محطات تحلية مياه البحر","العاملون في مزارع النخيل وجني التمور","العاملون في صناعة الطلاء ومخففات الطلاء والمواد اللاصقة","العاملون في مصانع الأسمنت ومواد البناء"]'::jsonb, 'فهم', 'تطبيق حقيقة على موقف', 'متوسط', 'الكتاب ص 152 — الربط مع الصحة (التولوين)'),
('mcq', 5, 'للتولوين تأثير في الجهاز العصبي عند التعرض لكميات ضئيلة منه. أيّ المجموعات الآتية كلها من الأعراض التي قد تظهر عندئذ؟', null, null, '["زيادة الشهية، وقوة الذاكرة، والنشاط","حدة السمع، وحدة البصر، والتركيز","الغثيان، وزيادة الشهية، وحدة البصر","الضعف، والاضطراب، والشعور بالسُّكر"]'::jsonb, 'تذكر', 'أعراض التعرض للتولوين', 'سهل', 'الكتاب ص 152 — الربط مع الصحة (التولوين)'),
('mcq', 6, 'يُنصح بتجنب استنشاق أبخرة الجازولين عند تعبئة الوقود. أيّ مما يأتي يفسر هذه النصيحة؟', null, null, '["أن أبخرة الجازولين تتكون من الماء وثاني أكسيد الكربون","أن بعض المركبات الأروماتية الموجودة في الجازولين مسرطنة","أن جميع مكونات الجازولين مركبات أروماتية ثابتة","أن المركبات الأروماتية في الجازولين تعالج أمراض التنفس"]'::jsonb, 'فهم', 'تفسير سلوك وقائي', 'متوسط', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 7, 'قال طالب: «لا خطر من المركبات الأروماتية إلا إذا كانت من المواد المسرطنة». ما التقويم الصحيح لعبارته؟', null, null, '["صحيحة؛ لأن الضرر الوحيد للمركبات الأروماتية هو السرطان","صحيحة؛ لأن التولوين لا يؤثر في الجسم إلا بكميات كبيرة","خاطئة؛ فبعضها يضر الجهاز العصبي والكبد والتنفس دون أن يكون مسرطنًا","خاطئة؛ لأن المركبات الأروماتية كلها مسرطنة بلا استثناء"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 152 وص 154'),
('essay', 1, 'اشرح الآثار الصحية الضارة المترتبة على التعرض المتكرر للمركبات الأروماتية، ثم بيّن لماذا ظهرت ضرورة الحد من استخدام البنزين والتولوين والزايلين مذيباتٍ صناعية ومختبرية.', null, null, null, 'فهم', 'شرح', 'متوسط', 'الكتاب ص 154 — المواد المسرطنة'),
('essay', 2, 'يعمل شخص منذ سنوات في مصنع للمواد اللاصقة ومخففات الطلاء، وبدأ يشكو من التعب والضعف ونسيان ما يحدث معه وفقدان الشهية. فسّر الحالة: حدّد المركب الأروماتي المرجح أنه سببها، والجهاز الذي يؤثر فيه، واذكر عرضين آخرين قد يظهران عليه، ثم وضّح لماذا لا يُعد التعرض لكميات قليلة منه آمنًا.', null, null, null, 'تطبيق', 'تحليل حالة', 'صعب', 'الكتاب ص 152 — الربط مع الصحة (التولوين)'),
('essay', 3, 'يعمل شخص في محطة وقود تقع في شارع مزدحم بالسيارات. وضّح كيف يمكن أن يتعرض في عمله لمركبات أروماتية ضارة، مسميًا مصدرين ومثالًا على المركبات الضارة في كل منهما، ثم اشرح الآثار الصحية المحتملة لتعرضه المتكرر لها.', null, null, null, 'تحليل', 'تحليل مصادر التعرض', 'صعب', 'الكتاب ص 154 — المواد المسرطنة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
