from (values
('mcq', 1, 1, 'أظهرت الاختبارات ضرورة الحد من استخدام هذه المركبات الأروماتية؛ لأنها تؤثر في صحة الأشخاص المعرضين لها بصورة متكررة، فتسبب أمراض الجهاز التنفسي ومشكلات الكبد وتلف الجهاز العصبي، وبعضها مسرطن.', '["سبب الحد من استخدامها صحي، لا ضعف قدرتها على الإذابة؛ فقد استُخدمت مذيبات فعلًا.","","المركبات الأروماتية ضعيفة النشاط الكيميائي، وسبب الحد من استخدامها ضررها الصحي.","التولوين مثلًا يوجد طبيعيًّا في النفط الخام، والسبب المذكور هو الضرر الصحي لا الندرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('mcq', 2, 3, 'تشمل المخاطر الصحية المرتبطة مع المركبات الأروماتية أمراض الجهاز التنفسي، والمشكلات المتعلقة بالكبد، وتلف الجهاز العصبي؛ فالمجموعة الصحيحة هي الجهاز التنفسي والكبد والجهاز العصبي.', '["لم تُذكر العظام والأسنان ضمن المخاطر الصحية المرتبطة بالمركبات الأروماتية.","المخاطر الصحية المرتبطة بهذه المركبات تشمل التنفس والكبد والأعصاب، لا العضلات والمفاصل.","هذه الأجزاء لا ترتبط بالمخاطر الصحية المذكورة للمركبات الأروماتية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('mcq', 3, 0, 'للتولوين تأثير في الجهاز العصبي عند التعرض بكميات ضئيلة منه، فتظهر أعراض مثل التعب والضعف والاضطراب والشعور بالسُّكر وفقدان الذاكرة والغثيان وفقدان الشهية وفقدان السمع والبصر. إذن الجهاز المتأثر هو الجهاز العصبي.', '["","الأعراض المذكورة (فقدان الذاكرة والسمع والبصر والتعب) ناتجة عن تأثر الجهاز العصبي لا العظام.","الأعراض المذكورة (فقدان الذاكرة والسمع والبصر والتعب) ناتجة عن تأثر الجهاز العصبي، لا القلب والأوعية الدموية.","لم يرتبط تأثير التولوين المذكور بالجهاز الإخراجي، بل بالجهاز العصبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('mcq', 4, 2, 'يوجد التولوين بشكل طبيعي في النفط الخام، ويُستخدم في صناعة الطلاء، ومخففات الطلاء، والمناكير، والمواد اللاصقة، والنايلون، وفي بعض مراحل الطباعة والدباغة؛ لذا يكون العاملون في صناعة الطلاء ومخففات الطلاء والمواد اللاصقة أكثر عرضة لخطره.', '["لا يرتبط عمل تحلية المياه باستخدام التولوين، بخلاف صناعة الطلاء ومخففات الطلاء والمواد اللاصقة.","الزراعة وجني التمور ليست من الصناعات التي يُستخدم فيها التولوين.","","لم يُذكر الأسمنت من استخدامات التولوين؛ فهو يُستخدم في الطلاء ومخففاته والمناكير والمواد اللاصقة والنايلون والطباعة والدباغة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('mcq', 5, 3, 'من أعراض تأثير التولوين في الجهاز العصبي: التعب، والضعف، والاضطراب، والشعور بالسُّكر، وفقدان الذاكرة، والغثيان، وفقدان الشهية، وفقدان السمع والبصر. والمجموعة التي كل عناصرها من هذه الأعراض هي: الضعف، والاضطراب، والشعور بالسُّكر.', '["هذه عكس الأعراض؛ فالتولوين يسبب فقدان الشهية وفقدان الذاكرة والتعب.","التولوين يسبب فقدان السمع والبصر والاضطراب، لا حدة الحواس والتركيز.","الغثيان من الأعراض، لكن التولوين يسبب فقدان الشهية وفقدان البصر لا زيادة الشهية وحدة البصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.638Z"}'::jsonb),
('mcq', 6, 1, 'عُرفت بعض المركبات الأروماتية الموجودة في الجازولين على أنها مسرطنة، أي تسبب مرض السرطان، فضلًا عن أن المركبات الأروماتية عمومًا قد تسبب أمراض الجهاز التنفسي؛ لذلك يُنصح بتجنب استنشاق أبخرته.', '["الماء وثاني أكسيد الكربون من نواتج احتراق الهيدروكربونات، لا مكونات أبخرة الجازولين.","","الجازولين خليط من هيدروكربونات متعددة، والثبات الكيميائي لا يفسر النصيحة الصحية.","المركبات الأروماتية لا تعالج أمراض التنفس، بل قد تسبب أمراض الجهاز التنفسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.639Z"}'::jsonb),
('mcq', 7, 2, 'تشمل المخاطر الصحية للمركبات الأروماتية أمراض الجهاز التنفسي ومشكلات الكبد وتلف الجهاز العصبي، وبالإضافة إلى ذلك فإن بعضها مسرطن. ومثال ذلك التولوين الذي يؤثر في الجهاز العصبي بكميات ضئيلة. إذن العبارة خاطئة لأن الضرر لا يقتصر على السرطان. فبعضها يضر الجهاز العصبي والكبد والتنفس دون أن يكون مسرطنًا.', '["المخاطر تشمل أيضًا أمراض الجهاز التنفسي ومشكلات الكبد وتلف الجهاز العصبي.","التولوين يؤثر في الجهاز العصبي عند التعرض لكميات ضئيلة منه.","","المذكور أن بعض المركبات الأروماتية مسرطنة، لا كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.639Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تؤثر المركبات الأروماتية في صحة الأشخاص المعرضين لها بصورة متكررة؛ فهي تسبب أمراض الجهاز التنفسي، ومشكلات متعلقة بالكبد، وتلف الجهاز العصبي، وبعضها مواد مسرطنة تسبب مرض السرطان مثل البنزوبايرين وبعض المركبات الأروماتية في الجازولين. وقد شاع سابقًا استخدام البنزين والتولوين والزايلين مذيبات، لكن الاختبارات أظهرت أنها تضر صحة من يتعرضون لها باستمرار؛ لذا ظهرت ضرورة الحد من استخدامها.', '["أمراض الجهاز التنفسي","مشكلات الكبد","تلف الجهاز العصبي","بعضها مسرطن مع مثال","سبب الحد من استخدامها: أثرها في صحة المعرضين لها بصورة متكررة"]'::jsonb, '[]'::jsonb, '[{"element":"أمراض الجهاز التنفسي","marks":1},{"element":"مشكلات الكبد","marks":1},{"element":"تلف الجهاز العصبي","marks":1},{"element":"التسبب في السرطان مع مثال","marks":1},{"element":"سبب الحد من استخدامها مذيبات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الآثار الأربعة وسبب الحد من الاستخدام صحيحة"},{"level":"3–4 درجات","description":"ثلاثة آثار أو أكثر مع نقص في سبب الحد أو المثال"},{"level":"1–2 درجة","description":"أثر أو أثران فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حصر الضرر في السرطان وحده","القول إن جميع المركبات الأروماتية مسرطنة","تعليل الحد من استخدامها بضعف إذابتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-14T13:39:20.639Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المركب المرجح هو التولوين (ميثيل بنزين)؛ لأنه يُستخدم في صناعة الطلاء ومخففاته والمواد اللاصقة. يؤثر التولوين في الجهاز العصبي، ومن أعراضه الأخرى: الاضطراب، والغثيان، وفقدان السمع والبصر (أي عرضين منها). ولا يُعد التعرض لكميات قليلة آمنًا لأن للتولوين تأثيرًا في الجهاز العصبي حتى عند التعرض لكميات ضئيلة منه، ولا سيما مع تكرار التعرض سنوات.', '["تحديد التولوين مع ربطه باستخدامه في الطلاء والمواد اللاصقة","الجهاز العصبي","عرضان آخران صحيحان","التأثير يحدث حتى بكميات ضئيلة ومع التعرض المتكرر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المركب وتعليله","marks":1},{"element":"الجهاز المتأثر","marks":1},{"element":"عرضان آخران","marks":1},{"element":"تفسير خطر الكميات القليلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العناصر الأربعة صحيحة"},{"level":"2–3 درجات","description":"تحديد المركب والجهاز مع نقص في الأعراض أو التفسير"},{"level":"1 درجة","description":"تحديد المركب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الأعراض إلى البنزوبايرين","ذكر الجهاز التنفسي بدلًا من العصبي لهذه الأعراض","القول إن الكميات القليلة لا تؤثر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.639Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المصدر الأول: أبخرة الجازولين عند تعبئة الوقود؛ إذ يحتوي الجازولين على مركبات أروماتية عُرف بعضها على أنه مسرطن. المصدر الثاني: عوادم السيارات المزدحمة في الشارع؛ إذ تحتوي على البنزوبايرين، وهو مادة مسرطنة ناتجة ثانويًّا عن الاحتراق. الآثار الصحية: يؤثر التعرض المتكرر للمركبات الأروماتية في الصحة، فيسبب أمراض الجهاز التنفسي، ومشكلات متعلقة بالكبد، وتلف الجهاز العصبي، وقد تسبب المركبات المسرطنة منها مرض السرطان.', '["أبخرة الجازولين وما فيها من مركبات أروماتية بعضها مسرطن","عوادم السيارات وما فيها من البنزوبايرين","أمراض الجهاز التنفسي ومشكلات الكبد وتلف الجهاز العصبي","خطر الإصابة بالسرطان من المركبات المسرطنة"]'::jsonb, '[]'::jsonb, '[{"element":"المصدر الأول ومثاله","marks":1},{"element":"المصدر الثاني ومثاله","marks":1},{"element":"أمراض التنفس والكبد والجهاز العصبي","marks":1},{"element":"خطر السرطان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مصدران صحيحان بمثاليهما والآثار الصحية كاملة"},{"level":"2–3 درجات","description":"مصدر واحد مكتمل مع آثار صحيحة، أو مصدران دون آثار كاملة"},{"level":"1 درجة","description":"ذكر مصدر صحيح أو أثر صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الجازولين خاليًا من المركبات الأروماتية","حصر الضرر في السرطان وحده","نسبة البنزوبايرين إلى أبخرة الوقود قبل احتراقه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.639Z"}'::jsonb)
