('mcq', 3, 'أيّ العبارات الآتية تصح على الهيدروكربونات الأروماتية والأليفاتية معًا؟', null, null, '["كلاهما يحتوي على حلقة بنزين واحدة على الأقل","كلاهما ذو إلكترونات روابط غير متمركزة","كلاهما حُصل عليه أول مرة من دهون الحيوانات","كلاهما مركبات تتكون من الكربون والهيدروجين فقط"]'::jsonb, 'فهم', 'مقارنة: أوجه الشبه', 'سهل', 'الكتاب ص 151 — المركبات الأروماتية والأليفاتية'),
('mcq', 4, 'كل من البنزين و1-هكسين هيدروكربون غير مشبع. كيف يختلفان في النشاط الكيميائي؟', null, null, '["البنزين أنشط؛ لأن فيه روابط ثنائية أكثر من 1-هكسين","1-هكسين أنشط؛ لأن إلكترونات البنزين غير متمركزة","يتساويان في النشاط؛ لأن كليهما غير مشبع","كلاهما غير نشط؛ لأن روابطهما كلها أحادية"]'::jsonb, 'فهم', 'مقارنة النشاط', 'متوسط', 'الكتاب ص 150 — بناء البنزين'),
('mcq', 5, 'أيّ العبارات الآتية تقارن بين البنزين C₆H₆ والهكسان الحلقي C₆H₁₂ مقارنة صحيحة؟', null, null, '["البنزين غير مشبع وإلكتروناته غير متمركزة، والهكسان الحلقي مشبع روابطه أحادية","البنزين مشبع روابطه أحادية، والهكسان الحلقي غير مشبع فيه رابطة ثنائية","كلاهما أروماتي؛ لأن كلًّا منهما حلقة سداسية من ذرات الكربون","كلاهما غير مشبع؛ لأن عدد ذرات الهيدروجين في كل منهما أقل من 14"]'::jsonb, 'فهم', 'مقارنة التشبع والبناء', 'متوسط', 'الكتاب ص 149–151'),
('mcq', 6, 'أُضيفت مادة تتفاعل بسهولة مع الروابط الثنائية المتمركزة إلى عينتين من هيدروكربونين مجهولين، فتفاعلت العينة (1) بسرعة، ولم تتفاعل العينة (2) بالطريقة نفسها مع أن صيغتها الجزيئية تدل على أنها غير مشبعة. ما الاستنتاج الأرجح؟', null, null, '["(1) مركب أروماتي، و(2) ألكين أليفاتي","(1) و(2) كلاهما ألكانان مشبعان","(1) مركب أروماتي، و(2) ألكان مشبع","(1) ألكين أليفاتي، و(2) مركب أروماتي"]'::jsonb, 'تحليل', 'استنتاج من ملاحظة تجريبية', 'صعب', 'الكتاب ص 150 — بناء البنزين'),
('mcq', 7, 'أيّ المركبات في الشكل الآتي يُتوقع أن يكون الأكثر ثباتًا والأقل تفاعلًا بالطرائق التي تتفاعل بها الألكينات؟', null, '[{"src":"qimg/chem22/c4-l5b-four-reactivity.svg","alt":"أربع صيغ هيكلية مرقمة: (1) سلسلة متعرجة مستقيمة من ست ذرات كربون فيها رابطة ثنائية واحدة بين ذرتي الكربون الأولى والثانية، وبقية الروابط أحادية. (2) حلقة سداسية فيها رابطة ثنائية واحدة، وبقية أضلاعها روابط أحادية. (3) حلقة سداسية بداخلها دائرة ترتبط بأحد رؤوسها مجموعة CH₂CH₃. (4) سلسلة من ست ذرات كربون فيها رابطة ثلاثية بين ذرتي الكربون الأولى والثانية، وبقية الروابط أحادية."}]'::jsonb, '["المركب (1)","المركب (2)","المركب (3)","المركب (4)"]'::jsonb, 'تطبيق', 'مقارنة الثبات من الصيغ', 'متوسط', 'الكتاب ص 150–152'),
('essay', 1, 'يبين الشكل الآتي مركبين لكل منهما حلقة سداسية من ذرات الكربون. قارن بينهما من حيث: نوع الهيدروكربون (أروماتي أم أليفاتي)، وتوزع إلكترونات الروابط الثنائية، والنشاط الكيميائي.', null, '[{"src":"qimg/chem22/c4-l5b-cyclohexene-benzene.svg","alt":"صيغتان هيكليتان مرقمتان لحلقتين سداسيتين من ذرات الكربون (دون كتابة الذرات): (1) حلقة سداسية فيها رابطة ثنائية واحدة بين ذرتين متجاورتين، وبقية الأضلاع روابط أحادية. (2) حلقة سداسية أضلاعها خطوط مفردة وبداخلها دائرة."}]'::jsonb, null, 'فهم', 'مقارنة من شكل', 'متوسط', 'الكتاب ص 150–151 وص 154 (س 34)'),
('essay', 2, 'لديك ثلاثة هيدروكربونات لكل منها ست ذرات كربون: الهكسان C₆H₁₄، و1-هكسين C₆H₁₂، والبنزين C₆H₆. صنّف كلًّا منها إلى أروماتي أو أليفاتي، وحدّد أيّها مشبع، ثم حلّل لماذا يكون البنزين أقل نشاطًا من 1-هكسين مع أنه أقل منه تشبعًا.', null, null, null, 'تحليل', 'تصنيف وتحليل', 'صعب', 'الكتاب ص 149–151'),
('essay', 3, 'سُمّيت المركبات الأروماتية بهذا الاسم لأن كثيرًا منها وُجد في زيوت ذات رائحة طيبة، وسُمّيت الأليفاتية بهذا الاسم لأنها استُخرجت من دهون الحيوانات. قيّم استمرار الكيميائيين في استخدام هذين المصطلحين إلى اليوم: هل ما زال أصل التسمية هو أساس التصنيف؟ وما الأساس العلمي الذي يبرر بقاء هذا التمييز؟', null, null, null, 'تقويم', 'تقويم وإصدار حكم', 'صعب', 'الكتاب ص 151 — ماذا قرأت؟')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
