insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'النفثالين يحتوي على حلقتي بنزين ملتحمتين فهو أروماتي، والإيثاين ألكاين لا يحتوي على حلقة بنزين فهو أليفاتي. أما التولوين والزايلين فكلاهما أروماتي، والبروبان والهكسين الحلقي كلاهما أليفاتي، والأنثراسين والفينانثرين كلاهما أروماتي.', '["","التولوين والزايلين كلاهما مشتق من البنزين، فهما أروماتيان.","البروبان ألكان والهكسين الحلقي ألكين حلقي، ولا يحتوي أيّ منهما على حلقة بنزين، فكلاهما أليفاتي.","الأنثراسين والفينانثرين كلاهما حلقات بنزين ملتحمة، فهما أروماتيان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 2, 2, 'الهيدروكربونات الأروماتية عالية الثبات لأن إلكتروناتها غير متمركزة، أما الألكينات والألكاينات الأليفاتية فأنشط كيميائيًّا؛ لذا الصف (3) صحيح. والصفوف (1) و(2) و(4) عُكست فيها الخاصيتان بين النوعين.', '["الصف (1) مقلوب: الأروماتية هي التي تحتوي على حلقة البنزين، والأليفاتية لا تحتوي عليها.","الصف (2) مقلوب: إلكترونات الأروماتية غير متمركزة، وإلكترونات الرابطة الثنائية في الأليفاتية متمركزة.","","الصف (4) مقلوب: أليفاتي تعني الدهن، وأروماتي ارتبط بالزيوت ذات الرائحة الطيبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 3, 3, 'النوعان كلاهما هيدروكربونات، أي مركبات عضوية تتكون من عنصري الكربون والهيدروجين فقط؛ ويختلفان في وجود حلقة البنزين وفي توزع الإلكترونات والثبات.', '["حلقة البنزين تميز الأروماتية وحدها، والأليفاتية لا تحتوي عليها.","عدم تمركز الإلكترونات من خصائص الأروماتية، أما الروابط الثنائية في الألكينات فمتمركزة.","تسخين دهون الحيوانات ارتبط بالمركبات الأليفاتية وحدها، وبه سُمّيت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 4, 1, '1-هكسين ألكين أليفاتي إلكترونات رابطته الثنائية متمركزة حول نواتين فيسهل تفاعله، أما البنزين فمادة غير نشطة كيميائيًّا ولا يتفاعل بالطرائق التي تتفاعل بها الألكينات والألكاينات عادة؛ لأن إلكتروناته غير متمركزة. إذن الهكسين أنشط من البنزين. إذن 1-هكسين أنشط لأن إلكترونات البنزين غير متمركزة.', '["البنزين ليس أنشط؛ فإلكتروناته غير متمركزة تجعله ثابتًا رغم عدم تشبعه.","","عدم التشبع وحده لا يحدد النشاط؛ فتوزع الإلكترونات في البنزين يجعله أثبت من الألكين.","كلاهما غير مشبع، و1-هكسين فيه رابطة ثنائية متمركزة تجعله نشطًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 5, 0, 'البنزين أروماتي غير مشبع (ينقصه ثماني ذرات هيدروجين عن C₆H₁₄)، وأزواج إلكترونات روابطه غير متمركزة. أما الهكسان الحلقي فألكان حلقي أليفاتي مشبع، كل روابطه أحادية، ونقص ذرتي الهيدروجين فيه سببه إغلاق الحلقة لا وجود رابطة ثنائية.', '["","المقارنة مقلوبة؛ فالبنزين هو غير المشبع، والهكسان الحلقي ألكان حلقي روابطه كلها أحادية.","وجود الحلقة لا يكفي؛ فالأروماتي يجب أن يحتوي على حلقة بنزين، والهكسان الحلقي أليفاتي.","الهكسان الحلقي مشبع لأن روابطه كلها أحادية، ونقص الهيدروجين فيه سببه إغلاق الحلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 6, 3, 'تفاعل (1) السريع مع المادة التي تهاجم الروابط الثنائية المتمركزة يدل على أنها ألكين أليفاتي. و(2) غير مشبعة لكنها لا تتفاعل بالطريقة نفسها، وهذا سلوك المركبات الأروماتية مثل البنزين التي تكون إلكتروناتها غير متمركزة فتكون ثابتة. إذن (1) ألكين أليفاتي و(2) مركب أروماتي.', '["المركب الأروماتي لا يتفاعل بطرائق الألكينات، فلا يمكن أن يكون هو العينة سريعة التفاعل.","صيغة (2) تدل على أنها غير مشبعة، و(1) تفاعلت مع الروابط الثنائية فليست مشبعة.","(2) غير مشبعة فليست ألكانًا، والمركب الأروماتي لا يتفاعل بسرعة بطرائق الألكينات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('mcq', 7, 2, 'المركب (3) إيثيل بنزين، وهو أروماتي يحتوي على حلقة بنزين إلكتروناتها غير متمركزة، فهو ثابت ولا يتفاعل بطرائق الألكينات. أما (1) ألكين و(2) هكسين حلقي و(4) ألكاين فمركبات أليفاتية روابطها المتعددة متمركزة فهي أنشط.', '["المركب (1) ألكين (1-هكسين) رابطته الثنائية متمركزة، فهو نشط.","المركب (2) هكسين حلقي أليفاتي، رابطته الثنائية متمركزة رغم أنه حلقي.","","المركب (4) ألكاين رابطته الثلاثية متمركزة، والألكاينات نشطة كيميائيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المركب (1) هكسين حلقي: هيدروكربون أليفاتي لأنه لا يحتوي على حلقة بنزين، وإلكترونات رابطته الثنائية متمركزة بين ذرتي كربون محددتين حول نواتين فقط، فيسهل سحبها ويكون نشطًا كالألكينات. المركب (2) بنزين: هيدروكربون أروماتي، والدائرة داخل الحلقة ترمز إلى أزواج إلكترونات غير متمركزة تشترك فيها ذرات الكربون الست وتتوزع على الحلقة بالتساوي، فيصعب سحبها ويكون ثابتًا ضعيف النشاط.', '["(1) أليفاتي و(2) أروماتي","(1) إلكترونات متمركزة بين ذرتين، و(2) غير متمركزة على الحلقة كاملة","(1) أنشط، و(2) ثابت ضعيف النشاط مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"نوع كل مركب","marks":1},{"element":"توزع الإلكترونات في كل منهما","marks":2},{"element":"مقارنة النشاط مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأوجه الثلاثة صحيحة لكلا المركبين"},{"level":"2–3 درجات","description":"وجهان صحيحان أو الأوجه الثلاثة لمركب واحد"},{"level":"1 درجة","description":"تصنيف المركبين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الهكسين الحلقي أروماتيًّا لأنه حلقي","القول إن الدائرة تعني غياب الروابط الثنائية","عدّ البنزين أنشط لأنه أقل تشبعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.640Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الهكسان: أليفاتي مشبع (ألكان روابطه أحادية فقط). 1-هكسين: أليفاتي غير مشبع (ألكين فيه رابطة ثنائية). البنزين: أروماتي غير مشبع (يحتوي على حلقة بنزين، وينقصه ثماني ذرات هيدروجين عن C₆H₁₄). التحليل: في 1-هكسين إلكترونات الرابطة الثنائية متمركزة حول نواتين فقط فيسهل سحبها فيكون نشطًا. أما في البنزين فأزواج الإلكترونات غير متمركزة تشترك فيها ذرات الكربون الست، فيصعب سحبها لأنها مشتركة مع ست نوى، فيكون ثابتًا ولا يتفاعل بطرائق الألكينات. إذن درجة النشاط تعتمد على توزع الإلكترونات لا على درجة عدم التشبع وحدها.', '["الهكسان أليفاتي مشبع","1-هكسين أليفاتي غير مشبع","البنزين أروماتي غير مشبع","إلكترونات 1-هكسين متمركزة فيسهل تفاعله","إلكترونات البنزين غير متمركزة مشتركة مع ست نوى فيثبت"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الهكسان","marks":1},{"element":"تصنيف 1-هكسين","marks":1},{"element":"تصنيف البنزين","marks":1},{"element":"تفسير نشاط 1-هكسين","marks":1},{"element":"تفسير ثبات البنزين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للمركبات الثلاثة وتحليل كامل للنشاط"},{"level":"3–4 درجات","description":"تصنيف صحيح وتحليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح فقط أو جزء منه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البنزين مشبعًا","عدّ البنزين أنشط لأنه أقل تشبعًا","تصنيف 1-هكسين أروماتيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لم يعد أصل التسمية (الرائحة أو الدهن) أساس التصنيف؛ فليس كل مركب ذي رائحة أروماتيًّا، ولا يُشترط في المركب الأليفاتي أن يُستخرج من الدهون. ومع ذلك يبرر بقاء التمييز اختلاف حقيقي في البناء والخواص: فالأروماتية تحتوي على حلقات بنزين إلكتروناتها غير متمركزة تتوزع على الحلقة كاملة بالتساوي، فتكون عالية الثبات ولا تتفاعل بطرائق الألكينات، أما الأليفاتية (الألكانات والألكينات والألكاينات) فلا تحتوي على حلقات بنزين، والألكينات والألكاينات منها روابطها المتعددة متمركزة فتكون أنشط. لذا فاستمرار المصطلحين مفيد لأنه يميز مجموعتين مختلفتين في البناء والثبات.', '["أصل التسمية لم يعد معيار التصنيف","الأساس الحالي: وجود حلقة البنزين أو عدمه","اختلاف الثبات بسبب عدم تمركز الإلكترونات","حكم مدعّم: بقاء المصطلحين مفيد"]'::jsonb, '[]'::jsonb, '[{"element":"نقد أصل التسمية معيارًا","marks":1},{"element":"أساس البناء","marks":1},{"element":"أساس الثبات وتوزع الإلكترونات","marks":1},{"element":"الحكم المدعّم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم متكامل يفصل أصل التسمية عن الأساس العلمي ويصدر حكمًا مدعّمًا"},{"level":"2–3 درجات","description":"بيان الأساس العلمي مع حكم ناقص التعليل"},{"level":"1 درجة","description":"ذكر أصل التسمية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كل مركب عطري الرائحة أروماتي","عدّ الأساس الحالي هو مصدر استخراج المركب","إغفال اختلاف الثبات بين النوعين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (2%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb)
