('mcq', 2, 'يمثّل الشكل الآتي مركبًا أروماتيًّا مسرطنًا يوجد في الرماد وفي دخان السجائر. ما اسمه؟', null, '[{"src":"qimg/chem22/c4-l5b-benzopyrene.svg","alt":"صيغة بنائية لمركب يتكون من خمس حلقات سداسية ملتحمة في داخل كل منها دائرة (حلقات بنزين): حلقتان متجاورتان في الوسط تشتركان في ضلع واحد، وحلقة فوقهما وأخرى تحتهما تشترك كل منهما في ضلع مع كل من الحلقتين الوسطيين، وحلقة خامسة في الأعلى ملتحمة بالحلقة العليا وحدها من ضلعها العلوي الأيمن."}]'::jsonb, '["الأنثراسين","البنزوبايرين","الفينانثرين","النفثالين"]'::jsonb, 'تذكر', 'تعرّف مثال من صيغته', 'سهل', 'الكتاب ص 154 — الشكل 4-28'),
('mcq', 3, 'أين يوجد البنزوبايرين المسبب للسرطان؟', null, null, '["في الزيوت العطرية للبهارات والفواكه","في كرات طارد العث المنزلية","في الرماد ودخان السجائر وعوادم السيارات","في ألياف البوليستر والأنسجة"]'::jsonb, 'تذكر', 'استرجاع مصدر', 'سهل', 'الكتاب ص 154 — الشكل 4-28'),
('mcq', 4, 'كيف يتكوّن البنزوبايرين؟', null, null, '["ناتج ثانوي عن احتراق مواد عضوية كالخشب والفحم","ناتج عن تحلل البروتينات داخل جسم الإنسان","مركب يُصنَّع عمدًا لاستخدامه في صناعة الأصباغ","ناتج عن تبريد الغاز الطبيعي إلى درجات منخفضة"]'::jsonb, 'فهم', 'تفسير مصدر', 'متوسط', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 5, 'وُصفت بعض المركبات الأروماتية الموجودة في الجازولين بأنها مسرطنة. ما معنى هذا الوصف؟', null, null, '["أنها ترفع قدرة الجازولين على الاحتراق","أنها تمنع تكوّن الدخان عند احتراق الوقود","أنها قد تسبب مرض السرطان لمن يتعرض لها","أنها مواد غير نشطة لا تضر الإنسان"]'::jsonb, 'فهم', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 6, 'عُرف منظفو المداخن في بريطانيا بإصابتهم بالسرطان بمعدلات عالية جدًّا. أيّ تفسير توصل إليه العلماء؟', null, null, '["استنشاقهم غاز الميثان المتسرب من المداخن بكميات كبيرة","تعرضهم للحرارة المرتفعة داخل المداخن مدة طويلة","تعاملهم مع النفثالين المستخدم طاردًا للعث في المنازل","تعرضهم المتكرر للبنزوبايرين الموجود في سناج المداخن"]'::jsonb, 'تحليل', 'تفسير ملاحظة تاريخية', 'صعب', 'الكتاب ص 154 — المواد المسرطنة'),
('mcq', 7, 'أيّ الأشخاص الآتين أكثر تعرضًا للبنزوبايرين في حياته اليومية؟', null, null, '["طاهٍ يستخدم البهارات العطرية في الطهي","مدخن يعمل في موقف مزدحم بالسيارات","خياط يعمل بأقمشة البوليستر","ربة منزل تضع طارد العث في الخزانة"]'::jsonb, 'تطبيق', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 154 — الشكل 4-28'),
('essay', 1, 'وضّح المقصود بالمادة المسرطنة، واذكر مثالين على مواد مسرطنة من المركبات الأروماتية، مبيّنًا مكان وجود كل منهما.', null, null, null, 'فهم', 'تعريف وأمثلة', 'متوسط', 'الكتاب ص 154 وص 161 (س 74)'),
('essay', 2, 'يمثّل الشكل الآتي البنزوبايرين. صف بناءه كما يظهر في الشكل، وصنّفه، ثم فسّر لماذا كانت العلاقة بين البنزوبايرين والسرطان وطيدة، مستعينًا بقصة منظفي المداخن في بريطانيا.', null, '[{"src":"qimg/chem22/c4-l5b-benzopyrene.svg","alt":"صيغة بنائية لمركب يتكون من خمس حلقات سداسية ملتحمة في داخل كل منها دائرة (حلقات بنزين): حلقتان متجاورتان في الوسط تشتركان في ضلع واحد، وحلقة فوقهما وأخرى تحتهما تشترك كل منهما في ضلع مع كل من الحلقتين الوسطيين، وحلقة خامسة في الأعلى ملتحمة بالحلقة العليا وحدها من ضلعها العلوي الأيمن."}]'::jsonb, null, 'تحليل', 'تفسير علاقة سبب ونتيجة', 'صعب', 'الكتاب ص 154 (س 37)'),
('essay', 3, 'قال شخص: «إشعال الحطب في المدفأة داخل البيت لا ضرر منه؛ لأن الخشب مادة طبيعية». قيّم هذه العبارة في ضوء ما تعرفه عن المواد المسرطنة، واقترح سلوكًا واحدًا يقلل الضرر مع بيان سببه.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 154 — المواد المسرطنة')
