('mcq', 1, 3, 'المواد المسرطنة هي المواد التي تسبب مرض السرطان، ومن أمثلتها بعض المركبات الأروماتية كالبنزوبايرين.', '["هذا عكس المقصود؛ فالمسرطنة تسبب السرطان ولا تعالجه.","المادة التي تسرّع التفاعلات دون أن تُستهلك عامل مساعد، لا مادة مسرطنة.","إذابة الدهون ليست تعريف المادة المسرطنة؛ فالمسرطنة هي المسببة للسرطان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('mcq', 2, 1, 'الشكل يمثّل خمس حلقات بنزين ملتحمة، وهو البنزوبايرين: مادة كيميائية مسببة للسرطان توجد في الرماد وفي دخان السجائر وعوادم السيارات.', '["الأنثراسين ثلاث حلقات بنزين ملتحمة على خط مستقيم، والشكل فيه خمس حلقات.","","الفينانثرين ثلاث حلقات ملتحمة بترتيب منحنٍ، والشكل فيه خمس حلقات.","النفثالين حلقتا بنزين ملتحمتان فقط، ويُستخدم طاردًا للعث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('mcq', 3, 2, 'البنزوبايرين مادة كيميائية مسببة للسرطان، توجد في الرماد وفي دخان السجائر وعوادم السيارات.', '["الزيوت العطرية ارتبط بها أصل تسمية المركبات الأروماتية، لا البنزوبايرين.","طارد العث يُتخذ من النفثالين، لا من البنزوبايرين.","","ألياف البوليستر تُصنع من الزايلين، لا من البنزوبايرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('mcq', 4, 0, 'البنزوبايرين ناتج ثانوي عن احتراق المخاليط المعقدة من المواد العضوية، ومنها الخشب والفحم؛ لذلك يوجد في السناج والرماد والدخان.', '["","البنزوبايرين لا يتكون في الجسم، بل ينتج عن احتراق مواد عضوية كالخشب والفحم.","الأنثراسين هو المستخدم في إنتاج الأصباغ، والبنزوبايرين ناتج ثانوي غير مقصود للاحتراق.","التبريد لا ينتج البنزوبايرين؛ فهو ناتج ثانوي عن الاحتراق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('mcq', 5, 2, 'المادة المسرطنة هي المسببة لمرض السرطان، فوصف بعض المركبات الأروماتية في الجازولين بأنها مسرطنة يعني أنها قد تسبب السرطان لمن يتعرض لها.', '["وصف «مسرطنة» صحي يتعلق بالسرطان، لا بخواص احتراق الوقود.","المسرطنة لا تعني منع الدخان؛ بل تعني التسبب في مرض السرطان.","","ضعف النشاط الكيميائي لا يعني عدم الضرر؛ فالمسرطنة تسبب السرطان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.641Z"}'::jsonb),
('mcq', 6, 3, 'أول مادة مسرطنة تم التعرف إليها مادة أروماتية اكتُشفت في القرن العشرين في سناج المداخن؛ فقد اكتشف العلماء أن سبب إصابة منظفي المداخن بالسرطان يعود إلى البنزوبايرين، وهو ناتج ثانوي عن احتراق المخاليط المعقدة من المواد العضوية كالخشب والفحم. إذن السبب تعرضهم المتكرر للبنزوبايرين الموجود في سناج المداخن.', '["الميثان ألكان أليفاتي ولم يُنسب إليه السرطان؛ والسبب مركب أروماتي في السناج.","السبب الذي اكتشفه العلماء كيميائي يعود إلى البنزوبايرين، لا إلى الحرارة.","النفثالين ليس مرتبطًا بالسناج؛ فالمادة المسرطنة في السناج هي البنزوبايرين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb),
('mcq', 7, 1, 'يوجد البنزوبايرين في دخان السجائر وعوادم السيارات والرماد؛ فالمدخن الذي يعمل في موقف مزدحم بالسيارات يتعرض لمصدرين منه معًا، فهو الأكثر تعرضًا له.', '["البهارات العطرية ليست مصدرًا مذكورًا للبنزوبايرين؛ فمصادره الدخان والعوادم والرماد.","","البوليستر يُصنع من الزايلين، وليس مصدرًا للبنزوبايرين.","طارد العث يحتوي على النفثالين، لا على البنزوبايرين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المادة المسرطنة: مادة تسبب مرض السرطان. مثال 1: البنزوبايرين، ويوجد في الرماد وسناج المداخن وفي دخان السجائر وعوادم السيارات، وهو ناتج ثانوي عن احتراق الخشب والفحم. مثال 2: بعض المركبات الأروماتية الموجودة في الجازولين، فقد عُرف أنها مسرطنة.', '["التعريف: مادة تسبب السرطان","البنزوبايرين ومكان وجوده","بعض المركبات الأروماتية في الجازولين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المثال الأول ومكانه","marks":1},{"element":"المثال الثاني ومكانه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومثالان بمكانيهما"},{"level":"2–3 درجات","description":"تعريف صحيح ومثال واحد، أو مثالان دون تعريف دقيق"},{"level":"1 درجة","description":"تعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المادة المسرطنة بأنها تعالج السرطان","ذكر النفثالين مثالًا على مادة مسرطنة","إغفال مكان وجود المثال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb),
('essay', 2, null::int, null, null, 'البناء: خمس حلقات بنزين ملتحمة تشترك كل حلقتين متجاورتين منها في ضلع، فهو مركب أروماتي من نظام الحلقات الملتحمة. التفسير: البنزوبايرين ناتج ثانوي عن احتراق المخاليط المعقدة من المواد العضوية كالخشب والفحم، لذا يوجد في السناج والرماد ودخان السجائر وعوادم السيارات. وقد عُرف منظفو المداخن في بريطانيا بإصابتهم بالسرطان بمعدلات عالية جدًّا، واكتشف العلماء أن السبب يعود إلى البنزوبايرين في سناج المداخن الذي يتعرضون له باستمرار؛ فكانت أول مادة مسرطنة تم التعرف إليها مادة أروماتية في السناج. ولأن هذا المركب ينتشر حيث يوجد الاحتراق ويتعرض له الناس بكثرة، كانت العلاقة بينه وبين السرطان وطيدة.', '["خمس حلقات بنزين ملتحمة","تصنيفه مركبًا أروماتيًّا ذا حلقات ملتحمة","ناتج ثانوي لاحتراق الخشب والفحم فيوجد في السناج","ارتفاع إصابة منظفي المداخن بالسرطان ونسبته إلى البنزوبايرين","استنتاج وطادة العلاقة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف البناء","marks":1},{"element":"التصنيف","marks":1},{"element":"مصدر البنزوبايرين","marks":1},{"element":"دليل منظفي المداخن","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف وتصنيف صحيحان وتفسير مكتمل بالدليل"},{"level":"3–4 درجات","description":"تفسير صحيح بالدليل مع نقص في الوصف أو التصنيف"},{"level":"1–2 درجة","description":"وصف البناء أو ذكر أنه مسرطن دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الحلقات أربعًا أو ستًّا","نسبة إصابة منظفي المداخن إلى الحرارة أو الغبار عمومًا","تصنيفه مركبًا أليفاتيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فكون الخشب طبيعيًّا لا يعني أن نواتج احتراقه آمنة. فاحتراق المخاليط المعقدة من المواد العضوية كالخشب والفحم ينتج البنزوبايرين ناتجًا ثانويًّا، وهو مادة مسرطنة توجد في الرماد والسناج والدخان، وقد ارتبط سناج المداخن بارتفاع إصابة منظفيها بالسرطان. السلوك المقترح: تقليل التعرض لدخان المدفأة ورمادها وسناجها، مثل عدم الجلوس قرب الدخان، وتنظيف المدخنة مع تجنب استنشاق السناج؛ لأن ذلك يقلل التعرض للبنزوبايرين المسرطن.', '["الحكم: العبارة غير صحيحة","احتراق الخشب ينتج البنزوبايرين","البنزوبايرين مسرطن ويوجد في الرماد والسناج والدخان","سلوك مقترح معلل بتقليل التعرض"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"ربط الاحتراق بالبنزوبايرين","marks":1},{"element":"بيان أنه مسرطن ومكان وجوده","marks":1},{"element":"السلوك المقترح وسببه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعّم علميًّا مع سلوك معلل"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل ناقص أو سلوك غير معلل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن كل ما هو طبيعي آمن","إغفال أن البنزوبايرين ناتج ثانوي للاحتراق","اقتراح سلوك لا علاقة له بتقليل التعرض للدخان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb)
