('mcq', 4, 'ما الذي فسرته صيغة كيكولي من خصائص البنزين، ولم تفسره الصيغة المفتوحة CH₂=C=CH−CH=C=CH₂ المقترحة عام 1860م؟', null, null, '["ضعف النشاط الكيميائي للبنزين","الشكل الحلقي السداسي المسطح لجزيء البنزين","عدم تمركز إلكترونات روابط البنزين","الصيغة الجزيئية C₆H₆ للبنزين"]'::jsonb, 'تحليل', 'مقارنة نماذج', 'صعب', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
('mcq', 5, 'لو كانت الروابط الثنائية الثلاث في البنزين متمركزة بين ذرات كربون محددة كما في صيغة كيكولي، فبمَ يُتوقع أن يتشابه سلوكه الكيميائي؟', null, null, '["بسلوك الألكانات، فيكون ضعيف النشاط","بسلوك الغازات النبيلة، فلا يتفاعل أبدًا","بسلوك البنزين الفعلي، فيكون ثابتًا","بسلوك الألكينات، فيتفاعل بسهولة"]'::jsonb, 'فهم', 'توقع سلوك', 'سهل', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
('mcq', 6, 'كيف عالجت نظرية المجالات المهجنة التي اقترحها لينوس باولنج عام 1930م قصور صيغة كيكولي؟', null, null, '["بيّنت أن إلكترونات الروابط الثنائية غير متمركزة في الحلقة","رفضت الشكل السداسي واقترحت سلسلة مفتوحة من ست ذرات كربون","بيّنت أن الروابط بين ذرات الكربون الست كلها ثلاثية","أضافت ذرتي هيدروجين إلى كل ذرة كربون في الحلقة"]'::jsonb, 'تحليل', 'تفسير تطور نموذج', 'متوسط', 'الكتاب ص 150 — حلم كيكولي ونموذج البنزين الحديث'),
('mcq', 7, 'قال طالب: «رُفضت صيغة كيكولي لأنها لا تتفق مع الصيغة الجزيئية للبنزين C₆H₆». ما التقويم الصحيح لعبارته؟', null, null, '["صحيحة؛ لأن صيغة كيكولي تحتوي على 12 ذرة هيدروجين","صحيحة؛ لأن الحلقة السداسية لا تتسع لست ذرات كربون","خاطئة؛ فصيغة كيكولي تتفق مع C₆H₆، لكنها لا تفسر ضعف نشاطه","خاطئة؛ لأن صيغة كيكولي مقبولة تمثيلًا فعليًّا للبنزين"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 150 وص 162 (س 89)'),
('essay', 1, 'صف خواص البنزين التي جعلت الكيميائيين ينفون احتمال كونه ألكينًا ذا روابط ثنائية متعددة.', null, null, null, 'فهم', 'وصف خواص', 'سهل', 'الكتاب ص 154 (س 35)'),
('essay', 2, 'يبين الشكل الآتي ثلاث صيغ اقتُرحت لجزيء البنزين. قارن بينها من حيث: اتفاقها مع الصيغة الجزيئية C₆H₆ (بعدّ ذرات C و H في كل منها)، وتفسيرها للشكل الحلقي، وتفسيرها لضعف نشاط البنزين، ثم استنتج سبب رفض الصيغتين (1) و(2) وقبول (3).', null, '[{"src":"qimg/chem22/c4-l5b-three-models.svg","alt":"ثلاث صيغ مرقمة اقتُرحت لجزيء البنزين: (1) سلسلة مفتوحة مستقيمة من ست ذرات كربون فيها أربع روابط ثنائية ورابطة أحادية واحدة في الوسط، ترتبط ذرتا هيدروجين بكل من ذرتي الطرفين، وذرة هيدروجين بكل من الذرتين الثالثة والرابعة، ولا هيدروجين على الذرتين الثانية والخامسة. (2) حلقة سداسية تتناوب فيها ثلاث روابط ثنائية مع ثلاث روابط أحادية. (3) حلقة سداسية أضلاعها خطوط مفردة وبداخلها دائرة."}]'::jsonb, null, 'تحليل', 'مقارنة نماذج واستنتاج', 'صعب', 'الكتاب ص 149–150'),
('essay', 3, 'استنتج طالب من صيغة كيكولي أن البنزين يتفاعل بسهولة كما يتفاعل 1-هكسين، بل أكثر منه؛ لأن في صيغة كيكولي ثلاث روابط ثنائية مقابل رابطة ثنائية واحدة في 1-هكسين. حلّل استنتاجه: على أيّ افتراض بناه؟ ولماذا تخالفه المشاهدة؟ وماذا تدل هذه المخالفة عليه بشأن صيغة كيكولي؟ وكيف فسرت نظرية المجالات المهجنة التي اقترحها لينوس باولنج عام 1930م هذه المشاهدة؟', null, null, null, 'تحليل', 'شرح وتحليل', 'صعب', 'الكتاب ص 149–150 وص 154 (س 35)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C4-L5-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الصيغة سلسلة مفتوحة فيها أربع روابط ثنائية بين ذرات كربون محددة، ومثل هذا الهيدروكربون غير مستقر وشديد التفاعل لوجود العديد من الروابط الثنائية. لكن البنزين غير نشط كيميائيًّا، ولهذا استنتج العلماء أن هذه الصيغة غير صحيحة.', '["","الصيغة فيها أربع روابط ثنائية متمركزة، فالمتوقع منها نشاط شديد لا ثبات.","الصيغة تحتوي على أربع روابط ثنائية فهي غير مشبعة.","الروابط الثنائية في السلسلة متمركزة بين ذرات محددة، ولا حلقة تتوزع عليها الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.642Z"}'::jsonb),
('mcq', 2, 3, 'الصيغ ذات الروابط الثنائية المتعددة تتنبأ بمركب غير مستقر وشديد التفاعل، إلا أن البنزين مادة غير نشطة كيميائيًّا ولا تتفاعل بالطرائق التي تتفاعل بها الألكينات والألكاينات عادة؛ وهذا هو الدليل الذي رُفضت به تلك الصيغ.', '["الصيغة الجزيئية للبنزين C₆H₆ فعلًا، والصيغ المرفوضة كانت تتفق معها.","البنزين غير مشبع؛ ينقصه ثماني ذرات هيدروجين عن C₆H₁₄.","العكس هو الصحيح؛ فالبنزين مادة غير نشطة كيميائيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('mcq', 3, 0, 'الصيغة (1) سلسلة ذات روابط ثنائية كثيرة تتنبأ بمركب شديد التفاعل، والصيغة (2) (كيكولي) حلقة بروابط ثنائية متمركزة لا تفسر ضعف النشاط. أما الصيغة (3) فالدائرة فيها ترمز إلى أزواج إلكترونات غير متمركزة تشترك فيها ذرات الكربون الست، وهذا ما يفسر ثبات البنزين. إذن الصيغة (3) فقط.', '["","صيغة كيكولي (2) تفسر الشكل السداسي المسطح لكنها لا تفسر ضعف النشاط؛ لأن روابطها الثنائية متمركزة.","كلتاهما تحتوي روابط ثنائية متمركزة بين ذرات محددة، فتتنبآن بنشاط يشبه الألكينات.","الصيغة (2) لا تفسر ضعف النشاط، فلا يصح جمعها مع (3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('mcq', 4, 1, 'صيغة كيكولي حلقة سداسية مسطحة تتناوب فيها الروابط الأحادية والثنائية؛ وهي تفسر الشكل السداسي المسطح وبعض خصائص البنزين، وقد أكدت الأبحاث أن البنزين فعلًا ذو شكل سداسي، لكنها لا تفسر ضعف نشاطه. أما الصيغة المفتوحة فلا تفسر الشكل الحلقي، والصيغتان تتفقان مع C₆H₆.', '["صيغة كيكولي نفسها لا تفسر ضعف النشاط؛ فهذا ما فسره نموذج باولنج لاحقًا.","","عدم التمركز جاءت به نظرية المجالات المهجنة عام 1930م، لا صيغة كيكولي.","الصيغتان كلتاهما تتفقان مع C₆H₆، فهذه ليست ميزة لصيغة كيكولي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('mcq', 5, 3, 'الروابط الثنائية المتمركزة بين ذرتين محددتين هي سمة الألكينات، وإلكتروناتها الثابتة حول نواتين فقط يسهل سحبها فتتفاعل بسهولة؛ لذا يُتوقع أن يسلك البنزين حينئذ سلوك الألكينات. ولأن البنزين لا يفعل ذلك، رُفضت فكرة الروابط المتمركزة.', '["الروابط الثنائية المتمركزة سمة الألكينات النشطة، لا الألكانات المشبعة.","الروابط الثنائية المتمركزة تجعل المركب نشطًا، لا خاملًا كالغازات النبيلة.","البنزين الفعلي ثابت لأن إلكتروناته غير متمركزة، وهذا عكس الافتراض المذكور.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('mcq', 6, 0, 'عند تطبيق نظرية المجالات المهجنة على البنزين تنبأت بأن أزواج الإلكترونات المكونة للروابط الثنائية لا تتجمع بين ذرتي كربون محددتين كما في الألكينات، بل تكون غير متمركزة تشترك فيها جميع ذرات الكربون الست، وهذا يفسر ضعف نشاطه الذي عجزت عنه صيغة كيكولي.', '["","الأبحاث أكدت الشكل السداسي، ولم تقترح النظرية سلسلة مفتوحة.","لم تقترح النظرية روابط ثلاثية؛ بل جعلت إلكترونات الروابط الثنائية غير متمركزة.","يبقى البنزين C₆H₆ بذرة هيدروجين واحدة على كل ذرة كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('mcq', 7, 2, 'صيغة كيكولي حلقة من ست ذرات كربون ترتبط كل منها بذرة هيدروجين واحدة، فصيغتها الجزيئية C₆H₆ مطابقة للبنزين. وسبب عدم قبولها أنها لا تفسر ضعف النشاط الكيميائي للبنزين. إذن العبارة خاطئة.', '["في صيغة كيكولي ست ذرات كربون ترتبط كل منها بذرة هيدروجين واحدة، أي C₆H₆.","الحلقة السداسية تتكون من ست ذرات كربون تحديدًا، فهي تتفق مع C₆.","","صيغة كيكولي لا تمثل البناء الفعلي؛ فروابطها المتمركزة لا تفسر ضعف النشاط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('essay', 1, null::int, null, null, 'البنزين C₆H₆ غير مشبع، لكنه مادة غير نشطة كيميائيًّا (ثابت)، ولا يتفاعل بالطرائق التي تتفاعل بها الألكينات والألكاينات عادة. ولو كان ألكينًا ذا روابط ثنائية متعددة لكان غير مستقر وشديد التفاعل. لذلك نفى الكيميائيون أن يكون كذلك، ثم فسرت نظرية المجالات المهجنة ثباته بأن إلكتروناته غير متمركزة.', '["البنزين ثابت غير نشط كيميائيًّا","لا يتفاعل بطرائق تفاعل الألكينات والألكاينات","الألكين ذو الروابط الثنائية المتعددة يُتوقع أن يكون غير مستقر وشديد التفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"ثبات البنزين وضعف نشاطه","marks":1},{"element":"عدم تفاعله بطرائق الألكينات","marks":1},{"element":"المقارنة بما يُتوقع من ألكين متعدد الروابط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الخواص الثلاث مع المقارنة"},{"level":"2 درجتان","description":"خاصيتان صحيحتان"},{"level":"1 درجة","description":"خاصية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أن البنزين مشبع","وصف البنزين بأنه شديد التفاعل","الاكتفاء بالصيغة الجزيئية دليلًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الصيغة (1): ست ذرات كربون، والهيدروجين 2 + 1 + 1 + 2 = 6، فهي C₆H₆؛ لا تفسر الشكل الحلقي لأنها سلسلة مفتوحة، ولا تفسر ضعف النشاط لأن روابطها الثنائية الأربع المتمركزة تجعلها شديدة التفاعل. الصيغة (2) (كيكولي): ست ذرات كربون وعلى كل منها ذرة هيدروجين واحدة، فهي C₆H₆؛ تفسر الشكل الحلقي السداسي المسطح، لكنها لا تفسر ضعف النشاط لأن روابطها الثنائية متمركزة كالألكينات. الصيغة (3): C₆H₆ أيضًا (ذرات الهيدروجين لا تُكتب لكنها موجودة)، وتفسر الشكل الحلقي، وتفسر ضعف النشاط لأن الدائرة ترمز إلى أزواج إلكترونات غير متمركزة تشترك فيها ذرات الكربون الست فيصعب سحبها. الاستنتاج: الاتفاق مع الصيغة الجزيئية لم يكن كافيًا؛ فقد رُفضت (1) و(2) لأنهما لا تفسران ضعف نشاط البنزين، وقُبلت (3) لأنها تفسر الشكل والثبات معًا.', '["الصيغ الثلاث تتفق مع C₆H₆ بعدّ الذرات","(1) لا تفسر الشكل الحلقي، و(2) و(3) تفسرانه","(1) و(2) لا تفسران ضعف النشاط لتمركز الروابط الثنائية","(3) تفسر ضعف النشاط بعدم تمركز الإلكترونات","الاستنتاج: سبب الرفض تفسير النشاط لا الصيغة الجزيئية"]'::jsonb, '["عدّ ذرات C و H في الصيغة (1): C = 6، H = 2 + 1 + 1 + 2 = 6","عدّ ذرات الصيغة (2): C = 6، H = 6 (ذرة على كل كربون)","الصيغة (3): C = 6، وذرات H الست موجودة وإن لم تُكتب","مقارنة تفسير الشكل الحلقي وضعف النشاط","الاستنتاج"]'::jsonb, '[{"element":"عدّ الذرات في الصيغ الثلاث","marks":1},{"element":"مقارنة تفسير الشكل الحلقي","marks":1},{"element":"قصور (1) و(2) في تفسير النشاط","marks":1},{"element":"تفسير (3) للثبات","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة بالأوجه الثلاثة واستنتاج صحيح"},{"level":"3–4 درجات","description":"مقارنة صحيحة في وجهين مع استنتاج"},{"level":"1–2 درجة","description":"عدّ الذرات أو وصف الصيغ دون مقارنة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الصيغة (1) لا تتفق مع C₆H₆","عدّ صيغة كيكولي مفسرة لضعف النشاط","نسيان ذرات الهيدروجين غير المكتوبة في الصيغة (3)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.643Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بنى الطالب استنتاجه على افتراض أن الروابط الثنائية الثلاث في صيغة كيكولي متمركزة بين أزواج محددة من ذرات الكربون كما في الألكينات، فتسلك كل منها سلوك الرابطة الثنائية في 1-هكسين. لكن المشاهدة أن البنزين مادة غير نشطة كيميائيًّا، ولا يتفاعل بالطرائق التي تتفاعل بها الألكينات والألكاينات عادة، فهو أقل نشاطًا من 1-هكسين لا أكثر. وتدل هذه المخالفة على أن صيغة كيكولي، مع أنها تتفق مع الصيغة الجزيئية C₆H₆ وتفسر الشكل السداسي، لا تمثل التوزيع الفعلي لإلكترونات الروابط، ولذلك لا تفسر ضعف نشاط البنزين. وقد فسرت نظرية المجالات المهجنة ذلك بأن أزواج الإلكترونات المكونة للروابط الثنائية لا تتجمع بين ذرتي كربون محددتين، بل تكون غير متمركزة تشترك فيها جميع ذرات الكربون الست، فيصعب سحبها لأنها مشتركة مع ست نوى، فيكون الجزيء ثابتًا.', '["الافتراض: الروابط الثنائية الثلاث متمركزة كما في الألكينات","المشاهدة: البنزين غير نشط ولا يتفاعل بطرائق الألكينات","الدلالة: صيغة كيكولي لا تمثل التوزيع الفعلي للإلكترونات فلا تفسر ضعف النشاط","تفسير باولنج: إلكترونات غير متمركزة مشتركة مع ست نوى فيثبت الجزيء"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الافتراض","marks":1},{"element":"المشاهدة المخالفة","marks":1},{"element":"دلالة المخالفة على صيغة كيكولي","marks":1},{"element":"تفسير نظرية المجالات المهجنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل للافتراض والمشاهدة والدلالة وتفسير النظرية"},{"level":"2–3 درجات","description":"بيان المشاهدة وتفسير النظرية مع نقص في تحديد الافتراض أو الدلالة"},{"level":"1 درجة","description":"ذكر أن البنزين غير نشط دون تحليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول استنتاج الطالب لأن صيغة كيكولي فيها ثلاث روابط ثنائية","القول إن صيغة كيكولي رُفضت لعدم اتفاقها مع C₆H₆","نسبة نظرية المجالات المهجنة إلى كيكولي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
