('mcq', 3, 'أيّ الصيغ في الشكل الآتي تمثّل نظام حلقات ملتحمة؟', null, '[{"src":"qimg/chem22/c4-l5b-fused-or-not.svg","alt":"أربع صيغ بنائية مرقمة: (1) حلقتا بنزين (حلقة سداسية بداخلها دائرة) إحداهما فوق الأخرى، تصل بينهما رابطة أحادية واحدة بين رأس من الأولى ورأس من الثانية، ولا تشتركان في أي ضلع. (2) حلقتا بنزين متجاورتان أفقيًّا تشتركان في ضلع واحد. (3) حلقة بنزين واحدة ترتبط بها مجموعتا CH₃ في موقعين متقابلين (أعلى الحلقة وأسفلها). (4) حلقة بنزين في الأعلى تصل بينها وبين حلقة سداسية مشبعة في الأسفل (كل أضلاعها روابط أحادية دون دائرة) رابطة أحادية، ولا تشتركان في أي ضلع."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'فهم', 'تمييز من صيغ', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('mcq', 4, 'تشترك حلقتا البنزين في النفثالين في ضلع واحد. كم ذرة كربون تنتمي إلى الحلقتين معًا؟', null, null, '["ذرة واحدة","ذرتان","أربع ذرات","ست ذرات"]'::jsonb, 'فهم', 'تفسير التعريف', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('mcq', 5, 'كم حلقة بنزين ملتحمة يحتوي عليها جزيء البنزوبايرين الممثَّل بالشكل الآتي؟', null, '[{"src":"qimg/chem22/c4-l5b-benzopyrene.svg","alt":"صيغة بنائية لمركب يتكون من خمس حلقات سداسية ملتحمة في داخل كل منها دائرة (حلقات بنزين): حلقتان متجاورتان في الوسط تشتركان في ضلع واحد، وحلقة فوقهما وأخرى تحتهما تشترك كل منهما في ضلع مع كل من الحلقتين الوسطيين، وحلقة خامسة في الأعلى ملتحمة بالحلقة العليا وحدها من ضلعها العلوي الأيمن."}]'::jsonb, '["ثلاث حلقات","أربع حلقات","خمس حلقات","ست حلقات"]'::jsonb, 'تذكر', 'قراءة صيغة', 'سهل', 'الكتاب ص 154 — الشكل 4-28'),
('mcq', 6, 'بماذا تتشارك ذرات الكربون المكوِّنة للحلقات في نظام الحلقات الملتحمة كالنفثالين؟', null, null, '["تتشارك بالإلكترونات كما في البنزين","تتشارك بذرات الهيدروجين المرتبطة بها","تتشارك بروابط ثلاثية متمركزة بين الحلقات","لا تتشارك بشيء؛ فكل حلقة مستقلة بإلكتروناتها"]'::jsonb, 'فهم', 'تفسير خاصية', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('mcq', 7, 'النفثالين حلقتا بنزين ملتحمتان تشتركان في ضلع واحد، ولا ترتبط ذرتا الكربون المشتركتان بأي ذرة هيدروجين. ما الصيغة الجزيئية للنفثالين؟', null, null, '["C₁₂H₁₂","C₁₀H₈","C₁₀H₁₀","C₁₂H₁₀"]'::jsonb, 'تطبيق', 'حساب صيغة جزيئية', 'صعب', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('essay', 1, 'عرّف نظام الحلقات الملتحمة، واذكر ثلاثة أمثلة عليه مع عدد حلقات البنزين في كل مثال، ثم وضّح بماذا تتشارك ذرات الكربون المكوِّنة للحلقات فيه.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'متوسط', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('essay', 2, 'يمثّل الشكل الآتي الأنثراسين (1) والفينانثرين (2). احسب الصيغة الجزيئية لكل منهما بعدّ ذرات الكربون وذرات الهيدروجين، موضحًا خطواتك، ثم بيّن هل لهما الصيغة الجزيئية نفسها، وما الذي يختلفان فيه.', null, '[{"src":"qimg/chem22/c4-l5b-anth-phen.svg","alt":"صيغتان بنائيتان مرقمتان، كل منهما ثلاث حلقات سداسية ملتحمة في داخل كل منها دائرة (حلقات بنزين): (1) الحلقات الثلاث مرتبة على خط مستقيم أفقي، وتشترك الحلقة الوسطى في ضلع مع كل من الحلقتين الجانبيتين. (2) حلقتان متجاورتان أفقيًّا تشتركان في ضلع، وحلقة ثالثة ملتحمة بالحلقة اليمنى من ضلعها العلوي الأيمن، فيكون ترتيب الحلقات منحنيًا."}]'::jsonb, null, 'تطبيق', 'حساب صيغة جزيئية ومقارنة', 'صعب', 'الكتاب ص 151 — المركبات الأروماتية (الحلقات الملتحمة)'),
('essay', 3, 'يمثّل الشكل الآتي البنزوبايرين. بيّن لماذا يُعد مثالًا على نظام الحلقات الملتحمة، ولماذا يُصنَّف مركبًا أروماتيًّا، ثم احسب صيغته الجزيئية علمًا بأن فيه 8 ذرات كربون مشتركة بين حلقتين أو أكثر لا ترتبط بأي ذرة هيدروجين، وأن عدد ذرات الكربون فيه 20.', null, '[{"src":"qimg/chem22/c4-l5b-benzopyrene.svg","alt":"صيغة بنائية لمركب يتكون من خمس حلقات سداسية ملتحمة في داخل كل منها دائرة (حلقات بنزين): حلقتان متجاورتان في الوسط تشتركان في ضلع واحد، وحلقة فوقهما وأخرى تحتهما تشترك كل منهما في ضلع مع كل من الحلقتين الوسطيين، وحلقة خامسة في الأعلى ملتحمة بالحلقة العليا وحدها من ضلعها العلوي الأيمن."}]'::jsonb, null, 'تطبيق', 'تحليل صيغة وحساب', 'صعب', 'الكتاب ص 151 وص 154')
