from (values
('mcq', 1, 0, 'نظام الحلقات الملتحمة (fused): أن يحتوي المركب العضوي على حلقتين أو أكثر تشتركان في الضلع نفسه، كما في النفثالين.', '["","الحلقتان المتصلتان برابطة أحادية لا تشتركان في ضلع، فليستا ملتحمتين.","هذا وصف مشتق بنزين متفرع كالتولوين، وفيه حلقة واحدة فقط.","هذا وصف ألكان حلقي كالهكسان الحلقي، لا نظام حلقات ملتحمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 2, 3, 'تبدو الصيغة البنائية للنفثالين كحلقتي بنزين متلاصقتين جنبًا إلى جنب تشتركان في ضلع، ويُعد مثالًا على نظام الحلقات الملتحمة. أما التولوين وبارا-زايلين وإيثيل بنزين ففي كل منها حلقة بنزين واحدة.', '["التولوين حلقة بنزين واحدة ترتبط بها مجموعة ميثيل، فلا التحام فيه.","بارا-زايلين حلقة بنزين واحدة ترتبط بها مجموعتا ميثيل، فلا التحام فيه.","إيثيل بنزين حلقة بنزين واحدة ترتبط بها مجموعة إيثيل، فلا التحام فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 3, 1, 'الحلقات الملتحمة حلقتان أو أكثر تشتركان في الضلع نفسه. في الصيغة (2) تشترك حلقتا البنزين في ضلع واحد (النفثالين)، أما (1) و(4) فالحلقتان متصلتان برابطة أحادية دون ضلع مشترك، و(3) حلقة واحدة. إذن الصيغة (2).', '["الحلقتان في (1) تصل بينهما رابطة أحادية ولا تشتركان في أي ضلع.","","الصيغة (3) حلقة بنزين واحدة ترتبط بها مجموعتا ميثيل، فلا توجد حلقتان أصلًا.","الحلقتان في (4) تصل بينهما رابطة أحادية ولا تشتركان في ضلع، فليستا ملتحمتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 4, 1, 'الضلع في الحلقة رابطة تصل بين ذرتي كربون، فاشتراك الحلقتين في ضلع واحد يعني أن ذرتي كربون تنتميان إلى الحلقتين معًا.', '["الضلع المشترك رابطة بين ذرتين، فالذرات المشتركة اثنتان لا واحدة.","","الحلقتان تشتركان في ضلع واحد فقط، أي في ذرتين لا أربع.","لو اشتركت الحلقتان في ست ذرات لانطبقتا وصارتا حلقة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 5, 2, 'يتكون البنزوبايرين من خمس حلقات بنزين ملتحمة: حلقتان في الوسط، وحلقة فوقهما، وحلقة تحتهما، وحلقة خامسة ملتحمة بالحلقة العليا.', '["ثلاث حلقات ملتحمة عدد حلقات الأنثراسين أو الفينانثرين، والشكل فيه أكثر من ذلك.","يظهر في الشكل حلقتان في الوسط وحلقة فوقهما وأخرى تحتهما وحلقة خامسة في الأعلى.","","عدد الحلقات في الشكل خمس؛ فلا توجد حلقة سادسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 6, 0, 'في نظام الحلقات الملتحمة تتشارك ذرات الكربون المكوِّنة للحلقات بالإلكترونات كما في البنزين؛ ولذلك تُعد هذه المركبات أروماتية.', '["","ذرات الكربون لا تتشارك بذرات الهيدروجين؛ وما يُتشارك فيه هو الإلكترونات.","لا توجد روابط ثلاثية في هذه المركبات، والإلكترونات فيها غير متمركزة.","الحلقات الملتحمة تتشارك ذراتها بالإلكترونات كما في البنزين، فليست مستقلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-14T13:39:20.644Z"}'::jsonb),
('mcq', 7, 1, 'ذرات الكربون: 6 + 6 − 2 = 10؛ لأن ذرتين مشتركتان بين الحلقتين. ذرات الهيدروجين: ترتبط ذرة هيدروجين بكل ذرة كربون غير مشتركة، وعددها 10 − 2 = 8. إذن الصيغة الجزيئية C₁₀H₈.', '["هذا مجموع جزيئي بنزين منفصلين (2 × C₆H₆)، مع إغفال أن ذرتي الكربون مشتركتان.","","عُدّت ذرات الكربون صحيحة، لكن أُضيفت ذرة هيدروجين لكل من ذرتي الكربون المشتركتين.","هذه صيغة حلقتي بنزين متصلتين برابطة أحادية، لا حلقتين ملتحمتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.645Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نظام الحلقات الملتحمة: أن يحتوي المركب العضوي على حلقتين أو أكثر تشتركان في الضلع نفسه. أمثلة: النفثالين (حلقتان)، والأنثراسين (ثلاث حلقات على خط مستقيم)، والفينانثرين (ثلاث حلقات بترتيب منحنٍ)، والبنزوبايرين (خمس حلقات). وتتشارك ذرات الكربون المكوِّنة للحلقات بالإلكترونات كما في البنزين.', '["التعريف: حلقتان أو أكثر تشتركان في الضلع نفسه","ثلاثة أمثلة صحيحة","عدد الحلقات في كل مثال","التشارك بالإلكترونات كما في البنزين"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الأمثلة الثلاثة","marks":1},{"element":"عدد الحلقات","marks":1},{"element":"التشارك بالإلكترونات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف وأمثلة وأعداد حلقات وتشارك صحيحة"},{"level":"2–3 درجات","description":"تعريف صحيح مع نقص في الأمثلة أو الأعداد"},{"level":"1 درجة","description":"تعريف فقط أو أمثلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الحلقات الملتحمة بأنها حلقات متصلة برابطة أحادية","ذكر التولوين أو الزايلين مثالًا","عدّ حلقات الفينانثرين أربعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-14T13:39:20.645Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأنثراسين: ثلاث حلقات، كل حلقتين متجاورتين تشتركان في ذرتين، والضلعان المشتركان منفصلان؛ فذرات الكربون = 18 − 4 = 14. ذرات الكربون المشتركة 4 لا ترتبط بهيدروجين، فذرات الهيدروجين = 14 − 4 = 10، والصيغة C₁₄H₁₀. الفينانثرين: ثلاث حلقات أيضًا بضلعين مشتركين منفصلين؛ فذرات الكربون = 18 − 4 = 14، وذرات الهيدروجين = 14 − 4 = 10، والصيغة C₁₄H₁₀. إذن لهما الصيغة الجزيئية نفسها C₁₄H₁₀، ويختلفان في طريقة التحام الحلقات: على خط مستقيم في الأنثراسين، وبترتيب منحنٍ في الفينانثرين.', '["الأنثراسين C₁₄H₁₀ مع الخطوات","الفينانثرين C₁₄H₁₀ مع الخطوات","لهما الصيغة الجزيئية نفسها","يختلفان في ترتيب التحام الحلقات"]'::jsonb, '["ذرات الكربون في ثلاث حلقات منفصلة: 3 × 6 = 18","في كل مركب ضلعان مشتركان منفصلان = 4 ذرات مشتركة، فذرات الكربون = 18 − 4 = 14","ذرات الهيدروجين = عدد ذرات الكربون غير المشتركة = 14 − 4 = 10","الصيغة لكل منهما C₁₄H₁₀","المقارنة: الصيغة نفسها والترتيب مختلف"]'::jsonb, '[{"element":"صيغة الأنثراسين","marks":1},{"element":"صيغة الفينانثرين","marks":1},{"element":"المقارنة بين الصيغتين","marks":1},{"element":"وجه الاختلاف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغتان صحيحتان بالخطوات مع المقارنة ووجه الاختلاف"},{"level":"2–3 درجات","description":"صيغة صحيحة واحدة مع مقارنة، أو الصيغتان دون مقارنة"},{"level":"1 درجة","description":"عدّ صحيح لذرات الكربون فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع ذرات الحلقات الثلاث (C₁₈H₁₈) دون طرح المشتركة","إضافة ذرات هيدروجين على ذرات الكربون المشتركة","القول إن الاختلاف في عدد الحلقات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.645Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يُعد البنزوبايرين نظام حلقات ملتحمة لأنه يحتوي على أكثر من حلقتين تشترك كل حلقتين متجاورتين منها في الضلع نفسه، ويُصنَّف أروماتيًّا لأن حلقاته الخمس حلقات بنزين تتشارك ذرات الكربون فيها بالإلكترونات كما في البنزين. ذرات الكربون 20، منها 8 مشتركة لا ترتبط بهيدروجين، فذرات الكربون التي يرتبط بكل منها ذرة هيدروجين = 20 − 8 = 12، والصيغة الجزيئية C₂₀H₁₂.', '["حلقات تشترك في الضلع نفسه","أروماتي: حلقات بنزين تتشارك ذراتها بالإلكترونات","حساب الهيدروجين: 20 − 8 = 12","الصيغة C₂₀H₁₂"]'::jsonb, '["ذرات الكربون غير المشتركة = 20 − 8 = 12","كل ذرة كربون غير مشتركة ترتبط بذرة هيدروجين واحدة: H = 12","الصيغة الجزيئية C₂₀H₁₂"]'::jsonb, '[{"element":"تعليل كونه حلقات ملتحمة","marks":1},{"element":"تعليل تصنيفه أروماتيًّا","marks":1},{"element":"حساب ذرات الهيدروجين","marks":1},{"element":"الصيغة الجزيئية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليلان وحساب وصيغة صحيحة"},{"level":"2–3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيفه أليفاتيًّا لكثرة حلقاته","عدّ الهيدروجين 20 بإغفال الذرات المشتركة","تعليل الالتحام بوجود روابط أحادية بين الحلقات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.645Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
