('mcq', 1, 'ما المقصود بالمجموعة الوظيفية في المركبات العضوية؟', null, null, '["أطول سلسلة متصلة من ذرات الكربون في الجزيء، ويُبنى عليها اسم المركب العضوي","ذرة أو مجموعة من الذرات في المركب العضوي تكسبه خواص مميزة وتتفاعل دائمًا بالطريقة نفسها","ذرات الهيدروجين المرتبطة بذرات الكربون في الهيدروكربونات المشبعة فقط","مجموعة ألكيل متفرعة من السلسلة الرئيسة يُحدَّد موقعها برقم عند التسمية"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 168 — المجموعات الوظيفية'),
('mcq', 2, 'ما اسم المجموعة الوظيفية في المركب الذي يمثله الشكل الآتي؟', null, '[{"src":"qimg/chem22/c5-l1a-propanol.svg","alt":"صيغة بنائية كاملة لجزيء من ثلاث ذرات كربون متصلة في سلسلة أفقية بروابط أحادية. ترتبط ذرة الكربون اليسرى بثلاث ذرات هيدروجين (يسار وأعلى وأسفل)، وترتبط ذرة الكربون الوسطى بذرتي هيدروجين (أعلى وأسفل)، وترتبط ذرة الكربون اليمنى بذرتي هيدروجين (أعلى وأسفل) وبذرة أكسجين O عن يمينها برابطة أحادية، وترتبط ذرة الأكسجين بذرة هيدروجين H برابطة أحادية: H–C–C–C–O–H."}]'::jsonb, '["الهيدروكسيل","الكربونيل","الإيثر","الكربوكسيل"]'::jsonb, 'تذكر', 'تعرف مجموعة وظيفية من الصيغة البنائية', 'سهل', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('mcq', 3, 'حدّد المجموعة الوظيفية في الصيغة البنائية الآتية.', null, '[{"src":"qimg/chem22/c5-l1a-acid.svg","alt":"صيغة بنائية مكثفة: مجموعة CH₃ على اليسار ترتبط برابطة أحادية بذرة كربون C في الوسط، وترتبط ذرة الكربون هذه بذرة أكسجين O فوقها برابطة ثنائية، وبمجموعة OH عن يمينها برابطة أحادية: CH₃–C(=O)–OH."}]'::jsonb, '["الكربونيل فقط","الهيدروكسيل فقط","الإستر","الكربوكسيل"]'::jsonb, 'فهم', 'تعرف مجموعة وظيفية من الصيغة البنائية', 'متوسط', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('mcq', 4, 'في أيّ الصيغ الآتية تكون المجموعة الوظيفية هي مجموعة الأمين؟', null, '[{"src":"qimg/chem22/c5-l1a-fg-four.svg","alt":"أربع صيغ بنائية مكثفة في شبكة من عمودين، (أ) أعلى اليمين و(ب) أعلى اليسار و(ج) أسفل اليمين و(د) أسفل اليسار. (أ): CH₃–CH₂–OH. (ب): CH₃ مرتبطة بذرة كربون C فوقها ذرة أكسجين O برابطة ثنائية، ويرتبط الكربون عن يمينه بمجموعة NH₂: CH₃–C(=O)–NH₂. (ج): CH₃–CH₂–NH₂. (د): CH₃–CH₂–Cl."}]'::jsonb, '["(أ)","(ب)","(ج)","(د)"]'::jsonb, 'فهم', 'تمييز مجموعة وظيفية بين صيغ', 'صعب', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('mcq', 5, 'أيّ مجموعات العناصر الآتية تُعدّ ذراتها من أكثر الذرات شيوعًا في المجموعات الوظيفية للمركبات العضوية؟', null, null, '["الصوديوم والبوتاسيوم والكالسيوم","الأكسجين والنيتروجين والهالوجينات","الهيليوم والنيون والأرجون","الحديد والنحاس والخارصين"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 168 — المجموعات الوظيفية'),
('mcq', 6, 'أيّ الأزواج الآتية (نوع المركب — مجموعته الوظيفية) صحيح؟', null, null, '["الإيثرات — الهيدروكسيل","الأمينات — الأميد","الكحولات — الكربوكسيل","الألدهيدات — الكربونيل"]'::jsonb, 'تذكر', 'مطابقة نوع المركب بمجموعته الوظيفية', 'متوسط', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('mcq', 7, 'تعود الرائحة المميزة لكثير من الفواكه والأزهار إلى مركبات من النوع الذي يمثله الشكل الآتي. ما المجموعة الوظيفية فيها؟', null, '[{"src":"qimg/chem22/c5-l1a-ester.svg","alt":"صيغة بنائية مكثفة أفقية: CH₃ مرتبطة برابطة أحادية بذرة كربون C، وفوق ذرة الكربون ذرة أكسجين O مرتبطة بها برابطة ثنائية، وعن يمين ذرة الكربون ذرة أكسجين O برابطة أحادية، ثم مجموعة CH₂CH₃ مرتبطة بذرة الأكسجين: CH₃–C(=O)–O–CH₂CH₃."}]'::jsonb, '["الإيثر","الكيتون","الإستر","الكربوكسيل"]'::jsonb, 'فهم', 'تعرف مجموعة وظيفية من الصيغة البنائية', 'متوسط', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('essay', 1, 'عرّف المجموعة الوظيفية، ثم اذكر ثلاثة أمثلة على مجموعات وظيفية، مع كتابة الصيغة العامة لنوع المركب الذي تميّزه كلٌّ منها.', null, null, null, 'تذكر', 'تعريف وأمثلة', 'متوسط', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('essay', 2, 'يمثل الشكل الآتي جزيء مركب عضوي. حدّد المجموعات الوظيفية فيه واذكر اسم كلٍّ منها، ثم وضّح لماذا يُتوقع أن تختلف خواصه عن خواص الإيثان CH₃CH₃.', null, '[{"src":"qimg/chem22/c5-l1a-clethanol.svg","alt":"صيغة بنائية كاملة لجزيء فيه ذرتا كربون متصلتان برابطة أحادية في خط أفقي. ترتبط ذرة الكربون اليسرى بذرة كلور Cl عن يسارها، وبذرتي هيدروجين فوقها وتحتها. وترتبط ذرة الكربون اليمنى بذرتي هيدروجين فوقها وتحتها، وبذرة أكسجين O عن يمينها، وترتبط ذرة الأكسجين بذرة هيدروجين H: Cl–C–C–O–H."}]'::jsonb, null, 'تحليل', 'تحديد المجموعات الوظيفية وتفسير', 'صعب', 'الكتاب ص 169 — الجدول 5-1 المركبات العضوية ومجموعاتها الوظيفية'),
('essay', 3, 'لا يحتوي الألكين والألكاين إلا على ذرات كربون وهيدروجين، ومع ذلك تُعدّ الرابطة الثنائية والرابطة الثلاثية بين ذرتي الكربون مجموعتين وظيفيتين. فسّر ذلك، ثم بيّن فائدة معرفة المجموعة الوظيفية في مركب عضوي لم تدرس خواصه من قبل.', null, null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 168 — المجموعات الوظيفية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المجموعة الوظيفية في المركبات العضوية ذرة أو مجموعة من الذرات تكسب المركب خواص مميزة، وتتفاعل دائمًا بالطريقة نفسها؛ ولذلك فإن إضافتها إلى الهيدروكربون تنتج مادة لها خواص فيزيائية وكيميائية مختلفة عن الهيدروكربون الأصلي.', '["هذا وصف السلسلة الرئيسة التي تُعتمد في التسمية، وليست هي المسؤولة عن الخواص المميزة للمركب.","","ذرات الهيدروجين في الهيدروكربونات المشبعة لا تكسب المركب خواص مميزة؛ والمجموعة الوظيفية غالبًا تحل محل ذرة هيدروجين.","هذا وصف المجموعة الفرعية (الألكيل) في تسمية الهيدروكربونات المتفرعة، لا المجموعة الوظيفية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 2, 0, 'في الشكل ترتبط ذرة أكسجين بذرة كربون طرفية من جهة وبذرة هيدروجين من جهة أخرى، أي مجموعة –OH، وهي مجموعة الهيدروكسيل التي تميّز الكحولات (R–OH).', '["","مجموعة الكربونيل ذرة أكسجين مرتبطة برابطة ثنائية مع ذرة كربون (C=O)، ولا توجد رابطة ثنائية في الشكل.","مجموعة الإيثر ذرة أكسجين بين ذرتي كربون (R–O–R′)، أما الأكسجين هنا فمرتبط بذرة كربون وذرة هيدروجين.","مجموعة الكربوكسيل (–COOH) تحتاج إلى ذرة أكسجين ثانية مرتبطة برابطة ثنائية مع ذرة الكربون نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 3, 3, 'ترتبط ذرة الكربون في الصيغة بذرة أكسجين برابطة ثنائية (C=O) وبمجموعة OH في الوقت نفسه، أي المجموعة –COOH، وهي مجموعة الكربوكسيل التي تميّز الأحماض الكربوكسيلية R–COOH.', '["تحتوي الصيغة على مجموعة كربونيل C=O، لكنها مرتبطة بمجموعة OH على ذرة الكربون نفسها، والمجموعتان معًا تكوّنان مجموعة الكربوكسيل.","توجد مجموعة OH فعلًا، لكنها مرتبطة بذرة كربون الكربونيل، فلا تُعدّ هيدروكسيلًا منفردًا كما في الكحولات.","في الإستر تحل مجموعة ألكيل محل ذرة الهيدروجين في OH (R–COO–R)، أما هنا فذرة الهيدروجين ما زالت مرتبطة بالأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 4, 2, 'الأمينات صيغتها العامة R–NH₂، أي مجموعة NH₂ مرتبطة بذرة كربون في سلسلة ألكيل. والصيغة (ج) CH₃CH₂NH₂ تطابق ذلك. أما (ب) ففيها NH₂ مرتبطة بمجموعة كربونيل، فهي أميد.', '["الصيغة (أ) CH₃CH₂OH تحتوي على مجموعة الهيدروكسيل، فهي كحول.","الصيغة (ب) تحتوي على NH₂ لكنها مرتبطة بذرة كربون الكربونيل C=O، فالمجموعة أميد لا أمين.","","الصيغة (د) CH₃CH₂Cl تحتوي على ذرة هالوجين، فهي هاليد ألكيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 5, 1, 'يمكن لذرة الكربون أن تكوّن روابط تساهمية قوية مع عناصر أخرى، أكثرها شيوعًا الأكسجين والنيتروجين والفلور والكلور والبروم واليود والكبريت والفوسفور، وتوجد ذرات هذه العناصر في المواد العضوية بوصفها جزءًا من المجموعات الوظيفية.', '["هذه فلزات نشطة تكوّن غالبًا مركبات أيونية، ولا تكوّن روابط تساهمية قوية مع الكربون في المجموعات الوظيفية.","","هذه غازات نبيلة لا تكوّن روابط مع الكربون في الظروف العادية.","هذه فلزات انتقالية، وليست من العناصر التي تكوّن المجموعات الوظيفية الشائعة في المركبات العضوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 6, 3, 'الألدهيدات صيغتها العامة R–CHO، أي ذرة كربون مرتبطة بذرة أكسجين برابطة ثنائية (C=O) وبذرة هيدروجين، والمجموعة C=O هي مجموعة الكربونيل؛ فالزوج «الألدهيدات — الكربونيل» صحيح.', '["المجموعة الوظيفية في الإيثرات هي الإيثر (R–O–R′)، أما الهيدروكسيل فيميّز الكحولات.","المجموعة الوظيفية في الأمينات هي الأمين (R–NH₂)، أما الأميد فيميّز الأميدات.","المجموعة الوظيفية في الكحولات هي الهيدروكسيل (R–OH)، أما الكربوكسيل فيميّز الأحماض الكربوكسيلية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('mcq', 7, 2, 'في الشكل ترتبط ذرة كربون بذرة أكسجين برابطة ثنائية وبذرة أكسجين أخرى ترتبط بدورها بمجموعة ألكيل (CH₂CH₃)، أي R–COO–R، وهي مجموعة الإستر. والإسترات هي التي تكسب الفواكه والأزهار روائحها المميزة.', '["في الصيغة ذرة أكسجين بين ذرتي كربون كما في الإيثر، لكن ذرة الكربون المجاورة لها مرتبطة بأكسجين برابطة ثنائية، فالمجموعة إستر.","الكيتون فيه مجموعة كربونيل بين ذرتي كربون (R–CO–R′)، أما هنا فذرة كربون الكربونيل مرتبطة بذرة أكسجين ثانية.","","الكربوكسيل –COOH ينتهي بذرة هيدروجين على الأكسجين، أما هنا فقد حلت مجموعة إيثيل محل هذه الذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المجموعة الوظيفية: ذرة أو مجموعة من الذرات في المركب العضوي تكسبه خواص مميزة، وتتفاعل دائمًا بالطريقة نفسها. أمثلة: (1) الهالوجين في هاليدات الألكيل R–X (X = F أو Cl أو Br أو I). (2) الهيدروكسيل في الكحولات R–OH. (3) الأمين في الأمينات R–NH₂. ويُقبل أيضًا: الإيثر R–O–R′، والكربونيل في الألدهيدات R–CHO والكيتونات R–CO–R′، والكربوكسيل في الأحماض الكربوكسيلية R–COOH، والإستر R–COO–R، والأميد.', '["التعريف: ذرة أو مجموعة ذرات تكسب المركب خواص مميزة","تتفاعل دائمًا بالطريقة نفسها","ثلاث مجموعات وظيفية صحيحة","الصيغة العامة الصحيحة لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف (الخواص المميزة + التفاعل بالطريقة نفسها)","marks":2},{"element":"ثلاثة أمثلة صحيحة (نصف درجة لكل مثال)","marks":1.5},{"element":"ثلاث صيغ عامة صحيحة (نصف درجة لكل صيغة)","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"تعريف كامل، وثلاثة أمثلة صحيحة بصيغها العامة"},{"level":"3–4 درجات","description":"تعريف ناقص جزءًا، أو خطأ في مثال أو صيغة واحدة"},{"level":"1–2 درجة","description":"تعريف غير دقيق مع مثال أو مثالين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المجموعة الوظيفية بأنها السلسلة الكربونية الرئيسة","الخلط بين الهيدروكسيل والكربوكسيل","كتابة R–OH صيغة عامة للإيثرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.646Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الجزيء مجموعتان وظيفيتان: (1) ذرة الكلور Cl المرتبطة بذرة الكربون اليسرى، وهي مجموعة الهالوجين (كما في هاليدات الألكيل). (2) مجموعة –OH المرتبطة بذرة الكربون اليمنى، وهي مجموعة الهيدروكسيل (كما في الكحولات). الإيثان لا يحتوي إلا على روابط C–C وC–H أحادية ولا توجد فيه مجموعة وظيفية، أما المجموعات الوظيفية فتكسب المركب خواص فيزيائية وكيميائية مميزة وتتفاعل دائمًا بالطريقة نفسها؛ لذا تختلف خواص هذا المركب عن خواص الإيثان.', '["تحديد الكلور مجموعة هالوجين","تحديد OH مجموعة هيدروكسيل","الإيثان بلا مجموعة وظيفية","المجموعات الوظيفية تكسب خواص مميزة وتتفاعل بالطريقة نفسها"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد مجموعة الهالوجين وتسميتها","marks":1},{"element":"تحديد مجموعة الهيدروكسيل وتسميتها","marks":1},{"element":"التفسير: الإيثان بلا مجموعة وظيفية، والمجموعات الوظيفية تكسب خواص مميزة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد المجموعتين وتسميتهما وتفسير كامل"},{"level":"2–3 درجات","description":"تحديد المجموعتين مع تفسير ناقص، أو مجموعة واحدة مع تفسير صحيح"},{"level":"1 درجة","description":"تحديد مجموعة واحدة فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرة الأكسجين وحدها مجموعة إيثر","إغفال ذرة الكلور بوصفها مجموعة وظيفية","القول إن الإيثان يحتوي على مجموعة وظيفية هي C–H"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تُعدّ الرابطتان الثنائية والثلاثية مجموعتين وظيفيتين لأنهما تكسبان الألكينات والألكاينات خواص مميزة تختلف عن خواص الألكانات (فهي أنشط كيميائيًّا من الألكانات)، وتتفاعل المركبات التي تحتوي عليها بالطريقة نفسها، وهذا هو معيار المجموعة الوظيفية وليس وجود ذرات عنصر غير الكربون والهيدروجين. ومعرفة المجموعة الوظيفية في مركب ما تمكّننا من توقع خواصه وتفاعلاته حتى لو لم ندرس هذا المركب سابقًا؛ لأن المجموعة الوظيفية تتفاعل دائمًا بالطريقة نفسها.', '["الرابطة المتعددة تكسب المركب خواص مميزة (نشاط أكبر من الألكانات)","المعيار هو الخواص المميزة والتفاعل بالطريقة نفسها لا نوع الذرات","الفائدة: توقع خواص المركب وتفاعلاته"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير عدّ الرابطة المتعددة مجموعة وظيفية","marks":2},{"element":"فائدة معرفة المجموعة الوظيفية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير صحيح كامل مع ذكر فائدة توقع الخواص"},{"level":"2 درجتان","description":"تفسير صحيح دون الفائدة، أو فائدة مع تفسير ناقص"},{"level":"1 درجة","description":"ذكر أن الرابطة نشطة دون ربطها بمفهوم المجموعة الوظيفية"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اشتراط وجود ذرة غير الكربون والهيدروجين لتكون هناك مجموعة وظيفية","القول إن الألكانات أنشط من الألكينات","عدّ الرابطة C–H الأحادية مجموعة وظيفية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O01') and x.type = v.type and x.number = v.number
